--
-- Name: allocate_clinic_packet_funding(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.allocate_clinic_packet_funding(p_briefcase_item_id uuid, p_consumer_auth_user_id uuid, p_expected_verification_hash text) RETURNS TABLE(funding_mode text, reason text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_item public.consumer_briefcase_items%rowtype;
  v_verification public.consumer_packet_verifications%rowtype;
  v_source public.consumer_pending_screening_results%rowtype;
  v_session public.screening_sessions%rowtype;
  v_case public.clinic_cases%rowtype;
  v_event public.clinic_events%rowtype;
  v_entitlement public.partner_entitlement%rowtype;
  v_choice public.clinic_packet_funding%rowtype;
  v_packet_entitlement public.partner_packet_entitlement%rowtype;
  v_packet_used bigint;
  v_route public.sponsored_packet_render_routes%rowtype;
  v_scope record;
  v_event_used bigint;
  v_partner_reserved bigint;
  v_mode text := 'sponsored';
  v_reason text := 'slot_reserved';
begin
  -- Match the canonical finalizer lock order. No client-selected sponsor/event.
  select * into v_item from public.consumer_briefcase_items
    where id=p_briefcase_item_id and user_id=p_consumer_auth_user_id for update;
  if not found then return query select 'denied'::text,'wrong_owner'::text; return; end if;
  select * into v_verification from public.consumer_packet_verifications
    where briefcase_item_id=v_item.id for update;
  if not found or v_verification.consumer_auth_user_id is distinct from v_item.user_id
     or v_verification.matter_id is distinct from public.consumer_matter_id_for_briefcase_item(v_item.id)
     or v_verification.status is distinct from 'verified'
     or v_verification.verification_hash is distinct from p_expected_verification_hash
     or p_expected_verification_hash is null then
    return query select 'denied'::text,'verification_mismatch'::text; return;
  end if;
  select * into v_source from public.consumer_pending_screening_results
    where pending_id=v_item.source_pending_result_id for update;
  if not found or v_source.product is distinct from 'rcap_partner'
     or v_source.claimed_user_id is distinct from v_item.user_id
     or v_source.claimed_matter_id is distinct from v_item.id or v_source.status is distinct from 'CLAIMED' then
    return query select 'denied'::text,'source_mismatch'::text; return;
  end if;
  select * into v_session from public.screening_sessions
    where session_id=v_source.anonymous_session_id for update;
  select * into v_case from public.clinic_cases
    where matter_id=v_item.id and participant_user_id=v_item.user_id
      and screening_session_id=v_source.anonymous_session_id and event_id=v_source.event_id for update;
  if not found then return query select 'denied'::text,'clinic_scope_mismatch'::text; return; end if;
  select * into v_event from public.clinic_events where id=v_case.event_id for update;
  select * into v_route from public.sponsored_packet_render_routes
    where route_key=(v_verification.verification_snapshot->>'jurisdiction')||':'||
      (v_verification.verification_snapshot->>'pathwayId') and active;
  if not found or (v_route.registry_track_id is not null and v_route.registry_track_id is distinct from
       v_verification.verification_snapshot->>'selectedTrackId') then
    return query select 'denied'::text,'route_mismatch'::text; return;
  end if;
  select * into v_scope from public.sponsored_packet_render_authority(
    v_route.route_key, v_source.anonymous_session_id, v_item.id, v_item.user_id);
  if not coalesce(v_scope.valid,false) then return query select 'denied'::text,v_scope.reason; return; end if;
  select * into v_choice from public.clinic_packet_funding where briefcase_item_id=v_item.id;
  if found then
    if v_choice.consumer_auth_user_id is distinct from v_item.user_id
       or v_choice.source_session_id is distinct from v_source.anonymous_session_id
       or v_choice.event_id is distinct from v_event.id or v_choice.partner_slug is distinct from v_event.partner_slug
       or v_choice.route_key is distinct from v_route.route_key or v_choice.packet_family_id is distinct from v_route.packet_family_id then
      return query select 'denied'::text,'funding_binding_mismatch'::text; return;
    end if;
    return query select v_choice.funding_mode,v_choice.reason; return;
  end if;
  -- Reuse delivered Applicant A and other already-consumed packets read-only.
  if exists(select 1 from public.consumer_packet_artifact_provenance p where p.briefcase_item_id=v_item.id
      and p.consumer_auth_user_id=v_item.user_id and p.entitlement_source='partner_sponsorship') then
    return query select 'sponsored'::text,'already_consumed'::text; return;
  end if;
  if v_session.claimed_slot_state is distinct from 'claimed' then
    return query select 'denied'::text,'sponsorship_inactive'::text; return;
  end if;
  -- Event and partner locks serialize all contenders, including different
  -- events sharing the final partner slot. Count reserved OR consumed once.
  select * into v_entitlement from public.partner_entitlement where partner_slug=v_event.partner_slug for update;
  if not found then return query select 'denied'::text,'no_entitlement'::text; return; end if;
  select count(*) into v_event_used from (
    select p.briefcase_item_id from public.consumer_packet_artifact_provenance p
      join public.clinic_cases c on c.matter_id=p.briefcase_item_id
      where c.event_id=v_event.id and p.entitlement_source='partner_sponsorship'
    union
    select f.briefcase_item_id from public.clinic_packet_funding f
      where f.event_id=v_event.id and f.funding_mode='sponsored'
  ) used;
  select count(*) into v_partner_reserved from public.clinic_packet_funding f
    where f.partner_slug=v_event.partner_slug and f.funding_mode='sponsored'
      and not exists(select 1 from public.consumer_packet_artifact_provenance p
        where p.briefcase_item_id=f.briefcase_item_id and p.entitlement_source='partner_sponsorship');
  select * into v_packet_entitlement from public.partner_packet_entitlement e
    where e.partner_id=v_scope.partner_id and e.effective_at<=now()
      and (e.expires_at is null or e.expires_at>now()) order by e.effective_at desc limit 1 for update;
  if not found then return query select 'denied'::text,'no_entitlement'::text; return; end if;
  select count(*) into v_packet_used from (
    select l.matter_id from public.packet_credit_ledger l where l.entitlement_id=v_packet_entitlement.id
      and l.event_type in ('consumed','overage_consumed')
    union
    select public.consumer_matter_id_for_briefcase_item(f.briefcase_item_id) from public.clinic_packet_funding f
      where f.packet_entitlement_id=v_packet_entitlement.id and f.funding_mode='sponsored'
  ) used;
  if v_event_used >= v_event.sponsorship_allocation then v_mode:='dtc'; v_reason:='event_cap_exhausted';
  elsif v_entitlement.screenings_used+v_partner_reserved >= v_entitlement.screenings_allowed
     or v_packet_used >= v_packet_entitlement.packet_cap then
    v_mode:='dtc'; v_reason:='partner_cap_exhausted';
  end if;
  insert into public.clinic_packet_funding(briefcase_item_id,consumer_auth_user_id,source_session_id,event_id,
    partner_slug,packet_entitlement_id,route_key,packet_family_id,initial_verification_hash,funding_mode,reason)
    values(v_item.id,v_item.user_id,v_source.anonymous_session_id,v_event.id,v_event.partner_slug,
      v_packet_entitlement.id,v_route.route_key,v_route.packet_family_id,p_expected_verification_hash,v_mode,v_reason);
  return query select v_mode,v_reason;
end;
$$;


ALTER FUNCTION public.allocate_clinic_packet_funding(p_briefcase_item_id uuid, p_consumer_auth_user_id uuid, p_expected_verification_hash text) OWNER TO postgres;

SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: packet_render_jobs; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.packet_render_jobs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    packet_id uuid NOT NULL,
    route_id text NOT NULL,
    renderer_kind text NOT NULL,
    source_sha256 text,
    profile_id text NOT NULL,
    profile_version text NOT NULL,
    input_hash text NOT NULL,
    status text DEFAULT 'queued'::text NOT NULL,
    attempt_count integer DEFAULT 0 NOT NULL,
    output_storage_path text,
    output_sha256 text,
    normalized_output_sha256 text,
    page_count integer,
    error_code text,
    claimed_by text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    claimed_at timestamp with time zone,
    rendering_at timestamp with time zone,
    validating_at timestamp with time zone,
    artifact_validated_at timestamp with time zone,
    delivered_at timestamp with time zone,
    renderer_version text DEFAULT '0.0.0'::text NOT NULL,
    briefcase_item_id uuid,
    partner_id uuid,
    person_id uuid,
    matter_id uuid,
    max_attempts integer DEFAULT 5 NOT NULL,
    next_attempt_at timestamp with time zone,
    claim_expires_at timestamp with time zone,
    fencing_token uuid,
    failure_disposition text,
    last_error_detail text,
    manual_requeue_authorized_by text,
    output_byte_count integer,
    container_digest text,
    delivery_eligibility text DEFAULT 'not_evaluated'::text NOT NULL,
    accounting_result text,
    credit_ledger_id uuid,
    consumer_briefcase_item_id uuid,
    consumer_auth_user_id uuid,
    consumer_verification_hash text,
    sponsored_route_key text,
    sponsored_session_id uuid,
    sponsored_clinic_event_id uuid,
    sponsored_consumer_briefcase_item_id uuid,
    sponsored_consumer_auth_user_id uuid,
    sponsored_verification_hash text,
    CONSTRAINT packet_render_jobs_accounting_result_check CHECK (((accounting_result IS NULL) OR (accounting_result = ANY (ARRAY['consumed'::text, 'already_consumed'::text, 'overage_consumed'::text, 'zero_charge'::text, 'cap_reached'::text, 'not_validated'::text, 'not_found'::text, 'unauthorized'::text, 'consumer_payment_required'::text, 'consumer_payment_matter_conflict'::text, 'consumer_payment_owner_mismatch'::text, 'consumer_payment_conflict'::text])))),
    CONSTRAINT packet_render_jobs_attempt_count_check CHECK ((attempt_count >= 0)),
    CONSTRAINT packet_render_jobs_consumer_verification_hash_check CHECK (((consumer_verification_hash IS NULL) OR (consumer_verification_hash ~ '^[a-f0-9]{64}$'::text))),
    CONSTRAINT packet_render_jobs_delivery_eligibility_check CHECK ((delivery_eligibility = ANY (ARRAY['not_evaluated'::text, 'eligible'::text, 'accounting_blocked'::text]))),
    CONSTRAINT packet_render_jobs_eligible_requires_accounting_check CHECK (((delivery_eligibility <> 'eligible'::text) OR ((status = ANY (ARRAY['artifact_validated'::text, 'delivered'::text])) AND (accounting_result = ANY (ARRAY['consumed'::text, 'already_consumed'::text, 'overage_consumed'::text, 'zero_charge'::text]))))),
    CONSTRAINT packet_render_jobs_error_code_check CHECK (((error_code IS NULL) OR (error_code = ANY (ARRAY['source_not_whitelisted'::text, 'profile_unknown'::text, 'render_failed'::text, 'invalid_pdf_output'::text, 'page_count_mismatch'::text, 'protected_field_populated'::text, 'storage_write_failed'::text, 'storage_readback_failed'::text, 'checksum_mismatch'::text, 'timeout'::text, 'worker_crashed'::text])))),
    CONSTRAINT packet_render_jobs_failed_requires_code CHECK (((status <> 'failed'::text) OR (error_code IS NOT NULL))),
    CONSTRAINT packet_render_jobs_failure_disposition_check CHECK (((failure_disposition IS NULL) OR (failure_disposition = ANY (ARRAY['retryable'::text, 'terminal'::text])))),
    CONSTRAINT packet_render_jobs_input_hash_check CHECK ((input_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT packet_render_jobs_max_attempts_check CHECK (((max_attempts >= 1) AND (max_attempts <= 50))),
    CONSTRAINT packet_render_jobs_normalized_sha_check CHECK (((normalized_output_sha256 IS NULL) OR (normalized_output_sha256 ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT packet_render_jobs_output_sha_check CHECK (((output_sha256 IS NULL) OR (output_sha256 ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT packet_render_jobs_page_count_check CHECK (((page_count IS NULL) OR (page_count > 0))),
    CONSTRAINT packet_render_jobs_partner_identity_check CHECK (((partner_id IS NULL) OR ((person_id IS NOT NULL) AND (matter_id IS NOT NULL)))),
    CONSTRAINT packet_render_jobs_source_presence_check CHECK (((renderer_kind = 'packet_document_v1'::text) OR (source_sha256 IS NOT NULL))),
    CONSTRAINT packet_render_jobs_source_sha_check CHECK (((source_sha256 IS NULL) OR (source_sha256 ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT packet_render_jobs_sponsored_verification_hash_check CHECK (((sponsored_verification_hash IS NULL) OR (sponsored_verification_hash ~ '^[a-f0-9]{64}$'::text))),
    CONSTRAINT packet_render_jobs_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'claimed'::text, 'rendering'::text, 'validating'::text, 'artifact_validated'::text, 'delivered'::text, 'failed'::text]))),
    CONSTRAINT packet_render_jobs_validated_requires_output CHECK (((status <> ALL (ARRAY['artifact_validated'::text, 'delivered'::text])) OR ((output_storage_path IS NOT NULL) AND (output_storage_path <> ''::text) AND (output_sha256 IS NOT NULL) AND (normalized_output_sha256 IS NOT NULL) AND (container_digest IS NOT NULL))))
);


ALTER TABLE public.packet_render_jobs OWNER TO postgres;

--
-- Name: TABLE packet_render_jobs; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.packet_render_jobs IS 'Durable unit of packet rendering work. Terminal success requires stored bytes that were read back and checksummed; credit movement is gated on it.';


--
-- Name: COLUMN packet_render_jobs.input_hash; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.packet_render_jobs.input_hash IS 'Hash of server-derived render inputs. Idempotency key: identical inputs are the same job, so a retry cannot double-consume credit.';


--
-- Name: COLUMN packet_render_jobs.normalized_output_sha256; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.packet_render_jobs.normalized_output_sha256 IS 'Content fingerprint with harmless metadata variance normalized away, so benign byte differences do not read as a changed document.';


--
-- Name: assert_packet_render_job_fencing(public.packet_render_jobs, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.assert_packet_render_job_fencing(p_job public.packet_render_jobs, p_fencing_token uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if p_job.fencing_token is null or p_fencing_token is null
     or p_job.fencing_token <> p_fencing_token then
    raise exception 'packet_render_jobs: fencing token is not the active claim';
  end if;
  if p_job.claim_expires_at is null or p_job.claim_expires_at < now() then
    raise exception 'packet_render_jobs: claim lease has expired';
  end if;
end;
$$;


ALTER FUNCTION public.assert_packet_render_job_fencing(p_job public.packet_render_jobs, p_fencing_token uuid) OWNER TO postgres;

--
-- Name: attach_consumer_packet_artifact_if_verified(uuid, uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.attach_consumer_packet_artifact_if_verified(p_consumer_auth_user_id uuid, p_briefcase_item_id uuid, p_expected_verification_hash text, p_entitlement_source text, p_artifact jsonb) RETURNS TABLE(status text, revision integer, verification_hash text, entitlement_source text, artifact jsonb, consumer_auth_user_id uuid, briefcase_item_id uuid, matter_id uuid, legacy_evidence jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_hash text;
  v_authorized boolean;
  v_item public.consumer_briefcase_items%rowtype;
begin
  if p_entitlement_source <> 'consumer_payment' or coalesce(jsonb_typeof(p_artifact), '') <> 'object' then return; end if;
  select * into v_item from public.consumer_briefcase_items i
    where i.id = p_briefcase_item_id and i.user_id = p_consumer_auth_user_id for update;
  if not found then return; end if;
  select v.verification_hash into v_hash from public.consumer_packet_verifications v
    where v.briefcase_item_id = p_briefcase_item_id
      and v.consumer_auth_user_id = p_consumer_auth_user_id
      and v.status = 'verified' for update;
  if v_hash is null or v_hash is distinct from p_expected_verification_hash then return; end if;
  select a.valid into v_authorized from public.consumer_packet_payment_authority(
    p_briefcase_item_id, p_consumer_auth_user_id, public.expungement_packet_product_id(),
    v_item.payment_person_id, public.consumer_matter_id_for_briefcase_item(p_briefcase_item_id)
  ) a;
  if not coalesce(v_authorized, false) then return; end if;

  insert into public.consumer_packet_artifact_provenance(
    briefcase_item_id, consumer_auth_user_id, matter_id, verification_hash,
    entitlement_source, artifact
  ) values (
    p_briefcase_item_id, p_consumer_auth_user_id,
    public.consumer_matter_id_for_briefcase_item(p_briefcase_item_id),
    p_expected_verification_hash, p_entitlement_source, p_artifact
  ) on conflict on constraint consumer_packet_artifact_provenance_pkey do nothing;
  if not exists (
    select 1 from public.consumer_packet_artifact_provenance p
    where p.briefcase_item_id = p_briefcase_item_id
      and p.consumer_auth_user_id = p_consumer_auth_user_id
      and p.verification_hash = p_expected_verification_hash
      and p.artifact = p_artifact
  ) then return; end if;
  update public.consumer_briefcase_items i set artifact_refs_json = p_artifact,
    packet_status = 'ready', updated_at = now() where i.id = p_briefcase_item_id;
  return query select 'ready'::text, p.revision, p.verification_hash,
    p.entitlement_source, p.artifact, p.consumer_auth_user_id,
    p.briefcase_item_id, p.matter_id, p.legacy_evidence
  from public.consumer_packet_artifact_provenance p where p.briefcase_item_id = p_briefcase_item_id;
end;
$$;


ALTER FUNCTION public.attach_consumer_packet_artifact_if_verified(p_consumer_auth_user_id uuid, p_briefcase_item_id uuid, p_expected_verification_hash text, p_entitlement_source text, p_artifact jsonb) OWNER TO postgres;

--
-- Name: bind_consumer_checkout_verification(uuid, uuid, text, text, text, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.bind_consumer_checkout_verification(p_consumer_auth_user_id uuid, p_briefcase_item_id uuid, p_checkout_session_id text, p_payment_provider text, p_product_id text, p_person_id uuid, p_matter_id uuid, p_expected_verification_hash text) RETURNS TABLE(ok boolean, reason text, briefcase_item_id uuid, checkout_session_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_item public.consumer_briefcase_items%rowtype;
  v_hash text;
  v_other uuid;
begin
  select * into v_item from public.consumer_briefcase_items i
   where i.id = p_briefcase_item_id for update;
  if not found or v_item.user_id is distinct from p_consumer_auth_user_id then
    return query select false, 'item_not_found'::text, null::uuid, null::text; return;
  end if;
  select v.verification_hash into v_hash from public.consumer_packet_verifications v
   where v.briefcase_item_id = p_briefcase_item_id and v.status = 'verified' for update;
  if v_hash is distinct from p_expected_verification_hash then
    return query select false, 'verification_changed'::text, p_briefcase_item_id, null::text; return;
  end if;
  if v_item.payment_allowed is not true or v_item.payment_status = 'not_applicable'
     or p_product_id is distinct from public.expungement_packet_product_id()
     or p_matter_id is distinct from public.consumer_matter_id_for_briefcase_item(p_briefcase_item_id)
     or p_person_id is null or p_payment_provider not in ('stripe', 'dry_run')
     or nullif(trim(coalesce(p_checkout_session_id, '')), '') is null then
    return query select false, 'checkout_binding_invalid'::text, p_briefcase_item_id, null::text; return;
  end if;
  select i.id into v_other from public.consumer_briefcase_items i
    where i.checkout_session_id = p_checkout_session_id and i.id <> p_briefcase_item_id limit 1;
  if v_other is not null then
    return query select false, 'checkout_session_in_use'::text, p_briefcase_item_id, null::text; return;
  end if;
  if v_item.checkout_session_id is not null and v_item.checkout_session_id <> p_checkout_session_id then
    return query select false, 'checkout_binding_conflict'::text, p_briefcase_item_id, v_item.checkout_session_id; return;
  end if;
  update public.consumer_briefcase_items i set
    checkout_session_id = p_checkout_session_id,
    payment_provider = p_payment_provider,
    payment_product_id = p_product_id,
    payment_person_id = p_person_id,
    payment_matter_id = p_matter_id,
    payment_status = case when i.payment_status = 'paid' then 'paid' else 'unpaid' end,
    amount_cents = case when i.payment_status = 'paid' then i.amount_cents else null end,
    updated_at = now()
  where i.id = p_briefcase_item_id;
  return query select true, 'bound'::text, p_briefcase_item_id, p_checkout_session_id;
end;
$$;


ALTER FUNCTION public.bind_consumer_checkout_verification(p_consumer_auth_user_id uuid, p_briefcase_item_id uuid, p_checkout_session_id text, p_payment_provider text, p_product_id text, p_person_id uuid, p_matter_id uuid, p_expected_verification_hash text) OWNER TO postgres;

--
-- Name: claim_packet_render_job(text, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_packet_render_job(p_worker_id text, p_renderer_kinds text[]) RETURNS SETOF public.packet_render_jobs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_worker text;
  v_id uuid;
begin
  v_worker := nullif(trim(p_worker_id), '');
  if v_worker is null then
    raise exception 'worker id is required';
  end if;
  if p_renderer_kinds is null or array_length(p_renderer_kinds, 1) is null then
    raise exception 'at least one renderer kind is required';
  end if;

  select id into v_id
  from public.packet_render_jobs
  where status = 'queued'
    and renderer_kind = any (p_renderer_kinds)
  order by created_at
  for update skip locked
  limit 1;

  if v_id is null then
    return;
  end if;

  return query
  update public.packet_render_jobs
  set status = 'claimed',
      claimed_by = v_worker,
      attempt_count = attempt_count + 1
  where id = v_id
  returning *;
end;
$$;


ALTER FUNCTION public.claim_packet_render_job(p_worker_id text, p_renderer_kinds text[]) OWNER TO postgres;

--
-- Name: FUNCTION claim_packet_render_job(p_worker_id text, p_renderer_kinds text[]); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.claim_packet_render_job(p_worker_id text, p_renderer_kinds text[]) IS 'Atomically claims one queued job for a worker. SKIP LOCKED: parallel workers never claim the same job.';


--
-- Name: claim_packet_render_job(text, text[], integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_packet_render_job(p_worker_id text, p_renderer_kinds text[], p_claim_seconds integer DEFAULT 600) RETURNS TABLE(id uuid, packet_id uuid, route_id text, renderer_kind text, renderer_version text, source_sha256 text, profile_id text, profile_version text, input_hash text, attempt_count integer, max_attempts integer, partner_id uuid, person_id uuid, matter_id uuid, fencing_token uuid, claim_expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_worker_id text;
  v_job_id uuid;
  v_token uuid;
begin
  v_worker_id := nullif(trim(p_worker_id), '');
  if v_worker_id is null then
    raise exception 'a worker id is required to claim a job';
  end if;
  if p_claim_seconds is null or p_claim_seconds < 30 or p_claim_seconds > 3600 then
    raise exception 'claim seconds must be between 30 and 3600';
  end if;

  select j.id into v_job_id
  from public.packet_render_jobs j
  where j.status = 'queued'
    and (j.next_attempt_at is null or j.next_attempt_at <= now())
    and (p_renderer_kinds is null or j.renderer_kind = any (p_renderer_kinds))
  order by j.created_at
  for update skip locked
  limit 1;

  if v_job_id is null then
    return;
  end if;

  v_token := gen_random_uuid();
  perform set_config('rcap.packet_mutation_authority', 'claim_packet_render_job', true);
  return query
  update public.packet_render_jobs j
  set status = 'claimed',
      claimed_by = v_worker_id,
      claim_expires_at = now() + make_interval(secs => p_claim_seconds),
      fencing_token = v_token,
      attempt_count = j.attempt_count + 1
  where j.id = v_job_id
  returning j.id, j.packet_id, j.route_id, j.renderer_kind, j.renderer_version,
            j.source_sha256, j.profile_id, j.profile_version, j.input_hash,
            j.attempt_count, j.max_attempts, j.partner_id, j.person_id, j.matter_id,
            j.fencing_token, j.claim_expires_at;
  perform set_config('rcap.packet_mutation_authority', '', true);
end;
$$;


ALTER FUNCTION public.claim_packet_render_job(p_worker_id text, p_renderer_kinds text[], p_claim_seconds integer) OWNER TO postgres;

--
-- Name: claim_partner_screening_session(text, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_partner_screening_session(p_partner_slug text, p_jurisdiction text, p_code_hash text DEFAULT NULL::text, p_now timestamp with time zone DEFAULT now()) RETURNS TABLE(ok boolean, session_id uuid, reason text, benefit_active boolean, attribution_source text, campaign_name text, access_mode text, code_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_partner_slug text;
  v_jurisdiction text;
  v_code_hash text;
  v_access_mode text;
  v_session_id uuid;
  v_code_id uuid;
  v_code_campaign text;
  v_code_valid boolean := false;
  v_code_reason text;
  v_code_type text;
  v_effective_max integer;
  v_rows integer;
  v_benefit boolean := false;
  v_source text;
  v_reason text;
begin
  v_partner_slug := nullif(trim(p_partner_slug), '');
  v_jurisdiction := upper(nullif(trim(p_jurisdiction), ''));
  v_code_hash := nullif(trim(p_code_hash), '');

  if v_jurisdiction is null or v_jurisdiction !~ '^[A-Z]{2,3}$' then
    raise exception 'jurisdiction must be a 2-3 letter uppercase code';
  end if;

  if v_partner_slug is null then
    return query select false, null::uuid, 'partner_inactive'::text, false, null::text, null::text, null::text, null::uuid;
    return;
  end if;

  perform 1 from public.partner_onboarding where partner_slug=v_partner_slug for update;
  if v_jurisdiction<>all(public.rcap_program_screening_jurisdictions(v_partner_slug)) then
    return query select false, null::uuid, 'jurisdiction_not_authorized'::text, false, null::text, null::text, null::text, null::uuid;
    return;
  end if;
  -- Partner must be active to grant any partner benefit.
  if not exists (
    select 1 from public.partner_records pr
    where pr.partner_slug = v_partner_slug
      and public.rcap_partner_activation_for_launch(pr.partner_slug)
      and ((pr.qualification_status = 'qualified' and pr.provisioning_status in ('provisioned', 'active')) or exists(select 1 from public.partner_onboarding where partner_slug=v_partner_slug and operating_model='legalease_managed' and public.rcap_program_internal_authority(id) is not null))
  ) then
    return query select false, null::uuid, 'partner_inactive'::text, false, null::text, null::text, null::text, null::uuid;
    return;
  end if;

  select pr.access_mode into v_access_mode
  from public.partner_records pr
  where pr.partner_slug = v_partner_slug;
  if exists(select 1 from public.partner_onboarding where partner_slug=v_partner_slug and operating_model='legalease_managed') then
    select public.rcap_program_policy_source(id)#>>'{access_sponsorship_capacity,participant_access_model}' into v_access_mode from public.partner_onboarding where partner_slug=v_partner_slug;
  end if;
  v_access_mode := coalesce(v_access_mode, 'open');

  -- Legacy allocation prerequisites remain intact. Internal screening grants no packet allocation.
  if not exists (
    select 1 from public.partner_entitlement pe where pe.partner_slug = v_partner_slug
  ) and not exists(select 1 from public.partner_onboarding where partner_slug=v_partner_slug and operating_model='legalease_managed') then
    return query select false, null::uuid, 'partner_inactive'::text, false, null::text, null::text, v_access_mode, null::uuid;
    return;
  end if;

  -- Resolve the code (validation only; redemption happens atomically below).
  if v_code_hash is not null then
    select v.valid, v.reason, v.campaign_name, v.code_id, v.code_type
    into v_code_valid, v_code_reason, v_code_campaign, v_code_id, v_code_type
    from public.validate_partner_access_code(v_partner_slug, v_code_hash, p_now) v;
  end if;

  -- Decide benefit + attribution source per access mode.
  if v_access_mode = 'open' then
    v_benefit := true;
    if v_code_valid then
      v_source := 'partner_code';
    else
      v_source := 'partner_page';
      v_code_id := null;
      v_code_campaign := null;
    end if;
  elsif v_access_mode = 'optional_code' then
    if v_code_hash is not null and not v_code_valid then
      -- A code was entered but is not valid: surface the error, do not attribute.
      return query select false, null::uuid, coalesce(v_code_reason, 'invalid')::text, false, null::text, null::text, v_access_mode, null::uuid;
      return;
    end if;
    v_benefit := true;
    if v_code_valid then
      v_source := 'partner_code';
    else
      v_source := 'partner_page';
      v_code_id := null;
      v_code_campaign := null;
    end if;
  else
    -- required_code and invite_only: a valid code is mandatory for partner benefit.
    if not v_code_valid then
      return query select false, null::uuid, coalesce(v_code_reason, 'code_required')::text, false, null::text, null::text, v_access_mode, null::uuid;
      return;
    end if;
    v_benefit := true;
    v_source := 'partner_code';
  end if;

  -- Atomically redeem a limited/single-use code as part of the claim.
  if v_benefit and v_source = 'partner_code' and v_code_id is not null then
    v_effective_max := case
      when v_code_type = 'single_use' then 1
      when v_code_type = 'limited_use' then (select c.max_uses from public.partner_access_codes c where c.id = v_code_id)
      else null
    end;

    update public.partner_access_codes c
    set uses_count = c.uses_count + 1,
        last_used_at = p_now,
        updated_at = now()
    where c.id = v_code_id
      and (v_effective_max is null or c.uses_count < v_effective_max);

    get diagnostics v_rows = row_count;

    if v_rows = 0 then
      -- Lost a race for the last remaining use.
      return query select false, null::uuid, 'exhausted'::text, false, null::text, null::text, v_access_mode, null::uuid;
      return;
    end if;
  end if;

  -- Create the attributed session.
  v_session_id := gen_random_uuid();
  insert into public.screening_sessions (
    session_id, jurisdiction, answers, current_question_id, furthest_stage,
    status, last_drop_question, partner_slug, flow_mode, claimed_slot_state,
    partner_access_code_id, campaign_name, attribution_source, partner_benefit_active
  )
  values (
    v_session_id, v_jurisdiction, '{}'::jsonb, null, null,
    'in_progress', null, v_partner_slug, 'rcap', 'claimed',
    v_code_id, v_code_campaign, v_source, true
  );

  -- Audit.
  if v_code_id is not null then
    insert into public.rcap_record_events (record_type, record_id, partner_slug, event_type, occurred_at, actor, metadata)
    values ('partner_access_code', v_code_id::text, v_partner_slug, 'partner_code_used', p_now, 'system',
            jsonb_build_object('session_id', v_session_id, 'campaign_name', v_code_campaign));
  end if;

  return query select true, v_session_id, null::text, v_benefit, v_source, v_code_campaign, v_access_mode, v_code_id;
end;
$_$;


ALTER FUNCTION public.claim_partner_screening_session(p_partner_slug text, p_jurisdiction text, p_code_hash text, p_now timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION claim_partner_screening_session(p_partner_slug text, p_jurisdiction text, p_code_hash text, p_now timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.claim_partner_screening_session(p_partner_slug text, p_jurisdiction text, p_code_hash text, p_now timestamp with time zone) IS 'Resolves partner attribution from access_mode, atomically redeems a code when required, and creates an attributed screening session. Does not consume packet allocation.';


--
-- Name: claim_pending_screening_result(text, uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_pending_screening_result(p_claim_token text, p_user_id uuid, p_matter jsonb, p_request_id text DEFAULT NULL::text) RETURNS TABLE(matter_id uuid, outcome text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_pending public.consumer_pending_screening_results%rowtype;
  v_hash text;
  v_matter_id uuid;
  v_owner uuid;
  v_pending_id uuid;
begin
  -- 1. Require an authenticated participant. The caller proves the session; this
  --    function refuses to act without a user id under any circumstance.
  if p_user_id is null then
    raise exception 'claim_requires_authenticated_participant' using errcode = '28000';
  end if;

  if p_claim_token is null or p_claim_token !~ '^[A-Za-z0-9_-]{32,200}$' then
    insert into public.participant_claim_events (event, actor_user_id, request_id)
      values ('claim_denied_invalid_token', p_user_id, p_request_id);
    return query select null::uuid, 'denied_invalid_token'::text;
    return;
  end if;

  -- 2. Resolve and lock the pending result by the hash of the presented token.
  --    Every later check reads a row no other claimant can move underneath it.
  v_hash := encode(sha256(convert_to(p_claim_token, 'utf8')), 'hex');

  select * into v_pending
    from public.consumer_pending_screening_results
   where claim_token_hash = v_hash
     for update;

  if not found then
    -- A wrong token and an unknown pending result are the same answer on
    -- purpose: neither tells the caller whether a result exists.
    insert into public.participant_claim_events (event, actor_user_id, request_id)
      values ('claim_denied_invalid_token', p_user_id, p_request_id);
    return query select null::uuid, 'denied_invalid_token'::text;
    return;
  end if;

  v_pending_id := v_pending.pending_id;

  if v_pending.status = 'REVOKED' then
    insert into public.participant_claim_events
      (event, pending_result_id, actor_user_id, product, jurisdiction, partner_slug, event_id, request_id)
      values ('claim_denied_revoked', v_pending_id, p_user_id, v_pending.product,
              v_pending.jurisdiction, v_pending.partner_slug, v_pending.event_id, p_request_id);
    return query select null::uuid, 'denied_revoked'::text;
    return;
  end if;

  -- 4. Existing claim state, checked before expiry on purpose. Once a pending
  --    result is claimed the matter is durable and the claim window governs
  --    claiming, not owning: an owner who returns after 24 hours must land on
  --    their matter, not be told the result expired.
  if v_pending.status = 'CLAIMED' then
    if v_pending.claimed_user_id = p_user_id then
      insert into public.participant_claim_events
        (event, pending_result_id, matter_id, actor_user_id, product, jurisdiction, partner_slug, event_id, request_id)
        values ('claim_idempotent_replay', v_pending_id, v_pending.claimed_matter_id, p_user_id,
                v_pending.product, v_pending.jurisdiction, v_pending.partner_slug, v_pending.event_id, p_request_id);
      return query select v_pending.claimed_matter_id, 'idempotent_replay'::text;
      return;
    end if;

    insert into public.participant_claim_events
      (event, pending_result_id, actor_user_id, product, jurisdiction, partner_slug, event_id, request_id)
      values ('claim_denied_other_user', v_pending_id, p_user_id, v_pending.product,
              v_pending.jurisdiction, v_pending.partner_slug, v_pending.event_id, p_request_id);
    return query select null::uuid, 'denied_other_user'::text;
    return;
  end if;

  -- 5. Expiration.
  if v_pending.expires_at <= now() or v_pending.status = 'EXPIRED' then
    update public.consumer_pending_screening_results
       set status = 'EXPIRED'
     where pending_id = v_pending_id
       and status = 'PENDING';
    insert into public.participant_claim_events
      (event, pending_result_id, actor_user_id, product, jurisdiction, partner_slug, event_id, request_id)
      values ('claim_denied_expired', v_pending_id, p_user_id, v_pending.product,
              v_pending.jurisdiction, v_pending.partner_slug, v_pending.event_id, p_request_id);
    return query select null::uuid, 'denied_expired'::text;
    return;
  end if;

  -- 6. Product and channel. A partner-attributed pending result may not be
  --    claimed through the consumer channel and the reverse, because the
  --    entitlement posture of the resulting matter differs.
  if coalesce(p_matter ->> 'product', v_pending.product) is distinct from v_pending.product then
    insert into public.participant_claim_events
      (event, pending_result_id, actor_user_id, product, jurisdiction, partner_slug, event_id, request_id)
      values ('claim_denied_product_mismatch', v_pending_id, p_user_id, v_pending.product,
              v_pending.jurisdiction, v_pending.partner_slug, v_pending.event_id, p_request_id);
    return query select null::uuid, 'denied_product_mismatch'::text;
    return;
  end if;

  -- 7. Create exactly one participant-owned matter, keyed by the pending result.
  --    ON CONFLICT DO NOTHING closes any race that slipped the row lock: the
  --    loser reads the winner's matter instead of creating a second one.
  insert into public.consumer_briefcase_items (
    user_id,
    item_type,
    jurisdiction,
    pathway_label,
    result_code,
    packet_type,
    payment_allowed,
    status,
    summary_json,
    next_steps_json,
    artifact_refs_json,
    payment_status,
    amount_cents,
    packet_status,
    reminder_at,
    source_session_id,
    source_pending_result_id
  )
  values (
    p_user_id,
    coalesce(p_matter ->> 'item_type', 'result'),
    p_matter ->> 'jurisdiction',
    nullif(p_matter ->> 'pathway_label', ''),
    nullif(p_matter ->> 'result_code', ''),
    nullif(p_matter ->> 'packet_type', ''),
    coalesce((p_matter ->> 'payment_allowed')::boolean, false),
    p_matter ->> 'status',
    coalesce(p_matter -> 'summary_json', '{}'::jsonb),
    coalesce(p_matter -> 'next_steps_json', '[]'::jsonb),
    coalesce(p_matter -> 'artifact_refs_json', '{}'::jsonb),
    coalesce(p_matter ->> 'payment_status', 'not_applicable'),
    (p_matter ->> 'amount_cents')::integer,
    coalesce(p_matter ->> 'packet_status', 'not_started'),
    (p_matter ->> 'reminder_at')::timestamptz,
    nullif(p_matter ->> 'source_session_id', ''),
    v_pending_id
  )
  on conflict (source_pending_result_id) do nothing
  returning id into v_matter_id;

  if v_matter_id is null then
    select id, user_id into v_matter_id, v_owner
      from public.consumer_briefcase_items
     where source_pending_result_id = v_pending_id;

    if v_matter_id is null then
      raise exception 'claim_matter_persistence_failed' using errcode = 'XX000';
    end if;

    if v_owner is distinct from p_user_id then
      insert into public.participant_claim_events
        (event, pending_result_id, actor_user_id, product, jurisdiction, partner_slug, event_id, request_id)
        values ('claim_denied_other_user', v_pending_id, p_user_id, v_pending.product,
                v_pending.jurisdiction, v_pending.partner_slug, v_pending.event_id, p_request_id);
      return query select null::uuid, 'denied_other_user'::text;
      return;
    end if;
  end if;

  -- 8-9. Mark the pending result claimed. The claim-shape constraint means this
  --      update and the matter above stand or fall together: there is no state
  --      in which a matter exists and the pending result is not claimed.
  update public.consumer_pending_screening_results
     set status = 'CLAIMED',
         claimed_at = now(),
         claimed_user_id = p_user_id,
         claimed_matter_id = v_matter_id
   where pending_id = v_pending_id;

  -- 10. Append-only audit.
  insert into public.participant_claim_events
    (event, pending_result_id, matter_id, actor_user_id, product, jurisdiction, partner_slug, event_id, request_id)
    values ('claim_succeeded', v_pending_id, v_matter_id, p_user_id, v_pending.product,
            v_pending.jurisdiction, v_pending.partner_slug, v_pending.event_id, p_request_id);

  return query select v_matter_id, 'claimed'::text;
end
$_$;


ALTER FUNCTION public.claim_pending_screening_result(p_claim_token text, p_user_id uuid, p_matter jsonb, p_request_id text) OWNER TO postgres;

--
-- Name: FUNCTION claim_pending_screening_result(p_claim_token text, p_user_id uuid, p_matter jsonb, p_request_id text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.claim_pending_screening_result(p_claim_token text, p_user_id uuid, p_matter jsonb, p_request_id text) IS 'The one atomic claim transaction shared by Expungement.ai and RCAP. Locks the pending result, verifies the single-use claim token, creates exactly one participant-owned matter keyed by source_pending_result_id, marks the pending result claimed and writes an append-only audit event. Denials return an outcome so their audit row survives.';


--
-- Name: claim_rcap_screening_session(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_rcap_screening_session(p_partner_slug text, p_jurisdiction text) RETURNS TABLE(ok boolean, session_id uuid, reason text, screenings_used integer, screenings_allowed integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
 begin return query select * from public.claim_rcap_screening_session(p_partner_slug,p_jurisdiction,null::text);end $$;


ALTER FUNCTION public.claim_rcap_screening_session(p_partner_slug text, p_jurisdiction text) OWNER TO postgres;

--
-- Name: FUNCTION claim_rcap_screening_session(p_partner_slug text, p_jurisdiction text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.claim_rcap_screening_session(p_partner_slug text, p_jurisdiction text) IS 'Validates an active RCAP partner and creates an attributed screening session without consuming partner packet capacity.';


--
-- Name: claim_rcap_screening_session(text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_rcap_screening_session(p_partner_slug text, p_jurisdiction text, p_clinic_redemption text) RETURNS TABLE(ok boolean, session_id uuid, reason text, screenings_used integer, screenings_allowed integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_partner_slug text;
  v_jurisdiction text;
  v_session_id uuid;
  v_screenings_used integer;
  v_screenings_allowed integer;
begin
  v_partner_slug := nullif(trim(p_partner_slug), '');
  v_jurisdiction := upper(nullif(trim(p_jurisdiction), ''));

  if v_partner_slug is null then
    return query select false, null::uuid, 'partner_inactive'::text, null::integer, null::integer;
    return;
  end if;

  if v_jurisdiction is null or v_jurisdiction !~ '^[A-Z]{2,3}$' then
    raise exception 'jurisdiction must be a 2-3 letter uppercase code';
  end if;

  perform 1 from public.partner_onboarding where partner_slug=v_partner_slug for update;
  if v_jurisdiction<>all(public.rcap_program_screening_jurisdictions(v_partner_slug)) then
    return query select false, null::uuid, 'jurisdiction_not_authorized'::text, null::integer, null::integer;
    return;
  end if;
  if p_clinic_redemption is not null and not exists(
    select 1 from public.clinic_event_access_redemptions d join public.clinic_events e on e.id=d.event_id
    where d.redemption_nonce_hash=p_clinic_redemption and d.redeemed_at>now()-interval '8 hours'
    and e.partner_slug=v_partner_slug and e.jurisdiction=v_jurisdiction and e.status='published'
  ) then return query select false,null::uuid,'clinic_entry_required'::text,null::integer,null::integer;return;end if;
  if not exists (
    select 1
    from public.partner_records pr
    where pr.partner_slug = v_partner_slug
      and public.rcap_partner_activation_for_launch(pr.partner_slug)
      and ((pr.qualification_status = 'qualified' and pr.provisioning_status in ('provisioned', 'active')) or exists(select 1 from public.partner_onboarding where partner_slug=v_partner_slug and operating_model='legalease_managed' and public.rcap_program_internal_authority(id) is not null))
  ) then
    return query select false, null::uuid, 'partner_inactive'::text, null::integer, null::integer;
    return;
  end if;

  select pe.screenings_used, pe.screenings_allowed
  into v_screenings_used, v_screenings_allowed
  from public.partner_entitlement pe
  where pe.partner_slug = v_partner_slug;

  if v_screenings_allowed is null and not exists(select 1 from public.partner_onboarding where partner_slug=v_partner_slug and operating_model='legalease_managed') then
    return query select false, null::uuid, 'partner_inactive'::text, null::integer, null::integer;
    return;
  end if;

  if p_clinic_redemption is null and coalesce((select case when w.operating_model='legalease_managed' then public.rcap_program_policy_source(w.id)#>>'{access_sponsorship_capacity,participant_access_model}' else r.access_mode end from public.partner_records r left join public.partner_onboarding w on w.partner_slug=r.partner_slug where r.partner_slug=v_partner_slug),'open') in ('required_code','invite_only') then
    return query select false,null::uuid,'code_required'::text,null::integer,null::integer;return;
  end if;
  v_session_id := gen_random_uuid();

  insert into public.screening_sessions (
    session_id, jurisdiction, answers, current_question_id, furthest_stage,
    status, last_drop_question, partner_slug, flow_mode, claimed_slot_state,
    attribution_source, partner_benefit_active
  )
  values (
    v_session_id, v_jurisdiction, '{}'::jsonb, null, null,
    'in_progress', null, v_partner_slug, 'rcap', 'claimed',
    'partner_page', true
  );

  return query
  select true, v_session_id, null::text, v_screenings_used, v_screenings_allowed;
end;
$_$;


ALTER FUNCTION public.claim_rcap_screening_session(p_partner_slug text, p_jurisdiction text, p_clinic_redemption text) OWNER TO postgres;

--
-- Name: clinic_actor_can_event(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.clinic_actor_can_event(p_event_id uuid, p_actor_user_id uuid, p_permission text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1 from public.clinic_events e
    join public.partner_users pu on pu.auth_user_id=p_actor_user_id and pu.status='active'
    where e.id=p_event_id and (
      (pu.role='internal_admin' and pu.partner_slug is null)
      or (pu.role='partner_admin' and pu.partner_slug=e.partner_slug)
    )
  ) or exists (
    select 1 from public.clinic_event_staff s
    join public.partner_users pu on pu.id=s.partner_user_id and pu.status='active'
    join public.clinic_events e on e.id=s.event_id and e.partner_slug=pu.partner_slug
    where s.event_id=p_event_id and s.status='approved'
      and pu.auth_user_id=p_actor_user_id and p_permission=any(s.permissions)
  )
$$;


ALTER FUNCTION public.clinic_actor_can_event(p_event_id uuid, p_actor_user_id uuid, p_permission text) OWNER TO postgres;

