    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select public.clinic_is_internal_admin()
    or exists (
      select 1 from public.clinic_events ce
      where ce.id = p_event_id and ce.partner_slug = public.clinic_current_partner_slug()
    )
$$;


ALTER FUNCTION public.clinic_can_read_event(p_event_id uuid) OWNER TO postgres;

--
-- Name: clinic_create_access_code(uuid, uuid, text, text, integer, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.clinic_create_access_code(p_actor_user_id uuid, p_event_id uuid, p_code_hash text, p_code_hint text, p_max_uses integer, p_starts_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_partner_slug text; v_id uuid;
begin
  select partner_slug into v_partner_slug from public.clinic_events where id = p_event_id;
  if not exists (
    select 1 from public.partner_users pu where pu.auth_user_id = p_actor_user_id
      and pu.status = 'active' and ((pu.role = 'internal_admin' and pu.partner_slug is null)
        or (pu.role = 'partner_admin' and pu.partner_slug = v_partner_slug))
  ) then raise exception 'clinic_code_forbidden'; end if;
  insert into public.clinic_event_access_codes(event_id, code_hash, code_hint, max_uses, starts_at, expires_at, created_by)
  values (p_event_id, lower(p_code_hash), p_code_hint, p_max_uses, p_starts_at, p_expires_at, p_actor_user_id)
  returning id into v_id;
  insert into public.clinic_event_audit(event_id, actor_user_id, action, target_type, target_id)
  values (p_event_id, p_actor_user_id, 'access_code_created', 'access_code', v_id);
  return v_id;
end $$;


ALTER FUNCTION public.clinic_create_access_code(p_actor_user_id uuid, p_event_id uuid, p_code_hash text, p_code_hint text, p_max_uses integer, p_starts_at timestamp with time zone, p_expires_at timestamp with time zone) OWNER TO postgres;

--
-- Name: clinic_create_event(uuid, text, text, text, timestamp with time zone, timestamp with time zone, text, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.clinic_create_event(p_actor_user_id uuid, p_partner_slug text, p_public_slug text, p_name text, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_timezone text, p_location_name text, p_geography text, p_capacity integer, p_sponsorship_allocation integer DEFAULT NULL::integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_id uuid;
begin
  if exists(select 1 from public.partner_onboarding where partner_slug=p_partner_slug and rcap_policy_version='rcap2.2') then
    return public.clinic_create_event(p_actor_user_id,p_partner_slug,p_public_slug,p_name,p_starts_at,p_ends_at,p_timezone,p_location_name,p_geography,p_capacity,p_sponsorship_allocation,public.rcap_program_clinic_scope(p_partner_slug,p_actor_user_id,'create_clinic',null,p_sponsorship_allocation));
  end if;
  if not exists (
    select 1 from public.partner_users pu where pu.auth_user_id = p_actor_user_id
      and pu.status = 'active'
      and ((pu.role = 'internal_admin' and pu.partner_slug is null)
        or (pu.role = 'partner_admin' and pu.partner_slug = p_partner_slug))
  ) then raise exception 'clinic_event_forbidden'; end if;
  insert into public.clinic_events(
    partner_slug, public_slug, name, starts_at, ends_at, timezone,
    location_name, geography, capacity, sponsorship_allocation, created_by
  ) values (
    p_partner_slug, lower(trim(p_public_slug)), trim(p_name), p_starts_at, p_ends_at,
    trim(p_timezone), trim(p_location_name), trim(p_geography), p_capacity,
    p_sponsorship_allocation, p_actor_user_id
  ) returning id into v_id;
  insert into public.clinic_event_audit(event_id, actor_user_id, action, target_type, target_id)
  values (v_id, p_actor_user_id, 'event_created', 'event', v_id);
  return v_id;
end $$;


ALTER FUNCTION public.clinic_create_event(p_actor_user_id uuid, p_partner_slug text, p_public_slug text, p_name text, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_timezone text, p_location_name text, p_geography text, p_capacity integer, p_sponsorship_allocation integer) OWNER TO postgres;

--
-- Name: clinic_create_event(uuid, text, text, text, timestamp with time zone, timestamp with time zone, text, text, text, integer, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.clinic_create_event(p_actor_user_id uuid, p_partner_slug text, p_public_slug text, p_name text, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_timezone text, p_location_name text, p_geography text, p_capacity integer, p_sponsorship_allocation integer, p_jurisdiction text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_id uuid;
begin
  if exists(select 1 from public.partner_onboarding where partner_slug=p_partner_slug and rcap_policy_version='rcap2.2') then
    p_jurisdiction:=public.rcap_program_clinic_scope(p_partner_slug,p_actor_user_id,'create_clinic',p_jurisdiction,p_sponsorship_allocation);
    select response_data->>'service_area_description' into p_geography from public.partner_onboarding_sections s join public.partner_onboarding w on w.id=s.workspace_id where w.partner_slug=p_partner_slug and s.section_key='geography_audience_language_accessibility';
  end if;
  if p_jurisdiction is not null and (p_jurisdiction <> upper(p_jurisdiction) or length(p_jurisdiction) not between 2 and 3) then
    raise exception 'clinic_event_jurisdiction_invalid';
  end if;
  if not exists (
    select 1 from public.partner_users pu where pu.auth_user_id = p_actor_user_id
      and pu.status = 'active'
      and ((pu.role = 'internal_admin' and pu.partner_slug is null)
        or (pu.role = 'partner_admin' and pu.partner_slug = p_partner_slug))
  ) then raise exception 'clinic_event_forbidden'; end if;
  insert into public.clinic_events(
    partner_slug, public_slug, name, starts_at, ends_at, timezone,
    location_name, geography, jurisdiction, capacity, sponsorship_allocation, created_by
  ) values (
    p_partner_slug, lower(trim(p_public_slug)), trim(p_name), p_starts_at, p_ends_at,
    trim(p_timezone), trim(p_location_name), trim(p_geography), p_jurisdiction,
    p_capacity, p_sponsorship_allocation, p_actor_user_id
  ) returning id into v_id;
  insert into public.clinic_event_audit(event_id, actor_user_id, action, target_type, target_id)
  values (v_id, p_actor_user_id, 'event_created', 'event', v_id);
  return v_id;
end $$;


