--
-- Name: clinic_end_assisted_session(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.clinic_end_assisted_session(p_session_id uuid, p_actor_user_id uuid, p_reason text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_session public.clinic_assisted_sessions%rowtype;
begin
  select * into v_session from public.clinic_assisted_sessions where id=p_session_id for update;
  if not found then return 'not_found'; end if;
  if v_session.status in ('ended','expired','reset') then return 'already_ended'; end if;
  if p_reason not in ('participant_handoff','participant_request','staff_reset','inactivity','event_closed','security_reset')
    then return 'invalid_reason'; end if;
  if p_actor_user_id <> v_session.participant_user_id and not exists (
    select 1 from public.clinic_event_staff s
    join public.partner_users pu on pu.id=s.partner_user_id
    join public.clinic_events e on e.id=s.event_id
    where s.event_id=v_session.event_id and s.status='approved' and 'assist'=any(s.permissions)
      and pu.auth_user_id=p_actor_user_id and pu.status='active' and pu.partner_slug=e.partner_slug
  ) then return 'forbidden'; end if;
  update public.clinic_assisted_sessions
  set status=case when p_reason in ('staff_reset','security_reset') then 'reset' else 'ended' end,
    ended_at=now(), ended_reason=p_reason
  where id=p_session_id;
  insert into public.clinic_event_audit(event_id,actor_user_id,action,target_type,target_id,metadata)
  values(v_session.event_id,p_actor_user_id,'assisted_session_ended','assisted_session',p_session_id,jsonb_build_object('reason',p_reason));
  return 'ended';
end $$;


ALTER FUNCTION public.clinic_end_assisted_session(p_session_id uuid, p_actor_user_id uuid, p_reason text) OWNER TO postgres;

--
-- Name: clinic_entry_sponsor_capacity(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.clinic_entry_sponsor_capacity(p_event uuid, p_partner text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare e public.clinic_events%rowtype; allowance public.partner_entitlement%rowtype;
  event_used bigint; reserved bigint; packet_allowance public.partner_packet_entitlement%rowtype; packet_used bigint;
begin
  select * into e from public.clinic_events where id=p_event and partner_slug=p_partner and status='published';
  if not found then raise exception 'invalid_event_scope'; end if;
  select * into allowance from public.partner_entitlement where partner_slug=e.partner_slug;
  if not found then raise exception 'missing_sponsor_authority'; end if;
  select count(*) into event_used from (
    select f.briefcase_item_id from public.clinic_packet_funding f where f.event_id=e.id and f.funding_mode='sponsored'
    union select p.briefcase_item_id from public.consumer_packet_artifact_provenance p
      join public.clinic_cases c on c.matter_id=p.briefcase_item_id where c.event_id=e.id and p.entitlement_source='partner_sponsorship'
  ) used;
  select count(*) into reserved from public.clinic_packet_funding f where f.partner_slug=e.partner_slug and f.funding_mode='sponsored'
    and not exists(select 1 from public.consumer_packet_artifact_provenance p where p.briefcase_item_id=f.briefcase_item_id and p.entitlement_source='partner_sponsorship');
  select ent.* into packet_allowance from public.partner_packet_entitlement ent join public.partner_records p on p.id=ent.partner_id
    where p.partner_slug=e.partner_slug and ent.effective_at<=now() and (ent.expires_at is null or ent.expires_at>now())
    order by ent.effective_at desc limit 1;
  if not found then raise exception 'missing_sponsor_authority'; end if;
  select count(*) into packet_used from (
    select l.matter_id from public.packet_credit_ledger l where l.entitlement_id=packet_allowance.id and l.event_type in ('consumed','overage_consumed')
    union select public.consumer_matter_id_for_briefcase_item(f.briefcase_item_id) from public.clinic_packet_funding f where f.packet_entitlement_id=packet_allowance.id and f.funding_mode='sponsored'
  ) used;
  return event_used<e.sponsorship_allocation and allowance.screenings_used+reserved<allowance.screenings_allowed and packet_used<packet_allowance.packet_cap;
end;
$$;


ALTER FUNCTION public.clinic_entry_sponsor_capacity(p_event uuid, p_partner text) OWNER TO postgres;

--
-- Name: clinic_finalize_packet_credit(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.clinic_finalize_packet_credit(p_render_job_id uuid) RETURNS TABLE(outcome text, reservation_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_res public.clinic_packet_reservations%rowtype; v_job public.packet_render_jobs%rowtype;
begin
  select * into v_res from public.clinic_packet_reservations where render_job_id=p_render_job_id for update;
  if not found then return query select 'reservation_not_found'::text,null::uuid; return; end if;
  if v_res.status='consumed' then return query select 'already_consumed'::text,v_res.id; return; end if;
  if v_res.status='released' then return query select 'reservation_released'::text,v_res.id; return; end if;
  select * into v_job from public.packet_render_jobs where id=p_render_job_id for update;
  if v_job.status not in ('artifact_validated','delivered') then return query select 'artifact_not_validated'::text,v_res.id; return; end if;
  if v_job.accounting_result not in ('consumed','already_consumed','overage_consumed') or v_job.credit_ledger_id is null
    then return query select 'accounting_blocked'::text,v_res.id; return; end if;
  update public.clinic_packet_reservations set status='consumed',packet_credit_ledger_id=v_job.credit_ledger_id,consumed_at=now()
    where id=v_res.id;
  insert into public.clinic_event_audit(event_id,action,target_type,target_id,metadata)
  values(v_res.event_id,'packet_credit_consumed','packet_reservation',v_res.id,jsonb_build_object('ledger_id',v_job.credit_ledger_id));
  return query select 'consumed'::text,v_res.id;
end $$;


ALTER FUNCTION public.clinic_finalize_packet_credit(p_render_job_id uuid) OWNER TO postgres;

--
-- Name: clinic_get_event_queue(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.clinic_get_event_queue(p_event_id uuid, p_actor_user_id uuid) RETURNS TABLE(id uuid, event_id uuid, participant_user_id uuid, queue_status text, route_disposition text, jurisdiction text, court_identity_verified boolean, county_name text, court_name text, follow_up_due_at timestamp with time zone, last_activity_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_privileged boolean;
begin
  if not public.clinic_actor_can_event(p_event_id,p_actor_user_id,'queue')
    then raise exception 'clinic_queue_forbidden'; end if;
  select exists(
    select 1 from public.clinic_events e join public.partner_users pu on pu.auth_user_id=p_actor_user_id and pu.status='active'
    where e.id=p_event_id and ((pu.role='internal_admin' and pu.partner_slug is null) or (pu.role='partner_admin' and pu.partner_slug=e.partner_slug))
  ) into v_privileged;
  return query
  select c.id,c.event_id,c.participant_user_id,c.queue_status,c.route_disposition,
    c.jurisdiction,c.court_identity_verified,c.county_name,c.court_name,
    c.follow_up_due_at,c.last_activity_at
  from public.clinic_cases c
  where c.event_id=p_event_id and (
    v_privileged or exists(
      select 1 from public.clinic_assisted_sessions s
      where s.id=c.assisted_session_id and s.event_id=c.event_id
        and s.status in ('active','handed_off') and s.expires_at>now()
    )
  )
  order by c.last_activity_at desc;
end $$;


ALTER FUNCTION public.clinic_get_event_queue(p_event_id uuid, p_actor_user_id uuid) OWNER TO postgres;

--
-- Name: clinic_get_event_report(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.clinic_get_event_report(p_event_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_report jsonb;
begin
  if not public.clinic_actor_can_event(p_event_id,p_actor_user_id,'reporting')
    then raise exception 'clinic_reporting_forbidden'; end if;
  select jsonb_build_object(
    'eventId',e.id,
    'eventName',e.name,
    'eventStatus',e.status,
    'capacity',e.capacity,
    'entries',(select count(*) from public.clinic_event_access_redemptions r where r.event_id=e.id),
    'participants',(select count(*) from public.clinic_cases c where c.event_id=e.id),
    'queueCounts',coalesce((
      select jsonb_object_agg(q.queue_status,q.total)
      from (select c.queue_status,count(*) as total from public.clinic_cases c where c.event_id=e.id group by c.queue_status) q
    ),'{}'::jsonb),
    'routeCounts',coalesce((
      select jsonb_object_agg(r.route_disposition,r.total)
      from (select c.route_disposition,count(*) as total from public.clinic_cases c where c.event_id=e.id group by c.route_disposition) r
    ),'{}'::jsonb),
    'followUpCounts',coalesce((
      select jsonb_object_agg(f.status,f.total)
      from (select u.status,count(*) as total from public.clinic_follow_ups u where u.event_id=e.id group by u.status) f
    ),'{}'::jsonb),
    'sponsorship',jsonb_build_object(
      'allocation',e.sponsorship_allocation,
      'reserved',(select count(*) from public.clinic_packet_reservations p where p.event_id=e.id and p.status='reserved'),
      'consumed',(select count(*) from public.clinic_packet_reservations p where p.event_id=e.id and p.status='consumed'),
      'released',(select count(*) from public.clinic_packet_reservations p where p.event_id=e.id and p.status='released')
    ),
    'incidents',jsonb_build_object(
      'open',(select count(*) from public.clinic_incidents i where i.event_id=e.id and i.status in ('open','investigating')),
      'resolved',(select count(*) from public.clinic_incidents i where i.event_id=e.id and i.status in ('resolved','closed'))
    )
  ) into v_report
  from public.clinic_events e where e.id=p_event_id;
  if v_report is null then raise exception 'clinic_event_not_found'; end if;
  return v_report;
end $$;


ALTER FUNCTION public.clinic_get_event_report(p_event_id uuid, p_actor_user_id uuid) OWNER TO postgres;

--
-- Name: clinic_get_follow_ups(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.clinic_get_follow_ups(p_event_id uuid, p_actor_user_id uuid) RETURNS TABLE(id uuid, clinic_case_id uuid, owner_event_staff_id uuid, jurisdiction text, due_at timestamp with time zone, status text, communication_state text, participant_safe_message text, internal_notes text, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not public.clinic_actor_can_event(p_event_id,p_actor_user_id,'follow_up')
    then raise exception 'clinic_follow_up_forbidden'; end if;
  return query
  select f.id,f.clinic_case_id,f.owner_event_staff_id,c.jurisdiction,f.due_at,
    f.status,f.communication_state,f.participant_safe_message,f.internal_notes,f.updated_at
  from public.clinic_follow_ups f
  join public.clinic_cases c on c.id=f.clinic_case_id and c.event_id=f.event_id
  where f.event_id=p_event_id
  order by f.due_at nulls last,f.updated_at desc;
end $$;


ALTER FUNCTION public.clinic_get_follow_ups(p_event_id uuid, p_actor_user_id uuid) OWNER TO postgres;

