--
-- Name: clinic_packet_dtc_authorized(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.clinic_packet_dtc_authorized(p_item uuid, p_owner uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists(select 1 from public.clinic_packet_funding f
    join public.consumer_briefcase_items i on i.id=f.briefcase_item_id and i.user_id=f.consumer_auth_user_id
    join public.consumer_pending_screening_results s on s.pending_id=i.source_pending_result_id
      and s.claimed_matter_id=i.id and s.claimed_user_id=i.user_id and s.status='CLAIMED'
      and s.anonymous_session_id=f.source_session_id and s.event_id=f.event_id and s.partner_slug=f.partner_slug
      and s.product='rcap_partner'
    join public.clinic_events e on e.id=f.event_id and e.partner_slug=f.partner_slug
    join public.clinic_cases c on c.event_id=f.event_id and c.matter_id=i.id
      and c.participant_user_id=i.user_id and c.screening_session_id=f.source_session_id
    join public.consumer_packet_verifications v on v.briefcase_item_id=i.id and v.consumer_auth_user_id=i.user_id
      and (v.verification_snapshot->>'jurisdiction')||':'||(v.verification_snapshot->>'pathwayId')=f.route_key
    join public.sponsored_packet_render_routes r on r.route_key=f.route_key and r.packet_family_id=f.packet_family_id
      and (r.registry_track_id is null or r.registry_track_id=v.verification_snapshot->>'selectedTrackId')
    where f.briefcase_item_id=p_item and f.consumer_auth_user_id=p_owner and f.funding_mode='dtc');
$$;


ALTER FUNCTION public.clinic_packet_dtc_authorized(p_item uuid, p_owner uuid) OWNER TO postgres;

--
-- Name: clinic_record_incident(uuid, uuid, uuid, text, text, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.clinic_record_incident(p_incident_id uuid, p_event_id uuid, p_actor_user_id uuid, p_severity text, p_status text, p_category text, p_summary text, p_detail text, p_assigned_to uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_id uuid;
begin
  if not exists(
    select 1 from public.clinic_event_staff s join public.partner_users pu on pu.id=s.partner_user_id
    where s.event_id=p_event_id and s.status='approved' and 'incident'=any(s.permissions)
      and pu.auth_user_id=p_actor_user_id and pu.status='active'
    union all select 1 from public.partner_users pu join public.clinic_events e on e.id=p_event_id
      where pu.auth_user_id=p_actor_user_id and pu.status='active' and
      ((pu.role='internal_admin' and pu.partner_slug is null) or (pu.role='partner_admin' and pu.partner_slug=e.partner_slug))
  ) then raise exception 'clinic_incident_forbidden'; end if;
  if p_incident_id is null then
    insert into public.clinic_incidents(event_id,severity,status,category,summary,detail,reported_by,assigned_to,resolved_at)
    values(p_event_id,p_severity,p_status,p_category,p_summary,p_detail,p_actor_user_id,p_assigned_to,case when p_status in ('resolved','closed') then now() else null end)
    returning id into v_id;
  else
    update public.clinic_incidents set severity=p_severity,status=p_status,category=p_category,summary=p_summary,detail=p_detail,
      assigned_to=p_assigned_to,resolved_at=case when p_status in ('resolved','closed') then now() else null end
    where id=p_incident_id and event_id=p_event_id returning id into v_id;
  end if;
  if v_id is null then raise exception 'clinic_incident_not_found'; end if;
  insert into public.clinic_event_audit(event_id,actor_user_id,action,target_type,target_id)
  values(p_event_id,p_actor_user_id,'incident_saved','incident',v_id);
  return v_id;
end $$;


ALTER FUNCTION public.clinic_record_incident(p_incident_id uuid, p_event_id uuid, p_actor_user_id uuid, p_severity text, p_status text, p_category text, p_summary text, p_detail text, p_assigned_to uuid) OWNER TO postgres;

--
-- Name: clinic_redeem_event_code(text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.clinic_redeem_event_code(p_public_slug text, p_code_hash text, p_redemption_nonce_hash text) RETURNS TABLE(outcome text, event_id uuid, partner_slug text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_event public.clinic_events%rowtype; v_code public.clinic_event_access_codes%rowtype;
begin
  select * into v_event from public.clinic_events where public_slug = p_public_slug for update;
  if not found or v_event.status <> 'published' then return query select 'event_unavailable'::text, null::uuid, null::text; return; end if;
  if v_event.jurisdiction is null or v_event.jurisdiction<>all(public.rcap_program_screening_jurisdictions(v_event.partner_slug)) then return query select 'event_unavailable'::text,null::uuid,null::text;return;end if;
  select * into v_code from public.clinic_event_access_codes
  where clinic_event_access_codes.event_id = v_event.id and code_hash = lower(p_code_hash) for update;
  if not found then return query select 'invalid_code'::text, null::uuid, null::text; return; end if;
  if exists (select 1 from public.clinic_event_access_redemptions r where r.access_code_id = v_code.id and r.redemption_nonce_hash = p_redemption_nonce_hash) then
    return query select 'already_redeemed'::text, v_event.id, v_event.partner_slug; return;
  end if;
  if not v_code.is_active or (v_code.starts_at is not null and now() < v_code.starts_at)
    or (v_code.expires_at is not null and now() >= v_code.expires_at)
    or (v_code.max_uses is not null and v_code.uses_count >= v_code.max_uses)
    or (select count(*) from public.clinic_event_access_redemptions r where r.event_id = v_event.id) >= v_event.capacity
  then return query select 'code_unavailable'::text, null::uuid, null::text; return; end if;
  insert into public.clinic_event_access_redemptions(event_id, access_code_id, redemption_nonce_hash)
  values (v_event.id, v_code.id, lower(p_redemption_nonce_hash));
  update public.clinic_event_access_codes set uses_count = uses_count + 1, last_used_at = now() where id = v_code.id;
  return query select 'redeemed'::text, v_event.id, v_event.partner_slug;
end $$;


ALTER FUNCTION public.clinic_redeem_event_code(p_public_slug text, p_code_hash text, p_redemption_nonce_hash text) OWNER TO postgres;

--
-- Name: clinic_release_packet_credit(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.clinic_release_packet_credit(p_render_job_id uuid, p_reason text) RETURNS TABLE(outcome text, reservation_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_res public.clinic_packet_reservations%rowtype;
  v_job public.packet_render_jobs%rowtype;
  v_case public.clinic_cases%rowtype;
  v_event public.clinic_events%rowtype;
begin
  select * into v_res from public.clinic_packet_reservations where render_job_id=p_render_job_id for update;
  if not found then return query select 'reservation_not_found'::text,null::uuid; return; end if;
  if v_res.status='consumed' then return query select 'already_consumed'::text,v_res.id; return; end if;
  if v_res.status='released' then return query select 'already_released'::text,v_res.id; return; end if;
  if p_reason not in ('generation_failed','route_changed','event_closed','manual_cancellation')
    then return query select 'invalid_reason'::text,v_res.id; return; end if;
  select * into v_job from public.packet_render_jobs where id=p_render_job_id;
  select * into v_case from public.clinic_cases where id=v_res.clinic_case_id;
  select * into v_event from public.clinic_events where id=v_res.event_id;
  if p_reason='generation_failed' and v_job.status <> 'failed'
    then return query select 'job_not_failed'::text,v_res.id; return; end if;
  if p_reason='route_changed' and v_case.route_disposition='packet'
    then return query select 'route_still_packet'::text,v_res.id; return; end if;
  if p_reason='event_closed' and v_event.status not in ('closed','archived')
    then return query select 'event_still_open'::text,v_res.id; return; end if;
  update public.clinic_packet_reservations
  set status='released',released_at=now(),release_reason=p_reason
  where id=v_res.id;
  insert into public.clinic_event_audit(event_id,action,target_type,target_id,metadata)
  values(v_res.event_id,'packet_credit_released','packet_reservation',v_res.id,jsonb_build_object('reason',p_reason));
  return query select 'released'::text,v_res.id;
end $$;


ALTER FUNCTION public.clinic_release_packet_credit(p_render_job_id uuid, p_reason text) OWNER TO postgres;

--
-- Name: clinic_reserve_packet_credit(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.clinic_reserve_packet_credit(p_case_id uuid, p_render_job_id uuid) RETURNS TABLE(outcome text, reservation_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_case public.clinic_cases%rowtype;
  v_event public.clinic_events%rowtype;
  v_job public.packet_render_jobs%rowtype;
  v_existing public.clinic_packet_reservations%rowtype;
  v_active_count integer;
  v_id uuid;
begin
  select * into v_case from public.clinic_cases where id=p_case_id for update;
  if not found then return query select 'case_not_found'::text,null::uuid; return; end if;
  if v_case.route_disposition <> 'packet' then return query select 'no_credit_route'::text,null::uuid; return; end if;
  if v_case.matter_id is null then return query select 'matter_not_bound'::text,null::uuid; return; end if;

  select * into v_job from public.packet_render_jobs where id=p_render_job_id for update;
  if not found then return query select 'render_job_not_found'::text,null::uuid; return; end if;
  select * into v_event from public.clinic_events where id=v_case.event_id for update;
  if not found or v_event.status not in ('published','paused','closed')
    then return query select 'event_unavailable'::text,null::uuid; return; end if;
  if v_job.matter_id is distinct from v_case.matter_id
    or v_job.partner_id is distinct from (
      select pr.id from public.partner_records pr where pr.partner_slug=v_event.partner_slug
    )
    or (v_job.consumer_auth_user_id is not null and v_job.consumer_auth_user_id is distinct from v_case.participant_user_id)
  then return query select 'render_job_owner_mismatch'::text,null::uuid; return; end if;

  select * into v_existing from public.clinic_packet_reservations
  where render_job_id=p_render_job_id for update;
  if found then
    return query select case v_existing.status
      when 'consumed' then 'already_consumed'
      when 'released' then 'already_released'
      else 'already_reserved' end,v_existing.id;
    return;
  end if;
  select * into v_existing from public.clinic_packet_reservations
  where clinic_case_id=p_case_id and status in ('reserved','consumed') for update;
  if found then
    return query select case when v_existing.status='consumed' then 'already_consumed' else 'already_reserved' end,v_existing.id;
    return;
  end if;

  if not coalesce(public.rcap_program_packet_authorized(v_event.partner_slug,v_event.jurisdiction),false) then
    return query select 'program_packet_authority_required'::text,null::uuid;return;
  end if;
  if v_event.sponsorship_allocation is not null then
    select count(*)::integer into v_active_count
    from public.clinic_packet_reservations
    where event_id=v_event.id and status in ('reserved','consumed');
    if v_active_count >= v_event.sponsorship_allocation
      then return query select 'sponsorship_exhausted'::text,null::uuid; return; end if;
  end if;

  insert into public.clinic_packet_reservations(
    event_id,clinic_case_id,render_job_id,participant_user_id
  ) values (v_case.event_id,v_case.id,p_render_job_id,v_case.participant_user_id)
  returning id into v_id;
  insert into public.clinic_event_audit(event_id,action,target_type,target_id)
  values(v_case.event_id,'packet_credit_reserved','packet_reservation',v_id);
  return query select 'reserved'::text,v_id;
end $$;


ALTER FUNCTION public.clinic_reserve_packet_credit(p_case_id uuid, p_render_job_id uuid) OWNER TO postgres;

--
-- Name: clinic_reserve_participant_packet_credit(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.clinic_reserve_participant_packet_credit(p_render_job_id uuid, p_actor_user_id uuid, p_handoff_token_hash text) RETURNS TABLE(outcome text, reservation_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_case_id uuid;
begin
  select c.id into v_case_id
  from public.packet_render_jobs j
  join public.partner_records pr on pr.id=j.partner_id
  join public.clinic_events e on e.partner_slug=pr.partner_slug
  join public.clinic_cases c on c.event_id=e.id and c.matter_id=j.matter_id
  join public.clinic_assisted_sessions s on s.id=c.assisted_session_id
  where j.id=p_render_job_id and c.participant_user_id=p_actor_user_id
    and c.route_disposition='packet'
    and s.participant_user_id=p_actor_user_id
    and s.handoff_token_hash=lower(p_handoff_token_hash)
    and s.status in ('active','handed_off') and s.expires_at>now()
    and (j.consumer_auth_user_id is null or j.consumer_auth_user_id=p_actor_user_id)
  limit 1;
  if v_case_id is null then
    return query select 'render_job_owner_mismatch'::text,null::uuid;
    return;
  end if;
  return query select * from public.clinic_reserve_packet_credit(v_case_id,p_render_job_id);
end $$;


ALTER FUNCTION public.clinic_reserve_participant_packet_credit(p_render_job_id uuid, p_actor_user_id uuid, p_handoff_token_hash text) OWNER TO postgres;

--
-- Name: clinic_set_event_staff(uuid, uuid, uuid, text, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.clinic_set_event_staff(p_actor_user_id uuid, p_event_id uuid, p_partner_user_id uuid, p_status text, p_permissions text[]) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_partner_slug text; v_staff_partner text; v_id uuid;
begin
  select partner_slug into v_partner_slug from public.clinic_events where id = p_event_id;
  if v_partner_slug is null then raise exception 'clinic_event_not_found'; end if;
  if not exists (
    select 1 from public.partner_users pu where pu.auth_user_id = p_actor_user_id
      and pu.status = 'active' and ((pu.role = 'internal_admin' and pu.partner_slug is null)
        or (pu.role = 'partner_admin' and pu.partner_slug = v_partner_slug))
  ) then raise exception 'clinic_staff_forbidden'; end if;
  select partner_slug into v_staff_partner from public.partner_users
    where id = p_partner_user_id and status = 'active' and role in ('partner_admin','partner_staff');
  if v_staff_partner is distinct from v_partner_slug then raise exception 'clinic_staff_cross_tenant'; end if;
  insert into public.clinic_event_staff(event_id, partner_user_id, status, permissions, approved_by, revoked_at)
  values (p_event_id, p_partner_user_id, p_status, p_permissions, p_actor_user_id,
    case when p_status = 'revoked' then now() else null end)
  on conflict (event_id, partner_user_id) do update set
    status = excluded.status, permissions = excluded.permissions,
    approved_by = excluded.approved_by, approved_at = now(), revoked_at = excluded.revoked_at
  returning id into v_id;
  insert into public.clinic_event_audit(event_id, actor_user_id, action, target_type, target_id, metadata)
  values (p_event_id, p_actor_user_id, 'staff_status_changed', 'staff', v_id, jsonb_build_object('status', p_status));
  return v_id;
end $$;


ALTER FUNCTION public.clinic_set_event_staff(p_actor_user_id uuid, p_event_id uuid, p_partner_user_id uuid, p_status text, p_permissions text[]) OWNER TO postgres;

--
-- Name: clinic_set_event_status(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.clinic_set_event_status(p_event_id uuid, p_actor_user_id uuid, p_status text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_event public.clinic_events%rowtype;
begin
  select * into v_event from public.clinic_events where id = p_event_id for update;
  if not found then return 'not_found'; end if;
  if not exists (
    select 1 from public.partner_users pu where pu.auth_user_id = p_actor_user_id
      and pu.status = 'active' and ((pu.role = 'internal_admin' and pu.partner_slug is null)
        or (pu.role = 'partner_admin' and pu.partner_slug = v_event.partner_slug))
  ) then return 'forbidden'; end if;
  if p_status='published' and exists(select 1 from public.partner_onboarding where partner_slug=v_event.partner_slug and rcap_policy_version='rcap2.2') then
    perform public.rcap_program_clinic_scope(v_event.partner_slug,p_actor_user_id,'publish_clinic',v_event.jurisdiction,v_event.sponsorship_allocation);
  end if;
  if p_status = v_event.status then return 'unchanged'; end if;
  if not ((v_event.status = 'draft' and p_status = 'published')
    or (v_event.status = 'published' and p_status in ('paused','closed'))
    or (v_event.status = 'paused' and p_status in ('published','closed'))
    or (v_event.status = 'closed' and p_status = 'archived')) then return 'invalid_transition'; end if;
  update public.clinic_events set status = p_status where id = p_event_id;
  if p_status in ('closed','archived') then
    update public.clinic_assisted_sessions set status = 'ended', ended_at = now(), ended_reason = 'event_closed'
    where event_id = p_event_id and status in ('active','handed_off');
  end if;
  insert into public.clinic_event_audit(event_id, actor_user_id, action, target_type, target_id, metadata)
  values (p_event_id, p_actor_user_id, 'event_status_changed', 'event', p_event_id,
    jsonb_build_object('from', v_event.status, 'to', p_status));
  return 'updated';
end $$;


ALTER FUNCTION public.clinic_set_event_status(p_event_id uuid, p_actor_user_id uuid, p_status text) OWNER TO postgres;

--
-- Name: clinic_set_updated_at(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.clinic_set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$ begin new.updated_at = now(); return new; end $$;


ALTER FUNCTION public.clinic_set_updated_at() OWNER TO postgres;

--
-- Name: clinic_start_assisted_session(uuid, uuid, uuid, uuid, text, text, text, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.clinic_start_assisted_session(p_event_id uuid, p_event_staff_id uuid, p_participant_user_id uuid, p_screening_session_id uuid, p_handoff_token_hash text, p_device_nonce_hash text, p_consent_version text, p_consented_at timestamp with time zone, p_ttl_minutes integer DEFAULT 30) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_id uuid;
begin
  if p_consented_at is null or p_consented_at > now() then raise exception 'clinic_consent_required'; end if;
  if p_ttl_minutes < 5 or p_ttl_minutes > 120 then raise exception 'clinic_session_ttl_invalid'; end if;
  if not exists (
    select 1 from public.clinic_event_staff s
    join public.partner_users pu on pu.id=s.partner_user_id
    join public.clinic_events e on e.id=s.event_id
    where s.id=p_event_staff_id and s.event_id=p_event_id and s.status='approved'
      and 'assist'=any(s.permissions) and pu.status='active' and pu.partner_slug=e.partner_slug
      and e.status='published'
  ) then raise exception 'clinic_staff_not_approved'; end if;
  if not exists (select 1 from auth.users where id=p_participant_user_id) then raise exception 'clinic_participant_not_found'; end if;
  if p_screening_session_id is null or not exists (
    select 1 from public.screening_sessions where session_id=p_screening_session_id
  ) then raise exception 'clinic_screening_not_found'; end if;
  if not exists(select 1 from public.clinic_events e join public.screening_sessions s on s.session_id=p_screening_session_id
    where e.id=p_event_id and s.partner_slug=e.partner_slug and s.jurisdiction=e.jurisdiction
    and e.jurisdiction=any(public.rcap_program_screening_jurisdictions(e.partner_slug))) then raise exception 'clinic_program_scope_denied' using errcode='42501';end if;
  insert into public.clinic_assisted_sessions(
    event_id,event_staff_id,participant_user_id,screening_session_id,handoff_token_hash,
    device_nonce_hash,consent_version,consented_at,expires_at
  ) values (
    p_event_id,p_event_staff_id,p_participant_user_id,p_screening_session_id,
    lower(p_handoff_token_hash),lower(p_device_nonce_hash),trim(p_consent_version),
    p_consented_at,now()+make_interval(mins=>p_ttl_minutes)
  ) returning id into v_id;
  insert into public.clinic_event_audit(event_id,action,target_type,target_id,metadata)
  values (p_event_id,'assistance_consented','assisted_session',v_id,jsonb_build_object('consent_version',p_consent_version));
  return v_id;
end $$;


ALTER FUNCTION public.clinic_start_assisted_session(p_event_id uuid, p_event_staff_id uuid, p_participant_user_id uuid, p_screening_session_id uuid, p_handoff_token_hash text, p_device_nonce_hash text, p_consent_version text, p_consented_at timestamp with time zone, p_ttl_minutes integer) OWNER TO postgres;

--
-- Name: clinic_sync_packet_reservation(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.clinic_sync_packet_reservation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not exists(select 1 from public.clinic_packet_reservations r where r.render_job_id=new.id and r.status='reserved')
    then return new; end if;
  if new.status='failed' and new.failure_disposition='terminal' then
    perform public.clinic_release_packet_credit(new.id,'generation_failed');
  elsif new.status in ('artifact_validated','delivered')
    and new.accounting_result in ('consumed','already_consumed','overage_consumed')
    and new.credit_ledger_id is not null then
    perform public.clinic_finalize_packet_credit(new.id);
  end if;
  return new;
end $$;


ALTER FUNCTION public.clinic_sync_packet_reservation() OWNER TO postgres;

--
-- Name: clinic_transition_case(uuid, uuid, text, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.clinic_transition_case(p_case_id uuid, p_actor_user_id uuid, p_queue_status text, p_follow_up_owner_staff_id uuid DEFAULT NULL::uuid, p_follow_up_due_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_case public.clinic_cases%rowtype;
begin
  select * into v_case from public.clinic_cases where id=p_case_id for update;
  if not found then return 'not_found'; end if;
  if not exists (
    select 1 from public.clinic_events e join public.partner_users pu on
      ((pu.role='internal_admin' and pu.partner_slug is null) or (pu.role='partner_admin' and pu.partner_slug=e.partner_slug))
      where e.id=v_case.event_id and pu.auth_user_id=p_actor_user_id and pu.status='active'
    union all
    select 1 from public.clinic_event_staff s join public.partner_users pu on pu.id=s.partner_user_id
      where s.event_id=v_case.event_id and s.status='approved' and 'queue'=any(s.permissions)
        and pu.auth_user_id=p_actor_user_id and pu.status='active'
  ) then return 'forbidden'; end if;
  if p_follow_up_owner_staff_id is not null and not exists(select 1 from public.clinic_event_staff where id=p_follow_up_owner_staff_id and event_id=v_case.event_id and status='approved')
    then return 'invalid_follow_up_owner'; end if;
  update public.clinic_cases set queue_status=p_queue_status,
    follow_up_owner_staff_id=p_follow_up_owner_staff_id,follow_up_due_at=p_follow_up_due_at,
    closed_at=case when p_queue_status='closed' then now() else null end,last_activity_at=now()
  where id=p_case_id;
  insert into public.clinic_event_audit(event_id,actor_user_id,action,target_type,target_id,metadata)
  values(v_case.event_id,p_actor_user_id,'case_status_changed','case',p_case_id,jsonb_build_object('from',v_case.queue_status,'to',p_queue_status));
  return 'updated';
end $$;


ALTER FUNCTION public.clinic_transition_case(p_case_id uuid, p_actor_user_id uuid, p_queue_status text, p_follow_up_owner_staff_id uuid, p_follow_up_due_at timestamp with time zone) OWNER TO postgres;

--
-- Name: clinic_transition_event_case(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.clinic_transition_event_case(p_event_id uuid, p_case_id uuid, p_actor_user_id uuid, p_queue_status text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_privileged boolean;
begin
  if not public.clinic_actor_can_event(p_event_id,p_actor_user_id,'queue')
    then return 'forbidden'; end if;
  if not exists(select 1 from public.clinic_cases c where c.id=p_case_id and c.event_id=p_event_id)
    then return 'not_found'; end if;
  select exists(
    select 1 from public.clinic_events e join public.partner_users pu on pu.auth_user_id=p_actor_user_id and pu.status='active'
    where e.id=p_event_id and ((pu.role='internal_admin' and pu.partner_slug is null) or (pu.role='partner_admin' and pu.partner_slug=e.partner_slug))
  ) into v_privileged;
  if not v_privileged and not exists(
    select 1 from public.clinic_cases c join public.clinic_assisted_sessions s on s.id=c.assisted_session_id
    where c.id=p_case_id and c.event_id=p_event_id and s.status in ('active','handed_off') and s.expires_at>now()
  ) then return 'session_inactive'; end if;
  return public.clinic_transition_case(p_case_id,p_actor_user_id,p_queue_status,null,null);
end $$;


ALTER FUNCTION public.clinic_transition_event_case(p_event_id uuid, p_case_id uuid, p_actor_user_id uuid, p_queue_status text) OWNER TO postgres;

--
-- Name: clinic_upsert_case(uuid, uuid, uuid, uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.clinic_upsert_case(p_event_id uuid, p_assisted_session_id uuid, p_participant_user_id uuid, p_screening_session_id uuid, p_matter_id uuid, p_queue_status text, p_route_disposition text, p_jurisdiction text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_id uuid;
begin
  if not exists (
    select 1 from public.clinic_assisted_sessions s
    where s.id=p_assisted_session_id and s.event_id=p_event_id
      and s.participant_user_id=p_participant_user_id
      and s.screening_session_id=p_screening_session_id
      and s.status in ('active','handed_off') and s.expires_at>now()
  ) then raise exception 'clinic_session_owner_mismatch'; end if;
  if p_matter_id is not null and not exists (
    select 1 from public.consumer_briefcase_items b
    where b.id=p_matter_id and b.user_id=p_participant_user_id
  ) then raise exception 'clinic_matter_owner_mismatch'; end if;
  if p_matter_id is not null and exists (
    select 1 from public.clinic_cases c
    where c.event_id=p_event_id and c.participant_user_id=p_participant_user_id
      and c.screening_session_id=p_screening_session_id and c.matter_id is not null
      and c.matter_id is distinct from p_matter_id
  ) then raise exception 'clinic_matter_rebind_forbidden'; end if;
  insert into public.clinic_cases(
    event_id,participant_user_id,assisted_session_id,screening_session_id,
    matter_id,queue_status,route_disposition,jurisdiction
  ) values (
    p_event_id,p_participant_user_id,p_assisted_session_id,p_screening_session_id,
    p_matter_id,p_queue_status,p_route_disposition,upper(p_jurisdiction)
  )
  on conflict(event_id,participant_user_id,screening_session_id) do update set
    assisted_session_id=excluded.assisted_session_id,
    matter_id=coalesce(excluded.matter_id,clinic_cases.matter_id),
    queue_status=excluded.queue_status,route_disposition=excluded.route_disposition,
    last_activity_at=now()
  returning id into v_id;
  return v_id;
end $$;


ALTER FUNCTION public.clinic_upsert_case(p_event_id uuid, p_assisted_session_id uuid, p_participant_user_id uuid, p_screening_session_id uuid, p_matter_id uuid, p_queue_status text, p_route_disposition text, p_jurisdiction text) OWNER TO postgres;

--
-- Name: clinic_upsert_event_follow_up(uuid, uuid, uuid, uuid, uuid, timestamp with time zone, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.clinic_upsert_event_follow_up(p_event_id uuid, p_follow_up_id uuid, p_case_id uuid, p_actor_user_id uuid, p_owner_event_staff_id uuid, p_due_at timestamp with time zone, p_status text, p_communication_state text, p_participant_safe_message text, p_internal_notes text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not public.clinic_actor_can_event(p_event_id,p_actor_user_id,'follow_up')
    then raise exception 'clinic_follow_up_forbidden'; end if;
  if not exists(select 1 from public.clinic_cases c where c.id=p_case_id and c.event_id=p_event_id)
    then raise exception 'clinic_follow_up_event_mismatch'; end if;
  return public.clinic_upsert_follow_up(
    p_follow_up_id,p_case_id,p_actor_user_id,p_owner_event_staff_id,p_due_at,
    p_status,p_communication_state,p_participant_safe_message,p_internal_notes
  );
end $$;


ALTER FUNCTION public.clinic_upsert_event_follow_up(p_event_id uuid, p_follow_up_id uuid, p_case_id uuid, p_actor_user_id uuid, p_owner_event_staff_id uuid, p_due_at timestamp with time zone, p_status text, p_communication_state text, p_participant_safe_message text, p_internal_notes text) OWNER TO postgres;

--
-- Name: clinic_upsert_follow_up(uuid, uuid, uuid, uuid, timestamp with time zone, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.clinic_upsert_follow_up(p_follow_up_id uuid, p_case_id uuid, p_actor_user_id uuid, p_owner_event_staff_id uuid, p_due_at timestamp with time zone, p_status text, p_communication_state text, p_participant_safe_message text, p_internal_notes text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_case public.clinic_cases%rowtype; v_id uuid;
begin
  select * into v_case from public.clinic_cases where id=p_case_id;
  if not found or not exists(
    select 1 from public.clinic_event_staff s join public.partner_users pu on pu.id=s.partner_user_id
    join public.clinic_events e on e.id=s.event_id
    where s.event_id=v_case.event_id and s.status='approved' and 'follow_up'=any(s.permissions)
      and pu.auth_user_id=p_actor_user_id and pu.status='active' and pu.partner_slug=e.partner_slug
    union all
    select 1 from public.partner_users pu join public.clinic_events e on e.id=v_case.event_id
    where pu.auth_user_id=p_actor_user_id and pu.status='active' and
      ((pu.role='internal_admin' and pu.partner_slug is null) or
       (pu.role='partner_admin' and pu.partner_slug=e.partner_slug))
  ) then raise exception 'clinic_follow_up_forbidden'; end if;
  if p_owner_event_staff_id is not null and not exists(
    select 1 from public.clinic_event_staff s
    where s.id=p_owner_event_staff_id and s.event_id=v_case.event_id and s.status='approved'
      and 'follow_up'=any(s.permissions)
  ) then raise exception 'clinic_follow_up_owner_invalid'; end if;
  if p_follow_up_id is null then
    insert into public.clinic_follow_ups(
      event_id,clinic_case_id,owner_event_staff_id,due_at,status,communication_state,
      participant_safe_message,internal_notes,created_by,completed_at
    ) values (
      v_case.event_id,p_case_id,p_owner_event_staff_id,p_due_at,p_status,p_communication_state,
      nullif(trim(p_participant_safe_message),''),nullif(trim(p_internal_notes),''),p_actor_user_id,
      case when p_status='completed' then now() else null end
    ) returning id into v_id;
  else
    update public.clinic_follow_ups set
      owner_event_staff_id=p_owner_event_staff_id,due_at=p_due_at,status=p_status,
      communication_state=p_communication_state,
      participant_safe_message=nullif(trim(p_participant_safe_message),''),
      internal_notes=nullif(trim(p_internal_notes),''),
      completed_at=case when p_status='completed' then now() else null end
    where id=p_follow_up_id and clinic_case_id=p_case_id and event_id=v_case.event_id
    returning id into v_id;
  end if;
  if v_id is null then raise exception 'clinic_follow_up_not_found'; end if;
  insert into public.clinic_event_audit(event_id,actor_user_id,action,target_type,target_id)
  values(v_case.event_id,p_actor_user_id,'follow_up_saved','follow_up',v_id);
  return v_id;
end $$;


ALTER FUNCTION public.clinic_upsert_follow_up(p_follow_up_id uuid, p_case_id uuid, p_actor_user_id uuid, p_owner_event_staff_id uuid, p_due_at timestamp with time zone, p_status text, p_communication_state text, p_participant_safe_message text, p_internal_notes text) OWNER TO postgres;

--
-- Name: consume_rcap_packet_credit(text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.consume_rcap_packet_credit(p_partner_slug text, p_matter_id text, p_render_job_id uuid) RETURNS TABLE(ok boolean, reason text, consumption_class text, units_used integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_partner text;
  v_matter text;
  v_status text;
  v_output text;
  v_allowed integer;
  v_used integer;
  v_class text;
begin
  v_partner := nullif(trim(p_partner_slug), '');
  v_matter := nullif(trim(p_matter_id), '');

  if v_partner is null or v_matter is null then
    return query select false, 'invalid_input'::text, null::text, null::integer;
    return;
  end if;

  -- The gate. Credit cannot move ahead of validated, stored bytes.
  select status, output_sha256 into v_status, v_output
  from public.packet_render_jobs
  where id = p_render_job_id;

  if v_status is null then
    return query select false, 'render_job_not_found'::text, null::text, null::integer;
    return;
  end if;

  if v_status not in ('artifact_validated', 'delivered') or v_output is null then
    return query select false, 'artifact_not_validated'::text, null::text, null::integer;
    return;
  end if;

  -- Already consumed for this matter: report success without moving anything.
  -- A retry is not an error and must not spend a second unit.
  -- Column is qualified: consumption_class is also an OUT parameter of this
  -- function, and an unqualified reference is ambiguous.
  select c.consumption_class into v_class
  from public.rcap_packet_credit_consumptions c
  where c.partner_slug = v_partner and c.matter_id = v_matter;

  if v_class is not null then
    select count(*)::integer into v_used
    from public.rcap_packet_credit_consumptions c
    where c.partner_slug = v_partner;
    return query select true, 'already_consumed'::text, v_class, v_used;
    return;
  end if;

  select a.packets_allowed into v_allowed
  from public.rcap_partner_packet_allocation a
  where a.partner_slug = v_partner;

  -- No allocation row means no sponsored capacity was ever granted. Fail closed
  -- rather than inventing one.
  if v_allowed is null then
    return query select false, 'no_allocation'::text, null::text, null::integer;
    return;
  end if;

  select count(*)::integer into v_used
  from public.rcap_packet_credit_consumptions c
  where c.partner_slug = v_partner;

  if v_used < v_allowed then
    v_class := 'included';
  elsif v_used < v_allowed + 10 then
    -- Internal continuity reserve. Delivered and non-billable; never surfaced
    -- to the partner as available capacity.
    v_class := 'overage';
  else
    return query select false, 'reserve_exhausted'::text, null::text, v_used;
    return;
  end if;

  insert into public.rcap_packet_credit_consumptions
    (partner_slug, matter_id, render_job_id, consumption_class)
  values (v_partner, v_matter, p_render_job_id, v_class)
  on conflict (partner_slug, matter_id) do nothing;

  select count(*)::integer into v_used
  from public.rcap_packet_credit_consumptions c
  where c.partner_slug = v_partner;

  return query select true, 'consumed'::text, v_class, v_used;
end;
$$;


ALTER FUNCTION public.consume_rcap_packet_credit(p_partner_slug text, p_matter_id text, p_render_job_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION consume_rcap_packet_credit(p_partner_slug text, p_matter_id text, p_render_job_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.consume_rcap_packet_credit(p_partner_slug text, p_matter_id text, p_render_job_id uuid) IS 'The only sanctioned path for sponsored credit movement. Refuses unless the named render job reached artifact_validated with a stored checksum.';


--
-- Name: consume_rcap_screening_session(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.consume_rcap_screening_session(p_session_id uuid) RETURNS TABLE(consumed boolean, partner_slug text, claimed_slot_state text, status text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with consumed_session as (
    update public.screening_sessions ss
    set status = 'completed',
        updated_at = now()
    where ss.session_id = p_session_id
      and ss.flow_mode = 'rcap'
      and ss.partner_slug is not null
      and ss.status <> 'completed'
    returning ss.partner_slug, ss.claimed_slot_state, ss.status
  )
  select true, cs.partner_slug, cs.claimed_slot_state, cs.status
  from consumed_session cs
  union all
  select false, ss.partner_slug, ss.claimed_slot_state, ss.status
  from public.screening_sessions ss
  where ss.session_id = p_session_id
    and ss.flow_mode = 'rcap'
    and not exists (select 1 from consumed_session)
  limit 1;
$$;


ALTER FUNCTION public.consume_rcap_screening_session(p_session_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION consume_rcap_screening_session(p_session_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.consume_rcap_screening_session(p_session_id uuid) IS 'Marks an attributed RCAP screening session completed without consuming partner packet capacity.';


--
-- Name: consumer_canonical_json(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.consumer_canonical_json(p_value jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
declare
  v_type text := jsonb_typeof(p_value);
  v_result text;
begin
  if v_type = 'object' then
    select '{' || coalesce(string_agg(to_jsonb(e.key)::text || ':' || public.consumer_canonical_json(e.value), ',' order by e.key), '') || '}'
      into v_result from jsonb_each(p_value) e;
    return v_result;
  elsif v_type = 'array' then
    select '[' || coalesce(string_agg(public.consumer_canonical_json(e.value), ',' order by e.ordinality), '') || ']'
      into v_result from jsonb_array_elements(p_value) with ordinality e(value, ordinality);
    return v_result;
  end if;
  return p_value::text;
end;
$$;


ALTER FUNCTION public.consumer_canonical_json(p_value jsonb) OWNER TO postgres;

--
-- Name: consumer_matter_id_for_briefcase_item(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.consumer_matter_id_for_briefcase_item(p_item_id uuid) RETURNS uuid
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_hash text;
  v_variant text;
begin
  if p_item_id is null then return null; end if;
  v_hash := encode(
    extensions.digest(convert_to('rcap:consumer-matter:v1:' || p_item_id::text, 'utf8'), 'sha256'),
    'hex'
  );
  v_variant := to_hex(((get_byte(decode(substr(v_hash, 17, 2), 'hex'), 0) >> 4) & 3) + 8);
  return (
    substr(v_hash, 1, 8) || '-' || substr(v_hash, 9, 4) || '-4' ||
    substr(v_hash, 14, 3) || '-' || v_variant || substr(v_hash, 18, 3) || '-' ||
    substr(v_hash, 21, 12)
  )::uuid;
end;
$$;


ALTER FUNCTION public.consumer_matter_id_for_briefcase_item(p_item_id uuid) OWNER TO postgres;

--
-- Name: consumer_packet_artifact_provenance_immutable(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.consumer_packet_artifact_provenance_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_erasure boolean := public.rcap_participant_erasure_authority() = 'erase_participant_identifiers';
begin
  if tg_op = 'UPDATE' then
    if new.briefcase_item_id is distinct from old.briefcase_item_id
       or new.matter_id is distinct from old.matter_id
       or new.render_job_id is distinct from old.render_job_id
       or new.entitlement_source is distinct from old.entitlement_source
       or new.verification_hash is distinct from old.verification_hash
       or new.artifact is distinct from old.artifact
       or new.legacy_evidence is distinct from old.legacy_evidence then
      raise exception 'consumer_packet_artifact_provenance: issued artifact provenance is immutable';
    end if;
    if new.consumer_auth_user_id is distinct from old.consumer_auth_user_id and not v_erasure then
      raise exception 'consumer_packet_artifact_provenance: consumer_auth_user_id is immutable once set';
    end if;
    new.revision := old.revision + 1;
    new.updated_at := now();
  end if;
  return new;
end;
$$;


ALTER FUNCTION public.consumer_packet_artifact_provenance_immutable() OWNER TO postgres;

--
-- Name: consumer_packet_payment_authority(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.consumer_packet_payment_authority(p_briefcase_item_id uuid, p_consumer_auth_user_id uuid) RETURNS TABLE(valid boolean, reason text, provider_event_id text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_product text;
  v_person uuid;
  v_matter uuid;
begin
  if to_regclass('public.consumer_briefcase_items') is null then
    return query select false, 'no_payment_storage'::text, null::text;
    return;
  end if;
  execute
    'select b.payment_product_id, b.payment_person_id, b.payment_matter_id
       from public.consumer_briefcase_items b where b.id = $1'
  into v_product, v_person, v_matter
  using p_briefcase_item_id;
  return query select * from public.consumer_packet_payment_authority(
    p_briefcase_item_id, p_consumer_auth_user_id, v_product, v_person, v_matter
  );
end;
$_$;


ALTER FUNCTION public.consumer_packet_payment_authority(p_briefcase_item_id uuid, p_consumer_auth_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION consumer_packet_payment_authority(p_briefcase_item_id uuid, p_consumer_auth_user_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.consumer_packet_payment_authority(p_briefcase_item_id uuid, p_consumer_auth_user_id uuid) IS 'Owner-scoped consumer payment probe: paid, 5000 cents, USD, server-written evidence, and owned by the participant the job is bound to. Phase 52.';


--
-- Name: consumer_packet_payment_authority(uuid, uuid, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.consumer_packet_payment_authority(p_briefcase_item_id uuid, p_consumer_auth_user_id uuid, p_product_id text, p_person_id uuid, p_matter_id uuid) RETURNS TABLE(valid boolean, reason text, provider_event_id text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_status text;
  v_amount integer;
  v_regular integer;
  v_discount integer;
  v_currency text;
  v_owner uuid;
  v_event text;
  v_authority text;
  v_session text;
  v_product text;
  v_person uuid;
  v_matter uuid;
begin
  if p_briefcase_item_id is null then return query select false, 'no_briefcase_item'::text, null::text; return; end if;
  if p_consumer_auth_user_id is null then return query select false, 'no_consumer_binding'::text, null::text; return; end if;
  if to_regclass('public.consumer_briefcase_items') is null then return query select false, 'no_payment_storage'::text, null::text; return; end if;

  execute
    'select b.payment_status, b.amount_cents, b.regular_price_cents, b.discount_cents,
            b.currency, b.user_id, b.provider_event_id, b.payment_authority,
            b.checkout_session_id, b.payment_product_id, b.payment_person_id, b.payment_matter_id
       from public.consumer_briefcase_items b where b.id = $1'
  into v_status, v_amount, v_regular, v_discount, v_currency, v_owner, v_event,
       v_authority, v_session, v_product, v_person, v_matter
  using p_briefcase_item_id;

  if v_status is null and v_owner is null then return query select false, 'item_not_found'::text, null::text; return; end if;
  if v_owner is distinct from p_consumer_auth_user_id then return query select false, 'owner_mismatch'::text, null::text; return; end if;
  if v_status is distinct from 'paid' then return query select false, ('payment_status_' || coalesce(v_status, 'null'))::text, null::text; return; end if;
  if v_regular is distinct from 5000
     or v_discount is null or v_discount < 0 or v_discount > v_regular
     or v_amount is distinct from (v_regular - v_discount) then
    return query select false, 'amount_not_product_price'::text, null::text; return;
  end if;
  if lower(coalesce(v_currency, '')) <> 'usd' then return query select false, 'currency_not_usd'::text, null::text; return; end if;
  if v_authority is null or nullif(trim(coalesce(v_event, '')), '') is null then return query select false, 'no_server_payment_evidence'::text, null::text; return; end if;
  if nullif(trim(coalesce(v_session, '')), '') is null then return query select false, 'no_checkout_session'::text, null::text; return; end if;
  if v_product is distinct from p_product_id or p_product_id is distinct from 'expungement_packet' then return query select false, 'product_mismatch'::text, null::text; return; end if;
  if v_person is distinct from p_person_id then return query select false, 'person_mismatch'::text, null::text; return; end if;
  if v_matter is distinct from p_matter_id or p_matter_id is distinct from public.consumer_matter_id_for_briefcase_item(p_briefcase_item_id) then return query select false, 'matter_mismatch'::text, null::text; return; end if;

  return query select true, 'authorized'::text, v_event;
end;
$_$;


ALTER FUNCTION public.consumer_packet_payment_authority(p_briefcase_item_id uuid, p_consumer_auth_user_id uuid, p_product_id text, p_person_id uuid, p_matter_id uuid) OWNER TO postgres;

--
-- Name: consumer_packet_payment_valid(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.consumer_packet_payment_valid(p_briefcase_item_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_valid boolean;
begin
  if p_briefcase_item_id is null then
    return false;
  end if;

  if to_regclass('public.consumer_briefcase_items') is null then
    return false;
  end if;

  execute
    'select exists (
       select 1 from public.consumer_briefcase_items b
       where b.id = $1
         and b.payment_status = ''paid''
         and b.amount_cents = 5000
     )'
  into v_valid
  using p_briefcase_item_id;

  return coalesce(v_valid, false);
end;
$_$;


ALTER FUNCTION public.consumer_packet_payment_valid(p_briefcase_item_id uuid) OWNER TO postgres;

--
-- Name: consumer_payment_consumption_binding_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.consumer_payment_consumption_binding_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_valid boolean;
  v_reason text;
  v_session text;
begin
  if tg_op = 'UPDATE' then
    if new.consumer_briefcase_item_id is distinct from old.consumer_briefcase_item_id
       or new.consumer_auth_user_id is distinct from old.consumer_auth_user_id
       or new.provider_event_id is distinct from old.provider_event_id
       or new.person_id is distinct from old.person_id
       or new.matter_id is distinct from old.matter_id
       or new.product_id is distinct from old.product_id
       or new.checkout_session_id is distinct from old.checkout_session_id
       or new.amount_cents is distinct from old.amount_cents
       or new.currency is distinct from old.currency then
      raise exception 'consumer payment consumption binding is immutable';
    end if;
    -- A refund removes authority for new work, but Phase 52 deliberately keeps
    -- an already-delivered artifact and its consumption evidence. A benign
    -- maintenance update therefore must not re-run current payment authority.
    return new;
  end if;

  select a.valid, a.reason, b.checkout_session_id
    into v_valid, v_reason, v_session
    from public.consumer_briefcase_items b
    cross join lateral public.consumer_packet_payment_authority(
      new.consumer_briefcase_item_id,
      new.consumer_auth_user_id,
      public.expungement_packet_product_id(),
      new.person_id,
      new.matter_id
    ) a
   where b.id = new.consumer_briefcase_item_id;
  if not coalesce(v_valid, false) then
    raise exception 'consumer payment consumption binding refused (%)', coalesce(v_reason, 'unknown');
  end if;
  new.product_id := public.expungement_packet_product_id();
  new.checkout_session_id := v_session;
  new.amount_cents := 5000;
  new.currency := 'usd';
  return new;
end;
$$;


ALTER FUNCTION public.consumer_payment_consumption_binding_guard() OWNER TO postgres;

--
-- Name: consumer_render_job_verification_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.consumer_render_job_verification_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_hash text;
begin
  if tg_op = 'UPDATE' and (
       (old.sponsored_route_key is not null and new.sponsored_route_key is distinct from old.sponsored_route_key)
    or (old.sponsored_session_id is not null and new.sponsored_session_id is distinct from old.sponsored_session_id)
    or (old.sponsored_clinic_event_id is not null and new.sponsored_clinic_event_id is distinct from old.sponsored_clinic_event_id)
    or (old.sponsored_consumer_briefcase_item_id is not null
        and new.sponsored_consumer_briefcase_item_id is distinct from old.sponsored_consumer_briefcase_item_id)
    or (old.sponsored_consumer_auth_user_id is not null
        and new.sponsored_consumer_auth_user_id is distinct from old.sponsored_consumer_auth_user_id)
    or (old.sponsored_verification_hash is not null
        and new.sponsored_verification_hash is distinct from old.sponsored_verification_hash)
  ) then
    raise exception 'sponsored render binding is immutable';
  end if;

  if new.sponsored_route_key is not null then
    if new.partner_id is null
       or new.sponsored_session_id is null
       or new.sponsored_clinic_event_id is null
       or new.sponsored_consumer_briefcase_item_id is null
       or new.sponsored_consumer_auth_user_id is null
       or new.sponsored_verification_hash is null then
      raise exception 'sponsored render job binding is incomplete';
    end if;
    if not exists (
      select 1 from public.sponsored_packet_render_routes r
      where r.route_key = new.sponsored_route_key and r.active
    ) then
      raise exception 'sponsored render route is not registered';
    end if;
    if new.status in ('artifact_validated', 'delivered') then
      select v.verification_hash into v_hash from public.consumer_packet_verifications v
        where v.briefcase_item_id = new.sponsored_consumer_briefcase_item_id
          and v.consumer_auth_user_id = new.sponsored_consumer_auth_user_id
          and v.status = 'verified';
      if v_hash is null or v_hash is distinct from new.sponsored_verification_hash then
        raise exception 'sponsored render job has stale verification authority';
      end if;
    end if;
    return new;
  end if;

  if new.partner_id is not null then return new; end if;
  if tg_op = 'UPDATE' and old.consumer_verification_hash is not null
     and new.consumer_verification_hash is distinct from old.consumer_verification_hash then
    raise exception 'consumer render verification binding is immutable';
  end if;
  if new.status in ('artifact_validated', 'delivered') then
    select v.verification_hash into v_hash from public.consumer_packet_verifications v
      where v.briefcase_item_id = new.consumer_briefcase_item_id
        and v.consumer_auth_user_id = new.consumer_auth_user_id
        and v.status = 'verified';
    if v_hash is null or v_hash is distinct from new.consumer_verification_hash then
      raise exception 'consumer render job has stale verification authority';
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION public.consumer_render_job_verification_guard() OWNER TO postgres;

--
-- Name: content_apply_legal_review(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.content_apply_legal_review(p_post_id uuid, p_decision text, p_notes text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_role text := public.content_current_role();
  v_status text;
  v_next_status text;
begin
  if v_actor is null then
    raise exception 'content_apply_legal_review: authentication required';
  end if;

  if v_role is null or v_role not in ('primary_admin', 'legal_reviewer') then
    raise exception 'content_apply_legal_review: a legal reviewer or primary admin is required (current content role: %)',
      coalesce(v_role, 'none');
  end if;

  if p_decision not in ('approved', 'changes_requested') then
    raise exception 'content_apply_legal_review: decision must be approved or changes_requested, got %', p_decision;
  end if;

  select status into v_status from public.content_posts where post_id = p_post_id;

  if v_status is null then
    raise exception 'content_apply_legal_review: post % does not exist', p_post_id;
  end if;

  -- Fail closed on an ineligible workflow state: a legal reviewer cannot "approve" a draft into
  -- existence, and cannot re-approve something already live.
  if v_status <> 'in_legal_review' then
    raise exception 'content_apply_legal_review: post % is in status %, but legal review can only act on in_legal_review',
      p_post_id, v_status;
  end if;

  v_next_status := case when p_decision = 'approved' then 'approved' else 'changes_requested' end;

  -- Column-scoped by construction. Note published_at/scheduled_for/status-to-published are absent.
  update public.content_posts
  set status = v_next_status,
      legal_approved_at = case when p_decision = 'approved' then now() else null end,
      legal_approved_by = case when p_decision = 'approved' then v_actor else null end
  where post_id = p_post_id;

  insert into public.content_reviews (post_id, review_kind, decision, notes, reviewer_id)
  values (p_post_id, 'legal', p_decision, p_notes, v_actor);

  insert into public.content_audit_events (actor_id, actor_role, action, entity_type, entity_id, detail)
  values (
    v_actor,
    v_role,
    case when p_decision = 'approved' then 'legal_approved' else 'changes_requested' end,
    'content_post',
    p_post_id::text,
    jsonb_build_object('decision', p_decision, 'from_status', v_status, 'to_status', v_next_status)
  );

  return v_next_status;
end;
$$;


ALTER FUNCTION public.content_apply_legal_review(p_post_id uuid, p_decision text, p_notes text) OWNER TO postgres;

