--
-- Name: packet_render_jobs_consumer_binding_immutable(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.packet_render_jobs_consumer_binding_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'UPDATE' then
    if old.consumer_briefcase_item_id is not null
       and new.consumer_briefcase_item_id is distinct from old.consumer_briefcase_item_id then
      raise exception 'packet_render_jobs: consumer_briefcase_item_id is immutable once set';
    end if;
    if old.consumer_auth_user_id is not null
       and new.consumer_auth_user_id is distinct from old.consumer_auth_user_id then
      raise exception 'packet_render_jobs: consumer_auth_user_id is immutable once set';
    end if;
    if old.person_id is not null and new.person_id is distinct from old.person_id then
      raise exception 'packet_render_jobs: person_id is immutable once set';
    end if;
    if old.matter_id is not null and new.matter_id is distinct from old.matter_id then
      raise exception 'packet_render_jobs: matter_id is immutable once set';
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION public.packet_render_jobs_consumer_binding_immutable() OWNER TO postgres;

--
-- Name: packet_render_jobs_guard_transition(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.packet_render_jobs_guard_transition() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  allowed text[];
begin
  if new.status = old.status then
    new.updated_at := now();
    return new;
  end if;

  allowed := case old.status
    when 'queued'             then array['claimed', 'failed']
    when 'claimed'            then array['rendering', 'failed', 'queued']
    when 'rendering'          then array['validating', 'failed']
    when 'validating'         then array['artifact_validated', 'failed']
    when 'artifact_validated' then array['delivered']
    when 'delivered'          then array[]::text[]
    when 'failed'             then array['queued']
    else array[]::text[]
  end;

  if not (new.status = any (allowed)) then
    raise exception
      'illegal packet_render_jobs transition % -> %', old.status, new.status
      using errcode = 'check_violation';
  end if;

  -- Stamp the timestamp for the state being entered.
  new.claimed_at            := case when new.status = 'claimed'            then now() else new.claimed_at end;
  new.rendering_at          := case when new.status = 'rendering'          then now() else new.rendering_at end;
  new.validating_at         := case when new.status = 'validating'         then now() else new.validating_at end;
  new.artifact_validated_at := case when new.status = 'artifact_validated' then now() else new.artifact_validated_at end;
  new.delivered_at          := case when new.status = 'delivered'          then now() else new.delivered_at end;

  -- Releasing a claim clears the holder so the job is claimable again.
  if new.status = 'queued' then
    new.claimed_by := null;
    new.claimed_at := null;
  end if;

  new.updated_at := now();
  return new;
end;
$$;


ALTER FUNCTION public.packet_render_jobs_guard_transition() OWNER TO postgres;

--
-- Name: packet_render_jobs_paid_matter_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.packet_render_jobs_paid_matter_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_valid boolean;
  v_reason text;
begin
  if new.partner_id is not null then return new; end if;
  select a.valid, a.reason into v_valid, v_reason
    from public.consumer_packet_payment_authority(
      new.consumer_briefcase_item_id,
      new.consumer_auth_user_id,
      public.expungement_packet_product_id(),
      new.person_id,
      new.matter_id
    ) a;
  if not coalesce(v_valid, false) then
    raise exception 'packet_render_jobs: consumer payment binding refused (%)', coalesce(v_reason, 'unknown');
  end if;
  return new;
end;
$$;


ALTER FUNCTION public.packet_render_jobs_paid_matter_guard() OWNER TO postgres;

