--
-- Name: rcap_onboarding_derive_authorization_actor(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_onboarding_derive_authorization_actor() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_actor_id uuid;
  v_actor_email text;
begin
  -- Only the service-role submission function can insert authorization rows.
  -- It supplies the actor resolved from the server session; this trigger then
  -- independently revalidates active partner-admin membership, normalizes the
  -- server-session work email, and derives the server timestamp.
  v_actor_id := new.approver_user_id;
  v_actor_email := lower(btrim(new.approver_work_email));

  perform 1
  from public.partner_users pu
  join public.partner_onboarding po
    on po.id = new.workspace_id
   and po.partner_slug = pu.partner_slug
  where pu.auth_user_id = v_actor_id
    and pu.status = 'active'
    and pu.role = 'partner_admin';

  if not found
     or v_actor_id is null
     or nullif(v_actor_email, '') is null
     or char_length(v_actor_email) > 254 then
    raise exception using
      errcode = '42501',
      message = 'Active partner administrator authorization is required';
  end if;

  new.approver_user_id := v_actor_id;
  new.approver_work_email := v_actor_email;
  new.authorization_timestamp := now();
  new.created_at := now();
  return new;
end;
$$;


ALTER FUNCTION public.rcap_onboarding_derive_authorization_actor() OWNER TO postgres;

--
-- Name: rcap_onboarding_derive_idempotency_actor(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_onboarding_derive_idempotency_actor() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if current_user <> 'authenticated' then
    if new.actor_user_id is null then
      raise exception using
        errcode = '23502',
        message = 'Idempotency actor is required';
    end if;
  elsif public.is_internal_admin() then
    if new.actor_user_id is null then
      new.actor_user_id := auth.uid();
    end if;
  else
    if public.current_partner_role() <> 'partner_admin' then
      raise exception using
        errcode = '42501',
        message = 'Active partner administrator is required';
    end if;
    new.actor_user_id := auth.uid();
  end if;
  return new;
end;
$$;


ALTER FUNCTION public.rcap_onboarding_derive_idempotency_actor() OWNER TO postgres;

--
-- Name: rcap_onboarding_guard_change_request_update(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_onboarding_guard_change_request_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.id <> old.id
     or new.workspace_id <> old.workspace_id
     or new.section_id <> old.section_id
     or new.requested_by <> old.requested_by
     or new.requested_at <> old.requested_at
     or new.created_at <> old.created_at then
    raise exception using
      errcode = '23514',
      message = 'Immutable change-request identity cannot be changed';
  end if;

  if public.current_partner_role() = 'partner_admin'
     and not public.is_internal_admin() then
    if old.status not in ('open', 'partner_responded')
       or new.status <> 'partner_responded'
       or new.partner_safe_instructions <> old.partner_safe_instructions
       or new.resolved_by is distinct from old.resolved_by
       or new.resolved_at is distinct from old.resolved_at
       or new.resolution_reason is distinct from old.resolution_reason then
      raise exception using
        errcode = '42501',
        message = 'Partner actors may only respond to an open change request';
    end if;
    new.responded_by := auth.uid();
    new.responded_at := now();
  end if;

  new.updated_at := now();
  return new;
end;
$$;


ALTER FUNCTION public.rcap_onboarding_guard_change_request_update() OWNER TO postgres;

--
-- Name: rcap_onboarding_guard_idempotency_update(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_onboarding_guard_idempotency_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.id <> old.id
     or new.workspace_id <> old.workspace_id
     or new.operation_key <> old.operation_key
     or new.request_id <> old.request_id
     or new.actor_user_id <> old.actor_user_id
     or new.payload_hash <> old.payload_hash
     or new.expires_at <> old.expires_at
     or new.created_at <> old.created_at then
    raise exception using
      errcode = '23514',
      message = 'Idempotency request identity cannot be changed';
  end if;

  if old.result_status <> 'started'
     or new.result_status not in ('succeeded', 'failed')
     or new.completed_at is null then
    raise exception using
      errcode = '23514',
      message = 'Invalid idempotency result transition';
  end if;

  return new;
end;
$$;


ALTER FUNCTION public.rcap_onboarding_guard_idempotency_update() OWNER TO postgres;

--
-- Name: rcap_onboarding_guard_partner_row_mutation(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_onboarding_guard_partner_row_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'UPDATE' then
    if new.workspace_id <> old.workspace_id
       or new.id <> old.id
       or new.created_at <> old.created_at then
      raise exception using
        errcode = '23514',
        message = 'Immutable onboarding row identity cannot be changed';
    end if;

    if new.revision <> old.revision + 1 then
      raise exception using
        errcode = '40001',
        message = 'Onboarding row revision conflict';
    end if;
  end if;

  new.updated_at := now();
  return new;
end;
$$;


ALTER FUNCTION public.rcap_onboarding_guard_partner_row_mutation() OWNER TO postgres;

--
-- Name: rcap_onboarding_guard_section_mutation(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_onboarding_guard_section_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'UPDATE' then
    if new.workspace_id <> old.workspace_id
       or new.section_key <> old.section_key
       or new.created_at <> old.created_at then
      raise exception using
        errcode = '23514',
        message = 'Immutable onboarding section identity cannot be changed';
    end if;

    if new.revision <> old.revision + 1 then
      raise exception using
        errcode = '40001',
        message = 'Onboarding section revision conflict';
    end if;

    if public.current_partner_role() = 'partner_admin'
       and not public.is_internal_admin()
       and (
         new.status in ('approved', 'waived', 'not_applicable')
         or new.approved_at is distinct from old.approved_at
         or new.approved_by is distinct from old.approved_by
         or new.waived_at is distinct from old.waived_at
         or new.waived_by is distinct from old.waived_by
         or new.waiver_reason is distinct from old.waiver_reason
         or new.reviewed_at is distinct from old.reviewed_at
         or new.reviewed_by is distinct from old.reviewed_by
       ) then
      raise exception using
        errcode = '42501',
        message = 'Partner actors cannot set internal section review fields';
    end if;
  end if;

  new.updated_at := now();
  return new;
end;
$$;


ALTER FUNCTION public.rcap_onboarding_guard_section_mutation() OWNER TO postgres;

--
-- Name: rcap_onboarding_prefill_current_value(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_onboarding_prefill_current_value(p_workspace_id uuid, p_section_key text, p_field_key text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  v_value jsonb;
begin
  if p_field_key = 'contacts' and p_section_key = 'organization_contacts' then
    select coalesce(jsonb_agg(
      jsonb_strip_nulls(jsonb_build_object(
        'stable_row_id', c.id,
        'role', c.role,
        'name', c.name,
        'title', c.title,
        'organization', c.organization,
        'work_email', c.work_email,
        'phone', c.phone
      ))
      order by c.created_at, c.id
    ), '[]'::jsonb)
      into v_value
    from public.partner_onboarding_contacts c
    where c.workspace_id = p_workspace_id
      and c.deleted_at is null;
    return v_value;
  end if;

  if p_field_key = 'planned_users'
     and p_section_key = 'staff_dashboard_plan' then
    select coalesce(jsonb_agg(
      jsonb_build_object(
        'stable_row_id', u.id,
        'name', u.name,
        'work_email', u.work_email,
        'requested_role', u.requested_role,
        'special_permissions', to_jsonb(u.special_permissions),
        'training_attendee', u.training_attendee
      )
      order by u.created_at, u.id
    ), '[]'::jsonb)
      into v_value
    from public.partner_onboarding_planned_users u
    where u.workspace_id = p_workspace_id
      and u.deleted_at is null;
    return v_value;
  end if;

  if p_field_key = 'report_recipients'
     and p_section_key = 'support_referrals_reporting' then
    select coalesce(jsonb_agg(
      jsonb_strip_nulls(jsonb_build_object(
        'stable_row_id', r.id,
        'name', r.name,
        'work_email', r.work_email
      ))
      order by r.created_at, r.id
    ), '[]'::jsonb)
      into v_value
    from public.partner_onboarding_report_recipients r
    where r.workspace_id = p_workspace_id
      and r.deleted_at is null;
    return v_value;
  end if;

  select coalesce(s.response_data -> p_field_key, 'null'::jsonb)
    into v_value
  from public.partner_onboarding_sections s
  where s.workspace_id = p_workspace_id
    and s.section_key = p_section_key;
  return coalesce(v_value, 'null'::jsonb);
end;
$$;


ALTER FUNCTION public.rcap_onboarding_prefill_current_value(p_workspace_id uuid, p_section_key text, p_field_key text) OWNER TO postgres;

--
-- Name: rcap_onboarding_prefill_supersede_prior_applied(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_onboarding_prefill_supersede_prior_applied() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.review_status = 'applied' and new.superseded_at is null then
    update public.partner_onboarding_prefill_values prior
    set superseded_at = now()
    where prior.workspace_id = new.workspace_id
      and prior.section_key = new.section_key
      and prior.field_key = new.field_key
      and prior.id <> new.id
      and prior.review_status = 'applied'
      and prior.superseded_at is null;
  end if;
  return new;
end;
$$;


