--
-- Name: rcap_screening_session_is_release_expired(text, timestamp with time zone, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_screening_session_is_release_expired(p_status text, p_created_at timestamp with time zone, p_resume_token_expires_at timestamp with time zone, p_now timestamp with time zone DEFAULT now()) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  select
    p_status in ('in_progress', 'resumed')
    and coalesce(p_resume_token_expires_at, p_created_at + interval '7 days') <= p_now;
$$;


ALTER FUNCTION public.rcap_screening_session_is_release_expired(p_status text, p_created_at timestamp with time zone, p_resume_token_expires_at timestamp with time zone, p_now timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION rcap_screening_session_is_release_expired(p_status text, p_created_at timestamp with time zone, p_resume_token_expires_at timestamp with time zone, p_now timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.rcap_screening_session_is_release_expired(p_status text, p_created_at timestamp with time zone, p_resume_token_expires_at timestamp with time zone, p_now timestamp with time zone) IS 'Shared RCAP slot expiry predicate. Mirrors the 7-day resume-token window, falling back to created_at for sessions with no resume token.';


--
-- Name: rcap_service_apply_onboarding_prefill(text, uuid, uuid, bigint, uuid[], jsonb, integer, text, text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_service_apply_onboarding_prefill(p_partner_slug text, p_actor_user_id uuid, p_workspace_id uuid, p_expected_workspace_version bigint, p_selected_value_ids uuid[], p_section_updates jsonb, p_workspace_completion integer, p_blocker_code text, p_next_action_code text, p_next_action_owner text, p_request_id uuid, p_payload_hash text) RETURNS TABLE(workspace_aggregate_version bigint, result jsonb, duplicate boolean)
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
declare
  v_workspace public.partner_onboarding%rowtype;
  v_existing public.partner_onboarding_idempotency%rowtype;
  v_value public.partner_onboarding_prefill_values%rowtype;
  v_section public.partner_onboarding_sections%rowtype;
  v_update jsonb;
  v_value_id uuid;
  v_applied uuid[] := '{}'::uuid[];
  v_conflicts uuid[] := '{}'::uuid[];
  v_skipped uuid[] := '{}'::uuid[];
  v_update_ids uuid[];
  v_new_revision bigint;
  v_applied_count integer := 0;
  v_conflict_count integer := 0;
begin
  perform public.rcap_studio_assert_prepare(p_actor_user_id,p_partner_slug);
  if p_expected_workspace_version < 1
     or p_selected_value_ids is null
     or cardinality(p_selected_value_ids) < 1
     or cardinality(p_selected_value_ids) > 200
     or p_section_updates is null
     or jsonb_typeof(p_section_updates) <> 'array'
     or p_workspace_completion not between 0 and 100
     or p_next_action_owner not in ('partner', 'legalease', 'none')
     or p_payload_hash !~ '^[0-9a-f]{64}$' then
    raise exception using errcode = '22023', message = 'Invalid prefill apply request';
  end if;

  select *
    into v_existing
  from public.partner_onboarding_idempotency i
  where i.request_id = p_request_id
  for update;
  if found then
    if v_existing.workspace_id <> p_workspace_id
       or v_existing.operation_key <> 'prefill_apply'
       or v_existing.actor_user_id <> p_actor_user_id
       or v_existing.payload_hash <> p_payload_hash then
      raise exception using
        errcode = '23505',
        message = 'Idempotency request does not match original mutation';
    end if;
    if v_existing.result_status = 'succeeded' then
      workspace_aggregate_version := v_existing.result_workspace_version;
      result := jsonb_build_object(
        'appliedIds', '[]'::jsonb,
        'conflictIds', '[]'::jsonb,
        'skippedIds', '[]'::jsonb,
        'replayed', true
      );
      duplicate := true;
      return next;
      return;
    end if;
  end if;

  select po.*
    into v_workspace
  from public.partner_onboarding po
  where po.id = p_workspace_id
    and po.partner_slug = p_partner_slug
  for update of po;
  if not found or v_workspace.partner_record_id is null then
    raise exception using errcode = 'P0002', message = 'Onboarding workspace not found';
  end if;
  if v_workspace.aggregate_version <> p_expected_workspace_version then
    raise exception using errcode = '40001', message = 'Onboarding workspace revision conflict';
  end if;
  if v_workspace.status not in ('draft', 'commercially_blocked', 'setup_in_progress') then
    raise exception using errcode = '55000', message = 'Onboarding workspace is not eligible for prefill';
  end if;

  insert into public.partner_onboarding_idempotency (
    workspace_id,
    operation_key,
    request_id,
    actor_user_id,
    payload_hash,
    expires_at
  ) values (
    p_workspace_id,
    'prefill_apply',
    p_request_id,
    p_actor_user_id,
    p_payload_hash,
    now() + interval '24 hours'
  );

  foreach v_value_id in array p_selected_value_ids loop
    select pv.*
      into v_value
    from public.partner_onboarding_prefill_values pv
    where pv.id = v_value_id
      and pv.workspace_id = p_workspace_id
    for update;

    if not found
       or v_value.review_status <> 'approved'
       or v_value.superseded_at is not null
       or v_value.partner_review_status <> 'not_applied' then
      v_skipped := array_append(v_skipped, v_value_id);
      continue;
    end if;

    select s.*
      into v_section
    from public.partner_onboarding_sections s
    where s.workspace_id = p_workspace_id
      and s.section_key = v_value.section_key
    for update;

    if not found
       or v_section.status not in ('not_started', 'in_progress')
       or v_section.revision <> v_value.base_section_revision then
      update public.partner_onboarding_prefill_values
      set
        review_status = 'conflict',
        reviewed_by = p_actor_user_id,
        reviewed_at = now()
      where id = v_value_id;
      v_conflicts := array_append(v_conflicts, v_value_id);
      v_conflict_count := v_conflict_count + 1;
      continue;
    end if;
  end loop;

  for v_update in
    select item
    from jsonb_array_elements(p_section_updates) item
  loop
    select coalesce(array_agg(value::uuid), '{}'::uuid[])
      into v_update_ids
    from jsonb_array_elements_text(
      coalesce(v_update->'valueIds', '[]'::jsonb)
    ) value;

    if cardinality(v_update_ids) = 0
       or v_update_ids && v_conflicts
       or v_update_ids && v_skipped then
      continue;
    end if;

    select s.*
      into v_section
    from public.partner_onboarding_sections s
    where s.workspace_id = p_workspace_id
      and s.section_key = v_update->>'sectionKey'
    for update;
    if not found
       or v_section.status not in ('not_started', 'in_progress')
       or v_section.revision <> (v_update->>'expectedRevision')::bigint then
      update public.partner_onboarding_prefill_values
      set
        review_status = 'conflict',
        reviewed_by = p_actor_user_id,
        reviewed_at = now()
      where id = any(v_update_ids)
        and review_status = 'approved';
      v_conflicts := v_conflicts || v_update_ids;
      v_conflict_count := v_conflict_count + cardinality(v_update_ids);
      continue;
    end if;

    foreach v_value_id in array v_update_ids loop
      select pv.*
        into v_value
      from public.partner_onboarding_prefill_values pv
      where pv.id = v_value_id
        and pv.workspace_id = p_workspace_id
        and pv.review_status = 'approved'
      for update;

      if not found
         or not (coalesce(v_update->'baseValues', '{}'::jsonb) ? v_value_id::text)
         or public.rcap_onboarding_prefill_current_value(
           p_workspace_id, v_value.section_key, v_value.field_key
         ) is distinct from v_update->'baseValues'->v_value_id::text then
        update public.partner_onboarding_prefill_values
        set
          review_status = 'conflict',
          reviewed_by = p_actor_user_id,
          reviewed_at = now()
        where id = v_value_id
          and review_status = 'approved';
        v_conflicts := array_append(v_conflicts, v_value_id);
        v_conflict_count := v_conflict_count + 1;
      end if;
    end loop;

    if v_update_ids && v_conflicts then
      continue;
    end if;

    v_new_revision := v_section.revision + 1;
    update public.partner_onboarding_sections
    set
      response_data = v_update->'responseData',
      revision = v_new_revision,
      status = 'in_progress',
      completion_percentage = (v_update->>'completionPercentage')::integer,
      missing_required_keys = coalesce(
        array(
          select jsonb_array_elements_text(
            coalesce(v_update->'missingRequiredKeys', '[]'::jsonb)
          )
        ),
        '{}'::text[]
      ),
      first_started_at = coalesce(first_started_at, now())
    where id = v_section.id;

    if v_section.section_key = 'organization_contacts' then
      update public.partner_onboarding_contacts c
      set deleted_at = now(), revision = c.revision + 1
      where c.workspace_id = p_workspace_id
        and c.deleted_at is null
        and not exists (
          select 1
          from jsonb_array_elements(
            coalesce(v_update->'collections'->'contacts', '[]'::jsonb)
          ) item
          where item->>'stable_row_id' = c.id::text
        );
      insert into public.partner_onboarding_contacts (
        id, workspace_id, role, name, title, organization, work_email, phone
      )
      select
        (item->>'stable_row_id')::uuid,
        p_workspace_id,
        item->>'role',
        item->>'name',
        item->>'title',
        nullif(item->>'organization', ''),
        lower(item->>'work_email'),
        nullif(item->>'phone', '')
      from jsonb_array_elements(
        coalesce(v_update->'collections'->'contacts', '[]'::jsonb)
      ) item
      on conflict (id) do update
      set
        role = excluded.role,
        name = excluded.name,
        title = excluded.title,
        organization = excluded.organization,
        work_email = excluded.work_email,
        phone = excluded.phone,
        revision = public.partner_onboarding_contacts.revision + 1,
        deleted_at = null
      where public.partner_onboarding_contacts.workspace_id = p_workspace_id;
    elsif v_section.section_key = 'staff_dashboard_plan' then
      update public.partner_onboarding_planned_users u
      set deleted_at = now(), revision = u.revision + 1
      where u.workspace_id = p_workspace_id
        and u.deleted_at is null
        and not exists (
          select 1
          from jsonb_array_elements(
            coalesce(v_update->'collections'->'planned_users', '[]'::jsonb)
          ) item
          where item->>'stable_row_id' = u.id::text
        );
      insert into public.partner_onboarding_planned_users (
        id, workspace_id, name, work_email, requested_role,
        special_permissions, training_attendee
      )
      select
        (item->>'stable_row_id')::uuid,
        p_workspace_id,
        item->>'name',
        lower(item->>'work_email'),
        item->>'requested_role',
        coalesce(array(
          select jsonb_array_elements_text(
            coalesce(item->'special_permissions', '[]'::jsonb)
          )
        ), '{}'::text[]),
        coalesce((item->>'training_attendee')::boolean, false)
      from jsonb_array_elements(
        coalesce(v_update->'collections'->'planned_users', '[]'::jsonb)
      ) item
      on conflict (id) do update
      set
        name = excluded.name,
        work_email = excluded.work_email,
        requested_role = excluded.requested_role,
        special_permissions = excluded.special_permissions,
        training_attendee = excluded.training_attendee,
        revision = public.partner_onboarding_planned_users.revision + 1,
        deleted_at = null
      where public.partner_onboarding_planned_users.workspace_id = p_workspace_id;
    elsif v_section.section_key = 'support_referrals_reporting' then
      update public.partner_onboarding_report_recipients r
      set deleted_at = now(), revision = r.revision + 1
      where r.workspace_id = p_workspace_id
        and r.deleted_at is null
        and not exists (
          select 1
          from jsonb_array_elements(
            coalesce(v_update->'collections'->'report_recipients', '[]'::jsonb)
          ) item
          where item->>'stable_row_id' = r.id::text
        );
      insert into public.partner_onboarding_report_recipients (
        id, workspace_id, name, work_email
      )
      select
        (item->>'stable_row_id')::uuid,
        p_workspace_id,
        nullif(item->>'name', ''),
        lower(item->>'work_email')
      from jsonb_array_elements(
        coalesce(v_update->'collections'->'report_recipients', '[]'::jsonb)
      ) item
      on conflict (id) do update
      set
        name = excluded.name,
        work_email = excluded.work_email,
        revision = public.partner_onboarding_report_recipients.revision + 1,
        deleted_at = null
      where public.partner_onboarding_report_recipients.workspace_id = p_workspace_id;
    end if;

    update public.partner_onboarding_prefill_values
    set
      review_status = 'applied',
      applied_value_hash = proposed_value_hash,
      applied_section_revision = v_new_revision,
      applied_workspace_version = p_expected_workspace_version + 1,
      partner_review_status = 'pending',
      applied_at = now()
    where id = any(v_update_ids)
      and review_status = 'approved';

    v_applied := v_applied || v_update_ids;
    v_applied_count := v_applied_count + cardinality(v_update_ids);
  end loop;

  foreach v_value_id in array p_selected_value_ids loop
    if not (v_value_id = any(v_applied))
       and not (v_value_id = any(v_conflicts))
       and not (v_value_id = any(v_skipped)) then
      update public.partner_onboarding_prefill_values
      set
        review_status = 'conflict',
        reviewed_by = p_actor_user_id,
        reviewed_at = now()
      where id = v_value_id
        and workspace_id = p_workspace_id
        and review_status = 'approved';
      if found then
        v_conflicts := array_append(v_conflicts, v_value_id);
        v_conflict_count := v_conflict_count + 1;
      else
        v_skipped := array_append(v_skipped, v_value_id);
      end if;
    end if;
  end loop;

  if v_applied_count > 0 then
    update public.partner_onboarding
    set
      aggregate_version = aggregate_version + 1,
      completion_percentage = p_workspace_completion,
      blocker_code = p_blocker_code,
      next_action_code = p_next_action_code,
      next_action_owner = p_next_action_owner,
      last_meaningful_activity_at = now()
    where id = p_workspace_id
    returning aggregate_version into workspace_aggregate_version;

    update public.partner_onboarding_prefill_values
    set applied_workspace_version = workspace_aggregate_version
    where id = any(v_applied);

    update public.partner_onboarding_prefill_batches b
    set
      aggregate_version = aggregate_version + 1,
      status = case
        when exists (
          select 1 from public.partner_onboarding_prefill_values pv
          where pv.batch_id = b.id
            and pv.review_status in ('proposed', 'approved', 'conflict')
        ) then 'partially_applied'
        else 'applied'
      end,
      applied_at = coalesce(applied_at, now())
    where exists (
      select 1
      from public.partner_onboarding_prefill_values pv
      where pv.batch_id = b.id
        and pv.id = any(v_applied)
    );

    insert into public.partner_onboarding_activity (
      workspace_id, event_type, status_code, summary_code, owner_type,
      actor_user_id, request_id, dedupe_key
    ) values (
      p_workspace_id, 'prefill_applied', 'pending_partner_review',
      'prefill_applied', 'legalease', p_actor_user_id, p_request_id,
      p_request_id::text || ':prefill_applied'
    );

    insert into public.partner_onboarding_integration_events (
      workspace_id, partner_record_id, event_type,
      workspace_aggregate_version, workspace_status,
      completion_percentage, blocker_code, next_action_code,
      next_action_owner, target_launch_date, idempotency_key
    )
    select
      po.id, po.partner_record_id, 'rcap_onboarding_prefill_applied',
      po.aggregate_version, po.status, po.completion_percentage,
      po.blocker_code, po.next_action_code, po.next_action_owner,
      po.target_launch_date, p_request_id::text || ':prefill_applied'
    from public.partner_onboarding po
    where po.id = p_workspace_id;
  else
    workspace_aggregate_version := v_workspace.aggregate_version;
  end if;

  if v_conflict_count > 0 then
    insert into public.partner_onboarding_activity (
      workspace_id, event_type, status_code, summary_code, owner_type,
      actor_user_id, request_id, dedupe_key
    ) values (
      p_workspace_id, 'prefill_apply_conflict', 'conflict',
      'prefill_apply_conflict', 'legalease', p_actor_user_id, p_request_id,
      p_request_id::text || ':prefill_apply_conflict'
    );
  end if;

  result := jsonb_build_object(
    'appliedIds', to_jsonb(v_applied),
    'conflictIds', to_jsonb(v_conflicts),
    'skippedIds', to_jsonb(v_skipped)
  );
  update public.partner_onboarding_idempotency
  set
    result_status = 'succeeded',
    result_workspace_version = workspace_aggregate_version,
    completed_at = now()
  where request_id = p_request_id;
  duplicate := false;
  return next;
end;
$_$;


ALTER FUNCTION public.rcap_service_apply_onboarding_prefill(p_partner_slug text, p_actor_user_id uuid, p_workspace_id uuid, p_expected_workspace_version bigint, p_selected_value_ids uuid[], p_section_updates jsonb, p_workspace_completion integer, p_blocker_code text, p_next_action_code text, p_next_action_owner text, p_request_id uuid, p_payload_hash text) OWNER TO postgres;

--
-- Name: rcap_service_assert_internal_actor(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_service_assert_internal_actor(p_actor_user_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
begin
  if p_actor_user_id is null
     or not exists (
       select 1
       from public.partner_users pu
       where pu.auth_user_id = p_actor_user_id
         and pu.partner_slug is null
         and pu.role = 'internal_admin'
         and pu.status = 'active'
     ) then
    raise exception using
      errcode = '42501',
      message = 'Active internal administrator is required';
  end if;
end;
$$;


ALTER FUNCTION public.rcap_service_assert_internal_actor(p_actor_user_id uuid) OWNER TO postgres;

--
-- Name: rcap_service_assert_partner_actor(text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_service_assert_partner_actor(p_partner_slug text, p_actor_user_id uuid, p_workspace_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
begin
  if p_partner_slug is null
     or p_actor_user_id is null
     or p_workspace_id is null
     or not exists (
       select 1
       from public.partner_users pu
       join public.partner_onboarding po
         on po.partner_slug = pu.partner_slug
       where pu.auth_user_id = p_actor_user_id
         and pu.partner_slug = p_partner_slug
         and pu.role = 'partner_admin'
         and pu.status = 'active'
         and po.id = p_workspace_id
     ) then
    raise exception using
      errcode = '42501',
      message = 'Active partner administrator does not match onboarding workspace';
  end if;
end;
$$;


ALTER FUNCTION public.rcap_service_assert_partner_actor(p_partner_slug text, p_actor_user_id uuid, p_workspace_id uuid) OWNER TO postgres;

--
-- Name: rcap_service_compensate_real_launch(text, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_service_compensate_real_launch(p_slug text, p_actor uuid, p_operation uuid, p_hash text) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare e public.rcap_launch_operation_events%rowtype; begin
 perform public.rcap_service_assert_internal_actor(p_actor);
 select ev.* into strict e from public.rcap_launch_operation_events ev join public.partner_onboarding w on w.id=ev.workspace_id where ev.partner_slug=p_slug and ev.operation_id=p_operation and ev.step='prepared' and ev.actor_auth_user_id=p_actor and ev.snapshot_hash=p_hash and ev.evidence->>'mode'='real' for update of w;
 if exists(select 1 from public.rcap_launch_operation_events where operation_id=p_operation and step='complete') then raise exception 'completed operation cannot compensate'; end if;
 if exists(select 1 from public.partner_onboarding where id=e.workspace_id and rcap_launch_operation_id=p_operation) then
 update public.partner_records set onboarding_status=e.evidence->'previousLegacyOnboarding'->>'onboarding_status',onboarding_completed_at=(e.evidence->'previousLegacyOnboarding'->>'onboarding_completed_at')::timestamptz where partner_slug=p_slug;
 end if;
 -- Retain the operation marker so an uncertain failure cannot expose a page.
 update public.partner_onboarding set status=e.evidence->'previousPublication'->>'status',landing_page_ready=false,internal_approved_at=(e.evidence->'previousPublication'->>'internal_approved_at')::timestamptz,launched_at=(e.evidence->'previousPublication'->>'launched_at')::timestamptz where id=e.workspace_id and rcap_launch_operation_id=p_operation;
 return true;
end $$;


ALTER FUNCTION public.rcap_service_compensate_real_launch(p_slug text, p_actor uuid, p_operation uuid, p_hash text) OWNER TO postgres;

--
-- Name: rcap_service_compensate_synthetic_launch(text, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_service_compensate_synthetic_launch(p_slug text, p_actor uuid, p_operation uuid, p_hash text) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare v_event public.rcap_launch_operation_events%rowtype; begin
 perform public.rcap_service_assert_internal_actor(p_actor);
 select e.* into strict v_event from public.rcap_launch_operation_events e join public.partner_onboarding po on po.id=e.workspace_id where e.partner_slug=p_slug and e.operation_id=p_operation and e.step='prepared' and e.actor_auth_user_id=p_actor and e.snapshot_hash=p_hash for update of po;
 if exists(select 1 from public.rcap_launch_operation_events where operation_id=p_operation and step='complete') then raise exception 'completed operation cannot compensate'; end if;
 if not exists(select 1 from public.rcap_launch_operation_events where operation_id=p_operation and step='publication_staged') then return true; end if;
 update public.partner_onboarding set status=v_event.evidence->'previousPublication'->>'status',landing_page_ready=(v_event.evidence->'previousPublication'->>'landing_page_ready')::boolean,internal_approved_at=(v_event.evidence->'previousPublication'->>'internal_approved_at')::timestamptz,launched_at=(v_event.evidence->'previousPublication'->>'launched_at')::timestamptz where id=v_event.workspace_id;
 return true;
end $$;


ALTER FUNCTION public.rcap_service_compensate_synthetic_launch(p_slug text, p_actor uuid, p_operation uuid, p_hash text) OWNER TO postgres;

--
-- Name: rcap_service_configure_launch_capacity(text, uuid, uuid, text, integer, integer, text, uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_service_configure_launch_capacity(p_slug text, p_actor uuid, p_document uuid, p_hash text, p_screenings integer, p_packets integer, p_reference text, p_request uuid, p_version bigint) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare w public.partner_onboarding%rowtype; old public.rcap_launch_capacity_events%rowtype; previous jsonb; begin
 perform public.rcap_service_assert_internal_actor(p_actor);
 select * into strict w from public.partner_onboarding where partner_slug=p_slug for update;
 select * into old from public.rcap_launch_capacity_events where workspace_id=w.id and request_id=p_request;
 if found then if old.actor_auth_user_id<>p_actor or old.document_id<>p_document or old.document_hash<>p_hash or old.screenings_allowed<>p_screenings or old.packet_cap<>p_packets or old.authority_reference<>p_reference then raise exception 'capacity request binding conflict'; end if;return true;end if;
 if w.status='live' or w.landing_page_ready or w.aggregate_version<>p_version then raise exception 'publication or source changed'; end if;
 if exists(select 1 from public.rcap_launch_operation_events e where e.workspace_id=w.id and e.step='prepared' and not exists(select 1 from public.rcap_launch_operation_events t where t.operation_id=e.operation_id and t.step in ('complete','held','failed'))) then raise exception 'launch in progress'; end if;
 perform 1 from public.partner_entitlement where partner_slug=p_slug for update;
 perform 1 from public.partner_packet_entitlement where partner_id=w.partner_record_id and entitlement_scope='sponsored_packets' and expires_at is null for update;
 previous:=jsonb_build_object('screening',(select to_jsonb(e) from public.partner_entitlement e where e.partner_slug=p_slug),'packet',(select to_jsonb(e) from public.partner_packet_entitlement e where e.partner_id=w.partner_record_id and e.entitlement_scope='sponsored_packets' and e.expires_at is null));
 insert into public.rcap_launch_capacity_events(workspace_id,actor_auth_user_id,document_id,document_hash,screenings_allowed,packet_cap,authority_reference,request_id,previous_capacity) values(w.id,p_actor,p_document,p_hash,p_screenings,p_packets,p_reference,p_request,previous);
 insert into public.partner_entitlement(partner_slug,screenings_allowed,contract_note) values(p_slug,p_screenings,p_reference) on conflict(partner_slug) do update set screenings_allowed=excluded.screenings_allowed,contract_note=excluded.contract_note;
 if exists(select 1 from public.partner_packet_entitlement where partner_id=w.partner_record_id and entitlement_scope='sponsored_packets' and expires_at is null) then
 update public.partner_packet_entitlement set packet_cap=p_packets where partner_id=w.partner_record_id and entitlement_scope='sponsored_packets' and expires_at is null;
 else insert into public.partner_packet_entitlement(partner_id,entitlement_scope,packet_cap,contract_note) values(w.partner_record_id,'sponsored_packets',p_packets,p_reference);end if;
 update public.partner_onboarding set aggregate_version=aggregate_version+1 where id=w.id;
 update public.partner_onboarding_launch_checks set invalidated_at=now(),invalidated_reason='Documented allocation changed' where workspace_id=w.id;
 update public.partner_onboarding_launch_approvals set invalidated_at=now() where workspace_id=w.id;
 return true;
end $$;


ALTER FUNCTION public.rcap_service_configure_launch_capacity(p_slug text, p_actor uuid, p_document uuid, p_hash text, p_screenings integer, p_packets integer, p_reference text, p_request uuid, p_version bigint) OWNER TO postgres;

--
-- Name: rcap_service_create_onboarding_workspace(text, uuid, uuid, date, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_service_create_onboarding_workspace(p_partner_slug text, p_actor_user_id uuid, p_request_id uuid, p_target_launch_date date, p_schema_version text, p_payload_hash text) RETURNS TABLE(workspace_id uuid, workspace_status text, created boolean)
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
declare
  v_partner public.partner_records%rowtype;
  v_workspace public.partner_onboarding%rowtype;
  v_existing public.partner_onboarding_idempotency%rowtype;
  v_created boolean := false;
  v_gate text;
  v_status text;
begin
  perform public.rcap_service_assert_internal_actor(p_actor_user_id);
  if nullif(btrim(p_partner_slug), '') is null
     or nullif(btrim(p_schema_version), '') is null
     or p_payload_hash !~ '^[0-9a-f]{64}$' then
    raise exception using errcode = '22023', message = 'Invalid workspace creation request';
  end if;

  select *
    into v_partner
  from public.partner_records pr
  where pr.partner_slug = p_partner_slug
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'Partner not found';
  end if;

  select *
    into v_existing
  from public.partner_onboarding_idempotency i
  where i.request_id = p_request_id
  for update;
  if found then
    if v_existing.operation_key <> 'workspace:create:' || p_partner_slug
       or v_existing.actor_user_id <> p_actor_user_id
       or v_existing.payload_hash <> p_payload_hash then
      raise exception using errcode = '23505', message = 'Idempotency request mismatch';
    end if;
    return query
    select
      po.id,
      po.status,
      false
    from public.partner_onboarding po
    where po.id = v_existing.workspace_id;
    return;
  end if;

  select *
    into v_workspace
  from public.partner_onboarding po
  where po.partner_slug = p_partner_slug
  for update;

  v_gate := case
    when v_partner.payment_status = 'paid' then 'cleared_by_paid_invoice'
    else 'blocked'
  end;
  v_status := case
    when v_gate = 'blocked' then 'commercially_blocked'
    else 'setup_in_progress'
  end;

  if not found then
    insert into public.partner_onboarding (
      partner_slug,
      partner_record_id,
      status,
      schema_version,
      aggregate_version,
      completion_percentage,
      blocker_code,
      next_action_code,
      next_action_owner,
      target_launch_date,
      target_launch_date_reason,
      target_launch_date_changed_at,
      target_launch_date_changed_by,
      commercial_gate_status,
      commercial_gate_evidence_reference,
      commercial_gate_changed_at,
      commercial_gate_changed_by,
      last_meaningful_activity_at
    ) values (
      p_partner_slug,
      v_partner.id,
      v_status,
      p_schema_version,
      1,
      0,
      case when v_gate = 'blocked' then 'commercial_gate_blocked' end,
      case
        when v_gate = 'blocked' then 'complete_commercial_requirements'
        else 'complete_section'
      end,
      'partner',
      p_target_launch_date,
      case
        when p_target_launch_date is not null then 'Set during workspace creation.'
        else null
      end,
      case when p_target_launch_date is not null then now() else null end,
      case when p_target_launch_date is not null then p_actor_user_id else null end,
      v_gate,
      case
        when v_gate = 'cleared_by_paid_invoice'
          then 'partner_record:' || v_partner.id::text
        else null
      end,
      now(),
      p_actor_user_id,
      now()
    )
    returning * into v_workspace;
    v_created := true;
  else
    update public.partner_onboarding
    set
      partner_record_id = v_partner.id,
      schema_version = p_schema_version,
      target_launch_date = coalesce(p_target_launch_date, target_launch_date),
      target_launch_date_reason = case
        when p_target_launch_date is not null then 'Set during workspace creation.'
        else target_launch_date_reason
      end,
      target_launch_date_changed_at = case
        when p_target_launch_date is not null then now()
        else target_launch_date_changed_at
      end,
      target_launch_date_changed_by = case
        when p_target_launch_date is not null then p_actor_user_id
        else target_launch_date_changed_by
      end,
      status = case
        when status in ('draft', 'commercially_blocked') then v_status
        else status
      end,
      commercial_gate_status = case
        when status in ('draft', 'commercially_blocked')
             or commercial_gate_changed_at is null then v_gate
        else commercial_gate_status
      end,
      commercial_gate_evidence_reference = case
        when status in ('draft', 'commercially_blocked')
             and v_gate = 'cleared_by_paid_invoice'
          then 'partner_record:' || v_partner.id::text
        when commercial_gate_changed_at is null
             and v_gate = 'cleared_by_paid_invoice'
          then 'partner_record:' || v_partner.id::text
        when status in ('draft', 'commercially_blocked') then null
        when commercial_gate_changed_at is null then null
        else commercial_gate_evidence_reference
      end,
      blocker_code = case
        when (
          status in ('draft', 'commercially_blocked')
          or commercial_gate_changed_at is null
        ) and v_gate = 'blocked'
          then 'commercial_gate_blocked'
        when status in ('live', 'paused', 'closed', 'ready_for_review', 'ready_to_launch')
             and commercial_gate_changed_at is null then null
        when status in ('draft', 'commercially_blocked')
             or commercial_gate_changed_at is null
          then 'required_section_incomplete'
        else blocker_code
      end,
      next_action_code = case
        when (
          status in ('draft', 'commercially_blocked')
          or commercial_gate_changed_at is null
        ) and v_gate = 'blocked'
          then 'complete_commercial_requirements'
        when status = 'ready_for_review'
             and commercial_gate_changed_at is null
          then 'await_legalease_review'
        when status = 'ready_to_launch'
             and commercial_gate_changed_at is null
          then 'prepare_for_launch'
        when status = 'live'
             and commercial_gate_changed_at is null
          then 'program_live'
        when status = 'paused'
             and commercial_gate_changed_at is null
          then 'program_paused'
        when status = 'closed'
             and commercial_gate_changed_at is null
          then 'onboarding_closed'
        when status in ('draft', 'commercially_blocked')
             or commercial_gate_changed_at is null
          then 'complete_section'
        else next_action_code
      end,
      next_action_owner = case
        when (
          status in ('draft', 'commercially_blocked')
          or commercial_gate_changed_at is null
        ) and v_gate = 'blocked'
          then 'partner'
        when status in ('ready_for_review', 'ready_to_launch', 'paused')
             and commercial_gate_changed_at is null
          then 'legalease'
        when status in ('live', 'closed')
             and commercial_gate_changed_at is null
          then 'none'
        when status in ('draft', 'commercially_blocked')
             or commercial_gate_changed_at is null
          then 'partner'
        else next_action_owner
      end,
      commercial_gate_changed_at = case
        when status in ('draft', 'commercially_blocked')
             or commercial_gate_changed_at is null then now()
        else commercial_gate_changed_at
      end,
      commercial_gate_changed_by = case
        when status in ('draft', 'commercially_blocked')
             or commercial_gate_changed_at is null then p_actor_user_id
        else commercial_gate_changed_by
      end,
      aggregate_version = aggregate_version + 1,
      last_meaningful_activity_at = coalesce(last_meaningful_activity_at, now())
    where id = v_workspace.id
    returning * into v_workspace;
  end if;

  insert into public.partner_onboarding_sections (
    workspace_id,
    section_key,
    response_data,
    revision,
    status,
    completion_percentage,
    missing_required_keys
  )
  select
    v_workspace.id,
    section_key,
    '{}'::jsonb,
    1,
    'not_started',
    0,
    '{}'::text[]
  from unnest(array[
    'organization_contacts',
    'program_goals',
    'geography_audience_language_accessibility',
    'access_sponsorship_capacity',
    'brand_public_page',
    'staff_dashboard_plan',
    'support_referrals_reporting',
    'review_authorization'
  ]::text[]) section_key
  on conflict on constraint partner_onboarding_sections_workspace_key_unique
  do nothing;

  insert into public.partner_onboarding_idempotency (
    workspace_id,
    operation_key,
    request_id,
    actor_user_id,
    payload_hash,
    result_status,
    result_workspace_version,
    expires_at,
    completed_at
  ) values (
    v_workspace.id,
    'workspace:create:' || p_partner_slug,
    p_request_id,
    p_actor_user_id,
    p_payload_hash,
    'succeeded',
    v_workspace.aggregate_version,
    now() + interval '24 hours',
    now()
  );

  insert into public.partner_onboarding_activity (
    workspace_id,
    event_type,
    status_code,
    summary_code,
    owner_type,
    actor_user_id,
    request_id,
    dedupe_key
  ) values (
    v_workspace.id,
    'workspace_created',
    v_workspace.status,
    'workspace_created',
    'legalease',
    p_actor_user_id,
    p_request_id,
    'workspace-created'
  )
  on conflict do nothing;

  insert into public.partner_onboarding_integration_events (
    workspace_id,
    partner_record_id,
    event_type,
    workspace_aggregate_version,
    workspace_status,
    completion_percentage,
    blocker_code,
    next_action_code,
    next_action_owner,
    target_launch_date,
    idempotency_key
  ) values (
    v_workspace.id,
    v_partner.id,
    'rcap_partner_workspace_created',
    v_workspace.aggregate_version,
    v_workspace.status,
    v_workspace.completion_percentage,
    v_workspace.blocker_code,
    v_workspace.next_action_code,
    v_workspace.next_action_owner,
    v_workspace.target_launch_date,
    p_request_id::text || ':workspace-created'
  )
  on conflict do nothing;

  workspace_id := v_workspace.id;
  workspace_status := v_workspace.status;
  created := v_created;
  return next;
end;
$_$;


ALTER FUNCTION public.rcap_service_create_onboarding_workspace(p_partner_slug text, p_actor_user_id uuid, p_request_id uuid, p_target_launch_date date, p_schema_version text, p_payload_hash text) OWNER TO postgres;

--
-- Name: rcap_service_delete_onboarding_asset(text, uuid, uuid, uuid, bigint, text, integer, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_service_delete_onboarding_asset(p_partner_slug text, p_actor_user_id uuid, p_workspace_id uuid, p_asset_id uuid, p_expected_workspace_version bigint, p_payload_hash text, p_workspace_completion integer, p_blocker_code text, p_next_action_code text, p_next_action_owner text, p_request_id uuid) RETURNS TABLE(object_path text, workspace_aggregate_version bigint, duplicate boolean)
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
declare
  v_workspace public.partner_onboarding%rowtype;
  v_asset public.partner_onboarding_assets%rowtype;
  v_existing public.partner_onboarding_idempotency%rowtype;
  v_partner_record_id uuid;
begin
  perform public.rcap_service_assert_partner_actor(
    p_partner_slug, p_actor_user_id, p_workspace_id
  );
  if p_expected_workspace_version < 1
     or p_payload_hash !~ '^[0-9a-f]{64}$'
     or p_workspace_completion not between 0 and 100
     or p_next_action_owner not in ('partner', 'legalease', 'none') then
    raise exception using
      errcode = '22023',
      message = 'Invalid organizational asset deletion summary';
  end if;

  select *
    into v_existing
  from public.partner_onboarding_idempotency i
  where i.request_id = p_request_id
  for update;
  if found then
    if v_existing.workspace_id <> p_workspace_id
       or v_existing.operation_key <> 'asset:delete'
       or v_existing.actor_user_id <> p_actor_user_id
       or v_existing.payload_hash <> p_payload_hash then
      raise exception using errcode = '23505', message = 'Idempotency request mismatch';
    end if;
    return query
    select
      a.object_path,
      v_existing.result_workspace_version,
      true
    from public.partner_onboarding_assets a
    where a.id = p_asset_id
      and a.workspace_id = p_workspace_id;
    return;
  end if;

  select *
    into v_workspace
  from public.partner_onboarding po
  where po.id = p_workspace_id
    and po.partner_slug = p_partner_slug
  for update;
  if not found
     or v_workspace.commercial_gate_status = 'blocked'
     or v_workspace.status not in ('setup_in_progress', 'waiting_on_partner') then
    raise exception using errcode = '55000', message = 'Workspace is not editable';
  end if;
  if v_workspace.aggregate_version <> p_expected_workspace_version then
    raise exception using
      errcode = '40001',
      message = 'Onboarding workspace revision conflict';
  end if;
  select coalesce(v_workspace.partner_record_id, pr.id)
    into v_partner_record_id
  from public.partner_records pr
  where pr.partner_slug = p_partner_slug;

  select *
    into v_asset
  from public.partner_onboarding_assets a
  where a.id = p_asset_id
    and a.workspace_id = p_workspace_id
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'Organizational asset not found';
  end if;
  if exists (
    select 1
    from public.partner_onboarding_agreements agreement
    where agreement.finalized_asset_id = v_asset.id
  ) then
    raise exception using
      errcode = '55000',
      message = 'A finalized agreement document cannot be removed';
  end if;

  insert into public.partner_onboarding_idempotency (
    workspace_id,
    operation_key,
    request_id,
    actor_user_id,
    payload_hash,
    expires_at
  ) values (
    p_workspace_id,
    'asset:delete',
    p_request_id,
    p_actor_user_id,
    p_payload_hash,
    now() + interval '24 hours'
  );

  if v_asset.deleted_at is null then
    update public.partner_onboarding_assets
    set
      lifecycle_status = 'deleted',
      deleted_by = p_actor_user_id,
      deleted_at = now(),
      deletion_reason = 'partner_removed',
      updated_at = now()
    where id = p_asset_id;

    update public.partner_onboarding
    set
      aggregate_version = aggregate_version + 1,
      completion_percentage = p_workspace_completion,
      blocker_code = p_blocker_code,
      next_action_code = p_next_action_code,
      next_action_owner = p_next_action_owner,
      last_meaningful_activity_at = now()
    where id = p_workspace_id
    returning aggregate_version into workspace_aggregate_version;

    insert into public.partner_onboarding_activity (
      workspace_id,
      event_type,
      section_key,
      status_code,
      summary_code,
      owner_type,
      actor_user_id,
      request_id,
      dedupe_key
    ) values (
      p_workspace_id,
      'required_asset_deleted',
      'brand_public_page',
      'deleted',
      'required_asset_deleted',
      'partner',
      p_actor_user_id,
      p_request_id,
      p_request_id::text || ':asset-delete'
    )
    on conflict do nothing;

    insert into public.partner_onboarding_integration_events (
      workspace_id,
      partner_record_id,
      event_type,
      workspace_aggregate_version,
      workspace_status,
      completion_percentage,
      blocker_code,
      next_action_code,
      next_action_owner,
      target_launch_date,
      section_key,
      artifact_category,
      artifact_status,
      idempotency_key
    )
    select
      po.id,
      v_partner_record_id,
      'rcap_brand_configuration_changed',
      po.aggregate_version,
      po.status,
      po.completion_percentage,
      po.blocker_code,
      po.next_action_code,
      po.next_action_owner,
      po.target_launch_date,
      'brand_public_page',
      v_asset.category,
      'deleted',
      p_request_id::text || ':asset-delete'
    from public.partner_onboarding po
    where po.id = p_workspace_id
    on conflict do nothing;
  else
    workspace_aggregate_version := v_workspace.aggregate_version;
  end if;

  update public.partner_onboarding_idempotency
  set
    result_status = 'succeeded',
    result_workspace_version = workspace_aggregate_version,
    completed_at = now()
  where request_id = p_request_id;

  object_path := v_asset.object_path;
  duplicate := v_asset.deleted_at is not null;
  return next;
end;
$_$;


ALTER FUNCTION public.rcap_service_delete_onboarding_asset(p_partner_slug text, p_actor_user_id uuid, p_workspace_id uuid, p_asset_id uuid, p_expected_workspace_version bigint, p_payload_hash text, p_workspace_completion integer, p_blocker_code text, p_next_action_code text, p_next_action_owner text, p_request_id uuid) OWNER TO postgres;

--
-- Name: rcap_service_enable_program_policy(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_service_enable_program_policy(p_slug text, p_actor uuid) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare w public.partner_onboarding%rowtype;
begin
 select * into strict w from public.partner_onboarding where partner_slug=p_slug for update;
 if exists(select 1 from public.partner_users where auth_user_id=p_actor and partner_slug is null and role='internal_admin' and status='active') then perform public.rcap_service_assert_internal_actor(p_actor);
 else perform public.rcap_service_assert_partner_actor(p_slug,p_actor,w.id); end if;
 if w.rcap_policy_version='rcap2.2' then return w.aggregate_version; end if;
 if w.status in ('live','paused','closed') then raise exception 'existing program retains its policy'; end if;
 update public.partner_onboarding set rcap_policy_version='rcap2.2',aggregate_version=aggregate_version+1 where id=w.id returning aggregate_version into w.aggregate_version;
 return w.aggregate_version;
end $$;


ALTER FUNCTION public.rcap_service_enable_program_policy(p_slug text, p_actor uuid) OWNER TO postgres;

--
-- Name: partner_onboarding_artifacts; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.partner_onboarding_artifacts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workspace_id uuid NOT NULL,
    partner_record_id uuid NOT NULL,
    artifact_type text NOT NULL,
    current_version_id uuid,
    lifecycle_status text DEFAULT 'not_generated'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT partner_onboarding_artifacts_lifecycle_check CHECK ((lifecycle_status = ANY (ARRAY['not_generated'::text, 'unavailable_in_release'::text, 'draft'::text, 'in_review'::text, 'approved'::text, 'superseded'::text, 'generation_failed'::text]))),
    CONSTRAINT partner_onboarding_artifacts_type_check CHECK ((artifact_type = ANY (ARRAY['implementation_brief'::text, 'operations_escalation_plan'::text, 'dashboard_user_reporting_matrix'::text, 'staff_quick_start_guide'::text, 'partner_launch_kit'::text, 'co_branded_page_configuration'::text])))
);


ALTER TABLE public.partner_onboarding_artifacts OWNER TO postgres;

--
-- Name: rcap_service_ensure_onboarding_artifacts(text, uuid, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_service_ensure_onboarding_artifacts(p_partner_slug text, p_workspace_id uuid, p_generatable_types text[]) RETURNS SETOF public.partner_onboarding_artifacts
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_partner_record_id uuid;
  v_type text;
begin
  select po.partner_record_id into v_partner_record_id
  from public.partner_onboarding po
  where po.id = p_workspace_id
    and po.partner_slug = p_partner_slug;

  if v_partner_record_id is null then
    raise exception 'workspace_not_found' using errcode = 'P0002';
  end if;

  foreach v_type in array array[
    'implementation_brief',
    'operations_escalation_plan',
    'dashboard_user_reporting_matrix',
    'staff_quick_start_guide',
    'partner_launch_kit',
    'co_branded_page_configuration'
  ]
  loop
    insert into public.partner_onboarding_artifacts (
      workspace_id, partner_record_id, artifact_type, lifecycle_status
    )
    values (
      p_workspace_id,
      v_partner_record_id,
      v_type,
      case when v_type = any(p_generatable_types)
        then 'not_generated'
        else 'unavailable_in_release'
      end
    )
    on conflict (workspace_id, artifact_type) do nothing;
  end loop;

  -- A type that gains a generator in a later release stops being unavailable.
  update public.partner_onboarding_artifacts
  set lifecycle_status = 'not_generated'
  where workspace_id = p_workspace_id
    and lifecycle_status = 'unavailable_in_release'
    and artifact_type = any(p_generatable_types);

  return query
  select *
  from public.partner_onboarding_artifacts
  where workspace_id = p_workspace_id;
end;
$$;


ALTER FUNCTION public.rcap_service_ensure_onboarding_artifacts(p_partner_slug text, p_workspace_id uuid, p_generatable_types text[]) OWNER TO postgres;

--
-- Name: rcap_service_evaluate_program(text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_service_evaluate_program(p_slug text, p_actor uuid, p_action text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $_$
declare w public.partner_onboarding%rowtype; r public.partner_records%rowtype; a public.rcap_commercial_authorizations%rowtype;
 s jsonb; role_name text; facts jsonb; item jsonb; check_ok boolean; exceptions jsonb:='[]'; blockers jsonb:='[]'; requirements jsonb:='[]'; dep text; ev uuid;
 materials_ok boolean; confirmation_ok boolean; internal_ok boolean; scope_hash text; setup_ok boolean; public_ok boolean; business_default boolean; managed boolean; internal_authority uuid; can_confirm boolean;
begin
 if p_action is null or p_action not in ('complete_setup','publish_partner_page','accept_screenings','issue_sponsored_packet','offer_paid_packet','create_clinic','publish_clinic','assist_participant','manage_team','view_reporting') then raise exception 'unknown action' using errcode='22023'; end if;
 select * into strict w from public.partner_onboarding where partner_slug=p_slug;
 select * into strict r from public.partner_records where id=w.partner_record_id;
 select role into role_name from public.partner_users where auth_user_id=p_actor and status='active' and ((partner_slug=p_slug and role in ('partner_admin','partner_staff')) or (partner_slug is null and role='internal_admin')) order by case when role='internal_admin' then 0 else 1 end limit 1;
 if role_name is null then raise exception 'actor or tenant denied' using errcode='42501'; end if;
 if role_name='partner_staff' and p_action not in ('view_reporting','assist_participant','offer_paid_packet') then raise exception 'administrator required' using errcode='42501'; end if;
 managed:=w.operating_model='legalease_managed' and w.rcap_policy_version='rcap2.2';
 internal_authority:=public.rcap_program_internal_authority(w.id);
 s:=public.rcap_program_policy_source(w.id); scope_hash:=public.rcap_program_launch_scope(w.id);
 select * into a from public.rcap_commercial_authorizations where workspace_id=w.id order by created_at desc,id desc limit 1;
 materials_ok:=(select count(*)=2 from public.partner_onboarding_artifacts ar join public.partner_onboarding_artifact_versions v on v.id=ar.current_version_id
 where ar.workspace_id=w.id and ar.artifact_type in ('implementation_brief','co_branded_page_configuration') and v.generation_status='succeeded' and v.superseded_at is null and v.source_drift_invalidated_at is null and v.normalized_snapshot->>'rcap_dependency_hash'=public.rcap_program_material_scope(w.id,ar.artifact_type) and (ar.artifact_type<>'co_branded_page_configuration' or v.rendered_content#>'{pagePreview,missing}'='[]'::jsonb)
 and (v.approval_status='approved' or (v.normalized_snapshot->>'rcap_standard_policy'='rcap2.2' and v.generator_version like '%_rcap2')));
 confirmation_ok:=materials_ok and exists(select 1 from public.partner_onboarding_launch_approvals c join public.partner_users u on u.auth_user_id=c.reviewer_user_id and u.partner_slug=p_slug and u.role='partner_admin' and u.status='active'
 where c.workspace_id=w.id and c.approval_type='partner_launch_approval' and c.decision='approve' and c.invalidated_at is null and c.policy_details->>'policy_version'='rcap2.2'
 and c.policy_details->>'materials_hash'=public.rcap_program_dependency_hash(w.id,array['materials'])
 and not exists(select 1 from public.partner_onboarding_launch_approvals newer where newer.workspace_id=w.id and newer.approval_type='partner_launch_approval' and (newer.recorded_at,newer.id)>(c.recorded_at,c.id)));
 internal_ok:=exists(select 1 from public.partner_onboarding_launch_approvals f join public.partner_users u on u.auth_user_id=f.reviewer_user_id and u.role='internal_admin' and u.partner_slug is null and u.status='active'
 where f.workspace_id=w.id and f.approval_type in ('legalease_final_review','standing_launch_authorization') and f.decision='approve' and f.invalidated_at is null
 and f.policy_details->>'policy_version'='rcap2.2' and f.policy_details->>'scope_hash'=scope_hash
 and f.policy_details->'capabilities' ? 'publish_partner_page' and (f.policy_details->>'expires_at')::timestamptz>now()
 and not exists(select 1 from public.partner_onboarding_launch_approvals newer where newer.workspace_id=w.id and newer.approval_type=f.approval_type and (newer.recorded_at,newer.id)>(f.recorded_at,f.id)));
 if managed then confirmation_ok:=materials_ok; internal_ok:=internal_authority is not null;end if;
 facts:=jsonb_build_object(
 'organization_facts',coalesce(length(btrim(s#>>'{organization_contacts,legal_organization_name}'))>0 and length(btrim(s#>>'{organization_contacts,public_organization_name}'))>0 and length(btrim(s#>>'{organization_contacts,public_program_name}'))>0,false),
 'program_scope',coalesce(jsonb_array_length(s#>'{geography_audience_language_accessibility,jurisdictions}') between 1 and 51
 and not exists(select 1 from jsonb_array_elements_text(s#>'{geography_audience_language_accessibility,jurisdictions}') j where j<>all(public.rcap_screening_jurisdictions()))
 and (select count(distinct j) from jsonb_array_elements_text(s#>'{geography_audience_language_accessibility,jurisdictions}') j)=jsonb_array_length(s#>'{geography_audience_language_accessibility,jurisdictions}')
 and length(btrim(s#>>'{geography_audience_language_accessibility,service_area_description}'))>0 and s#>>'{program_goals,participation_mode}' in ('online','clinics','both') and s#>>'{access_sponsorship_capacity,participant_access_model}' in ('open','optional_code','required_code','invite_only'),false),
 'support_and_referral_contacts_configured',coalesce(s#>>'{support_referrals_reporting,participant_support_email}' ~ '^[^@ ]+@[^@ ]+\.[^@ ]+$' and length(s#>>'{support_referrals_reporting,contested_matter_procedure}')>=20,false),
 'commercial_gate_cleared',public.rcap_program_commercial_valid(w.id),
 'agreements_and_procurement_recorded',(managed and s#>>'{program_goals,external_agreement_applicability}'='not_applicable' and not exists(select 1 from public.partner_onboarding_agreements where workspace_id=w.id and (signed_receipt_id is not null or finalized_asset_id is not null or status in ('executed','approved','finalized')))) or public.rcap_agreement_clearance(w.id) or (a.kind='screening_only' and public.rcap_program_commercial_valid(w.id)),
 'access_model_and_capacity_present',(managed and internal_ok) or coalesce(a.access_mode=s#>>'{access_sponsorship_capacity,participant_access_model}' and exists(select 1 from public.partner_entitlement where partner_slug=p_slug and screenings_allowed>screenings_used),false),
 'packet_entitlement',(managed and s#>>'{program_goals,service_mode}'='sponsored_packets' and public.rcap_program_funding_valid(w.id) and exists(select 1 from public.partner_packet_entitlement e where e.partner_id=w.partner_record_id and e.entitlement_scope='sponsored_packets' and e.expires_at is null and e.packet_cap>(select count(*) from public.packet_credit_ledger l where l.entitlement_id=e.id and l.event_type in ('reserved','consumed')))) or coalesce(not managed and public.rcap_program_funding_valid(w.id) and ((not managed or s#>>'{program_goals,service_mode}'='sponsored_packets') and a.kind<>'screening_only' and exists(select 1 from public.partner_packet_entitlement e where e.id=a.packet_entitlement_id and e.partner_id=r.id and e.entitlement_scope='sponsored_packets' and e.effective_at<=now() and (e.expires_at is null or e.expires_at>now()) and e.packet_cap>(select count(*) from public.packet_credit_ledger l where l.entitlement_id=e.id and l.event_type in ('reserved','consumed')))),false),
 'artifact_versions_current',materials_ok,'partner_launch_approval_received',confirmation_ok,'legalease_final_review_complete',internal_ok,
 'participant_access',false,'paid_packet_verification',false);
 setup_ok:=coalesce((facts->>'organization_facts')::boolean and (facts->>'program_scope')::boolean and (facts->>'support_and_referral_contacts_configured')::boolean,false);
 public_ok:=w.status='live' and w.landing_page_ready and materials_ok and confirmation_ok and public.rcap_program_commercial_valid(w.id) and exists(select 1 from public.rcap_launch_operation_events e where e.workspace_id=w.id and e.operation_id=w.rcap_launch_operation_id and e.step='complete');
 for item in select value from jsonb_array_elements(public.rcap_program_requirement_registry()) loop
  if not item->'actions' ? p_action then continue; end if;
  if managed and item->>'key'='partner_launch_approval_received' then item:=item||jsonb_build_object('label','Current program materials ready for Platform Admin confirmation','owner_domain','legalease_business');end if;
  if managed and item->>'key'='commercial_gate_cleared' then item:=item||jsonb_build_object('label','Confirm LegalEase operating authority with Start Program');end if;
  if managed and item->>'key'='access_model_and_capacity_present' then item:=item||jsonb_build_object('label','Authorize the configured screening access with Start Program');end if;
  if managed and item->>'key'='agreements_and_procurement_recorded' then item:=item||jsonb_build_object('label','External agreement applicability matches genuine operating responsibility');end if;
  dep:=public.rcap_program_dependency_hash(w.id,array(select jsonb_array_elements_text(item->'dependencies')));
  check_ok:=coalesce((facts->>(item->>'key'))::boolean,false);
  business_default:=item->>'owner_domain'='legalease_business' and item->>'permitted_default' is not null;
  ev:=null;
  if not check_ok and item->>'owner_domain'='legalease_business' then
   select e.id into ev from public.rcap_launch_exception_events e where e.workspace_id=w.id and e.partner_slug=p_slug and e.policy_version='rcap2.2'
    and e.kind='grant' and e.requirement_keys @> array[item->>'key'] and e.requested_action=p_action and e.event_id is null
    and e.dependency_hashes->>(item->>'key')=dep and (e.expires_at is null or e.expires_at>now())
    and exists(select 1 from public.partner_users where auth_user_id=e.actor_auth_user_id and partner_slug is null and role='internal_admin' and status='active')
    and not exists(select 1 from public.rcap_launch_exception_events x where x.grant_id=e.id and x.kind='revoke') order by e.created_at desc limit 1;
  end if;
  if ev is not null then exceptions:=exceptions||jsonb_build_array(ev); end if;
  requirements:=requirements||jsonb_build_array(item||jsonb_build_object('passing',check_ok,'effective',check_ok or ev is not null or business_default,'dependency_hash',dep,'exception_id',ev,'default_applied',not check_ok and ev is null and business_default));
  if not check_ok and ev is null and not business_default then blockers:=blockers||jsonb_build_array(item||jsonb_build_object('dependency_hash',dep)); end if;
 end loop;
 if w.status in ('paused','closed') and p_action not in ('view_reporting','manage_team') then blockers:=blockers||jsonb_build_array(jsonb_build_object('key','program_status','label','This program is paused or closed.','owner_domain','security')); end if;
 if p_action in ('accept_screenings','publish_clinic','issue_sponsored_packet') and not public_ok then blockers:=blockers||jsonb_build_array(jsonb_build_object('key','publication','label','Start the parent program first.','owner_domain','security')); end if;
 if p_action='create_clinic' and not setup_ok then blockers:=blockers||jsonb_build_array(jsonb_build_object('key','setup','label','Save the program service area before creating a clinic.','owner_domain','legal')); end if;
 if managed and p_action in ('create_clinic','publish_clinic') and coalesce(s#>>'{program_goals,participation_mode}','') not in ('clinics','both') then blockers:=blockers||jsonb_build_array(jsonb_build_object('key','clinic_scope','label','This program does not include Clinic participation.','owner_domain','legal'));end if;
 if managed and (coalesce(length(btrim(s#>>'{program_goals,operator_authority_reference}')),0)<10 or s#>>'{program_goals,service_mode}' not in ('screening_only','participant_paid','sponsored_packets') or coalesce(s#>>'{program_goals,external_agreement_applicability}','') not in ('not_applicable','required')) then
  blockers:=blockers||jsonb_build_array(jsonb_build_object('key','operating_authority','label','Establish genuine LegalEase operating responsibility without transferring third-party rights.','owner_domain','legal'));
 end if;
 if managed and p_action in ('publish_partner_page','accept_screenings','issue_sponsored_packet','publish_clinic') and s#>>'{program_goals,service_mode}'='sponsored_packets' and not coalesce((facts->>'packet_entitlement')::boolean,false) then blockers:=blockers||jsonb_build_array(jsonb_build_object('key','packet_entitlement','label','Sponsored packets require an actual available funded allocation.','owner_domain','financial'));end if;
 if managed and p_action='offer_paid_packet' and s#>>'{program_goals,service_mode}' is distinct from 'participant_paid' then blockers:=blockers||jsonb_build_array(jsonb_build_object('key','paid_service_scope','label','Participant-paid services are not part of this program. Independent consumer services retain their own payment and verification requirements.','owner_domain','financial'));end if;
 if p_action in ('complete_setup','publish_partner_page') and not public.rcap_program_geography_consistent(w.id) then
  setup_ok:=false;
  item:=jsonb_build_object('key','geographic_presentation','label','Correct the service-area description to match the selected authorized jurisdictions.','owner_domain','legal','classification','hard_stop','passing',false,'effective',false);
  requirements:=requirements||jsonb_build_array(item);blockers:=blockers||jsonb_build_array(item);
 end if;
 can_confirm:=role_name='internal_admin' and setup_ok and materials_ok and not exists(select 1 from jsonb_array_elements(blockers) b where b->>'key'<>all(case when managed then array['commercial_gate_cleared','access_model_and_capacity_present','legalease_final_review_complete'] else array['legalease_final_review_complete'] end));
 return jsonb_build_object('operatingModel',w.operating_model,'canAuthorizeStart',can_confirm,'jurisdictions',s#>'{geography_audience_language_accessibility,jurisdictions}','serviceMode',s#>>'{program_goals,service_mode}','policyVersion',w.rcap_policy_version,'workspaceId',w.id,'partnerSlug',p_slug,'actor',p_actor,'role',role_name,'action',p_action,'allowed',jsonb_array_length(blockers)=0,'requirements',requirements,'blockers',blockers,'activeExceptions',exceptions,'sourceVersion',w.aggregate_version,'scopeHash',scope_hash,'materialsHash',public.rcap_program_dependency_hash(w.id,array['materials']),'authorityId',case when managed then internal_authority else a.id end,'setupComplete',(confirmation_ok and (not managed or internal_ok)) or (w.rcap_policy_version='legacy' and w.status='live'),'configurationComplete',setup_ok,'live',public_ok,'delegated',exists(select 1 from public.partner_onboarding_launch_approvals z where z.workspace_id=w.id and z.approval_type='standing_launch_authorization' and z.decision='approve' and z.invalidated_at is null and z.policy_details->>'scope_hash'=scope_hash and (z.policy_details->>'expires_at')::timestamptz>now() and not exists(select 1 from public.partner_onboarding_launch_approvals n where n.workspace_id=w.id and n.approval_type=z.approval_type and (n.recorded_at,n.id)>(z.recorded_at,z.id))),'status',w.status,'primaryNextAction',coalesce(blockers->0->>'label',case when p_action='complete_setup' then 'Review your program' else 'Continue' end));
end $_$;


ALTER FUNCTION public.rcap_service_evaluate_program(p_slug text, p_actor uuid, p_action text) OWNER TO postgres;

--
-- Name: rcap_service_generate_onboarding_artifact_version(text, uuid, uuid, text, uuid, bigint, jsonb, jsonb, jsonb, text, text, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_service_generate_onboarding_artifact_version(p_partner_slug text, p_actor_user_id uuid, p_workspace_id uuid, p_artifact_type text, p_request_id uuid, p_source_workspace_version bigint, p_source_section_revisions jsonb, p_source_asset_versions jsonb, p_normalized_snapshot jsonb, p_snapshot_hash text, p_generator_version text, p_rendered_content jsonb, p_generation_status text, p_generation_error_code text) RETURNS TABLE(version_id uuid, version_number integer, duplicate boolean)
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_artifact public.partner_onboarding_artifacts%rowtype;
  v_existing public.partner_onboarding_artifact_versions%rowtype;
  v_next integer;
  v_new public.partner_onboarding_artifact_versions%rowtype;
begin
  if exists(select 1 from public.partner_onboarding where id=p_workspace_id and partner_slug=p_partner_slug and rcap_policy_version='rcap2.2') then
    if not exists(select 1 from public.partner_users where auth_user_id=p_actor_user_id and status='active' and ((partner_slug=p_partner_slug and role='partner_admin') or (partner_slug is null and role='internal_admin'))) then raise exception 'material actor denied' using errcode='42501';end if;
    perform 1 from public.partner_onboarding where id=p_workspace_id and aggregate_version=p_source_workspace_version for update;
    if not found or p_normalized_snapshot->>'rcap_dependency_hash' is distinct from public.rcap_program_material_scope(p_workspace_id,p_artifact_type) then raise exception 'material source changed' using errcode='40001';end if;
  end if;
  if p_generation_status not in ('succeeded', 'failed') then
    raise exception 'invalid_generation_status' using errcode = '22023';
  end if;

  select a.* into v_artifact
  from public.partner_onboarding_artifacts a
  join public.partner_onboarding po on po.id = a.workspace_id
  where a.workspace_id = p_workspace_id
    and a.artifact_type = p_artifact_type
    and po.partner_slug = p_partner_slug
  for update of a;

  if v_artifact.id is null then
    raise exception 'artifact_not_found' using errcode = 'P0002';
  end if;

  if v_artifact.lifecycle_status = 'unavailable_in_release' then
    raise exception 'artifact_generator_unavailable' using errcode = '0A000';
  end if;

  -- Idempotency: the same request id returns the version it already created.
  select v.* into v_existing
  from public.partner_onboarding_artifact_versions v
  where v.artifact_id = v_artifact.id
    and v.request_id = p_request_id;

  if v_existing.id is not null then
    version_id := v_existing.id;
    version_number := v_existing.version_number;
    duplicate := true;
    return next;
    return;
  end if;

  -- Under the existing artifact lock, identical RCAP materials are a no-op.
  -- Generation success is not completeness; incomplete identical results are
  -- reused too, so a retry cannot manufacture another misleading version.
  if exists(select 1 from public.partner_onboarding where id=p_workspace_id and rcap_policy_version='rcap2.2') then
    select * into v_existing from public.partner_onboarding_artifact_versions
    where id=v_artifact.current_version_id and snapshot_hash=p_snapshot_hash
      and generator_version=p_generator_version and rendered_content=p_rendered_content
      and generation_status=p_generation_status and generation_error_code is not distinct from p_generation_error_code
      and source_drift_invalidated_at is null and superseded_at is null;
    if found then
      version_id:=v_existing.id;version_number:=v_existing.version_number;duplicate:=true;return next;return;
    end if;
  end if;

  select coalesce(max(v.version_number), 0) + 1 into v_next
  from public.partner_onboarding_artifact_versions v
  where v.artifact_id = v_artifact.id;

  insert into public.partner_onboarding_artifact_versions (
    artifact_id, workspace_id, version_number,
    source_workspace_version, source_section_revisions, source_asset_versions,
    normalized_snapshot, snapshot_hash, generator_version, rendered_content,
    generation_status, generation_error_code,
    approval_status, generated_by, request_id
  )
  values (
    v_artifact.id, p_workspace_id, v_next,
    p_source_workspace_version, p_source_section_revisions, p_source_asset_versions,
    p_normalized_snapshot, p_snapshot_hash, p_generator_version, p_rendered_content,
    p_generation_status, p_generation_error_code,
    case when p_generation_status = 'failed' then 'generation_failed' else 'draft' end,
    p_actor_user_id, p_request_id
  )
  returning * into v_new;

  -- A superseded prior version stays readable in history; it is never rewritten.
  update public.partner_onboarding_artifact_versions
  set approval_status = 'superseded',
      superseded_at = now()
  where artifact_id = v_artifact.id
    and id <> v_new.id
    and approval_status <> 'generation_failed'
    and superseded_at is null;

  update public.partner_onboarding_artifacts
  set current_version_id = v_new.id,
      lifecycle_status = case
        when p_generation_status = 'failed' then 'generation_failed'
        else 'draft'
      end
  where id = v_artifact.id;

  insert into public.partner_onboarding_activity (
    workspace_id, event_type, owner_type, summary_code, status_code,
    artifact_version_id
  )
  values (
    p_workspace_id,
    case when p_generation_status = 'failed'
      then 'artifact_generation_failed'
      else 'artifact_generated'
    end,
    'legalease',
    p_artifact_type,
    p_generation_status,
    v_new.id
  );

  version_id := v_new.id;
  version_number := v_new.version_number;
  duplicate := false;
  return next;
end;
$$;


ALTER FUNCTION public.rcap_service_generate_onboarding_artifact_version(p_partner_slug text, p_actor_user_id uuid, p_workspace_id uuid, p_artifact_type text, p_request_id uuid, p_source_workspace_version bigint, p_source_section_revisions jsonb, p_source_asset_versions jsonb, p_normalized_snapshot jsonb, p_snapshot_hash text, p_generator_version text, p_rendered_content jsonb, p_generation_status text, p_generation_error_code text) OWNER TO postgres;

--
-- Name: rcap_service_get_program_configuration(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_service_get_program_configuration(p_slug text, p_actor uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare w public.partner_onboarding%rowtype; d jsonb;
begin
 select * into strict w from public.partner_onboarding where partner_slug=p_slug;
 if exists(select 1 from public.partner_users where auth_user_id=p_actor and partner_slug is null and role='internal_admin' and status='active') then
  perform public.rcap_service_assert_internal_actor(p_actor);
 else perform public.rcap_service_assert_partner_actor(p_slug,p_actor,w.id); end if;
 if w.rcap_policy_version not in ('legacy','rcap2.2') or not exists(select 1 from public.partner_records where id=w.partner_record_id and partner_slug=p_slug) then
  raise exception 'workspace identity invalid' using errcode='P0002';
 end if;
 select coalesce(jsonb_object_agg(section_key,response_data),'{}') into d from public.partner_onboarding_sections where workspace_id=w.id;
 d:=d||jsonb_build_object('organization_contacts',coalesce(d->'organization_contacts','{}')||jsonb_build_object('contacts',coalesce((select jsonb_agg(jsonb_build_object('stable_row_id',id,'role',role,'name',name,'title',title,'organization',organization,'work_email',work_email,'phone',phone) order by created_at,id) from public.partner_onboarding_contacts where workspace_id=w.id and deleted_at is null),'[]')));
 d:=d||jsonb_build_object('program_goals',coalesce(d->'program_goals','{}')||jsonb_build_object('operating_model',w.operating_model));
 return jsonb_build_object('operatingModel',w.operating_model,'workspaceId',w.id,'partnerSlug',p_slug,'version',w.aggregate_version,'policyVersion',w.rcap_policy_version,'status',w.status,'data',d,
 'legalIdentityLocked',w.agreement_status='signed' or exists(select 1 from public.rcap_commercial_authorizations where workspace_id=w.id));
end $$;


ALTER FUNCTION public.rcap_service_get_program_configuration(p_slug text, p_actor uuid) OWNER TO postgres;

--
-- Name: rcap_service_invalidate_affected_launch_checks(text, uuid, text[], text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_service_invalidate_affected_launch_checks(p_partner_slug text, p_workspace_id uuid, p_check_keys text[], p_reason text) RETURNS TABLE(invalidated_count integer)
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_count integer;
begin
  if p_reason is null or char_length(btrim(p_reason)) = 0 then
    raise exception 'invalidation_reason_required' using errcode = '22023';
  end if;

  with updated as (
    update public.partner_onboarding_launch_checks c
    set invalidated_at = now(),
        invalidated_reason = p_reason
    from public.partner_onboarding po
    where c.workspace_id = p_workspace_id
      and po.id = c.workspace_id
      and po.partner_slug = p_partner_slug
      and c.invalidated_at is null
      and c.status in ('passing', 'waived', 'not_applicable')
      and c.check_key = any(p_check_keys)
    returning c.id
  )
  select count(*)::integer into v_count from updated;

  if v_count > 0 then
    insert into public.partner_onboarding_activity (
      workspace_id, event_type, owner_type, summary_code, status_code
    )
    values (
      p_workspace_id, 'launch_check_invalidated', 'system',
      'affected_checks',
      'source_changed'
    );
  end if;

  invalidated_count := v_count;
  return next;
end;
$$;


ALTER FUNCTION public.rcap_service_invalidate_affected_launch_checks(p_partner_slug text, p_workspace_id uuid, p_check_keys text[], p_reason text) OWNER TO postgres;

--
-- Name: rcap_service_invalidate_onboarding_artifact_version(text, uuid, text, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_service_invalidate_onboarding_artifact_version(p_partner_slug text, p_artifact_version_id uuid, p_current_snapshot_hash text, p_drift_fields text[]) RETURNS TABLE(invalidated boolean)
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_updated public.partner_onboarding_artifact_versions%rowtype;
  v_artifact_type text;
begin
  update public.partner_onboarding_artifact_versions v
  set source_drift_invalidated_at = now(),
      source_drift_fields = p_drift_fields,
      invalidated_against_snapshot_hash = p_current_snapshot_hash
  from public.partner_onboarding po
  where v.id = p_artifact_version_id
    and po.id = v.workspace_id
    and po.partner_slug = p_partner_slug
    and v.generation_status = 'succeeded'
    and v.source_drift_invalidated_at is null
    and v.snapshot_hash <> p_current_snapshot_hash
  returning v.* into v_updated;

  if v_updated.id is null then
    invalidated := false;
    return next;
    return;
  end if;

  select a.artifact_type into v_artifact_type
  from public.partner_onboarding_artifacts a
  where a.id = v_updated.artifact_id;

  insert into public.partner_onboarding_activity (
    workspace_id, event_type, owner_type, summary_code, status_code,
    artifact_version_id
  )
  values (
    v_updated.workspace_id,
    'artifact_approval_invalidated',
    'system',
    v_artifact_type,
    'source_changed',
    v_updated.id
  )
  on conflict do nothing;

  invalidated := true;
  return next;
end;
$$;


ALTER FUNCTION public.rcap_service_invalidate_onboarding_artifact_version(p_partner_slug text, p_artifact_version_id uuid, p_current_snapshot_hash text, p_drift_fields text[]) OWNER TO postgres;

--
-- Name: rcap_service_invalidate_onboarding_launch_checks(text, uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_service_invalidate_onboarding_launch_checks(p_partner_slug text, p_workspace_id uuid, p_invalidate_partner_owned boolean, p_reason text) RETURNS TABLE(invalidated_count integer)
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_count integer;
begin
  if p_reason is null or char_length(btrim(p_reason)) = 0 then
    raise exception 'invalidation_reason_required' using errcode = '22023';
  end if;

  with updated as (
    update public.partner_onboarding_launch_checks c
    set invalidated_at = now(),
        invalidated_reason = p_reason
    from public.partner_onboarding po
    where c.workspace_id = p_workspace_id
      and po.id = c.workspace_id
      and po.partner_slug = p_partner_slug
      and c.invalidated_at is null
      and c.status in ('passing', 'waived', 'not_applicable')
      and (p_invalidate_partner_owned or c.owner_type = 'legalease')
    returning c.id
  )
  select count(*)::integer into v_count from updated;

  if v_count > 0 then
    insert into public.partner_onboarding_activity (
      workspace_id, event_type, owner_type, summary_code, status_code
    )
    values (
      p_workspace_id, 'launch_check_invalidated', 'system',
      case when p_invalidate_partner_owned then 'all_owners' else 'legalease_only' end,
      'source_changed'
    );
  end if;

  invalidated_count := v_count;
  return next;
end;
$$;


ALTER FUNCTION public.rcap_service_invalidate_onboarding_launch_checks(p_partner_slug text, p_workspace_id uuid, p_invalidate_partner_owned boolean, p_reason text) OWNER TO postgres;

--
-- Name: rcap_service_prepare_onboarding_prefill(text, uuid, uuid, uuid, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_service_prepare_onboarding_prefill(p_partner_slug text, p_actor_user_id uuid, p_workspace_id uuid, p_request_id uuid, p_payload_hash text, p_source_summary text, p_batch_status text, p_origin text, p_suggestions jsonb) RETURNS TABLE(batch_id uuid, batch_aggregate_version bigint, suggestion_count integer, duplicate boolean)
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
declare
  v_workspace public.partner_onboarding%rowtype;
  v_existing public.partner_onboarding_idempotency%rowtype;
  v_batch public.partner_onboarding_prefill_batches%rowtype;
  v_count integer;
begin
  perform public.rcap_studio_assert_prepare(p_actor_user_id,p_partner_slug);

  if p_batch_status not in ('draft', 'ready_for_review')
     or p_origin not in ('manual', 'import')
     or p_payload_hash !~ '^[0-9a-f]{64}$'
     or char_length(p_source_summary) not between 1 and 500
     or p_suggestions is null
     or jsonb_typeof(p_suggestions) <> 'array'
     or jsonb_array_length(p_suggestions) < 1
     or jsonb_array_length(p_suggestions) > 200 then
    raise exception using
      errcode = '22023',
      message = 'Invalid onboarding prefill preparation';
  end if;

  select *
    into v_existing
  from public.partner_onboarding_idempotency i
  where i.request_id = p_request_id
  for update;

  if found then
    if v_existing.workspace_id <> p_workspace_id
       or v_existing.operation_key <> 'prefill_prepare'
       or v_existing.actor_user_id <> p_actor_user_id
       or v_existing.payload_hash <> p_payload_hash then
      raise exception using
        errcode = '23505',
        message = 'Idempotency request does not match original mutation';
    end if;
    if v_existing.result_status = 'succeeded' then
      select *
        into v_batch
      from public.partner_onboarding_prefill_batches b
      where b.request_id = p_request_id;
      return query
      select
        v_batch.id,
        v_batch.aggregate_version,
        (
          select count(*)::integer
          from public.partner_onboarding_prefill_values pv
          where pv.batch_id = v_batch.id
        ),
        true;
      return;
    end if;
    raise exception using
      errcode = '55000',
      message = 'Idempotent request is still in progress';
  end if;

  select po.*
    into v_workspace
  from public.partner_onboarding po
  where po.id = p_workspace_id
    and po.partner_slug = p_partner_slug
  for update of po;

  if not found or v_workspace.partner_record_id is null then
    raise exception using
      errcode = 'P0002',
      message = 'Onboarding workspace not found';
  end if;
  if v_workspace.status in ('ready_to_launch', 'live', 'paused', 'closed') then
    raise exception using
      errcode = '55000',
      message = 'Onboarding workspace no longer accepts prefill suggestions';
  end if;

  insert into public.partner_onboarding_idempotency (
    workspace_id,
    operation_key,
    request_id,
    actor_user_id,
    payload_hash,
    expires_at
  ) values (
    p_workspace_id,
    'prefill_prepare',
    p_request_id,
    p_actor_user_id,
    p_payload_hash,
    now() + interval '24 hours'
  );

  insert into public.partner_onboarding_prefill_batches (
    workspace_id,
    partner_record_id,
    status,
    source_summary,
    created_by,
    request_id
  ) values (
    p_workspace_id,
    v_workspace.partner_record_id,
    p_batch_status,
    p_source_summary,
    p_actor_user_id,
    p_request_id
  )
  returning * into v_batch;

  insert into public.partner_onboarding_prefill_values (
    id,
    batch_id,
    workspace_id,
    section_key,
    field_key,
    proposed_value,
    source_type,
    source_reference_id,
    source_label,
    confidence,
    base_value_hash,
    proposed_value_hash,
    base_section_revision,
    created_by
  )
  select
    coalesce(nullif(item->>'id', '')::uuid, gen_random_uuid()),
    v_batch.id,
    p_workspace_id,
    item->>'sectionKey',
    item->>'fieldKey',
    item->'proposedValue',
    item->>'sourceType',
    nullif(item->>'sourceReferenceId', ''),
    item->>'sourceLabel',
    case
      when item ? 'confidence' and item->'confidence' <> 'null'::jsonb
        then (item->>'confidence')::numeric
      else null
    end,
    item->>'baseValueHash',
    item->>'proposedValueHash',
    (item->>'baseSectionRevision')::bigint,
    p_actor_user_id
  from jsonb_array_elements(p_suggestions) item;

  get diagnostics v_count = row_count;

  insert into public.partner_onboarding_activity (
    workspace_id,
    event_type,
    summary_code,
    owner_type,
    actor_user_id,
    request_id,
    dedupe_key
  ) values (
    p_workspace_id,
    'prefill_batch_created',
    'prefill_batch_created',
    'legalease',
    p_actor_user_id,
    p_request_id,
    p_request_id::text || ':prefill_batch_created'
  );

  if p_origin = 'import' then
    insert into public.partner_onboarding_activity (
      workspace_id,
      event_type,
      summary_code,
      owner_type,
      actor_user_id,
      request_id,
      dedupe_key
    ) values (
      p_workspace_id,
      'prefill_known_data_imported',
      'prefill_known_data_imported',
      'legalease',
      p_actor_user_id,
      p_request_id,
      p_request_id::text || ':prefill_known_data_imported'
    );
  end if;

  insert into public.partner_onboarding_integration_events (
    workspace_id,
    partner_record_id,
    event_type,
    workspace_aggregate_version,
    workspace_status,
    completion_percentage,
    blocker_code,
    next_action_code,
    next_action_owner,
    target_launch_date,
    idempotency_key
  ) values (
    v_workspace.id,
    v_workspace.partner_record_id,
    'rcap_onboarding_prefill_prepared',
    v_workspace.aggregate_version,
    v_workspace.status,
    v_workspace.completion_percentage,
    v_workspace.blocker_code,
    v_workspace.next_action_code,
    v_workspace.next_action_owner,
    v_workspace.target_launch_date,
    p_request_id::text || ':prefill_prepared'
  );

  update public.partner_onboarding_idempotency
  set
    result_status = 'succeeded',
    result_workspace_version = v_workspace.aggregate_version,
    result_section_revision = v_batch.aggregate_version,
    completed_at = now()
  where request_id = p_request_id;

  batch_id := v_batch.id;
  batch_aggregate_version := v_batch.aggregate_version;
  suggestion_count := v_count;
  duplicate := false;
  return next;
end;
$_$;


ALTER FUNCTION public.rcap_service_prepare_onboarding_prefill(p_partner_slug text, p_actor_user_id uuid, p_workspace_id uuid, p_request_id uuid, p_payload_hash text, p_source_summary text, p_batch_status text, p_origin text, p_suggestions jsonb) OWNER TO postgres;

--
-- Name: rcap_service_provision_partner(text, text, text, text, text, text, text, text, uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_service_provision_partner(p_partner_slug text, p_organization_name text, p_legal_organization_name text, p_program_name text, p_program_purpose text, p_administrator_name text, p_administrator_email text, p_clearance_reason text, p_actor_user_id uuid, p_request_id uuid, p_schema_version text, p_payload_hash text) RETURNS TABLE(partner_record_id uuid, workspace_id uuid, workspace_status text, section_count integer, milestone_count integer, page_configuration_id uuid, created boolean)
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
declare
  v_partner public.partner_records%rowtype;
  v_workspace public.partner_onboarding%rowtype;
  v_existing public.partner_onboarding_idempotency%rowtype;
  v_operation_key text;
  v_page_config_id uuid;
  v_email text;
  v_conflicts integer;
begin
  -- Only an active internal LegalEase administrator may provision. Partner
  -- administrators, partner staff, and any other tenant fail here with 42501,
  -- which the application renders as one generic denial.
  perform public.rcap_service_assert_internal_actor(p_actor_user_id);

  v_email := lower(btrim(coalesce(p_administrator_email, '')));

  if p_partner_slug !~ '^[a-z0-9](?:[a-z0-9-]{0,118}[a-z0-9])?$'
     or nullif(btrim(coalesce(p_organization_name, '')), '') is null
     or nullif(btrim(coalesce(p_legal_organization_name, '')), '') is null
     or nullif(btrim(coalesce(p_program_name, '')), '') is null
     or nullif(btrim(coalesce(p_program_purpose, '')), '') is null
     or nullif(btrim(coalesce(p_administrator_name, '')), '') is null
     or v_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
     or nullif(btrim(coalesce(p_clearance_reason, '')), '') is null
     or nullif(btrim(coalesce(p_schema_version, '')), '') is null
     or p_request_id is null
     or p_payload_hash !~ '^[0-9a-f]{64}$' then
    raise exception using errcode = '22023', message = 'Invalid partner provisioning request';
  end if;

  v_operation_key := 'partner:provision:' || p_partner_slug;

  -- Replay. The same idempotency key returns the original result and creates
  -- nothing. A key reused for a different operation, actor, or payload is a
  -- collision, not a replay, and fails closed.
  select *
    into v_existing
  from public.partner_onboarding_idempotency i
  where i.request_id = p_request_id
  for update;
  if found then
    if v_existing.operation_key <> v_operation_key
       or v_existing.actor_user_id <> p_actor_user_id
       or v_existing.payload_hash <> p_payload_hash then
      raise exception using errcode = '23505', message = 'Idempotency request mismatch';
    end if;
    return query
    select
      po.partner_record_id,
      po.id,
      po.status,
      (select count(*)::integer
         from public.partner_onboarding_sections s
        where s.workspace_id = po.id),
      (select count(*)::integer
         from public.partner_onboarding_tasks t
        where t.partner_slug = po.partner_slug),
      public.rcap_partner_page_configuration_id(po.partner_slug),
      false
    from public.partner_onboarding po
    where po.id = v_existing.workspace_id;
    return;
  end if;

  -- Exact slug uniqueness, and fail closed on anything ambiguous already
  -- carrying this slug. A pre-existing workspace, membership, or page
  -- configuration without a partner record is a broken half-state; provisioning
  -- over it would silently adopt records nobody reviewed.
  select count(*) into v_conflicts
  from public.partner_records pr
  where pr.partner_slug = p_partner_slug
     or pr.partner_id = p_partner_slug;
  if v_conflicts > 0 then
    raise exception using errcode = '23505', message = 'Partner slug already exists';
  end if;

  select
      (select count(*) from public.partner_onboarding po where po.partner_slug = p_partner_slug)
    + (select count(*) from public.partner_users pu where pu.partner_slug = p_partner_slug)
    + (select count(*) from public.partner_events pe
        where pe.partner_slug = p_partner_slug
          and pe.event_type in (
            'partner_page_configuration_record',
            'first_admin_invitation_record'
          ))
    into v_conflicts;
  if v_conflicts > 0 then
    raise exception using errcode = '23505', message = 'Ambiguous existing records for partner slug';
  end if;

  -- 1. The partner tenant. Every commercial and activation field is left in its
  -- pre-launch state on purpose: unpaid, unqualified, not provisioned. The
  -- participant activation contract in partner-public-eligibility.ts requires
  -- all three to be positive, so this record cannot activate benefits.
  -- access_mode 'invite_only' with no access code keeps participant intake off.
  insert into public.partner_records (
    partner_id,
    partner_slug,
    partner_name,
    organization_name,
    legal_name,
    program_name,
    program_description,
    primary_contact_name,
    primary_contact_email,
    contact_name,
    contact_email,
    organization_type,
    program_tier,
    access_mode,
    payment_status,
    qualification_status,
    provisioning_status,
    onboarding_status
  ) values (
    p_partner_slug,
    p_partner_slug,
    btrim(p_organization_name),
    btrim(p_organization_name),
    btrim(p_legal_organization_name),
    btrim(p_program_name),
    btrim(p_program_purpose),
    btrim(p_administrator_name),
    v_email,
    btrim(p_administrator_name),
    v_email,
    'other',
    'implementation',
    'invite_only',
    'unpaid',
    'request_received',
    'blocked_payment_required',
    'not_started'
  )
  returning * into v_partner;

  -- 2. The onboarding workspace, carrying the private participant-page
  -- configuration fields. landing_page_ready, internal_approved_at and
  -- launched_at stay false/null, which is what the publication contract reads,
  -- so the public route returns 404.
  insert into public.partner_onboarding (
    partner_slug,
    partner_record_id,
    status,
    agreement_status,
    schema_version,
    aggregate_version,
    completion_percentage,
    blocker_code,
    next_action_code,
    next_action_owner,
    launch_readiness_state,
    public_display_name,
    show_partner_logo,
    show_powered_by,
    landing_page_ready,
    internal_notes,
    commercial_gate_status,
    commercial_gate_changed_at,
    commercial_gate_changed_by,
    last_meaningful_activity_at
  ) values (
    p_partner_slug,
    v_partner.id,
    'commercially_blocked',
    'not_sent',
    p_schema_version,
    1,
    0,
    'commercial_gate_blocked',
    'complete_commercial_requirements',
    'partner',
    'not_ready',
    btrim(p_organization_name),
    true,
    true,
    false,
    'Provisioned under authorized internal clearance: ' || btrim(p_clearance_reason),
    'blocked',
    now(),
    p_actor_user_id,
    now()
  )
  returning * into v_workspace;

  -- 3. The canonical initial onboarding sections, all not started.
  insert into public.partner_onboarding_sections (
    workspace_id,
    section_key,
    response_data,
    revision,
    status,
    completion_percentage,
    missing_required_keys
  )
  select
    v_workspace.id,
    section_key,
    '{}'::jsonb,
    1,
    'not_started',
    0,
    '{}'::text[]
  from unnest(array[
    'organization_contacts',
    'program_goals',
    'geography_audience_language_accessibility',
    'access_sponsorship_capacity',
    'brand_public_page',
    'staff_dashboard_plan',
    'support_referrals_reporting',
    'review_authorization'
  ]::text[]) section_key;

  -- 4. Implementation milestone state. Every milestone starts not started; none
  -- is pre-completed, so the checklist cannot overstate readiness.
  insert into public.partner_onboarding_tasks (
    partner_slug,
    task_key,
    title,
    description,
    owner,
    required,
    status
  )
  select
    p_partner_slug,
    milestone.task_key,
    milestone.title,
    milestone.description,
    milestone.owner,
    milestone.required,
    'not_started'
  from (values
    ('profile_complete', 'Partner profile complete', 'Organization name, contact, and jurisdiction are set.', 'legalease', true),
    ('agreement_billing', 'Agreement and billing configured', 'Agreement status and billing contact are set.', 'legalease', true),
    ('packet_cap', 'Packet cap configured', 'The included packet allocation is set.', 'legalease', true),
    ('overage_pause', 'Overage and pause-at-cap preference configured', 'Decide whether to allow overages or pause at the cap.', 'legalease', true),
    ('access_mode', 'Access mode selected', 'Open link, optional code, required code, or invite only.', 'legalease', true),
    ('codes_created', 'Codes created if required', 'At least one active access code exists when codes are required.', 'legalease', true),
    ('landing_reviewed', 'Landing page preview reviewed', 'The co-branded landing page has been previewed and approved.', 'legalease', true),
    ('admin_invited', 'Partner admin invited', 'At least one partner admin has been invited.', 'legalease', true),
    ('launch_materials', 'Launch materials generated', 'The launch kit (link, QR code, copy) has been generated.', 'legalease', true),
    ('disclaimers_visible', 'Disclaimers visible', 'Not-legal-advice and no-guarantee disclaimers appear on the partner page.', 'legalease', true),
    ('internal_approval', 'Internal approval completed', 'LegalEase has reviewed and approved this partner for launch.', 'legalease', true),
    ('partner_upload_logo', 'Upload your logo', 'Add your organization''s logo for the co-branded page.', 'partner', false),
    ('partner_confirm_description', 'Confirm your public description', 'Review the short description shown to your community.', 'partner', false),
    ('partner_confirm_contact', 'Confirm your main contact', 'Verify the main contact for your program.', 'partner', false),
    ('partner_review_landing', 'Review your landing page', 'Preview how your co-branded page will look.', 'partner', false),
    ('partner_download_materials', 'Download launch materials', 'Grab your link, QR code, and suggested outreach copy.', 'partner', false)
  ) as milestone(task_key, title, description, owner, required);

  -- 5. The private participant-page configuration record. It is stored at a
  -- deterministic id derived from the slug, the same addressing the first-admin
  -- invitation record uses, so a replay can never create a second one.
  v_page_config_id := public.rcap_partner_page_configuration_id(p_partner_slug);
  insert into public.partner_events (id, partner_slug, event_type, event_label, event_payload)
  values (
    v_page_config_id,
    p_partner_slug,
    'partner_page_configuration_record',
    'Participant page configuration',
    jsonb_build_object(
      'schema_version', 1,
      'publication_state', 'private',
      'public_route_state', 'not_found',
      'participant_intake_state', 'inactive',
      'access_mode', 'invite_only',
      'access_code_state', 'absent',
      'sitemap_state', 'absent',
      'navigation_state', 'absent',
      'public_display_name', btrim(p_organization_name),
      'created_at', to_char(now() at time zone 'utc', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
    )
  );

  -- 6. The audit event. It names what was created and, deliberately, what was
  -- not, so a later reader cannot mistake provisioning for launch.
  insert into public.partner_events (partner_slug, event_type, event_label, event_payload)
  values (
    p_partner_slug,
    'partner_tenant_provisioned',
    'Partner tenant provisioned',
    jsonb_build_object(
      'schema_version', 1,
      'request_id', p_request_id::text,
      'actor_user_id', p_actor_user_id::text,
      'clearance_reason', btrim(p_clearance_reason),
      'program_name', btrim(p_program_name),
      'administrator_email', v_email,
      'publication_state', 'private',
      'program_activation_state', 'inactive',
      'participant_intake_state', 'inactive',
      'access_code_state', 'absent',
      'allocation_state', 'absent',
      'billing_state', 'absent',
      'auth_user_created', false,
      'membership_created', false,
      'invitation_created', false,
      'occurred_at', to_char(now() at time zone 'utc', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
    )
  );

  -- 7. The idempotency record, written last inside the same transaction, so it
  -- exists only if every record above committed.
  insert into public.partner_onboarding_idempotency (
    workspace_id,
    operation_key,
    request_id,
    actor_user_id,
    payload_hash,
    result_status,
    result_workspace_version,
    expires_at,
    completed_at
  ) values (
    v_workspace.id,
    v_operation_key,
    p_request_id,
    p_actor_user_id,
    p_payload_hash,
    'succeeded',
    v_workspace.aggregate_version,
    now() + interval '24 hours',
    now()
  );

  insert into public.partner_onboarding_activity (
    workspace_id,
    event_type,
    status_code,
    summary_code,
    owner_type,
    actor_user_id,
    request_id,
    dedupe_key
  ) values (
    v_workspace.id,
    'workspace_created',
    v_workspace.status,
    'workspace_created',
    'legalease',
    p_actor_user_id,
    p_request_id,
    'workspace-created'
  )
  on conflict do nothing;

  return query
  select
    v_partner.id,
    v_workspace.id,
    v_workspace.status,
    (select count(*)::integer
       from public.partner_onboarding_sections s
      where s.workspace_id = v_workspace.id),
    (select count(*)::integer
       from public.partner_onboarding_tasks t
      where t.partner_slug = p_partner_slug),
    v_page_config_id,
    true;
end;
$_$;


ALTER FUNCTION public.rcap_service_provision_partner(p_partner_slug text, p_organization_name text, p_legal_organization_name text, p_program_name text, p_program_purpose text, p_administrator_name text, p_administrator_email text, p_clearance_reason text, p_actor_user_id uuid, p_request_id uuid, p_schema_version text, p_payload_hash text) OWNER TO postgres;

--
-- Name: rcap_service_record_commercial_authority(text, uuid, text, uuid, text, text, timestamp with time zone, uuid, uuid, bigint, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_service_record_commercial_authority(p_slug text, p_actor uuid, p_kind text, p_document uuid, p_hash text, p_reference text, p_expires timestamp with time zone, p_packet uuid, p_request uuid, p_version bigint, p_reconcile boolean) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare w public.partner_onboarding%rowtype; a uuid; mode text; old public.rcap_commercial_authorizations%rowtype; begin
 perform public.rcap_service_assert_internal_actor(p_actor);
 select * into strict w from public.partner_onboarding where partner_slug=p_slug for update;
 select * into old from public.rcap_commercial_authorizations where workspace_id=w.id and request_id=p_request;
 if found then
 if old.actor_auth_user_id<>p_actor or old.kind<>p_kind or old.document_id<>p_document or old.document_hash<>p_hash or old.authority_reference<>p_reference or old.expires_at<>p_expires or old.packet_entitlement_id<>p_packet then raise exception 'request binding conflict'; end if; return old.id; end if;
 if w.aggregate_version<>p_version or w.status='live' or not p_reconcile then raise exception 'explicit current-source reconciliation required'; end if;
 if exists(select 1 from public.rcap_launch_operation_events e where e.workspace_id=w.id and e.step='prepared' and not exists(select 1 from public.rcap_launch_operation_events t where t.operation_id=e.operation_id and t.step in ('complete','held','failed'))) then raise exception 'launch in progress'; end if;
 select response_data->>'participant_access_model' into strict mode from public.partner_onboarding_sections where workspace_id=w.id and section_key='access_sponsorship_capacity';
 insert into public.rcap_commercial_authorizations(workspace_id,kind,document_id,document_hash,authority_reference,access_mode,packet_entitlement_id,actor_auth_user_id,expires_at,request_id)
 values(w.id,p_kind,p_document,p_hash,p_reference,mode,p_packet,p_actor,p_expires,p_request) returning id into a;
 -- Reconcile access/provisioning from documented authority. Never write payment.
 update public.partner_records set access_mode=mode,provisioning_status='provisioned' where id=w.partner_record_id;
 update public.partner_onboarding set aggregate_version=aggregate_version+1 where id=w.id;
 -- A changed commercial/activation source requires renewed exact-source approvals.
 update public.partner_onboarding_launch_checks set invalidated_at=now(),invalidated_reason='Commercial authorization and activation reconciled' where workspace_id=w.id;
 update public.partner_onboarding_launch_approvals set invalidated_at=now() where workspace_id=w.id;
 return a;
end $$;


ALTER FUNCTION public.rcap_service_record_commercial_authority(p_slug text, p_actor uuid, p_kind text, p_document uuid, p_hash text, p_reference text, p_expires timestamp with time zone, p_packet uuid, p_request uuid, p_version bigint, p_reconcile boolean) OWNER TO postgres;

--
-- Name: rcap_service_record_limited_program_authority(text, uuid, uuid, text, jsonb, timestamp with time zone, integer, bigint, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_service_record_limited_program_authority(p_slug text, p_actor uuid, p_document uuid, p_reference text, p_basis jsonb, p_expires timestamp with time zone, p_screenings integer, p_version bigint, p_request uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare w public.partner_onboarding%rowtype; old public.rcap_commercial_authorizations%rowtype; d public.partner_onboarding_assets%rowtype; ident uuid; mode text;
begin
 perform public.rcap_service_assert_internal_actor(p_actor);
 select * into strict w from public.partner_onboarding where partner_slug=p_slug for update;
 select * into old from public.rcap_commercial_authorizations where workspace_id=w.id and request_id=p_request;
 if found then
 if old.actor_auth_user_id is distinct from p_actor or old.document_id is distinct from p_document or old.legal_basis is distinct from (p_basis||jsonb_build_object('screenings_allowed',p_screenings)) or old.authority_reference is distinct from p_reference or old.expires_at is distinct from p_expires then raise exception 'request identity conflict';end if;return old.id;end if;
 if w.rcap_policy_version<>'rcap2.2' or w.status in ('live','closed') or w.landing_page_ready or p_version is null or w.aggregate_version<>p_version then raise exception 'source changed' using errcode='40001';end if;
 if p_screenings is null or p_screenings<1 or p_screenings>1000000 or p_expires is null or p_expires<=now() or p_basis is null or p_basis->>'funding_obligation' is distinct from 'none' or coalesce(length(btrim(p_basis->>'policy_reference')),0)<10 or coalesce(length(btrim(p_basis->>'effective_conditions')),0)<10 or coalesce(length(btrim(p_basis->>'termination_rule')),0)<10 or coalesce(p_basis->>'agreement_requirement','') not in ('not_required','executed') then raise exception 'documented limited service basis required';end if;
 if p_basis->>'agreement_requirement'='executed' and not public.rcap_agreement_clearance(w.id) then raise exception 'executed agreement required';end if;
 if p_basis->>'agreement_requirement'='not_required' and exists(select 1 from public.partner_onboarding_agreements where workspace_id=w.id and is_required and status not in ('not_required','waived')) then raise exception 'required contractual evidence cannot be waived';end if;
 select * into strict d from public.partner_onboarding_assets where id=p_document and workspace_id=w.id and category='procurement_document' and review_status='approved' and lifecycle_status='active' and deleted_at is null;
 select response_data->>'participant_access_model' into mode from public.partner_onboarding_sections where workspace_id=w.id and section_key='access_sponsorship_capacity';
 perform 1 from public.partner_entitlement where partner_slug=p_slug for update;
 if exists(select 1 from public.partner_entitlement where partner_slug=p_slug and screenings_used>p_screenings) then raise exception 'allowance below actual use';end if;
 insert into public.rcap_commercial_authorizations(workspace_id,kind,document_id,document_hash,authority_reference,access_mode,packet_entitlement_id,actor_auth_user_id,expires_at,request_id,legal_basis)
 values(w.id,'screening_only',d.id,d.sha256_hex,p_reference,mode,null,p_actor,p_expires,p_request,p_basis||jsonb_build_object('screenings_allowed',p_screenings)) returning id into ident;
 insert into public.partner_entitlement(partner_slug,screenings_allowed,screenings_used) values(p_slug,p_screenings,0)
 on conflict(partner_slug) do update set screenings_allowed=excluded.screenings_allowed;
 update public.partner_records set access_mode=mode,provisioning_status='provisioned' where id=w.partner_record_id;
 update public.partner_onboarding set aggregate_version=aggregate_version+1 where id=w.id;
 return ident;
end $$;


ALTER FUNCTION public.rcap_service_record_limited_program_authority(p_slug text, p_actor uuid, p_document uuid, p_reference text, p_basis jsonb, p_expires timestamp with time zone, p_screenings integer, p_version bigint, p_request uuid) OWNER TO postgres;

--
-- Name: rcap_service_record_onboarding_asset(text, uuid, uuid, uuid, bigint, text, text, text, text, text, text, bigint, integer, integer, text, text, integer, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_service_record_onboarding_asset(p_partner_slug text, p_actor_user_id uuid, p_workspace_id uuid, p_asset_id uuid, p_expected_workspace_version bigint, p_category text, p_object_path text, p_original_filename text, p_safe_filename text, p_media_type text, p_file_extension text, p_byte_size bigint, p_width_pixels integer, p_height_pixels integer, p_sha256_hex text, p_payload_hash text, p_workspace_completion integer, p_blocker_code text, p_next_action_code text, p_next_action_owner text, p_request_id uuid) RETURNS TABLE(asset_id uuid, superseded_object_path text, workspace_aggregate_version bigint, duplicate boolean)
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
declare
  v_workspace public.partner_onboarding%rowtype;
  v_existing_asset public.partner_onboarding_assets%rowtype;
  v_existing_request public.partner_onboarding_idempotency%rowtype;
  v_partner_record_id uuid;
begin
  perform public.rcap_service_assert_partner_actor(
    p_partner_slug, p_actor_user_id, p_workspace_id
  );
  if p_category not in (
    'transparent_logo',
    'brand_guide',
    'hero_or_community_image',
    'organizer_or_program_lead_image',
    'approved_partner_description_attachment',
    'procurement_document',
    'other_approved_organizational_asset'
  )
     or p_expected_workspace_version < 1
     or p_sha256_hex !~ '^[0-9a-f]{64}$'
     or p_payload_hash !~ '^[0-9a-f]{64}$'
     or p_workspace_completion not between 0 and 100
     or p_next_action_owner not in ('partner', 'legalease', 'none') then
    raise exception using errcode = '22023', message = 'Invalid organizational asset metadata';
  end if;

  select *
    into v_existing_request
  from public.partner_onboarding_idempotency i
  where i.request_id = p_request_id
  for update;
  if found then
    if v_existing_request.workspace_id <> p_workspace_id
       or v_existing_request.operation_key <> 'asset:record:' || p_category
       or v_existing_request.actor_user_id <> p_actor_user_id
       or v_existing_request.payload_hash <> p_payload_hash then
      raise exception using errcode = '23505', message = 'Idempotency request mismatch';
    end if;
    if v_existing_request.result_status = 'succeeded' then
      return query
      select
        a.id,
        null::text,
        v_existing_request.result_workspace_version,
        true
      from public.partner_onboarding_assets a
      where a.id = p_asset_id
        and a.workspace_id = p_workspace_id;
      return;
    end if;
    raise exception using errcode = '55000', message = 'Idempotent request is still in progress';
  end if;

  select *
    into v_workspace
  from public.partner_onboarding po
  where po.id = p_workspace_id
    and po.partner_slug = p_partner_slug
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'Onboarding workspace not found';
  end if;
  if v_workspace.aggregate_version <> p_expected_workspace_version then
    raise exception using
      errcode = '40001',
      message = 'Onboarding workspace revision conflict';
  end if;
  if v_workspace.commercial_gate_status = 'blocked'
     or v_workspace.status not in ('setup_in_progress', 'waiting_on_partner') then
    raise exception using errcode = '55000', message = 'Workspace is not editable';
  end if;
  select coalesce(v_workspace.partner_record_id, pr.id)
    into v_partner_record_id
  from public.partner_records pr
  where pr.partner_slug = p_partner_slug;

  insert into public.partner_onboarding_idempotency (
    workspace_id,
    operation_key,
    request_id,
    actor_user_id,
    payload_hash,
    expires_at
  ) values (
    p_workspace_id,
    'asset:record:' || p_category,
    p_request_id,
    p_actor_user_id,
    p_payload_hash,
    now() + interval '24 hours'
  );

  select *
    into v_existing_asset
  from public.partner_onboarding_assets a
  where a.workspace_id = p_workspace_id
    and a.category = p_category
    and a.deleted_at is null
    and a.lifecycle_status in ('pending_review', 'active')
  for update;

  if found then
    if exists (
      select 1
      from public.partner_onboarding_agreements agreement
      where agreement.finalized_asset_id = v_existing_asset.id
    ) then
      raise exception using
        errcode = '55000',
        message = 'A finalized agreement document cannot be replaced';
    end if;
    update public.partner_onboarding_assets
    set
      lifecycle_status = 'superseded',
      updated_at = now()
    where id = v_existing_asset.id;
  end if;

  insert into public.partner_onboarding_assets (
    id,
    workspace_id,
    partner_record_id,
    category,
    object_path,
    original_filename,
    safe_filename,
    media_type,
    file_extension,
    byte_size,
    width_pixels,
    height_pixels,
    sha256_hex,
    lifecycle_status,
    review_status,
    uploaded_by
  ) values (
    p_asset_id,
    p_workspace_id,
    v_partner_record_id,
    p_category,
    p_object_path,
    p_original_filename,
    p_safe_filename,
    p_media_type,
    p_file_extension,
    p_byte_size,
    p_width_pixels,
    p_height_pixels,
    p_sha256_hex,
    'pending_review',
    'pending',
    p_actor_user_id
  );

  if v_existing_asset.id is not null then
    update public.partner_onboarding_assets
    set replaced_by_asset_id = p_asset_id
    where id = v_existing_asset.id;
  end if;

  update public.partner_onboarding
  set
    aggregate_version = aggregate_version + 1,
    completion_percentage = p_workspace_completion,
    blocker_code = p_blocker_code,
    next_action_code = p_next_action_code,
    next_action_owner = p_next_action_owner,
    last_meaningful_activity_at = now()
  where id = p_workspace_id
  returning aggregate_version into workspace_aggregate_version;

  insert into public.partner_onboarding_activity (
    workspace_id,
    event_type,
    section_key,
    status_code,
    summary_code,
    owner_type,
    actor_user_id,
    request_id,
    dedupe_key
  ) values (
    p_workspace_id,
    case
      when v_existing_asset.id is null then 'required_asset_uploaded'
      else 'required_asset_replaced'
    end,
    'brand_public_page',
    'pending_review',
    case
      when v_existing_asset.id is null then 'required_asset_uploaded'
      else 'required_asset_replaced'
    end,
    'partner',
    p_actor_user_id,
    p_request_id,
    p_request_id::text || ':asset-record'
  )
  on conflict do nothing;

  insert into public.partner_onboarding_integration_events (
    workspace_id,
    partner_record_id,
    event_type,
    workspace_aggregate_version,
    workspace_status,
    completion_percentage,
    blocker_code,
    next_action_code,
    next_action_owner,
    target_launch_date,
    section_key,
    artifact_category,
    artifact_status,
    idempotency_key
  )
  select
    po.id,
    v_partner_record_id,
    'rcap_brand_configuration_changed',
    po.aggregate_version,
    po.status,
    po.completion_percentage,
    po.blocker_code,
    po.next_action_code,
    po.next_action_owner,
    po.target_launch_date,
    'brand_public_page',
    p_category,
    'pending_review',
    p_request_id::text || ':asset-record'
  from public.partner_onboarding po
  where po.id = p_workspace_id
  on conflict do nothing;

  update public.partner_onboarding_idempotency
  set
    result_status = 'succeeded',
    result_workspace_version = workspace_aggregate_version,
    completed_at = now()
  where request_id = p_request_id;

  asset_id := p_asset_id;
  superseded_object_path := v_existing_asset.object_path;
  duplicate := false;
  return next;
end;
$_$;


ALTER FUNCTION public.rcap_service_record_onboarding_asset(p_partner_slug text, p_actor_user_id uuid, p_workspace_id uuid, p_asset_id uuid, p_expected_workspace_version bigint, p_category text, p_object_path text, p_original_filename text, p_safe_filename text, p_media_type text, p_file_extension text, p_byte_size bigint, p_width_pixels integer, p_height_pixels integer, p_sha256_hex text, p_payload_hash text, p_workspace_completion integer, p_blocker_code text, p_next_action_code text, p_next_action_owner text, p_request_id uuid) OWNER TO postgres;

--
-- Name: rcap_service_record_onboarding_launch_approval(text, uuid, text, uuid, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_service_record_onboarding_launch_approval(p_partner_slug text, p_actor_user_id uuid, p_reviewer_type text, p_workspace_id uuid, p_approval_type text, p_decision text, p_comments text, p_request_id uuid) RETURNS TABLE(approval_id uuid, duplicate boolean)
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_partner_record_id uuid;
  v_existing uuid;
  v_row public.partner_onboarding_launch_approvals%rowtype;
  v_check_key text;
  v_owner text;
begin
  if p_decision not in ('approve', 'withdraw') then
    raise exception 'invalid_decision' using errcode = '22023';
  end if;

  if p_approval_type = 'partner_launch_approval' then
    v_check_key := 'partner_launch_approval_received';
    v_owner := 'partner';
  elsif p_approval_type = 'legalease_final_review' then
    v_check_key := 'legalease_final_review_complete';
    v_owner := 'legalease';
  else
    raise exception 'invalid_approval_type' using errcode = '22023';
  end if;

  if p_reviewer_type <> v_owner then
    raise exception 'reviewer_does_not_own_approval' using errcode = '42501';
  end if;

  select po.partner_record_id into v_partner_record_id
  from public.partner_onboarding po
  where po.id = p_workspace_id
    and po.partner_slug = p_partner_slug;

  if v_partner_record_id is null then
    raise exception 'workspace_not_found' using errcode = 'P0002';
  end if;

  select a.id into v_existing
  from public.partner_onboarding_launch_approvals a
  where a.workspace_id = p_workspace_id
    and a.request_id = p_request_id;

  if v_existing is not null then
    approval_id := v_existing;
    duplicate := true;
    return next;
    return;
  end if;

  insert into public.partner_onboarding_launch_approvals (
    workspace_id, approval_type, reviewer_type, reviewer_user_id,
    decision, comments, request_id
  )
  values (
    p_workspace_id, p_approval_type, p_reviewer_type, p_actor_user_id,
    p_decision, p_comments, p_request_id
  )
  returning * into v_row;

  insert into public.partner_onboarding_launch_checks (
    workspace_id, partner_record_id, check_key, category, owner_type,
    determination, blocking, status, evidence_summary, evidence_reference,
    checked_at, checked_by, request_id
  )
  values (
    p_workspace_id, v_partner_record_id, v_check_key, 'approvals', v_owner,
    'manual', true,
    case when p_decision = 'approve' then 'passing' else 'failing' end,
    case when p_decision = 'approve'
      then 'Launch approval recorded.'
      else 'Launch approval withdrawn.'
    end,
    'launch_approval',
    case when p_decision = 'approve' then now() else null end,
    case when p_decision = 'approve' then p_actor_user_id else null end,
    p_request_id
  )
  on conflict (workspace_id, check_key) do update
  set status = excluded.status,
      evidence_summary = excluded.evidence_summary,
      checked_at = excluded.checked_at,
      checked_by = excluded.checked_by,
      invalidated_at = null,
      invalidated_reason = null,
      request_id = excluded.request_id;

  insert into public.partner_onboarding_activity (
    workspace_id, event_type, owner_type, summary_code, status_code
  )
  values (
    p_workspace_id, 'launch_approval_recorded',
    case when p_reviewer_type = 'partner' then 'partner' else 'legalease' end,
    p_approval_type, p_decision
  );

  approval_id := v_row.id;
  duplicate := false;
  return next;
end;
$$;


ALTER FUNCTION public.rcap_service_record_onboarding_launch_approval(p_partner_slug text, p_actor_user_id uuid, p_reviewer_type text, p_workspace_id uuid, p_approval_type text, p_decision text, p_comments text, p_request_id uuid) OWNER TO postgres;

--
-- Name: rcap_service_record_onboarding_launch_check(text, uuid, text, uuid, text, text, text, boolean, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_service_record_onboarding_launch_check(p_partner_slug text, p_actor_user_id uuid, p_reviewer_type text, p_workspace_id uuid, p_check_key text, p_category text, p_owner_type text, p_blocking boolean, p_status text, p_evidence_summary text, p_request_id uuid) RETURNS TABLE(check_id uuid, check_status text, duplicate boolean)
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_partner_record_id uuid;
  v_existing public.partner_onboarding_launch_checks%rowtype;
  v_row public.partner_onboarding_launch_checks%rowtype;
begin
  if p_reviewer_type not in ('legalease', 'partner') then
    raise exception 'invalid_reviewer_type' using errcode = '22023';
  end if;
  if p_status not in ('passing', 'needs_review', 'waived', 'not_applicable') then
    raise exception 'invalid_launch_check_status' using errcode = '22023';
  end if;
  -- Only LegalEase may waive a check or mark one not applicable.
  if p_reviewer_type = 'partner'
     and p_status in ('waived', 'not_applicable') then
    raise exception 'waiver_requires_legalease' using errcode = '42501';
  end if;
  -- A reviewer may only decide a check its own side owns.
  if p_reviewer_type <> p_owner_type then
    raise exception 'reviewer_does_not_own_check' using errcode = '42501';
  end if;

  select po.partner_record_id into v_partner_record_id
  from public.partner_onboarding po
  where po.id = p_workspace_id
    and po.partner_slug = p_partner_slug;

  if v_partner_record_id is null then
    raise exception 'workspace_not_found' using errcode = 'P0002';
  end if;

  select c.* into v_existing
  from public.partner_onboarding_launch_checks c
  where c.workspace_id = p_workspace_id
    and c.request_id = p_request_id;

  if v_existing.id is not null then
    check_id := v_existing.id;
    check_status := v_existing.status;
    duplicate := true;
    return next;
    return;
  end if;

  insert into public.partner_onboarding_launch_checks (
    workspace_id, partner_record_id, check_key, category, owner_type,
    determination, blocking, status, evidence_summary, evidence_reference,
    checked_at, checked_by, request_id
  )
  values (
    p_workspace_id, v_partner_record_id, p_check_key, p_category, p_owner_type,
    'manual', p_blocking, p_status, p_evidence_summary, 'manual_review',
    now(), p_actor_user_id, p_request_id
  )
  on conflict (workspace_id, check_key) do update
  set status = excluded.status,
      evidence_summary = excluded.evidence_summary,
      checked_at = excluded.checked_at,
      checked_by = excluded.checked_by,
      blocking = excluded.blocking,
      category = excluded.category,
      -- Recording a fresh decision clears the previous invalidation.
      invalidated_at = null,
      invalidated_reason = null,
      request_id = excluded.request_id
  returning * into v_row;

  insert into public.partner_onboarding_activity (
    workspace_id, event_type, owner_type, summary_code, status_code
  )
  values (
    p_workspace_id,
    'launch_check_recorded',
    case when p_reviewer_type = 'partner' then 'partner' else 'legalease' end,
    p_check_key,
    p_status
  );

  check_id := v_row.id;
  check_status := v_row.status;
  duplicate := false;
  return next;
end;
$$;


ALTER FUNCTION public.rcap_service_record_onboarding_launch_check(p_partner_slug text, p_actor_user_id uuid, p_reviewer_type text, p_workspace_id uuid, p_check_key text, p_category text, p_owner_type text, p_blocking boolean, p_status text, p_evidence_summary text, p_request_id uuid) OWNER TO postgres;

--
-- Name: rcap_service_record_onboarding_launch_readiness(text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_service_record_onboarding_launch_readiness(p_partner_slug text, p_workspace_id uuid, p_state text) RETURNS TABLE(changed boolean)
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_updated public.partner_onboarding%rowtype;
begin
  if p_state not in ('ready', 'not_ready') then
    raise exception 'invalid_readiness_state' using errcode = '22023';
  end if;

  update public.partner_onboarding po
  set launch_readiness_state = p_state
  where po.id = p_workspace_id
    and po.partner_slug = p_partner_slug
    and po.launch_readiness_state is distinct from p_state
  returning * into v_updated;

  if v_updated.id is null then
    changed := false;
    return next;
    return;
  end if;

  insert into public.partner_onboarding_activity (
    workspace_id, event_type, owner_type, summary_code, status_code
  )
  values (
    p_workspace_id,
    case when p_state = 'ready'
      then 'launch_readiness_achieved'
      else 'launch_readiness_lost'
    end,
    'system',
    'launch_readiness',
    p_state
  );

  changed := true;
  return next;
end;
$$;


ALTER FUNCTION public.rcap_service_record_onboarding_launch_readiness(p_partner_slug text, p_workspace_id uuid, p_state text) OWNER TO postgres;

--
-- Name: rcap_service_record_program_decision(text, uuid, text, text, bigint, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_service_record_program_decision(p_slug text, p_actor uuid, p_type text, p_decision text, p_version bigint, p_details jsonb, p_request uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare w public.partner_onboarding%rowtype; old public.partner_onboarding_launch_approvals%rowtype; d jsonb; ident uuid; rt text;
begin
 select * into strict w from public.partner_onboarding where partner_slug=p_slug for update;
 if p_type='partner_launch_approval' then perform public.rcap_service_assert_partner_actor(p_slug,p_actor,w.id);rt:='partner';
 else perform public.rcap_service_assert_internal_actor(p_actor);rt:='legalease';end if;
 if p_type not in ('partner_launch_approval','legalease_final_review','standing_launch_authorization','commercial_revocation') or p_decision not in ('approve','withdraw') or p_details is null then raise exception 'invalid decision';end if;
 select * into old from public.partner_onboarding_launch_approvals where workspace_id=w.id and request_id=p_request;
 if found then
  if old.reviewer_user_id is distinct from p_actor or old.approval_type is distinct from p_type or old.decision is distinct from p_decision or old.policy_details is distinct from p_details then raise exception 'request identity conflict' using errcode='23505'; end if;
  return old.id;
 end if;
 if w.rcap_policy_version<>'rcap2.2' or p_version is null or w.aggregate_version<>p_version or p_details->>'policy_version' is distinct from 'rcap2.2' then raise exception 'source changed' using errcode='PT409';end if;
 if p_decision='approve' then
  if p_type='partner_launch_approval' then
   d:=public.rcap_service_evaluate_program(p_slug,p_actor,'complete_setup');
   if not (d->>'allowed')::boolean or p_details->>'materials_hash' is distinct from d->>'materialsHash' or p_details->>'statement_version' is distinct from 'rcap2-final-review-v1' then raise exception 'current substantive partner review required';end if;
   if (select count(*) from public.partner_onboarding_artifacts ar join public.partner_onboarding_artifact_versions v on v.id=ar.current_version_id where ar.workspace_id=w.id and ar.artifact_type in ('implementation_brief','co_branded_page_configuration') and v.generation_status='succeeded' and v.source_drift_invalidated_at is null and v.superseded_at is null and v.normalized_snapshot->>'rcap_dependency_hash'=public.rcap_program_material_scope(w.id,ar.artifact_type) and (ar.artifact_type<>'co_branded_page_configuration' or v.rendered_content#>'{pagePreview,missing}'='[]'::jsonb))<>2 then raise exception 'two current materials required';end if;
   -- These are real partner reviews of the two exact versions shown, not internal approvals.
   for ident in select current_version_id from public.partner_onboarding_artifacts where workspace_id=w.id and artifact_type in ('implementation_brief','co_branded_page_configuration') loop
    perform public.rcap_service_review_onboarding_artifact(p_slug,p_actor,'partner',ident,'approve','RCAP final factual and brand review',null,p_request);
   end loop;
  elsif w.operating_model='legalease_managed' and p_type='legalease_final_review' then
   d:=public.rcap_service_evaluate_program(p_slug,p_actor,'publish_partner_page');
   if not coalesce((d->>'canAuthorizeStart')::boolean,false)
    or p_details->>'scope_hash' is distinct from d->>'scopeHash'
    or p_details->>'materials_hash' is distinct from d->>'materialsHash'
    or p_details->>'operating_model' is distinct from 'legalease_managed'
    or p_details->>'operator_identity' is distinct from 'LegalEase'
    or p_details->>'authority_basis' is distinct from public.rcap_program_policy_source(w.id)#>>'{program_goals,operator_authority_reference}'
    or p_details->>'service_mode' is distinct from public.rcap_program_policy_source(w.id)#>>'{program_goals,service_mode}'
    or p_details->'jurisdictions' is distinct from d->'jurisdictions'
    or p_details->'spanish_enabled' is distinct from coalesce(public.rcap_program_policy_source(w.id)#>'{geography_audience_language_accessibility,enable_spanish}','false'::jsonb)
    or p_details->>'publication_scope' is distinct from '/p/'||p_slug
    or jsonb_typeof(p_details->'material_versions') is distinct from 'array' or jsonb_array_length(p_details->'material_versions')<>2
    or exists(select 1 from public.partner_onboarding_artifacts ar join public.partner_onboarding_artifact_versions v on v.id=ar.current_version_id where ar.workspace_id=w.id and ar.artifact_type in ('implementation_brief','co_branded_page_configuration') and not exists(select 1 from jsonb_array_elements(p_details->'material_versions') m where m->>'type'=ar.artifact_type and m->>'id'=v.id::text and m->>'hash'=v.snapshot_hash and (m->>'version')::integer=v.version_number))
    or p_details->>'statement_version' is distinct from 'rcap-operating-confirmation-v1'
    or p_details->'capabilities' is distinct from ('["publish_partner_page","accept_screenings"]'::jsonb || case when public.rcap_program_policy_source(w.id)#>>'{program_goals,participation_mode}' in ('clinics','both') then '["create_clinic","publish_clinic"]'::jsonb else '[]'::jsonb end || case public.rcap_program_policy_source(w.id)#>>'{program_goals,service_mode}' when 'participant_paid' then '["offer_paid_packet"]'::jsonb when 'sponsored_packets' then '["issue_sponsored_packet"]'::jsonb else '[]'::jsonb end)
    or jsonb_typeof(p_details->'screening_profiles') is distinct from 'object'
    or exists(select 1 from jsonb_array_elements_text(d->'jurisdictions') j where coalesce(length(p_details->'screening_profiles'->>j),0)=0)
    then raise exception 'current internal operating scope and exact materials required' using errcode='42501';end if;
   for ident in select current_version_id from public.partner_onboarding_artifacts where workspace_id=w.id and artifact_type in ('implementation_brief','co_branded_page_configuration') loop
    perform public.rcap_service_review_onboarding_artifact(p_slug,p_actor,'legalease',ident,'approve','Platform Admin operating and publication confirmation',null,p_request);
   end loop;
  else
   if p_details->>'scope_hash' is distinct from public.rcap_program_launch_scope(w.id) or (p_details->>'expires_at')::timestamptz is null or (p_details->>'expires_at')::timestamptz<=now()
    or coalesce(length(btrim(p_details->>'authority_basis')),0)<10 or p_details->'capabilities' is null or not (p_details->'capabilities' ? 'publish_partner_page')
    or not public.rcap_program_commercial_valid(w.id) then raise exception 'current scoped business authorization required';end if;
   if exists(select 1 from jsonb_array_elements_text(p_details->'capabilities') c where c not in ('publish_partner_page','accept_screenings','create_clinic','publish_clinic')) then raise exception 'delegation cannot grant participant or financial authority';end if;
  end if;
 end if;
 insert into public.partner_onboarding_launch_approvals(workspace_id,approval_type,reviewer_type,reviewer_user_id,decision,comments,request_id,policy_details)
 values(w.id,p_type,rt,p_actor,p_decision,'RCAP 2.0 scoped program decision',p_request,p_details) returning id into ident;
 return ident;
end $$;


ALTER FUNCTION public.rcap_service_record_program_decision(p_slug text, p_actor uuid, p_type text, p_decision text, p_version bigint, p_details jsonb, p_request uuid) OWNER TO postgres;

--
-- Name: rcap_service_record_program_exception(text, uuid, text, text[], text, text, bigint, jsonb, uuid, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_service_record_program_exception(p_slug text, p_actor uuid, p_action text, p_keys text[], p_resolution text, p_reason text, p_version bigint, p_hashes jsonb, p_request uuid, p_expires timestamp with time zone DEFAULT NULL::timestamp with time zone, p_grant uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare w public.partner_onboarding%rowtype; key text; item jsonb; ident uuid; old public.rcap_launch_exception_events%rowtype;
begin
 perform public.rcap_service_assert_internal_actor(p_actor);
 select * into strict w from public.partner_onboarding where partner_slug=p_slug for update;
 if p_keys is null or cardinality(p_keys)=0 or cardinality(p_keys)>32 or coalesce(length(btrim(p_reason)),0)<10 or p_resolution not in ('not_applicable','alternative_authorized','exception_granted') then raise exception 'specific business decision required';end if;
 select * into old from public.rcap_launch_exception_events where workspace_id=w.id and request_id=p_request;
 if found then
 if old.actor_auth_user_id is distinct from p_actor or old.requirement_keys is distinct from p_keys or old.requested_action is distinct from p_action or old.resolution is distinct from p_resolution or old.reason is distinct from p_reason or old.dependency_hashes is distinct from p_hashes or old.grant_id is distinct from p_grant or old.expires_at is distinct from p_expires then raise exception 'request identity conflict';end if;return old.id;end if;
 if w.rcap_policy_version<>'rcap2.2' or p_version is null or w.aggregate_version<>p_version then raise exception 'source changed' using errcode='40001';end if;
 foreach key in array p_keys loop
  select value into item from jsonb_array_elements(public.rcap_program_requirement_registry()) where value->>'key'=key;
  if item is null or item->>'owner_domain'<>'legalease_business' or item->>'classification'<>'EXCEPTION_ELIGIBLE' or not item->'exception_effects' ? p_action or item->>'permitted_alternative' is null then raise exception 'protected or unknown requirement' using errcode='42501';end if;
  if p_hashes->>key is distinct from public.rcap_program_dependency_hash(w.id,array(select jsonb_array_elements_text(item->'dependencies'))) then raise exception 'requirement source changed' using errcode='40001';end if;
 end loop;
 insert into public.rcap_launch_exception_events(kind,grant_id,workspace_id,partner_slug,check_key,actor_auth_user_id,actor_role,request_id,reason,authority_reference,snapshot_hash,expires_at,policy_version,requirement_keys,requested_action,resolution,dependency_hashes)
 values(case when p_grant is null then 'grant' else 'revoke' end,p_grant,w.id,p_slug,p_keys[1],p_actor,'internal_admin',p_request,p_reason,'Owner-authorized RCAP 2.2 business policy',public.rcap_program_launch_scope(w.id),p_expires,'rcap2.2',p_keys,p_action,p_resolution,p_hashes) returning id into ident;
 return ident;
end $$;


ALTER FUNCTION public.rcap_service_record_program_exception(p_slug text, p_actor uuid, p_action text, p_keys text[], p_resolution text, p_reason text, p_version bigint, p_hashes jsonb, p_request uuid, p_expires timestamp with time zone, p_grant uuid) OWNER TO postgres;

--
-- Name: rcap_service_record_signed_agreement(text, uuid, bigint, uuid, text, uuid, boolean, text, text, text, text, bigint, text, date, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_service_record_signed_agreement(p_slug text, p_actor uuid, p_expected_version bigint, p_request uuid, p_agreement_type text, p_asset uuid, p_new_asset boolean, p_object_path text, p_filename text, p_media_type text, p_extension text, p_byte_size bigint, p_sha256 text, p_effective_date date, p_review_reason text, p_confirmed boolean) RETURNS TABLE(workspace_version bigint, document_id uuid, duplicate boolean)
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
declare
  w public.partner_onboarding%rowtype;
  prior public.rcap_signed_agreement_receipts%rowtype;
  doc public.partner_onboarding_assets%rowtype;
  previous_doc public.partner_onboarding_assets%rowtype;
  previous_agreement jsonb;
  contract_changed boolean;
begin
  perform public.rcap_service_assert_internal_actor(p_actor);
  if p_confirmed is distinct from true or p_new_asset is null
     or p_request is null or p_asset is null or p_agreement_type is null
     or p_sha256 is null or p_agreement_type not in ('order_form','master_services_agreement')
     or p_effective_date is null or p_effective_date>current_date
     or length(btrim(coalesce(p_review_reason,''))) not between 10 and 5000
     or p_sha256 !~ '^[a-f0-9]{64}$' then
    raise exception 'A reviewed, executed agreement and signed document are required' using errcode='22023';
  end if;

  select * into strict w from public.partner_onboarding
    where partner_slug=p_slug for update;
  select * into prior from public.rcap_signed_agreement_receipts where id=p_request;
  if found then
    if prior.workspace_id<>w.id or prior.partner_slug<>p_slug
       or prior.actor_auth_user_id<>p_actor or prior.agreement_type<>p_agreement_type
       or (not p_new_asset and prior.asset_id is distinct from p_asset)
       or prior.asset_sha256<>p_sha256
       or prior.effective_date<>p_effective_date
       or prior.reviewed_reason<>btrim(p_review_reason) then
       raise exception 'Executed agreement request was reused with different inputs' using errcode='23505';
    end if;
    return query select prior.workspace_version,prior.asset_id,true;
    return;
  end if;

  if w.aggregate_version is distinct from p_expected_version
     or w.status in ('live','paused','closed')
     or (w.rcap_policy_version<>'rcap2.2' and w.commercial_gate_status='blocked') then
    -- A stale user snapshot is not a retryable database serialization failure.
    raise exception 'Current unpublished agreement workspace required' using errcode='55000';
  end if;

  if p_new_asset then
    if not exists(select 1 from storage.objects o join storage.buckets b on b.id=o.bucket_id
      where o.bucket_id='rcap-partner-onboarding-private' and o.name=p_object_path and b.public=false) then
      raise exception 'Executed copy is absent from private storage' using errcode='55000';
    end if;
    if p_media_type is null or p_extension is null
       or p_object_path is null or p_filename is null or p_byte_size is null
       or p_media_type not in (
      'application/pdf',
      'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
    ) or (p_media_type='application/pdf' and p_extension<>'pdf')
       or (p_media_type<>'application/pdf' and p_extension<>'docx')
       or p_byte_size<1 or p_byte_size>20971520
       or length(p_filename) not between 1 and 240
       or p_object_path<>('partners/'||w.partner_record_id::text||
       '/onboarding/'||w.id::text||'/procurement_document/'||p_asset::text||'.'||p_extension)
    then raise exception 'Signed file identity or document type is invalid' using errcode='22023';
    end if;
    select * into previous_doc from public.partner_onboarding_assets
      where workspace_id=w.id and category='procurement_document'
        and lifecycle_status in ('active','pending_review') and deleted_at is null for update;
    if found then
      -- Retain the original object and agreement evidence; only its current
      -- procurement slot is superseded by this executed copy.
      update public.partner_onboarding_assets set lifecycle_status='superseded',
        updated_at=now() where id=previous_doc.id;
    end if;
    insert into public.partner_onboarding_assets(
      id,workspace_id,partner_record_id,category,object_path,original_filename,
      safe_filename,media_type,file_extension,byte_size,sha256_hex,
      lifecycle_status,review_status,review_reason,uploaded_by
    ) values(
      p_asset,w.id,w.partner_record_id,'procurement_document',p_object_path,
      p_filename,'signed-agreement.'||p_extension,p_media_type,p_extension,
      p_byte_size,p_sha256,'active','approved',
      'Executed signed agreement inspected and certified by Platform Admin',p_actor
    );
  end if;

  select * into doc from public.partner_onboarding_assets
    where id=p_asset and workspace_id=w.id
      and category='procurement_document' and deleted_at is null
      and lifecycle_status='active' and review_status='approved'
      and sha256_hex=p_sha256 for update;
  if not found then
    raise exception 'An active, approved, matching signed agreement document is required' using errcode='55000';
  end if;
  if doc.media_type not in ('application/pdf','application/vnd.openxmlformats-officedocument.wordprocessingml.document')
     or not exists(select 1 from storage.objects o join storage.buckets b on b.id=o.bucket_id
       where o.bucket_id=doc.bucket_id and o.name=doc.object_path
         and b.id='rcap-partner-onboarding-private' and b.public=false) then
    raise exception 'The executed document must exist in private storage' using errcode='55000';
  end if;

  select to_jsonb(a) into previous_agreement from public.partner_onboarding_agreements a
    where a.workspace_id=w.id and a.agreement_type=p_agreement_type;
  contract_changed := previous_agreement is null
    or previous_agreement->>'status' is distinct from 'executed'
    or previous_agreement->>'finalized_asset_id' is distinct from doc.id::text
    or previous_agreement->>'effective_date' is distinct from p_effective_date::text
    or previous_agreement->>'signed_asset_sha256' is distinct from p_sha256
    or previous_agreement->>'signed_receipt_id' is null;
  insert into public.rcap_signed_agreement_receipts(
    id,workspace_id,partner_slug,actor_auth_user_id,agreement_type,asset_id,
    asset_sha256,effective_date,reviewed_reason,workspace_version,previous_agreement
  ) values(p_request,w.id,p_slug,p_actor,p_agreement_type,doc.id,
    p_sha256,p_effective_date,btrim(p_review_reason),w.aggregate_version+1,previous_agreement);

  insert into public.partner_onboarding_agreements(
    workspace_id,agreement_type,status,is_required,partner_safe_detail,
    finalized_asset_id,effective_date,recorded_by,recorded_at,signed_receipt_id,signed_asset_sha256
  ) values(
    w.id,p_agreement_type,'executed',true,
    'Executed agreement verified by LegalEase',doc.id,
    p_effective_date,p_actor,now(),p_request,p_sha256
  ) on conflict(workspace_id,agreement_type) do update set
    status='executed',is_required=true,partner_safe_detail=excluded.partner_safe_detail,
    finalized_asset_id=excluded.finalized_asset_id,
    effective_date=excluded.effective_date,
    recorded_by=excluded.recorded_by,recorded_at=excluded.recorded_at,
    signed_receipt_id=excluded.signed_receipt_id,
    signed_asset_sha256=excluded.signed_asset_sha256;

  perform set_config('rcap.agreement_projection',p_request::text,true);
  update public.partner_onboarding set agreement_status='signed',
    agreement_date=p_effective_date,aggregate_version=aggregate_version+1,
    last_meaningful_activity_at=now()
    where id=w.id returning aggregate_version into workspace_version;
  perform set_config('rcap.agreement_projection','',true);



  -- Preserve unrelated staff-training and operational attestations. Only
  -- launch decisions tied to changed contractual authority are renewed.
  if contract_changed then
  update public.partner_onboarding_launch_checks set
    invalidated_at=now(),invalidated_reason='Executed agreement changed'
    where workspace_id=w.id
      and check_key in ('legalease_final_review_complete','partner_launch_approval_received')
      and invalidated_at is null;
  update public.partner_onboarding_launch_approvals set
    invalidated_at=now() where workspace_id=w.id and invalidated_at is null;
  end if;

  document_id:=doc.id;
  duplicate:=false;
  return next;
end $_$;


ALTER FUNCTION public.rcap_service_record_signed_agreement(p_slug text, p_actor uuid, p_expected_version bigint, p_request uuid, p_agreement_type text, p_asset uuid, p_new_asset boolean, p_object_path text, p_filename text, p_media_type text, p_extension text, p_byte_size bigint, p_sha256 text, p_effective_date date, p_review_reason text, p_confirmed boolean) OWNER TO postgres;

--
-- Name: rcap_service_reserve_program_translation(text, uuid, bigint, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_service_reserve_program_translation(p_slug text, p_actor uuid, p_version bigint, p_source jsonb, p_request uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare w public.partner_onboarding%rowtype; snapshot jsonb;
begin
 select * into strict w from public.partner_onboarding where partner_slug=p_slug for update;
 snapshot:=public.rcap_service_get_program_configuration(p_slug,p_actor);
 if not exists(select 1 from public.partner_users where auth_user_id=p_actor and status='active' and ((partner_slug=p_slug and role='partner_admin') or (partner_slug is null and role='internal_admin'))) then raise exception 'administrator required' using errcode='42501';end if;
 if w.rcap_policy_version<>'rcap2.2' or w.status in ('live','paused','closed') then raise exception 'program not editable' using errcode='55000';end if;
 if p_version is distinct from w.aggregate_version or p_source is distinct from public.rcap_program_public_copy_source(w.id) then raise exception 'public source changed' using errcode='PT409';end if;
 if exists(select 1 from public.partner_onboarding_idempotency where workspace_id=w.id and operation_key='program_translation' and result_status='started' and expires_at>now()) then raise exception 'Spanish preparation is in progress. Retry in a minute.' using errcode='55P03';end if;
 -- Serialize per actor as well as workspace: parallel workspaces cannot evade the limit.
 perform pg_advisory_xact_lock(hashtextextended(p_actor::text,76102));
 if (select count(*) from public.partner_onboarding_idempotency where operation_key='program_translation' and created_at>now()-interval '10 minutes' and (workspace_id=w.id or actor_user_id=p_actor))>=5 then raise exception 'Spanish preparation limit reached. Retry in ten minutes.' using errcode='P0001';end if;
 insert into public.partner_onboarding_idempotency(workspace_id,operation_key,request_id,actor_user_id,payload_hash,result_status,expires_at)
 values(w.id,'program_translation',p_request,p_actor,encode(sha256(convert_to(p_source::text,'UTF8')),'hex'),'started',now()+interval '60 seconds');
end $$;


ALTER FUNCTION public.rcap_service_reserve_program_translation(p_slug text, p_actor uuid, p_version bigint, p_source jsonb, p_request uuid) OWNER TO postgres;

--
-- Name: rcap_service_retire_onboarding_artifact(text, uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_service_retire_onboarding_artifact(p_partner_slug text, p_actor_user_id uuid, p_artifact_version_id uuid, p_reason text, p_request_id uuid) RETURNS TABLE(superseded boolean)
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare v_workspace uuid; v_artifact uuid;
begin
  if not exists(select 1 from public.partner_users u where u.auth_user_id=p_actor_user_id and u.role='internal_admin' and u.status='active' and u.partner_slug is null) then raise exception 'internal_admin_required' using errcode='42501'; end if;
  if length(btrim(p_reason))<10 or length(p_reason)>2000 or p_request_id is null then raise exception 'specific_reason_required'; end if;
  select v.workspace_id,v.artifact_id into v_workspace,v_artifact from public.partner_onboarding_artifact_versions v join public.partner_onboarding po on po.id=v.workspace_id where v.id=p_artifact_version_id and po.partner_slug=p_partner_slug for update of v,po;
  if v_workspace is null then raise exception 'version_not_found'; end if;
  if exists(select 1 from public.partner_onboarding_artifact_reviews where artifact_version_id=p_artifact_version_id and request_id=p_request_id and (reviewer_user_id<>p_actor_user_id or comments<>'Version retirement: '||btrim(p_reason))) then raise exception 'idempotency_payload_conflict'; end if;
  -- Preserve the actual reviewer, reason and request identity in the existing
  -- append-only review ledger, then retire and clear only this current pointer.
  if not exists(select 1 from public.partner_onboarding_artifact_reviews where artifact_version_id=p_artifact_version_id and request_id=p_request_id) then
    insert into public.partner_onboarding_artifact_reviews(artifact_version_id,workspace_id,reviewer_type,reviewer_user_id,decision,comments,request_id)
      values(p_artifact_version_id,v_workspace,'legalease',p_actor_user_id,'request_changes','Version retirement: '||btrim(p_reason),p_request_id);
  end if;
  perform public.rcap_service_supersede_onboarding_artifact_version(p_partner_slug,p_actor_user_id,p_artifact_version_id);
  update public.partner_onboarding_artifacts set current_version_id=null,lifecycle_status='not_generated' where id=v_artifact and current_version_id=p_artifact_version_id;
  superseded:=true; return next;
end; $$;


ALTER FUNCTION public.rcap_service_retire_onboarding_artifact(p_partner_slug text, p_actor_user_id uuid, p_artifact_version_id uuid, p_reason text, p_request_id uuid) OWNER TO postgres;

--
-- Name: rcap_service_review_launch_package(text, uuid, uuid, bigint, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_service_review_launch_package(p_partner_slug text, p_actor_user_id uuid, p_request_id uuid, p_workspace_version bigint, p_versions jsonb) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_workspace public.partner_onboarding%rowtype;
  v_item jsonb;
  v_version public.partner_onboarding_artifact_versions%rowtype;
  v_count integer;
begin
  if not exists(select 1 from public.partner_users u where u.auth_user_id=p_actor_user_id and u.role='internal_admin' and u.status='active' and u.partner_slug is null) then
    raise exception 'internal_admin_required' using errcode='42501';
  end if;
  select * into v_workspace from public.partner_onboarding where partner_slug=p_partner_slug for update;
  if v_workspace.id is null or v_workspace.aggregate_version <> p_workspace_version then raise exception 'stale_workspace'; end if;
  if p_request_id is null then raise exception 'request_identity_required'; end if;
  if jsonb_typeof(p_versions)<>'array' or jsonb_array_length(p_versions)<>5 then raise exception 'exact_package_required'; end if;
  select count(distinct item->>'id') into v_count from jsonb_array_elements(p_versions) item;
  if v_count<>5 then raise exception 'duplicate_version'; end if;
  if exists(select 1 from public.partner_onboarding_artifact_reviews r where r.workspace_id=v_workspace.id and r.request_id=p_request_id and
    (r.reviewer_user_id<>p_actor_user_id or r.reviewer_type<>'legalease' or r.decision<>'approve' or not exists(select 1 from jsonb_array_elements(p_versions) item where (item->>'id')::uuid=r.artifact_version_id))) then raise exception 'idempotency_payload_conflict'; end if;
  -- Lock and validate the entire package before any review is recorded.
  for v_item in select * from jsonb_array_elements(p_versions) loop
    select v.* into v_version from public.partner_onboarding_artifact_versions v
      join public.partner_onboarding_artifacts a on a.id=v.artifact_id
      where v.id=(v_item->>'id')::uuid and v.workspace_id=v_workspace.id
      and a.current_version_id=v.id and a.artifact_type in ('implementation_brief','operations_escalation_plan','dashboard_user_reporting_matrix','staff_quick_start_guide','co_branded_page_configuration')
      for update of v,a;
    if v_version.id is null or v_version.snapshot_hash<>v_item->>'snapshotHash'
      or v_version.generation_status<>'succeeded' or v_version.approval_status='superseded'
      or v_version.superseded_at is not null or v_version.source_drift_invalidated_at is not null then raise exception 'package_version_changed'; end if;
  end loop;
  for v_item in select * from jsonb_array_elements(p_versions) loop
    perform public.rcap_service_review_onboarding_artifact(p_partner_slug,p_actor_user_id,'legalease',(v_item->>'id')::uuid,'approve','Reviewed as part of the exact launch package',null,p_request_id);
  end loop;
  return true;
end; $$;


ALTER FUNCTION public.rcap_service_review_launch_package(p_partner_slug text, p_actor_user_id uuid, p_request_id uuid, p_workspace_version bigint, p_versions jsonb) OWNER TO postgres;

--
-- Name: rcap_service_review_onboarding(text, uuid, uuid, bigint, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_service_review_onboarding(p_partner_slug text, p_actor_user_id uuid, p_workspace_id uuid, p_expected_workspace_version bigint, p_request_id uuid, p_payload_hash text, p_operation jsonb) RETURNS TABLE(workspace_aggregate_version bigint, workspace_status text, duplicate boolean)
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
declare
  v_workspace public.partner_onboarding%rowtype;
  v_existing public.partner_onboarding_idempotency%rowtype;
  v_section public.partner_onboarding_sections%rowtype;
  v_action text;
  v_section_key text;
  v_reason text;
  v_partner_record_id uuid;
  v_partner_payment_status text;
  v_activity_type text;
  v_activity_summary text;
  v_event_type text := 'rcap_onboarding_progressed';
  v_derived_completion integer;
  v_derived_blocker text;
  v_derived_next_action text;
  v_derived_next_owner text;
begin
  perform public.rcap_service_assert_internal_actor(p_actor_user_id);
  if p_operation is null
     or jsonb_typeof(p_operation) <> 'object'
     or p_payload_hash !~ '^[0-9a-f]{64}$' then
    raise exception using errcode = '22023', message = 'Invalid review operation';
  end if;
  v_action := p_operation->>'action';
  if v_action not in (
    'target_launch_date',
    'commercial_gate',
    'agreement',
    'request_changes',
    'approve_section',
    'waive_section',
    'ready_for_launch',
    'close'
  ) then
    raise exception using errcode = '22023', message = 'Unknown review operation';
  end if;

  select *
    into v_existing
  from public.partner_onboarding_idempotency i
  where i.request_id = p_request_id
  for update;
  if found then
    if v_existing.workspace_id <> p_workspace_id
       or v_existing.operation_key <> 'review:' || v_action
       or v_existing.actor_user_id <> p_actor_user_id
       or v_existing.payload_hash <> p_payload_hash then
      raise exception using errcode = '23505', message = 'Idempotency request mismatch';
    end if;
    if v_existing.result_status = 'succeeded' then
      return query
      select
        v_existing.result_workspace_version,
        po.status,
        true
      from public.partner_onboarding po
      where po.id = p_workspace_id;
      return;
    end if;
    raise exception using errcode = '55000', message = 'Idempotent request is still in progress';
  end if;

  select *
    into v_workspace
  from public.partner_onboarding po
  where po.id = p_workspace_id
    and po.partner_slug = p_partner_slug
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'Onboarding workspace not found';
  end if;
  if v_workspace.aggregate_version <> p_expected_workspace_version then
    raise exception using errcode = 'PT409', message = 'Onboarding workspace revision conflict';
  end if;
  select
    coalesce(v_workspace.partner_record_id, pr.id),
    pr.payment_status
    into v_partner_record_id, v_partner_payment_status
  from public.partner_records pr
  where pr.partner_slug = p_partner_slug;

  insert into public.partner_onboarding_idempotency (
    workspace_id,
    operation_key,
    request_id,
    actor_user_id,
    payload_hash,
    expires_at
  ) values (
    p_workspace_id,
    'review:' || v_action,
    p_request_id,
    p_actor_user_id,
    p_payload_hash,
    now() + interval '24 hours'
  );

  if v_action = 'target_launch_date' then
    v_reason := nullif(btrim(p_operation->>'reason'), '');
    if v_reason is null or char_length(v_reason) > 5000 then
      raise exception using errcode = '22023', message = 'Target-date reason is required';
    end if;
    update public.partner_onboarding
    set
      target_launch_date = nullif(p_operation->>'targetLaunchDate', '')::date,
      target_launch_date_reason = v_reason,
      target_launch_date_changed_at = now(),
      target_launch_date_changed_by = p_actor_user_id
    where id = p_workspace_id;
  elsif v_action = 'commercial_gate' then
    if p_operation->>'outcome' not in (
      'blocked',
      'cleared_by_paid_invoice',
      'cleared_by_approved_purchase_order',
      'cleared_by_authorized_internal_override'
    ) then
      raise exception using errcode = '22023', message = 'Invalid commercial gate outcome';
    end if;
    if (
      p_operation->>'outcome' = 'cleared_by_approved_purchase_order'
      and nullif(btrim(p_operation->>'evidenceReference'), '') is null
    ) then
      raise exception using errcode = '22023', message = 'Commercial evidence reference is required';
    end if;
    if p_operation->>'outcome' = 'cleared_by_paid_invoice'
       and v_partner_payment_status <> 'paid' then
      raise exception using
        errcode = '23514',
        message = 'Paid-invoice outcome requires authoritative paid partner status';
    end if;
    if p_operation->>'outcome' = 'cleared_by_authorized_internal_override'
       and nullif(btrim(p_operation->>'overrideReason'), '') is null then
      raise exception using errcode = '22023', message = 'Commercial override reason is required';
    end if;
    if coalesce(char_length(p_operation->>'evidenceReference'), 0) > 500
       or coalesce(char_length(p_operation->>'overrideReason'), 0) > 5000 then
      raise exception using errcode = '22023', message = 'Commercial evidence is too long';
    end if;
    if jsonb_typeof(p_operation->'systemDerived') <> 'object' then
      raise exception using
        errcode = '22023',
        message = 'Server-derived commercial summary is required';
    end if;
    v_derived_completion :=
      (p_operation->'systemDerived'->>'completionPercentage')::integer;
    v_derived_blocker :=
      nullif(p_operation->'systemDerived'->>'blockerCode', '');
    v_derived_next_action :=
      nullif(p_operation->'systemDerived'->>'nextActionCode', '');
    v_derived_next_owner :=
      nullif(p_operation->'systemDerived'->>'nextActionOwner', '');
    if v_derived_completion not between 0 and 100
       or v_derived_next_action is null
       or v_derived_next_owner not in ('partner', 'legalease', 'none')
       or (
         v_derived_blocker is not null
         and v_derived_blocker !~ '^[a-z0-9_]{1,120}$'
       )
       or v_derived_next_action !~ '^[a-z0-9_]{1,120}$' then
      raise exception using
        errcode = '22023',
        message = 'Server-derived commercial summary is invalid';
    end if;
    update public.partner_onboarding
    set
      commercial_gate_status = p_operation->>'outcome',
      commercial_gate_evidence_reference = case
        when p_operation->>'outcome' = 'cleared_by_paid_invoice'
          then 'partner_record:' || v_partner_record_id::text
        else nullif(btrim(p_operation->>'evidenceReference'), '')
      end,
      commercial_gate_override_reason = case
        when p_operation->>'outcome' = 'cleared_by_authorized_internal_override'
          then nullif(btrim(p_operation->>'overrideReason'), '')
        else null
      end,
      commercial_gate_changed_at = now(),
      commercial_gate_changed_by = p_actor_user_id,
      status = case
        when p_operation->>'outcome' = 'blocked'
          and status in ('draft', 'setup_in_progress') then 'commercially_blocked'
        when p_operation->>'outcome' <> 'blocked'
          and status in ('draft', 'commercially_blocked') then 'setup_in_progress'
        else status
      end,
      completion_percentage = v_derived_completion,
      blocker_code = v_derived_blocker,
      next_action_code = v_derived_next_action,
      next_action_owner = v_derived_next_owner
    where id = p_workspace_id;
    v_activity_type := 'commercial_gate_changed';
    v_activity_summary := 'commercial_gate_changed';
    v_event_type := 'rcap_commercial_gate_changed';
  elsif v_action = 'agreement' then
    if p_operation->>'agreementType' not in (
      'order_form',
      'master_services_agreement',
      'data_privacy_security_addendum',
      'procurement_requirements'
    )
       or p_operation->>'status' not in (
         'not_required',
         'not_started',
         'requested',
         'under_review',
         'finalized',
         'executed',
         'approved',
         'waived'
       ) then
      raise exception using errcode = '22023', message = 'Invalid agreement metadata';
    end if;
    if jsonb_typeof(p_operation->'systemDerived') <> 'object' then
      raise exception using
        errcode = '22023',
        message = 'Server-derived agreement summary is required';
    end if;
    v_derived_completion :=
      (p_operation->'systemDerived'->>'completionPercentage')::integer;
    v_derived_blocker :=
      nullif(p_operation->'systemDerived'->>'blockerCode', '');
    v_derived_next_action :=
      nullif(p_operation->'systemDerived'->>'nextActionCode', '');
    v_derived_next_owner :=
      nullif(p_operation->'systemDerived'->>'nextActionOwner', '');
    if v_derived_completion not between 0 and 100
       or v_derived_next_action is null
       or v_derived_next_owner not in ('partner', 'legalease', 'none')
       or (
         v_derived_blocker is not null
         and v_derived_blocker !~ '^[a-z0-9_]{1,120}$'
       )
       or v_derived_next_action !~ '^[a-z0-9_]{1,120}$' then
      raise exception using
        errcode = '22023',
        message = 'Server-derived agreement summary is invalid';
    end if;
    if nullif(p_operation->>'finalizedAssetId', '') is not null
       and p_operation->>'status' not in ('finalized', 'executed', 'approved') then
      raise exception using
        errcode = '22023',
        message = 'A finalized agreement document requires a finalized partner-safe status';
    end if;
    if nullif(p_operation->>'finalizedAssetId', '') is not null then
      update public.partner_onboarding_assets
      set
        lifecycle_status = 'active',
        review_status = 'approved',
        review_reason = 'authorized_as_finalized_agreement_document',
        updated_at = now()
      where id = (p_operation->>'finalizedAssetId')::uuid
        and workspace_id = p_workspace_id
        and deleted_at is null
        and lifecycle_status in ('pending_review', 'active')
        and media_type in (
          'application/pdf',
          'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
        );
      if not found then
        raise exception using
          errcode = '23514',
          message = 'Finalized agreement document is not an eligible private workspace asset';
      end if;
    end if;
    insert into public.partner_onboarding_agreements (
      workspace_id,
      agreement_type,
      status,
      is_required,
      partner_safe_detail,
      finalized_asset_id,
      effective_date,
      recorded_by,
      recorded_at
    ) values (
      p_workspace_id,
      p_operation->>'agreementType',
      p_operation->>'status',
      coalesce((p_operation->>'required')::boolean, false),
      nullif(btrim(p_operation->>'partnerSafeDetail'), ''),
      nullif(p_operation->>'finalizedAssetId', '')::uuid,
      nullif(p_operation->>'effectiveDate', '')::date,
      p_actor_user_id,
      now()
    )
    on conflict (workspace_id, agreement_type) do update
    set
      status = excluded.status,
      is_required = excluded.is_required,
      partner_safe_detail = excluded.partner_safe_detail,
      finalized_asset_id = excluded.finalized_asset_id,
      effective_date = excluded.effective_date,
      recorded_by = excluded.recorded_by,
      recorded_at = excluded.recorded_at;
    update public.partner_onboarding
    set
      completion_percentage = v_derived_completion,
      blocker_code = v_derived_blocker,
      next_action_code = v_derived_next_action,
      next_action_owner = v_derived_next_owner
    where id = p_workspace_id;
  elsif v_action in ('request_changes', 'approve_section', 'waive_section') then
    v_section_key := p_operation->>'sectionKey';
    if v_section_key not in (
      'organization_contacts',
      'program_goals',
      'geography_audience_language_accessibility',
      'access_sponsorship_capacity',
      'brand_public_page',
      'staff_dashboard_plan',
      'support_referrals_reporting',
      'review_authorization'
    ) then
      raise exception using errcode = '22023', message = 'Invalid section review key';
    end if;
    select *
      into v_section
    from public.partner_onboarding_sections s
    where s.workspace_id = p_workspace_id
      and s.section_key = v_section_key
    for update;
    if not found then
      raise exception using errcode = 'P0002', message = 'Onboarding section not found';
    end if;

    if v_action = 'request_changes' then
      v_reason := nullif(btrim(p_operation->>'instructions'), '');
      if v_workspace.status <> 'ready_for_review'
         or v_reason is null
         or char_length(v_reason) > 5000 then
        raise exception using errcode = '55000', message = 'Partner-safe change request is invalid';
      end if;
      update public.partner_onboarding_sections
      set
        revision = revision + 1,
        status = 'needs_changes',
        reviewed_at = now(),
        reviewed_by = p_actor_user_id,
        review_reason = v_reason
      where id = v_section.id;
      update public.partner_onboarding_change_requests
      set
        status = 'resolved',
        resolved_by = p_actor_user_id,
        resolved_at = now(),
        resolution_reason = 'Additional changes requested by LegalEase.',
        updated_at = now()
      where section_id = v_section.id
        and status = 'partner_responded';
      insert into public.partner_onboarding_change_requests (
        workspace_id,
        section_id,
        status,
        partner_safe_instructions,
        requested_by
      ) values (
        p_workspace_id,
        v_section.id,
        'open',
        v_reason,
        p_actor_user_id
      );
      update public.partner_onboarding
      set
        status = 'waiting_on_partner',
        blocker_code = 'partner_changes_requested',
        next_action_code = 'address_change_request',
        next_action_owner = 'partner'
      where id = p_workspace_id;
      v_activity_type := 'section_change_requested';
      v_activity_summary := 'section_change_requested';
    else
      v_reason := nullif(btrim(p_operation->>'reason'), '');
      if v_reason is null or char_length(v_reason) > 5000 then
        raise exception using errcode = '22023', message = 'Section review reason is required';
      end if;
      if v_action = 'approve_section' and v_section.status not in ('submitted', 'needs_changes') then
        raise exception using errcode = '55000', message = 'Section is not ready for approval';
      end if;
      update public.partner_onboarding_sections
      set
        revision = revision + 1,
        status = case
          when v_action = 'approve_section' then 'approved'
          else 'waived'
        end,
        approved_at = case
          when v_action = 'approve_section' then now()
          else approved_at
        end,
        approved_by = case
          when v_action = 'approve_section' then p_actor_user_id
          else approved_by
        end,
        waived_at = case
          when v_action = 'waive_section' then now()
          else waived_at
        end,
        waived_by = case
          when v_action = 'waive_section' then p_actor_user_id
          else waived_by
        end,
        waiver_reason = case
          when v_action = 'waive_section' then v_reason
          else waiver_reason
        end,
        reviewed_at = now(),
        reviewed_by = p_actor_user_id,
        review_reason = v_reason
      where id = v_section.id;
      update public.partner_onboarding_change_requests
      set
        status = 'resolved',
        resolved_by = p_actor_user_id,
        resolved_at = now(),
        resolution_reason = v_reason,
        updated_at = now()
      where section_id = v_section.id
        and status in ('open', 'partner_responded');
      update public.partner_onboarding
      set
        status = case
          when exists (
            select 1
            from public.partner_onboarding_change_requests cr
            where cr.workspace_id = p_workspace_id
              and cr.status = 'open'
          ) then 'waiting_on_partner'
          else 'ready_for_review'
        end,
        blocker_code = case
          when exists (
            select 1
            from public.partner_onboarding_change_requests cr
            where cr.workspace_id = p_workspace_id
              and cr.status = 'open'
          ) then 'partner_changes_requested'
          else null
        end,
        next_action_code = case
          when exists (
            select 1
            from public.partner_onboarding_change_requests cr
            where cr.workspace_id = p_workspace_id
              and cr.status = 'open'
          ) then 'address_change_request'
          else 'await_legalease_review'
        end,
        next_action_owner = case
          when exists (
            select 1
            from public.partner_onboarding_change_requests cr
            where cr.workspace_id = p_workspace_id
              and cr.status = 'open'
          ) then 'partner'
          else 'legalease'
        end
      where id = p_workspace_id;
      v_activity_type := case
        when v_action = 'approve_section' then 'section_approved'
        else 'section_waived'
      end;
      v_activity_summary := v_activity_type;
    end if;
    v_event_type := 'rcap_section_review_changed';
  elsif v_action = 'ready_for_launch' then
    v_reason := nullif(btrim(p_operation->>'reason'), '');
    if v_reason is null
       or char_length(v_reason) > 5000
       or v_workspace.status <> 'ready_for_review'
       or v_workspace.commercial_gate_status = 'blocked'
       or exists (
         select 1
         from public.partner_onboarding_change_requests cr
         where cr.workspace_id = p_workspace_id
           and cr.status in ('open', 'partner_responded')
       )
       or (
         select count(*)
         from public.partner_onboarding_sections s
         where s.workspace_id = p_workspace_id
           and s.status in ('approved', 'waived', 'not_applicable')
       ) <> 8 then
      raise exception using errcode = '55000', message = 'Workspace is not approved for launch preparation';
    end if;
    update public.partner_onboarding
    set
      status = 'ready_to_launch',
      blocker_code = null,
      next_action_code = 'prepare_for_launch',
      next_action_owner = 'legalease',
      internal_approved_at = now(),
      internal_approved_by = p_actor_user_id,
      internal_approval_reason = v_reason
    where id = p_workspace_id;
    v_activity_type := 'ready_for_launch_decided';
    v_activity_summary := 'ready_for_launch_decided';
    v_event_type := 'rcap_section_review_changed';
  elsif v_action = 'close' then
    v_reason := nullif(btrim(p_operation->>'reason'), '');
    if v_reason is null
       or char_length(v_reason) > 5000
       or v_workspace.status not in (
         'draft',
         'commercially_blocked',
         'setup_in_progress',
         'waiting_on_partner',
         'ready_for_review',
         'ready_to_launch'
       ) then
      raise exception using errcode = '55000', message = 'Workspace cannot be closed';
    end if;
    update public.partner_onboarding
    set
      status = 'closed',
      blocker_code = null,
      next_action_code = 'onboarding_closed',
      next_action_owner = 'none',
      closed_at = now(),
      closed_by = p_actor_user_id,
      closed_reason = v_reason
    where id = p_workspace_id;
  end if;

  update public.partner_onboarding
  set
    aggregate_version = aggregate_version + 1,
    last_meaningful_activity_at = case
      when v_activity_type is not null then now()
      else last_meaningful_activity_at
    end
  where id = p_workspace_id
  returning aggregate_version, status
    into workspace_aggregate_version, workspace_status;

  if v_activity_type is not null then
    insert into public.partner_onboarding_activity (
      workspace_id,
      event_type,
      section_key,
      status_code,
      summary_code,
      owner_type,
      actor_user_id,
      request_id,
      dedupe_key
    ) values (
      p_workspace_id,
      v_activity_type,
      v_section_key,
      workspace_status,
      v_activity_summary,
      'legalease',
      p_actor_user_id,
      p_request_id,
      p_request_id::text || ':' || v_activity_type
    )
    on conflict do nothing;
  end if;

  insert into public.partner_onboarding_integration_events (
    workspace_id,
    partner_record_id,
    event_type,
    workspace_aggregate_version,
    workspace_status,
    completion_percentage,
    blocker_code,
    next_action_code,
    next_action_owner,
    target_launch_date,
    section_key,
    section_status,
    idempotency_key
  )
  select
    po.id,
    v_partner_record_id,
    v_event_type,
    po.aggregate_version,
    po.status,
    po.completion_percentage,
    po.blocker_code,
    po.next_action_code,
    po.next_action_owner,
    po.target_launch_date,
    v_section_key,
    case when v_section_key is null then null else (
      select s.status
      from public.partner_onboarding_sections s
      where s.workspace_id = po.id
        and s.section_key = v_section_key
    ) end,
    p_request_id::text || ':review'
  from public.partner_onboarding po
  where po.id = p_workspace_id
  on conflict do nothing;

  update public.partner_onboarding_idempotency
  set
    result_status = 'succeeded',
    result_workspace_version = workspace_aggregate_version,
    completed_at = now()
  where request_id = p_request_id;

  duplicate := false;
  return next;
end;
$_$;


ALTER FUNCTION public.rcap_service_review_onboarding(p_partner_slug text, p_actor_user_id uuid, p_workspace_id uuid, p_expected_workspace_version bigint, p_request_id uuid, p_payload_hash text, p_operation jsonb) OWNER TO postgres;

--
-- Name: rcap_service_review_onboarding_artifact(text, uuid, text, uuid, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_service_review_onboarding_artifact(p_partner_slug text, p_actor_user_id uuid, p_reviewer_type text, p_artifact_version_id uuid, p_decision text, p_comments text, p_partner_visible_instructions text, p_request_id uuid) RETURNS TABLE(approval_status text, partner_review_status text, duplicate boolean)
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_version public.partner_onboarding_artifact_versions%rowtype;
  v_artifact public.partner_onboarding_artifacts%rowtype;
  v_existing uuid;
begin
  if p_reviewer_type not in ('legalease', 'partner') then
    raise exception 'invalid_reviewer_type' using errcode = '22023';
  end if;
  if p_decision not in ('approve', 'request_changes', 'reject') then
    raise exception 'invalid_decision' using errcode = '22023';
  end if;

  select v.* into v_version
  from public.partner_onboarding_artifact_versions v
  join public.partner_onboarding po on po.id = v.workspace_id
  where v.id = p_artifact_version_id
    and po.partner_slug = p_partner_slug
  for update of v;

  if v_version.id is null then
    raise exception 'artifact_version_not_found' using errcode = 'P0002';
  end if;

  select a.* into v_artifact
  from public.partner_onboarding_artifacts a
  where a.id = v_version.artifact_id;

  select r.id into v_existing
  from public.partner_onboarding_artifact_reviews r
  where r.artifact_version_id = p_artifact_version_id
    and r.request_id = p_request_id;

  if v_existing is not null then
    approval_status := v_version.approval_status;
    partner_review_status := v_version.partner_review_status;
    duplicate := true;
    return next;
    return;
  end if;

  -- A failed generation is not reviewable.
  if v_version.generation_status <> 'succeeded' then
    raise exception 'artifact_generation_failed' using errcode = '0A000';
  end if;

  -- A stale version cannot be approved. It stays readable and can still be
  -- rejected or have changes requested, but approval requires regeneration.
  if p_decision = 'approve' and v_version.source_drift_invalidated_at is not null then
    raise exception 'artifact_version_stale' using errcode = '55000';
  end if;

  if v_version.approval_status = 'superseded' and p_decision = 'approve' then
    raise exception 'artifact_version_superseded' using errcode = '55000';
  end if;

  insert into public.partner_onboarding_artifact_reviews (
    artifact_version_id, workspace_id, reviewer_type, reviewer_user_id,
    decision, comments, request_id
  )
  values (
    p_artifact_version_id, v_version.workspace_id, p_reviewer_type,
    p_actor_user_id, p_decision, p_comments, p_request_id
  );

  if p_reviewer_type = 'legalease' then
    -- LegalEase controls the document's own approval state and retains control
    -- of legal and platform language. The partner review state is untouched
    -- except that requesting changes routes the version back to the partner.
    -- The alias is required: this function's OUT parameters share names with
    -- these columns, so unqualified references would be ambiguous.
    update public.partner_onboarding_artifact_versions v
    set approval_status = case p_decision
          when 'approve' then 'approved'
          when 'request_changes' then 'changes_requested'
          else 'changes_requested'
        end,
        partner_visible_instructions = coalesce(
          p_partner_visible_instructions, v.partner_visible_instructions
        ),
        partner_review_status = case
          when p_decision = 'approve' and v.partner_review_status = 'not_requested'
            then 'awaiting_partner'
          else v.partner_review_status
        end
    where v.id = p_artifact_version_id
    returning v.* into v_version;
  else
    -- The partner approves only partner-owned factual and branding content. It
    -- cannot move approval_status, publish, or activate anything.
    update public.partner_onboarding_artifact_versions v
    set partner_review_status = case p_decision
          when 'approve' then 'approved'
          else 'changes_requested'
        end
    where v.id = p_artifact_version_id
    returning v.* into v_version;
  end if;

  update public.partner_onboarding_artifacts
  set lifecycle_status = case
        when v_version.approval_status = 'approved' then 'approved'
        when v_version.approval_status = 'changes_requested' then 'in_review'
        else lifecycle_status
      end
  where id = v_artifact.id;

  insert into public.partner_onboarding_activity (
    workspace_id, event_type, owner_type, summary_code, status_code,
    artifact_version_id
  )
  values (
    v_version.workspace_id,
    case
      when p_reviewer_type = 'partner' then 'artifact_partner_reviewed'
      when p_decision = 'approve' then 'artifact_approved'
      else 'artifact_changes_requested'
    end,
    case when p_reviewer_type = 'partner' then 'partner' else 'legalease' end,
    v_artifact.artifact_type,
    p_decision,
    p_artifact_version_id
  )
  on conflict do nothing;

  approval_status := v_version.approval_status;
  partner_review_status := v_version.partner_review_status;
  duplicate := false;
  return next;
end;
$$;


ALTER FUNCTION public.rcap_service_review_onboarding_artifact(p_partner_slug text, p_actor_user_id uuid, p_reviewer_type text, p_artifact_version_id uuid, p_decision text, p_comments text, p_partner_visible_instructions text, p_request_id uuid) OWNER TO postgres;

--
-- Name: rcap_service_review_onboarding_prefill(text, uuid, uuid, uuid, bigint, text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_service_review_onboarding_prefill(p_partner_slug text, p_actor_user_id uuid, p_workspace_id uuid, p_value_id uuid, p_expected_batch_version bigint, p_action text, p_request_id uuid, p_payload_hash text) RETURNS TABLE(batch_aggregate_version bigint, review_status text, duplicate boolean)
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
declare
  v_workspace public.partner_onboarding%rowtype;
  v_batch public.partner_onboarding_prefill_batches%rowtype;
  v_value public.partner_onboarding_prefill_values%rowtype;
  v_existing public.partner_onboarding_idempotency%rowtype;
  v_status text;
  v_event_type text;
begin
  perform public.rcap_studio_assert_prepare(p_actor_user_id,p_partner_slug);
  if p_action not in ('approve', 'reject', 'supersede')
     or p_expected_batch_version < 1
     or p_payload_hash !~ '^[0-9a-f]{64}$' then
    raise exception using errcode = '22023', message = 'Invalid prefill review';
  end if;

  select *
    into v_existing
  from public.partner_onboarding_idempotency i
  where i.request_id = p_request_id
  for update;
  if found then
    if v_existing.workspace_id <> p_workspace_id
       or v_existing.operation_key <> 'prefill_review:' || p_value_id::text
       or v_existing.actor_user_id <> p_actor_user_id
       or v_existing.payload_hash <> p_payload_hash then
      raise exception using
        errcode = '23505',
        message = 'Idempotency request does not match original mutation';
    end if;
    if v_existing.result_status = 'succeeded' then
      select pv.review_status, b.aggregate_version
        into v_status, batch_aggregate_version
      from public.partner_onboarding_prefill_values pv
      join public.partner_onboarding_prefill_batches b on b.id = pv.batch_id
      where pv.id = p_value_id;
      review_status := v_status;
      duplicate := true;
      return next;
      return;
    end if;
  end if;

  select po.*
    into v_workspace
  from public.partner_onboarding po
  where po.id = p_workspace_id
    and po.partner_slug = p_partner_slug;
  if not found then
    raise exception using errcode = 'P0002', message = 'Onboarding workspace not found';
  end if;

  select pv.*
    into v_value
  from public.partner_onboarding_prefill_values pv
  where pv.id = p_value_id
    and pv.workspace_id = p_workspace_id
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'Prefill suggestion not found';
  end if;

  select *
    into v_batch
  from public.partner_onboarding_prefill_batches b
  where b.id = v_value.batch_id
    and b.workspace_id = p_workspace_id
  for update;
  if v_batch.aggregate_version <> p_expected_batch_version then
    raise exception using errcode = '40001', message = 'Prefill batch revision conflict';
  end if;
  if v_value.review_status not in ('proposed', 'approved', 'conflict') then
    raise exception using errcode = '55000', message = 'Suggestion is no longer reviewable';
  end if;

  insert into public.partner_onboarding_idempotency (
    workspace_id,
    operation_key,
    request_id,
    actor_user_id,
    payload_hash,
    expires_at
  ) values (
    p_workspace_id,
    'prefill_review:' || p_value_id::text,
    p_request_id,
    p_actor_user_id,
    p_payload_hash,
    now() + interval '24 hours'
  );

  v_status := case p_action
    when 'approve' then 'approved'
    when 'reject' then 'rejected'
    else 'superseded'
  end;
  v_event_type := case p_action
    when 'approve' then 'prefill_suggestion_approved'
    when 'reject' then 'prefill_suggestion_rejected'
    else 'prefill_suggestion_superseded'
  end;

  update public.partner_onboarding_prefill_values
  set
    review_status = v_status,
    reviewed_by = p_actor_user_id,
    reviewed_at = now(),
    superseded_at = case when v_status = 'superseded' then now() end
  where id = p_value_id;

  update public.partner_onboarding_prefill_batches
  set
    aggregate_version = aggregate_version + 1,
    status = case
      when v_status = 'approved' then 'approved'
      when not exists (
        select 1
        from public.partner_onboarding_prefill_values pv
        where pv.batch_id = v_batch.id
          and pv.id <> p_value_id
          and pv.review_status in ('proposed', 'approved', 'applied', 'conflict')
      ) then case
        when v_status = 'superseded' then 'superseded'
        else 'rejected'
      end
      else status
    end,
    approved_by = case when v_status = 'approved' then p_actor_user_id else approved_by end,
    approved_at = case when v_status = 'approved' then coalesce(approved_at, now()) else approved_at end,
    superseded_at = case when v_status = 'superseded' then now() else superseded_at end
  where id = v_batch.id
  returning aggregate_version into batch_aggregate_version;

  insert into public.partner_onboarding_activity (
    workspace_id,
    event_type,
    section_key,
    status_code,
    summary_code,
    owner_type,
    actor_user_id,
    request_id,
    dedupe_key
  ) values (
    p_workspace_id,
    v_event_type,
    v_value.section_key,
    v_status,
    v_event_type,
    'legalease',
    p_actor_user_id,
    p_request_id,
    p_request_id::text || ':' || v_event_type
  );

  update public.partner_onboarding_idempotency
  set
    result_status = 'succeeded',
    result_workspace_version = v_workspace.aggregate_version,
    result_section_revision = batch_aggregate_version,
    completed_at = now()
  where request_id = p_request_id;

  review_status := v_status;
  duplicate := false;
  return next;
end;
$_$;


ALTER FUNCTION public.rcap_service_review_onboarding_prefill(p_partner_slug text, p_actor_user_id uuid, p_workspace_id uuid, p_value_id uuid, p_expected_batch_version bigint, p_action text, p_request_id uuid, p_payload_hash text) OWNER TO postgres;

--
-- Name: rcap_service_review_operational_artifact(text, uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_service_review_operational_artifact(p_partner_slug text, p_actor_user_id uuid, p_version uuid, p_decision text, p_request_id uuid) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare v_type text; begin
 if not public.rcap_studio_actor_can(p_actor_user_id,p_partner_slug,'review_operational_material') then raise exception 'assigned review authority required' using errcode='42501'; end if;
 select a.artifact_type into v_type from public.partner_onboarding_artifacts a join public.partner_onboarding_artifact_versions v on v.artifact_id=a.id join public.partner_onboarding po on po.id=v.workspace_id where v.id=p_version and po.partner_slug=p_partner_slug and a.current_version_id=v.id and v.generation_status='succeeded' and v.superseded_at is null and v.source_drift_invalidated_at is null;
 if v_type is null or v_type not in ('operations_escalation_plan','dashboard_user_reporting_matrix','staff_quick_start_guide') then raise exception 'operational review only' using errcode='42501'; end if;
 perform public.rcap_service_review_onboarding_artifact(p_partner_slug,p_actor_user_id,'legalease',p_version,p_decision,'Operational material reviewed by assigned operator',null,p_request_id);
 return true;
end $$;


ALTER FUNCTION public.rcap_service_review_operational_artifact(p_partner_slug text, p_actor_user_id uuid, p_version uuid, p_decision text, p_request_id uuid) OWNER TO postgres;

--
-- Name: rcap_service_review_studio_asset(text, uuid, uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_service_review_studio_asset(p_slug text, p_actor uuid, p_asset uuid, p_decision text, p_reason text, p_request uuid) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare v_workspace uuid; v_prior public.rcap_studio_asset_reviews%rowtype; begin
 perform public.rcap_service_assert_internal_actor(p_actor);
 select a.workspace_id into v_workspace from public.partner_onboarding_assets a join public.partner_onboarding po on po.id=a.workspace_id where a.id=p_asset and po.partner_slug=p_slug and a.deleted_at is null and a.lifecycle_status in ('pending_review','active') for update of a,po;
 if v_workspace is null then raise exception 'current scoped organizational asset required'; end if;
 select * into v_prior from public.rcap_studio_asset_reviews where workspace_id=v_workspace and request_id=p_request;
 if found then if v_prior.asset_id<>p_asset or v_prior.actor_auth_user_id<>p_actor or v_prior.decision<>p_decision or v_prior.reason<>btrim(p_reason) then raise exception 'review request conflict'; end if;return true;end if;
 insert into public.rcap_studio_asset_reviews(workspace_id,asset_id,actor_auth_user_id,decision,reason,request_id)values(v_workspace,p_asset,p_actor,p_decision,btrim(p_reason),p_request);
 update public.partner_onboarding_assets set review_status=case when p_decision='approve' then 'approved' else 'rejected' end,lifecycle_status=case when p_decision='approve' then 'active' else 'pending_review' end,review_reason=btrim(p_reason) where id=p_asset;
 update public.partner_onboarding set aggregate_version=aggregate_version+1 where id=v_workspace;
 return true;
end $$;


ALTER FUNCTION public.rcap_service_review_studio_asset(p_slug text, p_actor uuid, p_asset uuid, p_decision text, p_reason text, p_request uuid) OWNER TO postgres;

--
-- Name: rcap_service_save_onboarding_section(text, uuid, uuid, text, bigint, bigint, jsonb, jsonb, text, integer, text[], integer, text, text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_service_save_onboarding_section(p_partner_slug text, p_actor_user_id uuid, p_workspace_id uuid, p_section_key text, p_expected_revision bigint, p_expected_workspace_version bigint, p_response_data jsonb, p_collections jsonb, p_mode text, p_section_completion integer, p_missing_required_keys text[], p_workspace_completion integer, p_blocker_code text, p_next_action_code text, p_next_action_owner text, p_request_id uuid, p_payload_hash text) RETURNS TABLE(section_revision bigint, workspace_aggregate_version bigint, section_status text, duplicate boolean)
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
declare
  v_workspace public.partner_onboarding%rowtype;
  v_section public.partner_onboarding_sections%rowtype;
  v_existing public.partner_onboarding_idempotency%rowtype;
  v_next_status text;
  v_next_revision bigint;
  v_first_started boolean := false;
  v_completed boolean := false;
  v_resubmitted boolean := false;
  v_partner_review_pending boolean := false;
  v_event_type text;
  v_event_summary text;
  v_partner_record_id uuid;
begin
  perform public.rcap_service_assert_partner_actor(
    p_partner_slug, p_actor_user_id, p_workspace_id
  );

  if p_section_key not in (
    'organization_contacts',
    'program_goals',
    'geography_audience_language_accessibility',
    'access_sponsorship_capacity',
    'brand_public_page',
    'staff_dashboard_plan',
    'support_referrals_reporting',
    'review_authorization'
  )
     or p_mode not in ('draft_save', 'section_complete')
     or p_expected_revision < 0
     or p_expected_workspace_version < 1
     or p_response_data is null
     or jsonb_typeof(p_response_data) <> 'object'
     or p_collections is null
     or jsonb_typeof(p_collections) <> 'object'
     or octet_length(p_response_data::text) > 65536
     or p_section_completion not between 0 and 100
     or p_workspace_completion not between 0 and 100
     or p_next_action_owner not in ('partner', 'legalease', 'none')
     or p_payload_hash !~ '^[0-9a-f]{64}$' then
    raise exception using
      errcode = '22023',
      message = 'Invalid onboarding section mutation';
  end if;

  select *
    into v_existing
  from public.partner_onboarding_idempotency i
  where i.request_id = p_request_id
  for update;

  if found then
    if v_existing.workspace_id <> p_workspace_id
       or v_existing.operation_key <> 'section:' || p_section_key
       or v_existing.actor_user_id <> p_actor_user_id
       or v_existing.payload_hash <> p_payload_hash then
      raise exception using
        errcode = '23505',
        message = 'Idempotency request does not match original mutation';
    end if;
    if v_existing.result_status = 'succeeded' then
      return query
      select
        v_existing.result_section_revision,
        v_existing.result_workspace_version,
        coalesce((
          select s.status
          from public.partner_onboarding_sections s
          where s.workspace_id = p_workspace_id
            and s.section_key = p_section_key
        ), 'in_progress'),
        true;
      return;
    end if;
    raise exception using
      errcode = '55000',
      message = 'Idempotent request is still in progress';
  end if;

  select po.*
    into v_workspace
  from public.partner_onboarding po
  where po.id = p_workspace_id
    and po.partner_slug = p_partner_slug
  for update of po;

  if not found then
    raise exception using errcode = 'P0002', message = 'Onboarding workspace not found';
  end if;
  if v_workspace.aggregate_version <> p_expected_workspace_version then
    raise exception using
      errcode = '40001',
      message = 'Onboarding workspace revision conflict';
  end if;
  select coalesce(v_workspace.partner_record_id, pr.id)
    into v_partner_record_id
  from public.partner_records pr
  where pr.partner_slug = p_partner_slug;
  if v_workspace.rcap_policy_version <> 'rcap2.2' and v_workspace.commercial_gate_status = 'blocked' then
    raise exception using errcode = '55000', message = 'Commercial gate is blocked';
  end if;
  if (v_workspace.rcap_policy_version <> 'rcap2.2' and v_workspace.status not in ('setup_in_progress', 'waiting_on_partner')) or v_workspace.status in ('paused','closed') then
    raise exception using errcode = '55000', message = 'Onboarding workspace is not editable';
  end if;

  insert into public.partner_onboarding_idempotency (
    workspace_id,
    operation_key,
    request_id,
    actor_user_id,
    payload_hash,
    expires_at
  ) values (
    p_workspace_id,
    'section:' || p_section_key,
    p_request_id,
    p_actor_user_id,
    p_payload_hash,
    now() + interval '24 hours'
  );

  select *
    into v_section
  from public.partner_onboarding_sections s
  where s.workspace_id = p_workspace_id
    and s.section_key = p_section_key
  for update;

  if found then
    if v_workspace.rcap_policy_version='rcap2.2' and p_section_key='organization_contacts' and (v_workspace.agreement_status='signed' or exists(select 1 from public.rcap_commercial_authorizations where workspace_id=v_workspace.id)) and nullif(v_section.response_data->>'legal_organization_name','') is not null and p_response_data->>'legal_organization_name' is distinct from v_section.response_data->>'legal_organization_name' then raise exception 'legal identity requires documented internal correction' using errcode='42501';end if;
    if v_workspace.rcap_policy_version <> 'rcap2.2' and v_section.status in ('approved', 'waived', 'not_applicable') then
      raise exception using
        errcode = '42501',
        message = 'Reviewed onboarding section is not partner-editable';
    end if;
    if v_section.revision <> p_expected_revision then
      raise exception using
        errcode = '40001',
        message = 'Onboarding section revision conflict';
    end if;
    v_next_revision := v_section.revision + 1;
    v_first_started := v_section.status = 'not_started';
    v_resubmitted :=
      p_mode = 'section_complete'
      and (
        v_section.status = 'needs_changes'
        or exists (
          select 1
          from public.partner_onboarding_change_requests cr
          where cr.section_id = v_section.id
            and cr.status = 'open'
        )
      );
    v_completed :=
      p_mode = 'section_complete'
      and v_section.status not in ('submitted', 'approved', 'waived', 'not_applicable');
    v_next_status := case
      when p_mode = 'section_complete' then 'submitted'
      when v_workspace.rcap_policy_version='rcap2.2' then 'in_progress'
      when v_section.status = 'needs_changes' then 'in_progress'
      when v_section.status in ('approved', 'waived', 'not_applicable') then v_section.status
      else 'in_progress'
    end;

    update public.partner_onboarding_sections
    set
      response_data = p_response_data,
      revision = v_next_revision,
      status = v_next_status,
      completion_percentage = p_section_completion,
      missing_required_keys = coalesce(p_missing_required_keys, '{}'::text[]),
      first_started_at = coalesce(first_started_at, now()),
      completed_at = case
        when p_mode = 'section_complete' then now()
        else completed_at
      end,
      submitted_at = case
        when p_mode = 'section_complete' then now()
        else submitted_at
      end,
      approved_at = case when v_next_status = 'submitted' or v_workspace.rcap_policy_version='rcap2.2' then null else approved_at end,
      approved_by = case when v_next_status = 'submitted' or v_workspace.rcap_policy_version='rcap2.2' then null else approved_by end,
      reviewed_at = case when v_next_status = 'submitted' or v_workspace.rcap_policy_version='rcap2.2' then null else reviewed_at end,
      reviewed_by = case when v_next_status = 'submitted' or v_workspace.rcap_policy_version='rcap2.2' then null else reviewed_by end,
      review_reason = case when v_next_status = 'submitted' or v_workspace.rcap_policy_version='rcap2.2' then null else review_reason end
    where id = v_section.id;
  else
    if p_expected_revision <> 0 then
      raise exception using
        errcode = '40001',
        message = 'Onboarding section revision conflict';
    end if;
    v_next_revision := 1;
    v_first_started := true;
    v_completed := p_mode = 'section_complete';
    v_next_status := case
      when p_mode = 'section_complete' then 'submitted'
      else 'in_progress'
    end;

    insert into public.partner_onboarding_sections (
      workspace_id,
      section_key,
      response_data,
      revision,
      status,
      completion_percentage,
      missing_required_keys,
      first_started_at,
      completed_at,
      submitted_at
    ) values (
      p_workspace_id,
      p_section_key,
      p_response_data,
      v_next_revision,
      v_next_status,
      p_section_completion,
      coalesce(p_missing_required_keys, '{}'::text[]),
      now(),
      case when p_mode = 'section_complete' then now() end,
      case when p_mode = 'section_complete' then now() end
    )
    returning * into v_section;
  end if;

  if p_section_key = 'organization_contacts' then
    if jsonb_typeof(coalesce(p_collections->'contacts', '[]'::jsonb)) <> 'array' then
      raise exception using errcode = '22023', message = 'Contacts must be an array';
    end if;
    if exists (
      select 1
      from jsonb_array_elements(coalesce(p_collections->'contacts', '[]'::jsonb)) item
      join public.partner_onboarding_contacts existing
        on existing.id = (item->>'stable_row_id')::uuid
      where existing.workspace_id <> p_workspace_id
    ) then
      raise exception using errcode = '42501', message = 'Contact identity belongs to another workspace';
    end if;

    update public.partner_onboarding_contacts c
    set deleted_at = now(), revision = c.revision + 1
    where c.workspace_id = p_workspace_id
      and c.deleted_at is null
      and not exists (
        select 1
        from jsonb_array_elements(coalesce(p_collections->'contacts', '[]'::jsonb)) item
        where item->>'stable_row_id' = c.id::text
      );

    insert into public.partner_onboarding_contacts (
      id, workspace_id, role, name, title, organization, work_email, phone
    )
    select
      (item->>'stable_row_id')::uuid,
      p_workspace_id,
      item->>'role',
      item->>'name',
      item->>'title',
      nullif(item->>'organization', ''),
      lower(item->>'work_email'),
      nullif(item->>'phone', '')
    from jsonb_array_elements(coalesce(p_collections->'contacts', '[]'::jsonb)) item
    on conflict (id) do update
    set
      role = excluded.role,
      name = excluded.name,
      title = excluded.title,
      organization = excluded.organization,
      work_email = excluded.work_email,
      phone = excluded.phone,
      revision = public.partner_onboarding_contacts.revision + 1,
      deleted_at = null
    where public.partner_onboarding_contacts.workspace_id = p_workspace_id;
  elsif p_section_key = 'staff_dashboard_plan' then
    if jsonb_typeof(coalesce(p_collections->'planned_users', '[]'::jsonb)) <> 'array' then
      raise exception using errcode = '22023', message = 'Planned users must be an array';
    end if;
    if exists (
      select 1
      from jsonb_array_elements(coalesce(p_collections->'planned_users', '[]'::jsonb)) item
      join public.partner_onboarding_planned_users existing
        on existing.id = (item->>'stable_row_id')::uuid
      where existing.workspace_id <> p_workspace_id
    ) then
      raise exception using errcode = '42501', message = 'Planned user identity belongs to another workspace';
    end if;

    update public.partner_onboarding_planned_users u
    set deleted_at = now(), revision = u.revision + 1
    where u.workspace_id = p_workspace_id
      and u.deleted_at is null
      and not exists (
        select 1
        from jsonb_array_elements(coalesce(p_collections->'planned_users', '[]'::jsonb)) item
        where item->>'stable_row_id' = u.id::text
      );

    insert into public.partner_onboarding_planned_users (
      id,
      workspace_id,
      name,
      work_email,
      requested_role,
      special_permissions,
      training_attendee
    )
    select
      (item->>'stable_row_id')::uuid,
      p_workspace_id,
      item->>'name',
      lower(item->>'work_email'),
      item->>'requested_role',
      coalesce(
        array(
          select jsonb_array_elements_text(
            coalesce(item->'special_permissions', '[]'::jsonb)
          )
        ),
        '{}'::text[]
      ),
      coalesce((item->>'training_attendee')::boolean, false)
    from jsonb_array_elements(coalesce(p_collections->'planned_users', '[]'::jsonb)) item
    on conflict (id) do update
    set
      name = excluded.name,
      work_email = excluded.work_email,
      requested_role = excluded.requested_role,
      special_permissions = excluded.special_permissions,
      training_attendee = excluded.training_attendee,
      revision = public.partner_onboarding_planned_users.revision + 1,
      deleted_at = null
    where public.partner_onboarding_planned_users.workspace_id = p_workspace_id;
  elsif p_section_key = 'support_referrals_reporting' then
    if jsonb_typeof(coalesce(p_collections->'report_recipients', '[]'::jsonb)) <> 'array' then
      raise exception using errcode = '22023', message = 'Report recipients must be an array';
    end if;
    if exists (
      select 1
      from jsonb_array_elements(coalesce(p_collections->'report_recipients', '[]'::jsonb)) item
      join public.partner_onboarding_report_recipients existing
        on existing.id = (item->>'stable_row_id')::uuid
      where existing.workspace_id <> p_workspace_id
    ) then
      raise exception using errcode = '42501', message = 'Report recipient identity belongs to another workspace';
    end if;

    update public.partner_onboarding_report_recipients r
    set deleted_at = now(), revision = r.revision + 1
    where r.workspace_id = p_workspace_id
      and r.deleted_at is null
      and not exists (
        select 1
        from jsonb_array_elements(coalesce(p_collections->'report_recipients', '[]'::jsonb)) item
        where item->>'stable_row_id' = r.id::text
      );

    insert into public.partner_onboarding_report_recipients (
      id, workspace_id, name, work_email
    )
    select
      (item->>'stable_row_id')::uuid,
      p_workspace_id,
      nullif(item->>'name', ''),
      lower(item->>'work_email')
    from jsonb_array_elements(coalesce(p_collections->'report_recipients', '[]'::jsonb)) item
    on conflict (id) do update
    set
      name = excluded.name,
      work_email = excluded.work_email,
      revision = public.partner_onboarding_report_recipients.revision + 1,
      deleted_at = null
    where public.partner_onboarding_report_recipients.workspace_id = p_workspace_id;
  end if;

  if p_mode = 'section_complete' then
    update public.partner_onboarding_change_requests
    set
      status = 'partner_responded',
      partner_response = 'Updated section submitted for review.',
      responded_by = p_actor_user_id,
      responded_at = now(),
      updated_at = now()
    where workspace_id = p_workspace_id
      and section_id = v_section.id
      and status = 'open';

    v_partner_review_pending :=
      v_resubmitted
      and not exists (
        select 1
        from public.partner_onboarding_change_requests cr
        where cr.workspace_id = p_workspace_id
          and cr.status = 'open'
      );
  end if;

  update public.partner_onboarding
  set
    status = case
      when v_workspace.rcap_policy_version='rcap2.2' then status
      when v_partner_review_pending then 'ready_for_review'
      when exists (
        select 1
        from public.partner_onboarding_change_requests cr
        where cr.workspace_id = p_workspace_id
          and cr.status = 'open'
      ) then 'waiting_on_partner'
      when status = 'waiting_on_partner' then 'setup_in_progress'
      else status
    end,
    aggregate_version = aggregate_version + 1,
    completion_percentage = p_workspace_completion,
    blocker_code = case
      when v_partner_review_pending then null
      else p_blocker_code
    end,
    next_action_code = case
      when v_partner_review_pending then 'await_legalease_review'
      else p_next_action_code
    end,
    next_action_owner = case
      when v_partner_review_pending then 'legalease'
      else p_next_action_owner
    end,
    last_meaningful_activity_at = case
      when v_first_started or v_completed or v_resubmitted then now()
      else last_meaningful_activity_at
    end
  where id = p_workspace_id
  returning aggregate_version into workspace_aggregate_version;

  if v_resubmitted then
    v_event_type := 'section_resubmitted';
    v_event_summary := 'section_resubmitted';
  elsif v_completed then
    v_event_type := 'section_completed';
    v_event_summary := 'section_completed';
  elsif v_first_started then
    v_event_type := 'section_started';
    v_event_summary := 'section_started';
  end if;

  if v_event_type is not null then
    insert into public.partner_onboarding_activity (
      workspace_id,
      event_type,
      section_key,
      status_code,
      summary_code,
      owner_type,
      actor_user_id,
      request_id,
      dedupe_key
    ) values (
      p_workspace_id,
      v_event_type,
      p_section_key,
      v_next_status,
      v_event_summary,
      'partner',
      p_actor_user_id,
      p_request_id,
      p_request_id::text || ':' || v_event_type
    )
    on conflict do nothing;

    insert into public.partner_onboarding_integration_events (
      workspace_id,
      partner_record_id,
      event_type,
      workspace_aggregate_version,
      workspace_status,
      completion_percentage,
      blocker_code,
      next_action_code,
      next_action_owner,
      target_launch_date,
      section_key,
      section_status,
      idempotency_key
    )
    select
      po.id,
      v_partner_record_id,
      case
        when p_section_key = 'brand_public_page' then 'rcap_brand_configuration_changed'
        when p_section_key = 'staff_dashboard_plan' then 'rcap_team_configuration_changed'
        when p_blocker_code is not null then 'rcap_onboarding_blocked'
        else 'rcap_onboarding_progressed'
      end,
      po.aggregate_version,
      po.status,
      po.completion_percentage,
      po.blocker_code,
      po.next_action_code,
      po.next_action_owner,
      po.target_launch_date,
      p_section_key,
      v_next_status,
      p_request_id::text || ':progress'
    from public.partner_onboarding po
    where po.id = p_workspace_id
    on conflict do nothing;
  end if;

  update public.partner_onboarding_idempotency
  set
    result_status = 'succeeded',
    result_workspace_version = workspace_aggregate_version,
    result_section_revision = v_next_revision,
    completed_at = now()
  where request_id = p_request_id;

  section_revision := v_next_revision;
  section_status := v_next_status;
  duplicate := false;
  return next;
end;
$_$;


ALTER FUNCTION public.rcap_service_save_onboarding_section(p_partner_slug text, p_actor_user_id uuid, p_workspace_id uuid, p_section_key text, p_expected_revision bigint, p_expected_workspace_version bigint, p_response_data jsonb, p_collections jsonb, p_mode text, p_section_completion integer, p_missing_required_keys text[], p_workspace_completion integer, p_blocker_code text, p_next_action_code text, p_next_action_owner text, p_request_id uuid, p_payload_hash text) OWNER TO postgres;

--
-- Name: rcap_service_save_onboarding_section_with_prefill(text, uuid, uuid, text, bigint, bigint, jsonb, jsonb, text, integer, text[], integer, text, text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_service_save_onboarding_section_with_prefill(p_partner_slug text, p_actor_user_id uuid, p_workspace_id uuid, p_section_key text, p_expected_revision bigint, p_expected_workspace_version bigint, p_response_data jsonb, p_collections jsonb, p_mode text, p_section_completion integer, p_missing_required_keys text[], p_workspace_completion integer, p_blocker_code text, p_next_action_code text, p_next_action_owner text, p_request_id uuid, p_payload_hash text) RETURNS TABLE(section_revision bigint, workspace_aggregate_version bigint, section_status text, duplicate boolean)
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_saved record;
  v_pending integer := 0;
  v_modified integer := 0;
  v_partner_record_id uuid;
begin
  select *
    into v_saved
  from public.rcap_service_save_onboarding_section(
    p_partner_slug,
    p_actor_user_id,
    p_workspace_id,
    p_section_key,
    p_expected_revision,
    p_expected_workspace_version,
    p_response_data,
    p_collections,
    p_mode,
    p_section_completion,
    p_missing_required_keys,
    p_workspace_completion,
    p_blocker_code,
    p_next_action_code,
    p_next_action_owner,
    p_request_id,
    p_payload_hash
  );

  if p_mode = 'section_complete' and not v_saved.duplicate then
    select count(*)::integer
      into v_pending
    from public.partner_onboarding_prefill_values pv
    where pv.workspace_id = p_workspace_id
      and pv.section_key = p_section_key
      and pv.review_status = 'applied'
      and pv.partner_review_status = 'pending';

    if v_pending > 0 then
      update public.partner_onboarding_prefill_values pv
      set
        partner_review_status = case
          when public.rcap_onboarding_prefill_current_value(
            p_workspace_id, p_section_key, pv.field_key
          ) = pv.proposed_value then 'confirmed'
          when public.rcap_onboarding_prefill_current_value(
            p_workspace_id, p_section_key, pv.field_key
          ) in ('null'::jsonb, '""'::jsonb, '[]'::jsonb) then 'rejected'
          else 'modified'
        end,
        partner_reviewed_at = now(),
        partner_reviewed_section_revision = v_saved.section_revision,
        partner_modified = public.rcap_onboarding_prefill_current_value(
          p_workspace_id, p_section_key, pv.field_key
        ) <> pv.proposed_value
      where pv.workspace_id = p_workspace_id
        and pv.section_key = p_section_key
        and pv.review_status = 'applied'
        and pv.partner_review_status = 'pending';

      select count(*)::integer
        into v_modified
      from public.partner_onboarding_prefill_values pv
      where pv.workspace_id = p_workspace_id
        and pv.section_key = p_section_key
        and pv.review_status = 'applied'
        and pv.partner_reviewed_section_revision = v_saved.section_revision
        and pv.partner_review_status in ('modified', 'rejected');

      insert into public.partner_onboarding_activity (
        workspace_id, event_type, section_key, status_code, summary_code,
        owner_type, actor_user_id, request_id, dedupe_key
      ) values (
        p_workspace_id,
        case when v_modified > 0
          then 'prefill_section_modified'
          else 'prefill_section_confirmed'
        end,
        p_section_key,
        case when v_modified > 0
          then 'partner_modified'
          else 'partner_confirmed'
        end,
        case when v_modified > 0
          then 'prefill_section_modified'
          else 'prefill_section_confirmed'
        end,
        'partner',
        p_actor_user_id,
        p_request_id,
        p_request_id::text || ':prefill_reviewed'
      )
      on conflict do nothing;

      select po.partner_record_id
        into v_partner_record_id
      from public.partner_onboarding po
      where po.id = p_workspace_id;

      insert into public.partner_onboarding_integration_events (
        workspace_id, partner_record_id, event_type,
        workspace_aggregate_version, workspace_status,
        completion_percentage, blocker_code, next_action_code,
        next_action_owner, target_launch_date, section_key,
        section_status, idempotency_key
      )
      select
        po.id, v_partner_record_id, 'rcap_onboarding_prefill_reviewed',
        po.aggregate_version, po.status, po.completion_percentage,
        po.blocker_code, po.next_action_code, po.next_action_owner,
        po.target_launch_date, p_section_key, v_saved.section_status,
        p_request_id::text || ':prefill_reviewed'
      from public.partner_onboarding po
      where po.id = p_workspace_id
      on conflict do nothing;
    end if;
  end if;

  section_revision := v_saved.section_revision;
  workspace_aggregate_version := v_saved.workspace_aggregate_version;
  section_status := v_saved.section_status;
  duplicate := v_saved.duplicate;
  return next;
end;
$$;


ALTER FUNCTION public.rcap_service_save_onboarding_section_with_prefill(p_partner_slug text, p_actor_user_id uuid, p_workspace_id uuid, p_section_key text, p_expected_revision bigint, p_expected_workspace_version bigint, p_response_data jsonb, p_collections jsonb, p_mode text, p_section_completion integer, p_missing_required_keys text[], p_workspace_completion integer, p_blocker_code text, p_next_action_code text, p_next_action_owner text, p_request_id uuid, p_payload_hash text) OWNER TO postgres;

--
-- Name: rcap_service_save_program_configuration(text, uuid, bigint, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_service_save_program_configuration(p_slug text, p_actor uuid, p_version bigint, p_changes jsonb, p_request uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare w public.partner_onboarding%rowtype; snapshot jsonb; item jsonb; k text; section_name text; stored jsonb; proposed jsonb; value jsonb;
 previous public.partner_onboarding_idempotency%rowtype; fingerprint text; changed jsonb:='[]'; internal_actor boolean; external_rights jsonb:='[]'; operating_decision jsonb;
 allowed constant jsonb:='{
 "organization_contacts":["legal_organization_name","public_organization_name","public_program_name","website","primary_address","contacts"],
 "program_goals":["participation_mode","target_population","operating_model","operator_authority_reference","external_agreement_applicability","service_mode"],
 "geography_audience_language_accessibility":["jurisdictions","service_area_description","counties","primary_language","enable_spanish"],
 "access_sponsorship_capacity":["participant_access_model"],
 "support_referrals_reporting":["participant_support_email","referral_arrangement","contested_matter_procedure"],
 "brand_public_page":["program_headline","program_subheadline","approved_organization_description","primary_cta_label","participant_support_copy","program_headline_es","program_subheadline_es","approved_organization_description_es","primary_cta_label_es","participant_support_copy_es","service_area_es","target_audience_es"]}';
begin
 select * into strict w from public.partner_onboarding where partner_slug=p_slug for update;
 -- Revalidate current membership even for an idempotent replay.
 snapshot:=public.rcap_service_get_program_configuration(p_slug,p_actor);
 internal_actor:=exists(select 1 from public.partner_users where auth_user_id=p_actor and partner_slug is null and role='internal_admin' and status='active');
 if p_request is null or p_version is null or p_version<1 or p_changes is null or jsonb_typeof(p_changes)<>'array' or jsonb_array_length(p_changes)>6 or octet_length(p_changes::text)>131072 then
  raise exception 'invalid configuration request' using errcode='22023';
 end if;
 fingerprint:=encode(sha256(convert_to(jsonb_build_object('version',p_version,'changes',p_changes)::text,'UTF8')),'hex');
 select * into previous from public.partner_onboarding_idempotency where request_id=p_request;
 if found then
  if previous.workspace_id<>w.id or previous.actor_user_id<>p_actor or previous.operation_key<>'program_configuration' or previous.payload_hash<>fingerprint then
   raise exception 'request belongs to another mutation' using errcode='23505';
  end if;
  if previous.result_status<>'succeeded' then raise exception 'request in progress' using errcode='55000';end if;
  return snapshot;
 end if;
 if w.aggregate_version<>p_version then raise exception 'configuration revision conflict' using errcode='PT409';end if;
 if w.status in ('paused','closed') then raise exception 'program not editable' using errcode='55000';end if;
 if (select count(distinct v->>'section') from jsonb_array_elements(p_changes) v)<>jsonb_array_length(p_changes) then raise exception 'duplicate sections' using errcode='22023';end if;
 for item in select v from jsonb_array_elements(p_changes) v loop
  section_name:=item->>'section';
  if not allowed ? section_name or jsonb_typeof(item->'values') is distinct from 'object' or jsonb_typeof(item->'base') is distinct from 'object' then raise exception 'invalid configuration section' using errcode='22023';end if;
  stored:=coalesce(snapshot#>array['data',section_name],'{}');
  proposed:=stored||(item->'values');
  for k,value in select * from jsonb_each(item->'values') loop
   if not (allowed->section_name) ? k then raise exception 'protected configuration field' using errcode='42501';end if;
   if coalesce(stored->k,'null') is distinct from coalesce(item->'base'->k,'null') and coalesce(stored->k,'null') is distinct from value then raise exception 'field revision conflict' using errcode='PT409';end if;
   if value is not distinct from coalesce(stored->k,'null') then continue;end if;
   if k='legal_organization_name' and coalesce(stored->>k,'')<>'' and (snapshot->>'legalIdentityLocked')::boolean then raise exception 'protected legal identity' using errcode='42501';end if;
   -- A live scope change needs a separate authorized publication transition.
   if w.status='live' and (section_name in ('geography_audience_language_accessibility','access_sponsorship_capacity') or k='participation_mode') then raise exception 'live service scope is protected' using errcode='55000';end if;
   if k in ('operating_model','operator_authority_reference','external_agreement_applicability','service_mode') then
    if not internal_actor then raise exception 'Platform Admin operating decision required' using errcode='42501';end if;
    if w.status='live' then raise exception 'published operating scope is protected' using errcode='55000';end if;
    if k='operating_model' and (value#>>'{}' not in ('partner_managed','legalease_managed') or jsonb_typeof(value)<>'string') then raise exception 'invalid operating model' using errcode='22023';end if;
    if k='service_mode' and (value#>>'{}' not in ('screening_only','participant_paid','sponsored_packets') or jsonb_typeof(value)<>'string') then raise exception 'invalid service mode' using errcode='22023';end if;
    if k='external_agreement_applicability' and (value#>>'{}' not in ('not_applicable','required') or jsonb_typeof(value)<>'string') then raise exception 'invalid agreement applicability' using errcode='22023';end if;
    if k='operator_authority_reference' and (jsonb_typeof(value)<>'string' or length(btrim(value#>>'{}')) not between 10 and 1000) then raise exception 'actual operator authority required' using errcode='22023';end if;
   end if;
   if k='participation_mode' and (jsonb_typeof(value)<>'string' or value#>>'{}' not in ('online','clinics','both')) then raise exception 'invalid participation mode' using errcode='22023';end if;
   if k='participant_access_model' and (jsonb_typeof(value)<>'string' or value#>>'{}' not in ('open','optional_code','required_code','invite_only')) then raise exception 'invalid access model' using errcode='22023';end if;
   if k='jurisdictions' then
    if jsonb_typeof(value)<>'array' then raise exception 'invalid jurisdictions' using errcode='22023';end if;
    if exists(select 1 from jsonb_array_elements_text(value) code where code<>all(array['AL','AK','AZ','AR','CA','CO','CT','DE','DC','FL','GA','HI','ID','IL','IN','IA','KS','KY','LA','ME','MD','MA','MI','MN','MS','MO','MT','NE','NV','NH','NJ','NM','NY','NC','ND','OH','OK','OR','PA','RI','SC','SD','TN','TX','UT','VT','VA','WA','WV','WI','WY'])) then raise exception 'invalid jurisdiction' using errcode='22023';end if;
   end if;
  end loop;
  if section_name='program_goals' and item->'values' ? 'operating_model' and proposed->>'operating_model' is distinct from w.operating_model then
   -- An operator selection is an explicit Platform Admin responsibility decision,
   -- not a mutation of memberships, agreement history, consent or financial rights.
   external_rights:=public.rcap_program_external_rights_evidence(w.id);
   if proposed->>'operating_model'='legalease_managed' then
    if jsonb_array_length(external_rights)>0 then
     raise exception 'rcap_external_operating_rights' using errcode='42501',detail=external_rights::text;
    end if;
    if coalesce(length(btrim(proposed->>'operator_authority_reference')),0)<10 then
     raise exception 'Operating responsibility must identify the actual LegalEase operating basis' using errcode='22023';
    end if;
   end if;
   operating_decision:=jsonb_build_object('actor',p_actor,'role','internal_admin','at',now(),
    'from',w.operating_model,'to',proposed->>'operating_model','basis',proposed->>'operator_authority_reference',
    'externalRights',external_rights,'evaluationVersion','external-rights-v2',
    'membershipsPreserved',true,'agreementHistoryPreserved',true,'approvalHistoryPreserved',true);
   update public.partner_onboarding set operating_model=proposed->>'operating_model',rcap_policy_version=case when proposed->>'operating_model'='legalease_managed' then 'rcap2.2' else rcap_policy_version end where id=w.id;
   w.operating_model:=proposed->>'operating_model';
   if w.operating_model='legalease_managed' then w.rcap_policy_version:='rcap2.2';end if;
  end if;
  if proposed=stored then continue;end if;
  if item->'values' ? 'contacts' then
   if jsonb_typeof(proposed->'contacts')<>'array' then raise exception 'invalid contacts' using errcode='22023';end if;
   if exists(select 1 from jsonb_array_elements(proposed->'contacts') c join public.partner_onboarding_contacts existing on existing.id=(c->>'stable_row_id')::uuid where existing.workspace_id<>w.id) then raise exception 'contact tenant mismatch' using errcode='42501';end if;
   update public.partner_onboarding_contacts c set deleted_at=now(),revision=revision+1 where workspace_id=w.id and deleted_at is null and not exists(select 1 from jsonb_array_elements(proposed->'contacts') item where item->>'stable_row_id'=c.id::text);
   insert into public.partner_onboarding_contacts(id,workspace_id,role,name,title,organization,work_email,phone)
   select (c->>'stable_row_id')::uuid,w.id,c->>'role',c->>'name',c->>'title',nullif(c->>'organization',''),lower(c->>'work_email'),nullif(c->>'phone','') from jsonb_array_elements(proposed->'contacts') c
   on conflict(id) do update set role=excluded.role,name=excluded.name,title=excluded.title,organization=excluded.organization,work_email=excluded.work_email,phone=excluded.phone,deleted_at=null,revision=public.partner_onboarding_contacts.revision+1
   where public.partner_onboarding_contacts.workspace_id=w.id;
  end if;
  update public.partner_onboarding_sections set response_data=proposed-'contacts',revision=revision+1,
   status=case when status='not_started' then 'in_progress' else status end,first_started_at=coalesce(first_started_at,now())
   where workspace_id=w.id and section_key=section_name;
  if not found then raise exception 'configuration section missing' using errcode='P0002';end if;
  changed:=changed||jsonb_build_array(jsonb_build_object('section',section_name,'fields',(select jsonb_agg(key order by key) from jsonb_object_keys(item->'values') key)));
 end loop;
 if jsonb_array_length(changed)>0 then
  update public.partner_onboarding set aggregate_version=aggregate_version+1 where id=w.id returning aggregate_version into w.aggregate_version;
  insert into public.partner_events(id,partner_slug,event_type,event_label,event_payload) values(p_request,p_slug,'rcap_program_configuration_saved','Program configuration saved',jsonb_build_object('actor',p_actor,'role',case when internal_actor then 'internal_admin' else 'partner_admin' end,'workspaceId',w.id,'policyVersion',w.rcap_policy_version,'sourceVersion',p_version,'resultVersion',w.aggregate_version,'changes',changed,'operatingModelBefore',snapshot->>'operatingModel','operatingModel',w.operating_model,'policyBefore',snapshot->>'policyVersion','operatorAuthority',public.rcap_program_policy_source(w.id)#>>'{program_goals,operator_authority_reference}','operatingResponsibilityDecision',operating_decision));
 end if;
 insert into public.partner_onboarding_idempotency(workspace_id,operation_key,request_id,actor_user_id,payload_hash,result_status,result_workspace_version,expires_at,completed_at)
 values(w.id,'program_configuration',p_request,p_actor,fingerprint,'succeeded',w.aggregate_version,now()+interval '24 hours',now());
 return public.rcap_service_get_program_configuration(p_slug,p_actor);
end $$;


ALTER FUNCTION public.rcap_service_save_program_configuration(p_slug text, p_actor uuid, p_version bigint, p_changes jsonb, p_request uuid) OWNER TO postgres;

--
-- Name: rcap_service_save_program_translation(text, uuid, bigint, jsonb, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_service_save_program_translation(p_slug text, p_actor uuid, p_version bigint, p_source jsonb, p_copy jsonb, p_request uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare w public.partner_onboarding%rowtype; snapshot jsonb; stored jsonb; proposed jsonb; changes jsonb; k text; field_name text; value jsonb; reservation public.partner_onboarding_idempotency%rowtype;
 mapping constant jsonb:='{"headline":"program_headline_es","subheadline":"program_subheadline_es","organizationDescription":"approved_organization_description_es","primaryActionLabel":"primary_cta_label_es","participantSupportCopy":"participant_support_copy_es","serviceArea":"service_area_es","targetAudience":"target_audience_es"}';
begin
 select * into strict w from public.partner_onboarding where partner_slug=p_slug for update;
 snapshot:=public.rcap_service_get_program_configuration(p_slug,p_actor);
 if not exists(select 1 from public.partner_users where auth_user_id=p_actor and status='active' and ((partner_slug=p_slug and role='partner_admin') or (partner_slug is null and role='internal_admin'))) then raise exception 'administrator required' using errcode='42501';end if;
 select * into reservation from public.partner_onboarding_idempotency where request_id=p_request;
 if found then
  if reservation.workspace_id<>w.id or reservation.actor_user_id<>p_actor or reservation.operation_key not in ('program_translation','program_translation_reuse') or reservation.payload_hash<>encode(sha256(convert_to(p_source::text,'UTF8')),'hex') then raise exception 'translation request mismatch' using errcode='42501';end if;
  if reservation.result_status='succeeded' then return snapshot;end if;
  if reservation.result_status<>'started' or reservation.expires_at<=now() then raise exception 'translation attempt expired; retry' using errcode='PT409';end if;
 end if;
 if w.rcap_policy_version<>'rcap2.2' or w.status in ('live','paused','closed') then raise exception 'program not editable' using errcode='55000';end if;
 if p_version is distinct from w.aggregate_version or p_source is distinct from public.rcap_program_public_copy_source(w.id) then raise exception 'public source changed' using errcode='PT409';end if;
 if p_copy is null or jsonb_typeof(p_copy)<>'object' or (select count(*) from jsonb_object_keys(p_copy))<>7 then raise exception 'seven public fields required' using errcode='22023';end if;
 stored:=coalesce(snapshot#>'{data,brand_public_page}','{}');
 select event_payload->'spanishPreparation' into value from public.partner_events where partner_slug=p_slug and event_type='rcap_spanish_draft_prepared' order by created_at desc,id desc limit 1;
 if value is not null then stored:=stored||jsonb_build_object('spanish_preparation',value);end if;
 proposed:=stored;
 for k,field_name in select * from jsonb_each_text(mapping) loop
  value:=p_copy->k;
  if jsonb_typeof(value) is distinct from 'string' or coalesce(length(btrim(value#>>'{}')),0) not between 1 and 4000 then raise exception 'incomplete Spanish copy' using errcode='22023';end if;
  proposed:=jsonb_set(proposed,array[field_name],value);
 end loop;
 proposed:=proposed||jsonb_build_object('spanish_preparation',jsonb_build_object('source',p_source,'copy',p_copy));
 if proposed is distinct from stored then
  changes:=(select jsonb_object_agg(m.field_name,proposed->m.field_name) from jsonb_each_text(mapping) m(k,field_name));
  snapshot:=public.rcap_service_save_program_configuration(p_slug,p_actor,p_version,jsonb_build_array(jsonb_build_object('section','brand_public_page','values',changes,'base',stored)),gen_random_uuid());
  update public.partner_onboarding set aggregate_version=aggregate_version+1 where id=w.id returning aggregate_version into w.aggregate_version;
  insert into public.partner_events(id,partner_slug,event_type,event_label,event_payload) values(p_request,p_slug,'rcap_spanish_draft_prepared','Spanish public-page draft prepared',jsonb_build_object('actor',p_actor,'workspaceId',w.id,'sourceVersion',p_version,'resultVersion',w.aggregate_version,'sourceHash',encode(sha256(convert_to(p_source::text,'UTF8')),'hex'),'requiresFinalReview',true,'spanishPreparation',proposed->'spanish_preparation'));
 end if;
 if reservation.id is not null then update public.partner_onboarding_idempotency set result_status='succeeded',completed_at=now(),result_workspace_version=w.aggregate_version where id=reservation.id;
 else insert into public.partner_onboarding_idempotency(workspace_id,operation_key,request_id,actor_user_id,payload_hash,result_status,result_workspace_version,expires_at,completed_at)
 values(w.id,'program_translation_reuse',p_request,p_actor,encode(sha256(convert_to(p_source::text,'UTF8')),'hex'),'succeeded',w.aggregate_version,now()+interval '24 hours',now());end if;
 return public.rcap_service_get_program_configuration(p_slug,p_actor);
end $$;


ALTER FUNCTION public.rcap_service_save_program_translation(p_slug text, p_actor uuid, p_version bigint, p_source jsonb, p_copy jsonb, p_request uuid) OWNER TO postgres;

--
-- Name: rcap_service_stage_program_launch(text, uuid, uuid, bigint, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_service_stage_program_launch(p_slug text, p_actor uuid, p_operation uuid, p_version bigint, p_hash text, p_versions jsonb, p_authority uuid) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
declare w public.partner_onboarding%rowtype; d jsonb; prepared public.rcap_launch_operation_events%rowtype; delegated public.partner_onboarding_launch_approvals%rowtype;
begin
 perform public.rcap_service_assert_internal_actor(p_actor);
 select * into strict w from public.partner_onboarding where partner_slug=p_slug for update;
 perform 1 from public.partner_records where id=w.partner_record_id for update;
 perform 1 from public.partner_onboarding_sections where workspace_id=w.id for update;
 perform 1 from public.partner_onboarding_artifacts where workspace_id=w.id for update;
 perform 1 from public.partner_onboarding_artifact_versions where workspace_id=w.id for update;
 perform 1 from public.partner_onboarding_launch_approvals where workspace_id=w.id for update;
 perform 1 from public.partner_onboarding_assets where workspace_id=w.id for update;
 perform 1 from public.partner_entitlement where partner_slug=p_slug for update;
 if w.rcap_policy_version<>'rcap2.2' or w.status in ('live','paused','closed') or w.landing_page_ready or p_version is null or w.aggregate_version<>p_version then raise exception 'source changed' using errcode='PT409';end if;
 select * into strict prepared from public.rcap_launch_operation_events where workspace_id=w.id and operation_id=p_operation and actor_auth_user_id=p_actor and snapshot_hash=p_hash and step='prepared' and evidence->>'mode'='real';
 if (case when w.operating_model='legalease_managed' then prepared.evidence->>'operatingDecisionId' else prepared.evidence->>'commercialAuthorityId' end) is distinct from p_authority::text or coalesce(prepared.evidence->>'releaseAuthorization','') !~ '^release:[a-f0-9]{40}$' then raise exception 'exact release and authority binding required';end if;
 if exists(select 1 from public.partner_records r join public.rcap_launch_operation_events e on e.workspace_id=w.id and e.operation_id=p_operation and e.step='prepared' where r.id=w.partner_record_id and ((e.evidence->'snapshot'->'activationRecord'->>'payment_status') is distinct from r.payment_status or (e.evidence->'snapshot'->'activationRecord'->>'stripe_payment_intent_id') is distinct from r.stripe_payment_intent_id or (e.evidence->'snapshot'->'activationRecord'->>'paid_at')::timestamptz is distinct from r.paid_at or (e.evidence->'snapshot'->'activationRecord'->>'payment_amount')::numeric is distinct from r.payment_amount or (e.evidence->'snapshot'->'activationRecord'->>'qualification_status') is distinct from r.qualification_status)) then raise exception 'financial or activation source changed after snapshot';end if;
 if coalesce(prepared.evidence->'intakeJurisdictions',jsonb_build_array(prepared.evidence->>'intakeJurisdiction')) is distinct from public.rcap_program_policy_source(w.id)#>'{geography_audience_language_accessibility,jurisdictions}' then raise exception 'exact current screening jurisdiction set required';end if;
 d:=public.rcap_service_evaluate_program(p_slug,p_actor,'publish_partner_page');
 if not coalesce((d->>'allowed')::boolean,false) or d->>'authorityId' is distinct from p_authority::text or prepared.evidence->'snapshot'->>'scopeHash' is distinct from d->>'scopeHash' then raise exception 'program capability held' using errcode='42501';end if;
 if prepared.evidence->'snapshot'->>'delegationId' is not null then
 select * into delegated from public.partner_onboarding_launch_approvals where id=(prepared.evidence->'snapshot'->>'delegationId')::uuid and workspace_id=w.id and reviewer_user_id=p_actor and approval_type='standing_launch_authorization' and decision='approve' and invalidated_at is null;
 if delegated.id is null or delegated.policy_details->>'scope_hash' is distinct from d->>'scopeHash' or not delegated.policy_details->'capabilities' ? 'publish_partner_page' or coalesce((delegated.policy_details->>'expires_at')::timestamptz,now())<=now() or exists(select 1 from public.partner_onboarding_launch_approvals n where n.workspace_id=w.id and n.approval_type=delegated.approval_type and (n.recorded_at,n.id)>(delegated.recorded_at,delegated.id)) then raise exception 'standing delegation stale or revoked' using errcode='42501';end if;
 end if;
 if jsonb_typeof(p_versions) is distinct from 'array' or jsonb_array_length(p_versions)<>2 or (select count(distinct item->>'type') from jsonb_array_elements(p_versions) item)<>2 then raise exception 'two exact substantive materials required';end if;
 if exists(select 1 from jsonb_array_elements(p_versions) item where not exists(select 1 from public.partner_onboarding_artifacts ar join public.partner_onboarding_artifact_versions v on v.id=ar.current_version_id where ar.workspace_id=w.id and ar.artifact_type=item->>'type' and ar.artifact_type in ('implementation_brief','co_branded_page_configuration') and v.id::text=item->>'id' and v.snapshot_hash=item->>'hash' and v.normalized_snapshot->>'rcap_dependency_hash'=public.rcap_program_material_scope(w.id,ar.artifact_type) and (ar.artifact_type<>'co_branded_page_configuration' or v.rendered_content#>'{pagePreview,missing}'='[]'::jsonb) and (v.partner_review_status='approved' or (w.operating_model='legalease_managed' and v.approval_status='approved' and public.rcap_program_internal_authority(w.id)=p_authority)) and v.generation_status='succeeded' and v.superseded_at is null and v.source_drift_invalidated_at is null and (v.approval_status='approved' or (v.normalized_snapshot->>'rcap_standard_policy'='rcap2.2' and v.generator_version like '%_rcap2')))) then raise exception 'reviewed materials changed' using errcode='PT409';end if;
 if prepared.evidence->'snapshot'->>'materialsHash' is distinct from d->>'materialsHash' then raise exception 'material snapshot changed';end if;
 update public.partner_records set onboarding_status='approved',onboarding_completed_at=coalesce(onboarding_completed_at,now()) where id=w.partner_record_id;
 update public.partner_onboarding set status='live',landing_page_ready=true,internal_approved_at=now(),launched_at=now(),rcap_launch_operation_id=p_operation where id=w.id;
 insert into public.rcap_launch_operation_events(workspace_id,partner_slug,operation_id,request_id,step,actor_auth_user_id,snapshot_hash,authority_reference,evidence)
 values(w.id,p_slug,p_operation,prepared.request_id,'publication_staged',p_actor,p_hash,prepared.authority_reference,jsonb_build_object('mode','real','operatingDecisionId',case when w.operating_model='legalease_managed' then p_authority else null end,'commercialAuthorityId',case when w.operating_model='partner_managed' then p_authority else null end,'workspaceVersion',p_version,'policyVersion','rcap2.2'));
 return true;
end $_$;


ALTER FUNCTION public.rcap_service_stage_program_launch(p_slug text, p_actor uuid, p_operation uuid, p_version bigint, p_hash text, p_versions jsonb, p_authority uuid) OWNER TO postgres;

--
-- Name: rcap_service_stage_real_launch(text, uuid, uuid, bigint, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_service_stage_real_launch(p_slug text, p_actor uuid, p_operation uuid, p_version bigint, p_hash text, p_versions jsonb, p_authority uuid) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
declare w public.partner_onboarding%rowtype; a public.rcap_commercial_authorizations%rowtype; consent public.partner_onboarding_launch_approvals%rowtype; final_review public.partner_onboarding_launch_approvals%rowtype; begin
 if exists(select 1 from public.partner_onboarding where partner_slug=p_slug and rcap_policy_version='rcap2.2') then return public.rcap_service_stage_program_launch(p_slug,p_actor,p_operation,p_version,p_hash,p_versions,p_authority);end if;
 perform public.rcap_service_assert_internal_actor(p_actor);
 select * into strict w from public.partner_onboarding where partner_slug=p_slug for update;
 perform 1 from public.partner_records where id=w.partner_record_id for update;
 perform 1 from public.partner_onboarding_sections where workspace_id=w.id for update;
 perform 1 from public.partner_onboarding_assets where workspace_id=w.id for update;
 perform 1 from public.partner_onboarding_artifacts where workspace_id=w.id for update;
 perform 1 from public.partner_onboarding_artifact_versions where workspace_id=w.id for update;
 perform 1 from public.partner_onboarding_launch_checks where workspace_id=w.id for update;
 perform 1 from public.partner_onboarding_launch_approvals where workspace_id=w.id for update;
 select * into strict a from public.rcap_commercial_authorizations where id=p_authority and workspace_id=w.id;
 if w.status='live' or w.landing_page_ready or w.aggregate_version<>p_version or w.agreement_status<>'signed' or w.commercial_gate_status='blocked' then raise exception 'stale or unapproved publication source' using errcode='PT409'; end if;
 if not exists(select 1 from public.rcap_launch_operation_events where workspace_id=w.id and operation_id=p_operation and actor_auth_user_id=p_actor and snapshot_hash=p_hash and step='prepared' and evidence->>'mode'='real' and evidence->>'commercialAuthorityId'=a.id::text) then raise exception 'matching real launch authorization required'; end if;
 if exists(select 1 from public.rcap_launch_capacity_events ce where ce.workspace_id=w.id and ce.created_at>a.created_at) then raise exception 'renew commercial authorization after capacity changes';end if;
 if a.expires_at<=now() or not exists(select 1 from public.partner_onboarding_assets where id=a.document_id and workspace_id=w.id and sha256_hex=a.document_hash and lifecycle_status='active' and review_status='approved') then raise exception 'commercial authority expired or withdrawn'; end if;
 if exists(select 1 from public.partner_records r join public.rcap_launch_operation_events e on e.workspace_id=w.id and e.operation_id=p_operation and e.step='prepared' where r.id=w.partner_record_id and ((e.evidence->'snapshot'->'activationRecord'->>'payment_status') is distinct from r.payment_status or (e.evidence->'snapshot'->'activationRecord'->>'stripe_payment_intent_id') is distinct from r.stripe_payment_intent_id or (e.evidence->'snapshot'->'activationRecord'->>'paid_at')::timestamptz is distinct from r.paid_at or (e.evidence->'snapshot'->'activationRecord'->>'payment_amount')::numeric is distinct from r.payment_amount or (e.evidence->'snapshot'->'activationRecord'->>'qualification_status') is distinct from r.qualification_status)) then raise exception 'financial or activation source changed after snapshot';end if;
 if not exists(select 1 from public.partner_records r where r.id=w.partner_record_id and r.qualification_status='qualified' and r.payment_status is distinct from 'demo_paid' and r.provisioning_status in ('active','provisioned') and r.access_mode=a.access_mode and (a.kind<>'verified_paid' or (r.payment_status='paid' and r.stripe_payment_intent_id ~ '^pi_[A-Za-z0-9]+$' and r.paid_at<=now() and r.payment_amount>0))) then raise exception 'activation or payment authority changed'; end if;
 if (select count(*) from public.partner_onboarding_sections where workspace_id=w.id and status='approved')<>8 or not exists(select 1 from public.partner_onboarding_sections where workspace_id=w.id and section_key='access_sponsorship_capacity' and response_data->>'participant_access_model'=a.access_mode) then raise exception 'canonical configuration unapproved or conflicting'; end if;
 if not exists(select 1 from public.partner_onboarding_sections geo join public.partner_records r on r.id=w.partner_record_id join public.rcap_launch_operation_events e on e.operation_id=p_operation and e.step='prepared' where geo.workspace_id=w.id and geo.section_key='geography_audience_language_accessibility' and geo.status='approved' and case when e.evidence ? 'intakeJurisdictions' then
 jsonb_typeof(e.evidence->'intakeJurisdictions')='array' and jsonb_array_length(e.evidence->'intakeJurisdictions')>0
 and e.evidence->'intakeJurisdictions'=(select jsonb_agg(distinct j order by j) from jsonb_array_elements_text(geo.response_data->'jurisdictions') j)
 and not exists(select 1 from jsonb_array_elements_text(geo.response_data->'jurisdictions') j where j<>all(public.rcap_screening_jurisdictions()))
 else case when jsonb_array_length(geo.response_data->'jurisdictions')=1 then geo.response_data->'jurisdictions'->>0 else case when geo.response_data->'jurisdictions' ? coalesce(r.target_state,r.state) then coalesce(r.target_state,r.state) end end=e.evidence->>'intakeJurisdiction' end) then raise exception 'approved screening jurisdiction scope changed or absent';end if;
 perform 1 from public.partner_entitlement where partner_slug=p_slug for update;
 if not exists(select 1 from public.partner_entitlement where partner_slug=p_slug and screenings_allowed>screenings_used) then raise exception 'screening allocation exhausted or absent'; end if;
 perform 1 from public.partner_packet_entitlement where id=a.packet_entitlement_id for update;
 if not exists(select 1 from public.partner_packet_entitlement e where e.id=a.packet_entitlement_id and e.partner_id=w.partner_record_id and e.effective_at<=now() and (e.expires_at is null or e.expires_at>now()) and e.packet_cap>(select count(*) from public.packet_credit_ledger l where l.entitlement_id=e.id and l.event_type='consumed')) then raise exception 'packet allocation exhausted or absent'; end if;
 select * into consent from public.partner_onboarding_launch_approvals where workspace_id=w.id and approval_type='partner_launch_approval' order by recorded_at desc,id desc limit 1;
 select * into final_review from public.partner_onboarding_launch_approvals where workspace_id=w.id and approval_type='legalease_final_review' order by recorded_at desc,id desc limit 1;
 if consent.id is null or consent.decision<>'approve' or consent.invalidated_at is not null or not exists(select 1 from public.partner_users where auth_user_id=consent.reviewer_user_id and partner_slug=p_slug and role='partner_admin' and status='active') or final_review.id is null or final_review.decision<>'approve' or final_review.invalidated_at is not null then raise exception 'current partner consent and final review required'; end if;
 perform public.rcap_service_assert_internal_actor(final_review.reviewer_user_id);
 if not exists(select 1 from public.partner_onboarding_launch_checks where workspace_id=w.id and check_key='staff_training_completed' and status='passing' and invalidated_at is null) then raise exception 'current training review required'; end if;
 if jsonb_typeof(p_versions)<>'array' or jsonb_array_length(p_versions)<>5 or (select count(distinct item->>'type') from jsonb_array_elements(p_versions) item)<>5 then raise exception 'exact five-material package required'; end if;
 if exists(select 1 from jsonb_array_elements(p_versions) item where not exists(select 1 from public.partner_onboarding_artifact_versions v join public.partner_onboarding_artifacts ar on ar.id=v.artifact_id where v.workspace_id=w.id and v.id=(item->>'id')::uuid and ar.current_version_id=v.id and ar.artifact_type=item->>'type' and ar.artifact_type in ('implementation_brief','operations_escalation_plan','dashboard_user_reporting_matrix','staff_quick_start_guide','co_branded_page_configuration') and v.snapshot_hash=item->>'hash' and item->>'freshness'='current' and v.approval_status='approved' and v.generation_status='succeeded' and v.superseded_at is null and v.source_drift_invalidated_at is null and (ar.artifact_type not in ('implementation_brief','co_branded_page_configuration') or v.partner_review_status='approved'))) then raise exception 'approved package changed' using errcode='PT409'; end if;
 if exists(select 1 from public.rcap_launch_operation_events e cross join lateral jsonb_array_elements(e.evidence->'checks') c where e.operation_id=p_operation and e.step='prepared' and exists(select 1 from public.partner_onboarding_launch_checks lc where lc.workspace_id=w.id and lc.check_key=c->>'key' and (lc.status<>c->>'status' or lc.invalidated_at is not null or lc.checked_at is distinct from (c->>'checkedAt')::timestamptz))) then raise exception 'recorded checks changed after snapshot'; end if;
 update public.partner_records set onboarding_status='approved',onboarding_completed_at=coalesce(onboarding_completed_at,now()) where id=w.partner_record_id;
 update public.partner_onboarding set status='live' ,landing_page_ready=true,internal_approved_at=now(),launched_at=now(),rcap_launch_operation_id=p_operation where id=w.id;
 insert into public.rcap_launch_operation_events(workspace_id,partner_slug,operation_id,request_id,step,actor_auth_user_id,snapshot_hash,authority_reference,evidence)
 select workspace_id,partner_slug,operation_id,request_id,'publication_staged',actor_auth_user_id,snapshot_hash,authority_reference,jsonb_build_object('mode','real','commercialAuthorityId',a.id,'workspaceVersion',p_version) from public.rcap_launch_operation_events where workspace_id=w.id and operation_id=p_operation and step='prepared';
 return true;
end $_$;


ALTER FUNCTION public.rcap_service_stage_real_launch(p_slug text, p_actor uuid, p_operation uuid, p_version bigint, p_hash text, p_versions jsonb, p_authority uuid) OWNER TO postgres;

--
-- Name: rcap_service_stage_synthetic_launch(text, uuid, uuid, bigint, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_service_stage_synthetic_launch(p_slug text, p_actor uuid, p_operation uuid, p_version bigint, p_hash text, p_versions jsonb) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare v_workspace public.partner_onboarding%rowtype; begin
 perform public.rcap_service_assert_internal_actor(p_actor);
 if not exists(select 1 from public.rcap_synthetic_launch_targets t join public.partner_users u on u.auth_user_id=t.registered_by where t.partner_slug=p_slug and u.role='internal_admin' and u.status='active' and u.partner_slug is null) then raise exception 'registered synthetic target required' using errcode='42501'; end if;
 select * into strict v_workspace from public.partner_onboarding where partner_slug=p_slug for update;
 if v_workspace.status='live' then raise exception 'already published' using errcode='40001'; end if;
 if v_workspace.aggregate_version<>p_version then raise exception 'stale launch source' using errcode='40001'; end if;
 if not exists(select 1 from public.rcap_launch_operation_events where workspace_id=v_workspace.id and operation_id=p_operation and actor_auth_user_id=p_actor and snapshot_hash=p_hash and step='prepared') then raise exception 'matching prepared authority required' using errcode='42501'; end if;
 if not exists(select 1 from public.partner_records where partner_slug=p_slug and payment_status in ('paid','demo_paid') and qualification_status='qualified' and provisioning_status in ('provisioned','active')) then raise exception 'existing activation authority required' using errcode='42501'; end if;
 if not exists(select 1 from public.partner_entitlement where partner_slug=p_slug and screenings_allowed>screenings_used) then raise exception 'screening capacity required' using errcode='42501'; end if;
 if v_workspace.commercial_gate_status='blocked' or v_workspace.agreement_status<>'signed' then raise exception 'commercial and contractual authority required' using errcode='42501'; end if;
 if jsonb_typeof(p_versions)<>'array' or jsonb_array_length(p_versions)<>5 or (select count(distinct item->>'id') from jsonb_array_elements(p_versions) item)<>5 then raise exception 'exact package required'; end if;
 if exists(select 1 from jsonb_array_elements(p_versions) item where not exists(select 1 from public.partner_onboarding_artifact_versions v join public.partner_onboarding_artifacts a on a.id=v.artifact_id where v.workspace_id=v_workspace.id and v.id=(item->>'id')::uuid and a.current_version_id=v.id and v.snapshot_hash=item->>'hash' and v.approval_status='approved' and v.generation_status='succeeded' and v.superseded_at is null and v.source_drift_invalidated_at is null and (a.artifact_type not in ('implementation_brief','co_branded_page_configuration') or v.partner_review_status='approved'))) then raise exception 'package changed' using errcode='40001'; end if;
 update public.partner_onboarding set status='live',landing_page_ready=true,internal_approved_at=now(),launched_at=now() where id=v_workspace.id;
 insert into public.rcap_launch_operation_events(workspace_id,partner_slug,operation_id,request_id,step,actor_auth_user_id,snapshot_hash,authority_reference,evidence)
 select workspace_id,partner_slug,operation_id,request_id,'publication_staged',actor_auth_user_id,snapshot_hash,authority_reference,jsonb_build_object('workspaceVersion',p_version) from public.rcap_launch_operation_events where workspace_id=v_workspace.id and operation_id=p_operation and step='prepared';
 return true;
end $$;


ALTER FUNCTION public.rcap_service_stage_synthetic_launch(p_slug text, p_actor uuid, p_operation uuid, p_version bigint, p_hash text, p_versions jsonb) OWNER TO postgres;

--
-- Name: rcap_service_submit_onboarding(text, uuid, text, uuid, bigint, uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_service_submit_onboarding(p_partner_slug text, p_actor_user_id uuid, p_actor_work_email text, p_workspace_id uuid, p_expected_workspace_version bigint, p_request_id uuid, p_payload_hash text, p_schema_version text, p_authorization jsonb) RETURNS TABLE(workspace_aggregate_version bigint, submitted_at timestamp with time zone, duplicate boolean)
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
declare
  v_workspace public.partner_onboarding%rowtype;
  v_existing public.partner_onboarding_idempotency%rowtype;
  v_partner_record_id uuid;
begin
  perform public.rcap_service_assert_partner_actor(
    p_partner_slug, p_actor_user_id, p_workspace_id
  );
  if p_authorization is null
     or jsonb_typeof(p_authorization) <> 'object'
     or nullif(lower(btrim(p_actor_work_email)), '') is null
     or char_length(p_actor_work_email) > 254
     or p_payload_hash !~ '^[0-9a-f]{64}$'
     or nullif(btrim(p_schema_version), '') is null then
    raise exception using errcode = '22023', message = 'Invalid onboarding submission';
  end if;

  select *
    into v_existing
  from public.partner_onboarding_idempotency i
  where i.request_id = p_request_id
  for update;
  if found then
    if v_existing.workspace_id <> p_workspace_id
       or v_existing.operation_key <> 'submit'
       or v_existing.actor_user_id <> p_actor_user_id
       or v_existing.payload_hash <> p_payload_hash then
      raise exception using errcode = '23505', message = 'Idempotency request mismatch';
    end if;
    if v_existing.result_status = 'succeeded' then
      return query
      select
        v_existing.result_workspace_version,
        po.submitted_at,
        true
      from public.partner_onboarding po
      where po.id = p_workspace_id;
      return;
    end if;
    raise exception using errcode = '55000', message = 'Idempotent request is still in progress';
  end if;

  select po.*
    into v_workspace
  from public.partner_onboarding po
  where po.id = p_workspace_id
    and po.partner_slug = p_partner_slug
  for update of po;

  if not found then
    raise exception using errcode = 'P0002', message = 'Onboarding workspace not found';
  end if;
  select coalesce(v_workspace.partner_record_id, pr.id)
    into v_partner_record_id
  from public.partner_records pr
  where pr.partner_slug = p_partner_slug;
  if v_workspace.aggregate_version <> p_expected_workspace_version then
    raise exception using errcode = '40001', message = 'Onboarding workspace revision conflict';
  end if;
  if v_workspace.commercial_gate_status = 'blocked' then
    raise exception using errcode = '55000', message = 'Commercial gate is blocked';
  end if;
  if v_workspace.status <> 'setup_in_progress' then
    raise exception using errcode = '55000', message = 'Workspace is not ready for partner submission';
  end if;
  if (
    select count(*)
    from public.partner_onboarding_sections s
    where s.workspace_id = p_workspace_id
      and (
        s.status in ('submitted', 'approved', 'waived', 'not_applicable')
        and (
          s.completion_percentage = 100
          or s.status in ('waived', 'not_applicable')
        )
      )
  ) <> 8 then
    raise exception using errcode = '55000', message = 'Active partner requirements are incomplete';
  end if;
  if exists (
    select 1
    from public.partner_onboarding_change_requests cr
    where cr.workspace_id = p_workspace_id
      and cr.status in ('open', 'partner_responded')
  ) then
    raise exception using errcode = '55000', message = 'Requested changes remain unresolved';
  end if;
  if not exists (
    select 1
    from public.partner_onboarding_assets a
    where a.workspace_id = p_workspace_id
      and a.category = 'transparent_logo'
      and a.deleted_at is null
      and a.lifecycle_status in ('pending_review', 'active')
  ) then
    raise exception using errcode = '55000', message = 'Required organizational asset is missing';
  end if;

  insert into public.partner_onboarding_idempotency (
    workspace_id,
    operation_key,
    request_id,
    actor_user_id,
    payload_hash,
    expires_at
  ) values (
    p_workspace_id,
    'submit',
    p_request_id,
    p_actor_user_id,
    p_payload_hash,
    now() + interval '24 hours'
  );

  insert into public.partner_onboarding_authorizations (
    workspace_id,
    organization_information_accurate,
    program_scope_approved_for_configuration,
    brand_assets_authorized_for_use,
    no_eligibility_or_outcome_guarantee_understood,
    contested_and_representation_matters_follow_escalation_plan,
    dashboard_users_authorized,
    legalease_may_prepare_draft_implementation_materials,
    approver_name,
    approver_title,
    approver_user_id,
    approver_work_email,
    authorization_timestamp,
    terms_or_schema_version,
    request_id
  ) values (
    p_workspace_id,
    coalesce((p_authorization->>'organization_information_accurate')::boolean, false),
    coalesce((p_authorization->>'program_scope_approved_for_configuration')::boolean, false),
    coalesce((p_authorization->>'brand_assets_authorized_for_use')::boolean, false),
    coalesce((p_authorization->>'no_eligibility_or_outcome_guarantee_understood')::boolean, false),
    coalesce((p_authorization->>'contested_and_representation_matters_follow_escalation_plan')::boolean, false),
    coalesce((p_authorization->>'dashboard_users_authorized')::boolean, false),
    coalesce((p_authorization->>'legalease_may_prepare_draft_implementation_materials')::boolean, false),
    p_authorization->>'approver_name',
    p_authorization->>'approver_title',
    p_actor_user_id,
    lower(btrim(p_actor_work_email)),
    now(),
    p_schema_version,
    p_request_id
  );

  update public.partner_onboarding
  set
    status = 'ready_for_review',
    aggregate_version = aggregate_version + 1,
    blocker_code = null,
    next_action_code = 'await_legalease_review',
    next_action_owner = 'legalease',
    submitted_at = now(),
    submitted_by = p_actor_user_id,
    submission_request_id = p_request_id,
    submitted_schema_version = p_schema_version,
    last_meaningful_activity_at = now()
  where id = p_workspace_id
  returning aggregate_version, partner_onboarding.submitted_at
    into workspace_aggregate_version, submitted_at;

  insert into public.partner_onboarding_activity (
    workspace_id,
    event_type,
    status_code,
    summary_code,
    owner_type,
    actor_user_id,
    request_id,
    dedupe_key
  ) values (
    p_workspace_id,
    'onboarding_submitted',
    'ready_for_review',
    'onboarding_submitted',
    'partner',
    p_actor_user_id,
    p_request_id,
    p_request_id::text || ':submitted'
  )
  on conflict do nothing;

  insert into public.partner_onboarding_integration_events (
    workspace_id,
    partner_record_id,
    event_type,
    workspace_aggregate_version,
    workspace_status,
    completion_percentage,
    blocker_code,
    next_action_code,
    next_action_owner,
    target_launch_date,
    idempotency_key
  )
  select
    po.id,
    v_partner_record_id,
    'rcap_onboarding_submitted',
    po.aggregate_version,
    po.status,
    po.completion_percentage,
    po.blocker_code,
    po.next_action_code,
    po.next_action_owner,
    po.target_launch_date,
    p_request_id::text || ':submitted'
  from public.partner_onboarding po
  where po.id = p_workspace_id
  on conflict do nothing;

  update public.partner_onboarding_idempotency
  set
    result_status = 'succeeded',
    result_workspace_version = workspace_aggregate_version,
    completed_at = now()
  where request_id = p_request_id;

  duplicate := false;
  return next;
end;
$_$;


ALTER FUNCTION public.rcap_service_submit_onboarding(p_partner_slug text, p_actor_user_id uuid, p_actor_work_email text, p_workspace_id uuid, p_expected_workspace_version bigint, p_request_id uuid, p_payload_hash text, p_schema_version text, p_authorization jsonb) OWNER TO postgres;

--
-- Name: rcap_service_supersede_onboarding_artifact_version(text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_service_supersede_onboarding_artifact_version(p_partner_slug text, p_actor_user_id uuid, p_artifact_version_id uuid) RETURNS TABLE(superseded boolean)
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_updated public.partner_onboarding_artifact_versions%rowtype;
  v_artifact_type text;
begin
  update public.partner_onboarding_artifact_versions v
  set approval_status = 'superseded',
      superseded_at = now()
  from public.partner_onboarding po
  where v.id = p_artifact_version_id
    and po.id = v.workspace_id
    and po.partner_slug = p_partner_slug
    and v.superseded_at is null
    and v.generation_status = 'succeeded'
  returning v.* into v_updated;

  if v_updated.id is null then
    superseded := false;
    return next;
    return;
  end if;

  select a.artifact_type into v_artifact_type
  from public.partner_onboarding_artifacts a
  where a.id = v_updated.artifact_id;

  update public.partner_onboarding_artifacts
  set lifecycle_status = 'superseded'
  where id = v_updated.artifact_id
    and current_version_id = v_updated.id;

  insert into public.partner_onboarding_activity (
    workspace_id, event_type, owner_type, summary_code, status_code,
    artifact_version_id
  )
  values (
    v_updated.workspace_id, 'artifact_superseded', 'legalease',
    v_artifact_type, 'superseded', v_updated.id
  )
  on conflict do nothing;

  superseded := true;
  return next;
end;
$$;


ALTER FUNCTION public.rcap_service_supersede_onboarding_artifact_version(p_partner_slug text, p_actor_user_id uuid, p_artifact_version_id uuid) OWNER TO postgres;

--
-- Name: rcap_studio_actor_can(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_studio_actor_can(p_actor uuid, p_slug text, p_capability text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
select exists(select 1 from public.partner_users where auth_user_id=p_actor and role='internal_admin' and partner_slug is null and status='active') or
(p_capability in ('prepare','review_operational_material') and exists(select 1 from public.rcap_partner_operator_assignments where auth_user_id=p_actor and partner_slug=p_slug and revoked_at is null and (expires_at is null or expires_at>now()) and p_capability=any(capabilities)))
$$;


ALTER FUNCTION public.rcap_studio_actor_can(p_actor uuid, p_slug text, p_capability text) OWNER TO postgres;

--
-- Name: rcap_studio_assert_prepare(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_studio_assert_prepare(p_actor uuid, p_slug text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$ begin
 if not public.rcap_studio_actor_can(p_actor,p_slug,'prepare') then raise exception 'assigned preparation authority required' using errcode='42501'; end if;
end $$;


ALTER FUNCTION public.rcap_studio_assert_prepare(p_actor uuid, p_slug text) OWNER TO postgres;

--
-- Name: rcap_validate_signed_agreement_reference(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rcap_validate_signed_agreement_reference() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.signed_receipt_id is not null and not exists (
    select 1 from public.rcap_signed_agreement_receipts r
    join public.partner_onboarding_assets d on d.id=r.asset_id
      and d.workspace_id=r.workspace_id and d.sha256_hex=r.asset_sha256
      and d.lifecycle_status='active' and d.review_status='approved' and d.deleted_at is null
    where r.id=new.signed_receipt_id and r.workspace_id=new.workspace_id
      and r.agreement_type=new.agreement_type and r.asset_id=new.finalized_asset_id
      and r.effective_date=new.effective_date and r.asset_sha256=new.signed_asset_sha256
      and new.status='executed'
  ) then new.signed_receipt_id:=null; new.signed_asset_sha256:=null; end if;
  return new;
end $$;


ALTER FUNCTION public.rcap_validate_signed_agreement_reference() OWNER TO postgres;

--
-- Name: recompute_rcap_partner_entitlements(text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.recompute_rcap_partner_entitlements(p_partner_slug text DEFAULT NULL::text, p_now timestamp with time zone DEFAULT now()) RETURNS TABLE(partner_slug text, screenings_used integer, screenings_allowed integer, ledger_count integer, period_label text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with ledger as (
    select
      pe.partner_slug,
      count(ss.session_id)::integer as ledger_count
    from public.partner_entitlement pe
    left join public.screening_sessions ss
      on ss.partner_slug = pe.partner_slug
     and ss.flow_mode = 'rcap'
     and ss.claimed_slot_state = 'consumed'
    where p_partner_slug is null
       or pe.partner_slug = p_partner_slug
    group by pe.partner_slug
  ),
  updated_entitlements as (
    update public.partner_entitlement pe
    set screenings_used = l.ledger_count,
        updated_at = now()
    from ledger l
    where pe.partner_slug = l.partner_slug
    returning pe.partner_slug, pe.screenings_used, pe.screenings_allowed, l.ledger_count, pe.period_label
  )
  select ue.partner_slug, ue.screenings_used, ue.screenings_allowed, ue.ledger_count, ue.period_label
  from updated_entitlements ue
  order by ue.partner_slug;
$$;


ALTER FUNCTION public.recompute_rcap_partner_entitlements(p_partner_slug text, p_now timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION recompute_rcap_partner_entitlements(p_partner_slug text, p_now timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.recompute_rcap_partner_entitlements(p_partner_slug text, p_now timestamp with time zone) IS 'Rebuilds partner_entitlement.screenings_used from consumed partner packet-generation sessions only.';


--
-- Name: record_consumer_packet_payment(uuid, text, integer, text, text, text, text, text, text, text, text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_consumer_packet_payment(p_briefcase_item_id uuid, p_payment_status text, p_amount_cents integer, p_currency text, p_payment_provider text, p_provider_event_id text, p_checkout_session_id text, p_payment_intent_id text, p_receipt_url text, p_authority text, p_recorded_by text, p_product_id text, p_person_id uuid, p_matter_id uuid) RETURNS TABLE(outcome text, briefcase_item_id uuid, provider_event_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  -- No caller may record a payment without saying what the regular price and
  -- the discount were. Silence here would mean a discounted order recorded at
  -- full price.
  return query select 'invalid_payment_evidence'::text, p_briefcase_item_id, null::text;
end;
$$;


