ALTER FUNCTION public.record_consumer_packet_payment(p_briefcase_item_id uuid, p_payment_status text, p_amount_cents integer, p_currency text, p_payment_provider text, p_provider_event_id text, p_checkout_session_id text, p_payment_intent_id text, p_receipt_url text, p_authority text, p_recorded_by text, p_product_id text, p_person_id uuid, p_matter_id uuid, p_expected_verification_hash text) OWNER TO postgres;

--
-- Name: record_consumer_packet_payment(uuid, text, integer, integer, integer, text, text, text, text, text, text, text, text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_consumer_packet_payment(p_briefcase_item_id uuid, p_payment_status text, p_amount_cents integer, p_regular_price_cents integer, p_discount_cents integer, p_currency text, p_payment_provider text, p_provider_event_id text, p_checkout_session_id text, p_payment_intent_id text, p_receipt_url text, p_authority text, p_recorded_by text, p_product_id text, p_person_id uuid, p_matter_id uuid) RETURNS TABLE(outcome text, briefcase_item_id uuid, provider_event_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_found boolean;
  v_owner uuid;
  v_status text;
  v_existing_event text;
  v_existing_session text;
  v_existing_product text;
  v_existing_person uuid;
  v_existing_matter uuid;
  v_existing_amount integer;
  v_existing_currency text;
  v_payment_allowed boolean;
  v_source_session_id text;
  v_item_type text;
  v_jurisdiction text;
  v_pathway_label text;
  v_result_code text;
  v_packet_type text;
  v_item_status text;
  v_sponsored boolean := false;
  v_expected_match_key text;
  v_amount_due integer;
begin
  if to_regclass('public.consumer_briefcase_items') is null then
    return query select 'no_payment_storage'::text, p_briefcase_item_id, null::text;
    return;
  end if;
  if p_briefcase_item_id is null then
    return query select 'invalid_item'::text, null::uuid, null::text;
    return;
  end if;
  if coalesce(p_authority, '') not in ('server_webhook', 'server_admin') then
    return query select 'invalid_authority'::text, p_briefcase_item_id, null::text;
    return;
  end if;

  execute
    'select true, b.user_id, b.payment_status, b.provider_event_id,
            b.checkout_session_id, b.payment_product_id, b.payment_person_id,
            b.payment_matter_id, b.amount_cents, b.currency,
            b.payment_allowed, b.source_session_id, b.item_type,
            b.jurisdiction, b.pathway_label, b.result_code,
            b.packet_type, b.status
       from public.consumer_briefcase_items b
      where b.id = $1 for update'
  into v_found, v_owner, v_status, v_existing_event, v_existing_session,
       v_existing_product, v_existing_person, v_existing_matter,
       v_existing_amount, v_existing_currency, v_payment_allowed,
       v_source_session_id, v_item_type, v_jurisdiction,
       v_pathway_label, v_result_code, v_packet_type, v_item_status
  using p_briefcase_item_id;

  if not coalesce(v_found, false) then
    return query select 'item_not_found'::text, p_briefcase_item_id, null::text;
    return;
  end if;

  if p_payment_status = 'paid' then
    if v_payment_allowed is not true then
      return query select 'payment_not_allowed'::text, p_briefcase_item_id, null::text;
      return;
    end if;

    if v_item_type not in ('result', 'packet')
       or nullif(trim(coalesce(v_jurisdiction, '')), '') is null
       or nullif(trim(coalesce(v_pathway_label, '')), '') is null
       or v_result_code not in ('packet_ready', 'packet_ready_with_caution')
       or v_packet_type not in ('official_pdf_overlay', 'custom_pleading', 'legacy_packet')
       or v_item_status is distinct from 'packet_ready' then
      return query select 'invalid_item'::text, p_briefcase_item_id, null::text;
      return;
    end if;

    if to_regclass('public.screening_sessions') is not null
       and exists (
         select 1
           from information_schema.columns c
          where c.table_schema = 'public'
            and c.table_name = 'screening_sessions'
            and c.column_name in ('session_id', 'flow_mode', 'partner_slug', 'partner_benefit_active')
          group by c.table_schema, c.table_name
         having count(*) = 4
       ) then
      execute
        'select exists (
           select 1 from public.screening_sessions s
            where s.session_id::text = nullif(trim($1), '''')
              and s.flow_mode = ''rcap''
              and nullif(trim(coalesce(s.partner_slug, '''')), '''') is not null
              and s.partner_benefit_active is true
         )'
      into v_sponsored
      using v_source_session_id;
    end if;

    if (coalesce(v_sponsored, false) or exists (
      select 1 from public.consumer_briefcase_items i
      join public.consumer_pending_screening_results s on s.pending_id=i.source_pending_result_id
      where i.id=p_briefcase_item_id and s.product='rcap_partner'
    )) and not public.clinic_packet_dtc_authorized(p_briefcase_item_id,v_owner) then
      return query select 'sponsored_item'::text, p_briefcase_item_id, null::text;
      return;
    end if;

    -- The reconciliation, in the database, where it holds even if the
    -- application is wrong. This is what replaces `p_amount_cents <> 5000`.
    v_amount_due := coalesce(p_regular_price_cents, -1) - coalesce(p_discount_cents, -1);
    if p_regular_price_cents is distinct from 5000
       or p_discount_cents is null
       or p_discount_cents < 0
       or p_discount_cents > p_regular_price_cents
       or p_amount_cents is distinct from v_amount_due
       or lower(coalesce(p_currency, '')) <> 'usd'
       or nullif(trim(coalesce(p_provider_event_id, '')), '') is null
       or nullif(trim(coalesce(p_checkout_session_id, '')), '') is null
       or p_product_id is distinct from 'expungement_packet'
       or p_person_id is null
       or p_matter_id is distinct from public.consumer_matter_id_for_briefcase_item(p_briefcase_item_id) then
      return query select 'invalid_payment_evidence'::text, p_briefcase_item_id, null::text;
      return;
    end if;

    -- Stripe creates no PaymentIntent for a zero-total order and always creates
    -- one when money is due. A row that disagrees with its own total is not a
    -- description of any order Stripe produced.
    if (v_amount_due > 0) <> (nullif(trim(coalesce(p_payment_intent_id, '')), '') is not null) then
      return query select 'invalid_payment_evidence'::text, p_briefcase_item_id, null::text;
      return;
    end if;

    v_expected_match_key := 'consumer:' || encode(
      extensions.digest(convert_to('rcap:consumer-person:v1:' || v_owner::text, 'utf8'), 'sha256'),
      'hex'
    );
    if not exists (
      select 1 from public.rcap_persons p
       where p.id = p_person_id
         and p.partner_slug = 'expungement-ai-consumer'
         and p.match_key = v_expected_match_key
    ) then
      return query select 'invalid_payment_identity'::text, p_briefcase_item_id, null::text;
      return;
    end if;

    if v_existing_session is distinct from p_checkout_session_id
       or v_existing_product is distinct from p_product_id
       or v_existing_person is distinct from p_person_id
       or v_existing_matter is distinct from p_matter_id then
      return query select 'checkout_binding_mismatch'::text, p_briefcase_item_id, null::text;
      return;
    end if;

    -- A second signed event for the same already-settled Session is an
    -- idempotent success. The stored amount is compared against what this event
    -- reconciles to rather than against 5000, so a replayed no-cost order
    -- converges instead of reading as a conflict.
    if v_status = 'paid' then
      if v_existing_amount is not distinct from p_amount_cents
         and lower(coalesce(v_existing_currency, '')) = 'usd'
         and nullif(trim(coalesce(v_existing_event, '')), '') is not null then
        return query select 'already_paid'::text, p_briefcase_item_id, v_existing_event;
        return;
      end if;
      return query select 'payment_conflict'::text, p_briefcase_item_id, v_existing_event;
      return;
    end if;

    begin
      execute
        'update public.consumer_briefcase_items
            set payment_status = ''paid'', amount_cents = $11,
                regular_price_cents = $12, discount_cents = $13, currency = ''usd'',
                payment_provider = coalesce($2, payment_provider),
                payment_intent_id = coalesce($3, payment_intent_id),
                receipt_url = coalesce($4, receipt_url), provider_event_id = $5,
                payment_authority = $6, payment_recorded_at = now(),
                payment_recorded_by = $7, payment_product_id = $8,
                payment_person_id = $9, payment_matter_id = $10
          where id = $1'
      using p_briefcase_item_id, p_payment_provider, p_payment_intent_id,
            p_receipt_url, trim(p_provider_event_id), p_authority, p_recorded_by,
            p_product_id, p_person_id, p_matter_id,
            p_amount_cents, p_regular_price_cents, p_discount_cents;
    exception when unique_violation then
      return query select 'duplicate_provider_event'::text, p_briefcase_item_id, trim(p_provider_event_id);
      return;
    end;

    return query select 'recorded_paid'::text, p_briefcase_item_id, trim(p_provider_event_id);
    return;
  end if;

  if p_payment_status not in ('not_applicable', 'unpaid', 'refunded') then
    return query select 'invalid_status'::text, p_briefcase_item_id, null::text;
    return;
  end if;

  execute
    'update public.consumer_briefcase_items
        set payment_status = $2, payment_authority = $3,
            payment_recorded_at = now(), payment_recorded_by = $4
      where id = $1'
  using p_briefcase_item_id, p_payment_status, p_authority, p_recorded_by;

  return query select ('recorded_' || p_payment_status)::text, p_briefcase_item_id, v_existing_event;
end;
$_$;


ALTER FUNCTION public.record_consumer_packet_payment(p_briefcase_item_id uuid, p_payment_status text, p_amount_cents integer, p_regular_price_cents integer, p_discount_cents integer, p_currency text, p_payment_provider text, p_provider_event_id text, p_checkout_session_id text, p_payment_intent_id text, p_receipt_url text, p_authority text, p_recorded_by text, p_product_id text, p_person_id uuid, p_matter_id uuid) OWNER TO postgres;

--
-- Name: record_consumer_packet_payment(uuid, text, integer, integer, integer, text, text, text, text, text, text, text, text, text, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_consumer_packet_payment(p_briefcase_item_id uuid, p_payment_status text, p_amount_cents integer, p_regular_price_cents integer, p_discount_cents integer, p_currency text, p_payment_provider text, p_provider_event_id text, p_checkout_session_id text, p_payment_intent_id text, p_receipt_url text, p_authority text, p_recorded_by text, p_product_id text, p_person_id uuid, p_matter_id uuid, p_expected_verification_hash text) RETURNS TABLE(outcome text, briefcase_item_id uuid, provider_event_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_hash text;
  v_result record;
begin
  select v.verification_hash into v_hash from public.consumer_packet_verifications v
   where v.briefcase_item_id = p_briefcase_item_id and v.status = 'verified' for update;
  if v_hash is null or v_hash is distinct from p_expected_verification_hash then
    return query select 'invalid_payment_evidence'::text, p_briefcase_item_id, null::text; return;
  end if;
  select * into v_result from public.record_consumer_packet_payment(
    p_briefcase_item_id, p_payment_status, p_amount_cents,
    p_regular_price_cents, p_discount_cents, p_currency,
    p_payment_provider, p_provider_event_id, p_checkout_session_id,
    p_payment_intent_id, p_receipt_url, p_authority, p_recorded_by,
    p_product_id, p_person_id, p_matter_id
  );
  return query select v_result.outcome::text, v_result.briefcase_item_id::uuid,
    v_result.provider_event_id::text;
end;
$$;


ALTER FUNCTION public.record_consumer_packet_payment(p_briefcase_item_id uuid, p_payment_status text, p_amount_cents integer, p_regular_price_cents integer, p_discount_cents integer, p_currency text, p_payment_provider text, p_provider_event_id text, p_checkout_session_id text, p_payment_intent_id text, p_receipt_url text, p_authority text, p_recorded_by text, p_product_id text, p_person_id uuid, p_matter_id uuid, p_expected_verification_hash text) OWNER TO postgres;

--
-- Name: record_packet_delivery_event(uuid, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_packet_delivery_event(p_job_id uuid, p_event_type text, p_actor_user_id uuid, p_request_context jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_job public.packet_render_jobs%rowtype;
  v_event_id uuid;
begin
  if p_event_type not in ('delivery_authorized', 'transmission_started', 'transmission_completed', 'transmission_aborted', 'transmission_failed') then
    raise exception 'packet_delivery_events: unknown event type %', p_event_type;
  end if;

  select * into v_job from public.packet_render_jobs where id = p_job_id for update;
  if not found then
    raise exception 'packet_delivery_events: unknown render job';
  end if;

  -- No event of any kind is recorded against a packet that accounting has not
  -- authorized. artifact_validated by itself is never sufficient.
  if v_job.delivery_eligibility <> 'eligible'
     or v_job.status not in ('artifact_validated', 'delivered') then
    raise exception 'packet_delivery_events: job is not delivery-eligible';
  end if;

  perform set_config('rcap.packet_mutation_authority', 'record_packet_delivery_event', true);
  insert into public.packet_delivery_events (render_job_id, event_type, actor_user_id, request_context)
  values (p_job_id, p_event_type, p_actor_user_id, coalesce(p_request_context, '{}'::jsonb))
  returning id into v_event_id;

  if p_event_type = 'transmission_completed' and v_job.status = 'artifact_validated' then
    update public.packet_render_jobs
    set status = 'delivered'
    where id = p_job_id;
  end if;
  perform set_config('rcap.packet_mutation_authority', '', true);

  return v_event_id;
end;
$$;


ALTER FUNCTION public.record_packet_delivery_event(p_job_id uuid, p_event_type text, p_actor_user_id uuid, p_request_context jsonb) OWNER TO postgres;

--
-- Name: record_partner_packet_generation(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_partner_packet_generation(p_session_id uuid, p_now timestamp with time zone DEFAULT now()) RETURNS TABLE(recorded boolean, counted_as text, reason text, partner_slug text, screenings_used integer, screenings_allowed integer, overage_packets integer, overage_amount_cents integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_session public.screening_sessions%rowtype;
  v_ent public.partner_entitlement%rowtype;
  v_counted text;
  v_price integer;
begin
  select * into v_session
  from public.screening_sessions ss
  where ss.session_id = p_session_id
  limit 1;

  if not found
     or v_session.flow_mode <> 'rcap'
     or v_session.partner_slug is null
     or v_session.partner_benefit_active is not true then
    return query select false, 'not_counted'::text, 'not_partner_benefit'::text,
                        v_session.partner_slug, null::integer, null::integer, null::integer, null::integer;
    return;
  end if;

  perform 1 from public.partner_onboarding locked_workspace where locked_workspace.partner_slug=v_session.partner_slug for update;
  if v_session.jurisdiction<>all(public.rcap_program_screening_jurisdictions(v_session.partner_slug))
    or exists(select 1 from public.partner_onboarding w where w.partner_slug=v_session.partner_slug and w.rcap_policy_version='rcap2.2'
      and not public.rcap_program_packet_scope_authorized(v_session.partner_slug,v_session.jurisdiction)) then
    return query select false,'not_counted'::text,'packet_authority_required'::text,v_session.partner_slug,null::integer,null::integer,null::integer,null::integer;return;
  end if;
  if v_session.claimed_slot_state is distinct from 'claimed' then
    return query select false, 'not_counted'::text, 'already_recorded'::text,
                        v_session.partner_slug, null::integer, null::integer, null::integer, null::integer;
    return;
  end if;

  select * into v_ent
  from public.partner_entitlement pe
  where pe.partner_slug = v_session.partner_slug
  for update;

  if not found then
    return query select false, 'not_counted'::text, 'no_entitlement'::text,
                        v_session.partner_slug, null::integer, null::integer, null::integer, null::integer;
    return;
  end if;

  if v_ent.screenings_used < v_ent.screenings_allowed then
    update public.partner_entitlement pe
    set screenings_used = pe.screenings_used + 1, updated_at = now()
    where pe.partner_slug = v_ent.partner_slug
    returning pe.screenings_used, pe.screenings_allowed, pe.overage_packets, pe.overage_amount_cents
    into v_ent.screenings_used, v_ent.screenings_allowed, v_ent.overage_packets, v_ent.overage_amount_cents;
    v_counted := 'included';
  elsif v_ent.pause_at_cap then
    insert into public.rcap_record_events (record_type, record_id, partner_slug, event_type, occurred_at, actor, metadata)
    values ('partner_entitlement', v_ent.partner_slug, v_ent.partner_slug, 'partner_packet_cap_reached', p_now, 'system',
            jsonb_build_object('session_id', p_session_id, 'paused', true));
    return query select false, 'capped'::text, 'paused_at_cap'::text,
                        v_ent.partner_slug, v_ent.screenings_used, v_ent.screenings_allowed,
                        v_ent.overage_packets, v_ent.overage_amount_cents;
    return;
  elsif v_ent.overage_enabled then
    v_price := v_ent.overage_packet_price_cents;
    update public.partner_entitlement pe
    set overage_packets = pe.overage_packets + 1,
        overage_amount_cents = pe.overage_amount_cents + v_price,
        updated_at = now()
    where pe.partner_slug = v_ent.partner_slug
    returning pe.screenings_used, pe.screenings_allowed, pe.overage_packets, pe.overage_amount_cents
    into v_ent.screenings_used, v_ent.screenings_allowed, v_ent.overage_packets, v_ent.overage_amount_cents;
    v_counted := 'overage';
  else
    update public.screening_sessions ss
    set claimed_slot_state = 'consumed', status = 'completed', updated_at = now()
    where ss.session_id = p_session_id;
    insert into public.rcap_record_events (record_type, record_id, partner_slug, event_type, occurred_at, actor, metadata)
    values ('partner_entitlement', v_ent.partner_slug, v_ent.partner_slug, 'partner_packet_cap_reached', p_now, 'system',
            jsonb_build_object('session_id', p_session_id, 'paused', false, 'overage_enabled', false));
    return query select false, 'not_counted'::text, 'cap_reached_no_overage'::text,
                        v_ent.partner_slug, v_ent.screenings_used, v_ent.screenings_allowed,
                        v_ent.overage_packets, v_ent.overage_amount_cents;
    return;
  end if;

  update public.screening_sessions ss
  set claimed_slot_state = 'consumed', status = 'completed', updated_at = now()
  where ss.session_id = p_session_id;

  insert into public.rcap_record_events (record_type, record_id, partner_slug, event_type, occurred_at, actor, metadata)
  values ('partner_entitlement', v_ent.partner_slug, v_ent.partner_slug,
          case when v_counted = 'overage' then 'partner_packet_overage_recorded' else 'partner_packet_credit_consumed' end,
          p_now, 'system', jsonb_build_object('session_id', p_session_id, 'counted_as', v_counted));

  -- Analytics: one packet_generated per successful credit (included or overage),
  -- plus packet_overage_recorded for overage. Fires once (slot just consumed).
  insert into public.rcap_screening_analytics_events
    (session_id, partner_slug, partner_access_code_id, campaign_name, event_type, packet_route_available, occurred_at, metadata)
  values
    (v_session.session_id, v_session.partner_slug, v_session.partner_access_code_id, v_session.campaign_name,
     'packet_generated', true, p_now, jsonb_build_object('counted_as', v_counted));

  if v_counted = 'overage' then
    insert into public.rcap_screening_analytics_events
      (session_id, partner_slug, partner_access_code_id, campaign_name, event_type, occurred_at, metadata)
    values
      (v_session.session_id, v_session.partner_slug, v_session.partner_access_code_id, v_session.campaign_name,
       'packet_overage_recorded', p_now, jsonb_build_object('overage_packet_price_cents', v_price));
  end if;

  return query select true, v_counted, null::text,
                      v_ent.partner_slug, v_ent.screenings_used, v_ent.screenings_allowed,
                      v_ent.overage_packets, v_ent.overage_amount_cents;
end;
$$;


ALTER FUNCTION public.record_partner_packet_generation(p_session_id uuid, p_now timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION record_partner_packet_generation(p_session_id uuid, p_now timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.record_partner_packet_generation(p_session_id uuid, p_now timestamp with time zone) IS 'Consumes exactly one partner packet credit (included or overage) per successful partner-benefit packet, idempotently, and emits packet_generated / packet_overage_recorded analytics. Respects pause_at_cap and overage_enabled.';


--
-- Name: record_rcap_partner_packet_generation(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_rcap_partner_packet_generation(p_session_id uuid) RETURNS TABLE(recorded boolean, partner_slug text, claimed_slot_state text, status text, screenings_used integer, screenings_allowed integer)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with counted_session as (
    update public.screening_sessions ss
    set claimed_slot_state = 'consumed',
        status = 'completed',
        updated_at = now()
    where ss.session_id = p_session_id
      and ss.flow_mode = 'rcap'
      and ss.partner_slug is not null
      and ss.claimed_slot_state = 'claimed'
      and exists (
        select 1
        from public.partner_entitlement pe
        where pe.partner_slug = ss.partner_slug
          and pe.screenings_used < pe.screenings_allowed
      )
    returning ss.partner_slug, ss.claimed_slot_state, ss.status
  ),
  incremented_entitlement as (
    update public.partner_entitlement pe
    set screenings_used = pe.screenings_used + 1,
        updated_at = now()
    from counted_session cs
    where pe.partner_slug = cs.partner_slug
      and pe.screenings_used < pe.screenings_allowed
    returning pe.partner_slug, pe.screenings_used, pe.screenings_allowed
  )
  select
    true,
    cs.partner_slug,
    cs.claimed_slot_state,
    cs.status,
    ie.screenings_used,
    ie.screenings_allowed
  from counted_session cs
  join incremented_entitlement ie on ie.partner_slug = cs.partner_slug
  union all
  select
    false,
    ss.partner_slug,
    ss.claimed_slot_state,
    ss.status,
    pe.screenings_used,
    pe.screenings_allowed
  from public.screening_sessions ss
  left join public.partner_entitlement pe on pe.partner_slug = ss.partner_slug
  where ss.session_id = p_session_id
    and ss.flow_mode = 'rcap'
    and not exists (select 1 from counted_session)
  limit 1;
$$;


ALTER FUNCTION public.record_rcap_partner_packet_generation(p_session_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION record_rcap_partner_packet_generation(p_session_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.record_rcap_partner_packet_generation(p_session_id uuid) IS 'Consumes one partner packet-cap unit exactly once when a partner-covered packet is generated.';


--
-- Name: record_rcap_screening_analytics_event(uuid, text, text, boolean, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_rcap_screening_analytics_event(p_session_id uuid, p_event_type text, p_outcome_category text DEFAULT NULL::text, p_packet_route_available boolean DEFAULT NULL::boolean, p_now timestamp with time zone DEFAULT now()) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_session public.screening_sessions%rowtype;
begin
  if p_event_type not in ('screening_completed', 'eligibility_result_recorded', 'guidance_only_result', 'packet_ready_result') then
    raise exception 'unsupported analytics event type: %', p_event_type;
  end if;

  select * into v_session
  from public.screening_sessions ss
  where ss.session_id = p_session_id
  limit 1;

  -- Partner-benefit gate: DTC and un-attributed sessions produce no analytics.
  if not found
     or v_session.flow_mode <> 'rcap'
     or v_session.partner_slug is null
     or v_session.partner_benefit_active is not true then
    return false;
  end if;

  insert into public.rcap_screening_analytics_events
    (session_id, partner_slug, partner_access_code_id, campaign_name, event_type, outcome_category, packet_route_available, occurred_at)
  values
    (v_session.session_id, v_session.partner_slug, v_session.partner_access_code_id, v_session.campaign_name,
     p_event_type, p_outcome_category, p_packet_route_available, p_now);

  return true;
end;
$$;


ALTER FUNCTION public.record_rcap_screening_analytics_event(p_session_id uuid, p_event_type text, p_outcome_category text, p_packet_route_available boolean, p_now timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION record_rcap_screening_analytics_event(p_session_id uuid, p_event_type text, p_outcome_category text, p_packet_route_available boolean, p_now timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.record_rcap_screening_analytics_event(p_session_id uuid, p_event_type text, p_outcome_category text, p_packet_route_available boolean, p_now timestamp with time zone) IS 'Appends a partner screening analytics event for partner-benefit sessions only. No-op for DTC/un-attributed sessions.';


