--
-- Name: release_expired_packet_render_claims(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.release_expired_packet_render_claims() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_released integer := 0;
  v_count integer;
begin
  perform set_config('rcap.packet_mutation_authority', 'release_expired_packet_render_claims', true);

  -- A job stuck in claimed goes straight back to the queue.
  update public.packet_render_jobs j
  set status = 'queued',
      claim_expires_at = null,
      fencing_token = null
  where j.status = 'claimed'
    and j.claim_expires_at is not null
    and j.claim_expires_at < now();
  get diagnostics v_count = row_count;
  v_released := v_released + v_count;

  -- A job that died mid-render or mid-validation fails retryably (or
  -- terminally once attempts are exhausted) so its history stays visible.
  update public.packet_render_jobs j
  set status = 'failed',
      failure_disposition = case when j.attempt_count < j.max_attempts then 'retryable' else 'terminal' end,
      error_code = 'timeout',
      last_error_detail = 'claim lease expired before the worker finished',
      next_attempt_at = case
        when j.attempt_count < j.max_attempts
        then now() + make_interval(secs => least(3600, 30 * power(2, j.attempt_count))::integer)
        else null
      end,
      claim_expires_at = null,
      fencing_token = null
  where j.status in ('rendering', 'validating')
    and j.claim_expires_at is not null
    and j.claim_expires_at < now();
  get diagnostics v_count = row_count;
  v_released := v_released + v_count;

  perform set_config('rcap.packet_mutation_authority', '', true);
  return v_released;
end;
$$;


ALTER FUNCTION public.release_expired_packet_render_claims() OWNER TO postgres;

--
-- Name: release_expired_rcap_screening_slots(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.release_expired_rcap_screening_slots(p_now timestamp with time zone DEFAULT now()) RETURNS TABLE(partner_slug text, released_count integer, screenings_used integer, screenings_allowed integer, period_label text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with released_sessions as (
    update public.screening_sessions ss
    set claimed_slot_state = 'released',
        updated_at = now()
    where ss.flow_mode = 'rcap'
      and ss.partner_slug is not null
      and ss.claimed_slot_state = 'claimed'
      and public.rcap_screening_session_is_release_expired(
        ss.status,
        ss.created_at,
        ss.resume_token_expires_at,
        p_now
      )
    returning ss.partner_slug
  ),
  release_counts as (
    select rs.partner_slug, count(*)::integer as released_count
    from released_sessions rs
    group by rs.partner_slug
  )
  select pe.partner_slug, rc.released_count, pe.screenings_used, pe.screenings_allowed, pe.period_label
  from release_counts rc
  join public.partner_entitlement pe on pe.partner_slug = rc.partner_slug
  order by pe.partner_slug;
$$;


ALTER FUNCTION public.release_expired_rcap_screening_slots(p_now timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION release_expired_rcap_screening_slots(p_now timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.release_expired_rcap_screening_slots(p_now timestamp with time zone) IS 'Marks expired unfinished RCAP screening sessions released without decrementing packet-cap usage.';


--
-- Name: requeue_packet_render_job_manual(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.requeue_packet_render_job_manual(p_job_id uuid, p_authorized_by text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_job public.packet_render_jobs%rowtype;
begin
  if nullif(trim(p_authorized_by), '') is null then
    raise exception 'a manual requeue requires a named authorizer';
  end if;
  select * into v_job from public.packet_render_jobs where id = p_job_id for update;
  if not found then return false; end if;
  if v_job.status <> 'failed' then
    raise exception 'packet_render_jobs: only a failed job can be requeued manually';
  end if;

  perform set_config('rcap.packet_mutation_authority', 'requeue_packet_render_job_manual', true);
  update public.packet_render_jobs
  set status = 'queued',
      failure_disposition = null,
      next_attempt_at = null,
      manual_requeue_authorized_by = trim(p_authorized_by),
      max_attempts = greatest(max_attempts, attempt_count + 1)
  where id = p_job_id;
  perform set_config('rcap.packet_mutation_authority', '', true);
  return true;
end;
$$;


ALTER FUNCTION public.requeue_packet_render_job_manual(p_job_id uuid, p_authorized_by text) OWNER TO postgres;

--
-- Name: requeue_retryable_packet_render_jobs(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.requeue_retryable_packet_render_jobs() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_count integer;
begin
  perform set_config('rcap.packet_mutation_authority', 'requeue_retryable_packet_render_jobs', true);
  update public.packet_render_jobs j
  set status = 'queued',
      failure_disposition = null
  where j.status = 'failed'
    and j.failure_disposition = 'retryable'
    and j.attempt_count < j.max_attempts
    and (j.next_attempt_at is null or j.next_attempt_at <= now());
  get diagnostics v_count = row_count;
  perform set_config('rcap.packet_mutation_authority', '', true);
  return v_count;
end;
$$;


ALTER FUNCTION public.requeue_retryable_packet_render_jobs() OWNER TO postgres;

