--
-- Name: validate_partner_access_code(text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.validate_partner_access_code(p_partner_slug text, p_code_hash text, p_now timestamp with time zone DEFAULT now()) RETURNS TABLE(valid boolean, reason text, campaign_name text, code_id uuid, code_type text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_partner_slug text;
  v_code_hash text;
  v_code public.partner_access_codes%rowtype;
  v_effective_max integer;
begin
  v_partner_slug := nullif(trim(p_partner_slug), '');
  v_code_hash := nullif(trim(p_code_hash), '');

  if v_partner_slug is null or v_code_hash is null then
    return query select false, 'invalid'::text, null::text, null::uuid, null::text;
    return;
  end if;

  select * into v_code
  from public.partner_access_codes c
  where c.partner_slug = v_partner_slug
    and c.code_hash = v_code_hash
  limit 1;

  if not found then
    return query select false, 'invalid'::text, null::text, null::uuid, null::text;
    return;
  end if;

  if not v_code.is_active then
    return query select false, 'inactive'::text, null::text, v_code.id, v_code.code_type;
    return;
  end if;

  if v_code.starts_at is not null and p_now < v_code.starts_at then
    return query select false, 'inactive'::text, null::text, v_code.id, v_code.code_type;
    return;
  end if;

  if v_code.expires_at is not null and p_now >= v_code.expires_at then
    return query select false, 'expired'::text, null::text, v_code.id, v_code.code_type;
    return;
  end if;

  v_effective_max := case
    when v_code.code_type = 'single_use' then 1
    when v_code.code_type = 'limited_use' then v_code.max_uses
    else null
  end;

  if v_effective_max is not null and v_code.uses_count >= v_effective_max then
    return query select false, 'exhausted'::text, null::text, v_code.id, v_code.code_type;
    return;
  end if;

  return query select true, null::text, v_code.campaign_name, v_code.id, v_code.code_type;
end;
$$;


ALTER FUNCTION public.validate_partner_access_code(p_partner_slug text, p_code_hash text, p_now timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION validate_partner_access_code(p_partner_slug text, p_code_hash text, p_now timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.validate_partner_access_code(p_partner_slug text, p_code_hash text, p_now timestamp with time zone) IS 'Read-only code validation by hash. Never redeems, never mutates uses. Returns a minimal status for the server route to relay.';


--
-- Name: write_rcap_document_packet_relief_outcome_event(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.write_rcap_document_packet_relief_outcome_event() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if old.relief_outcome is distinct from new.relief_outcome then
    insert into rcap_record_events (
      record_type,
      record_id,
      partner_slug,
      partner_id,
      event_type,
      from_status,
      to_status,
      actor,
      metadata
    )
    values (
      'document_packet',
      new.id::text,
      new.partner_slug,
      null,
      'relief_outcome_changed',
      old.relief_outcome,
      new.relief_outcome,
      coalesce(nullif(current_setting('request.jwt.claim.sub', true), ''), 'system'),
      jsonb_build_object(
        'state', new.state,
        'county', new.county,
        'document_type', new.document_type,
        'pathway', new.pathway,
        'status', new.status,
        'has_briefcase_item', new.briefcase_id is not null,
        'source', 'rcap_document_packets_relief_outcome_trigger'
      )
    );
  end if;

  return new;
end;
$$;


ALTER FUNCTION public.write_rcap_document_packet_relief_outcome_event() OWNER TO postgres;

--
-- Name: allow_any_operation(text[]); Type: FUNCTION; Schema: storage; Owner: postgres
--

CREATE FUNCTION storage.allow_any_operation(expected_operations text[]) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  WITH current_operation AS (
    SELECT storage.operation() AS raw_operation
  ),
  normalized AS (
    SELECT CASE
      WHEN raw_operation LIKE 'storage.%' THEN substr(raw_operation, 9)
      ELSE raw_operation
    END AS current_operation
    FROM current_operation
  )
  SELECT EXISTS (
    SELECT 1
    FROM normalized n
    CROSS JOIN LATERAL unnest(expected_operations) AS expected_operation
    WHERE expected_operation IS NOT NULL
      AND expected_operation <> ''
      AND n.current_operation = CASE
        WHEN expected_operation LIKE 'storage.%' THEN substr(expected_operation, 9)
        ELSE expected_operation
      END
  );
$$;


ALTER FUNCTION storage.allow_any_operation(expected_operations text[]) OWNER TO postgres;

--
-- Name: allow_only_operation(text); Type: FUNCTION; Schema: storage; Owner: postgres
--

CREATE FUNCTION storage.allow_only_operation(expected_operation text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  WITH current_operation AS (
    SELECT storage.operation() AS raw_operation
  ),
  normalized AS (
    SELECT
      CASE
        WHEN raw_operation LIKE 'storage.%' THEN substr(raw_operation, 9)
        ELSE raw_operation
      END AS current_operation,
      CASE
        WHEN expected_operation LIKE 'storage.%' THEN substr(expected_operation, 9)
        ELSE expected_operation
      END AS requested_operation
    FROM current_operation
  )
  SELECT CASE
    WHEN requested_operation IS NULL OR requested_operation = '' THEN FALSE
    ELSE COALESCE(current_operation = requested_operation, FALSE)
  END
  FROM normalized;
$$;


ALTER FUNCTION storage.allow_only_operation(expected_operation text) OWNER TO postgres;

--
-- Name: can_insert_object(text, text, uuid, jsonb); Type: FUNCTION; Schema: storage; Owner: postgres
--

CREATE FUNCTION storage.can_insert_object(bucketid text, name text, owner uuid, metadata jsonb) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  INSERT INTO "storage"."objects" ("bucket_id", "name", "owner", "metadata") VALUES (bucketid, name, owner, metadata);
  -- hack to rollback the successful insert
  RAISE sqlstate 'PT200' using
  message = 'ROLLBACK',
  detail = 'rollback successful insert';
END
$$;


ALTER FUNCTION storage.can_insert_object(bucketid text, name text, owner uuid, metadata jsonb) OWNER TO postgres;

--
-- Name: enforce_bucket_lifecycle_service_role(); Type: FUNCTION; Schema: storage; Owner: postgres
--

CREATE FUNCTION storage.enforce_bucket_lifecycle_service_role() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF current_user::text IS DISTINCT FROM TG_ARGV[0]
     AND (
       OLD.lifecycle_configuration IS DISTINCT FROM NEW.lifecycle_configuration
       OR OLD.lifecycle_configuration_generation IS DISTINCT FROM NEW.lifecycle_configuration_generation
     ) THEN
    -- AFTER runs only after caller RLS has accepted the proposed row. The API
    -- recognizes this specific error after rolling back its permission probe;
    -- direct non-service writes still fail and cannot persist the change.
    RAISE EXCEPTION 'bucket control columns may only be changed by the configured storage service role'
      USING ERRCODE = 'PST01',
            SCHEMA = TG_TABLE_SCHEMA,
            TABLE = TG_TABLE_NAME,
            CONSTRAINT = TG_NAME;
  END IF;

  RETURN NULL;
END;
$$;


ALTER FUNCTION storage.enforce_bucket_lifecycle_service_role() OWNER TO postgres;

