-- Name: clinic_incidents; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.clinic_incidents (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    event_id uuid NOT NULL,
    severity text NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    category text NOT NULL,
    summary text NOT NULL,
    detail text,
    reported_by uuid NOT NULL,
    assigned_to uuid,
    resolved_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT clinic_incidents_category_check CHECK ((category = ANY (ARRAY['privacy'::text, 'safety'::text, 'access'::text, 'device'::text, 'network'::text, 'packet'::text, 'other'::text]))),
    CONSTRAINT clinic_incidents_check CHECK (((status = ANY (ARRAY['resolved'::text, 'closed'::text])) = (resolved_at IS NOT NULL))),
    CONSTRAINT clinic_incidents_severity_check CHECK ((severity = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text, 'critical'::text]))),
    CONSTRAINT clinic_incidents_status_check CHECK ((status = ANY (ARRAY['open'::text, 'investigating'::text, 'resolved'::text, 'closed'::text]))),
    CONSTRAINT clinic_incidents_summary_check CHECK (((length(TRIM(BOTH FROM summary)) >= 3) AND (length(TRIM(BOTH FROM summary)) <= 500)))
);


ALTER TABLE public.clinic_incidents OWNER TO postgres;

--
-- Name: clinic_packet_funding; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.clinic_packet_funding (
    briefcase_item_id uuid NOT NULL,
    consumer_auth_user_id uuid NOT NULL,
    source_session_id uuid NOT NULL,
    event_id uuid NOT NULL,
    partner_slug text NOT NULL,
    packet_entitlement_id uuid NOT NULL,
    route_key text NOT NULL,
    packet_family_id text NOT NULL,
    initial_verification_hash text NOT NULL,
    funding_mode text NOT NULL,
    reason text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT clinic_packet_funding_funding_mode_check CHECK ((funding_mode = ANY (ARRAY['sponsored'::text, 'dtc'::text]))),
    CONSTRAINT clinic_packet_funding_initial_verification_hash_check CHECK ((initial_verification_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT clinic_packet_funding_reason_check CHECK ((reason = ANY (ARRAY['slot_reserved'::text, 'event_cap_exhausted'::text, 'partner_cap_exhausted'::text])))
);


ALTER TABLE public.clinic_packet_funding OWNER TO postgres;

--
-- Name: TABLE clinic_packet_funding; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.clinic_packet_funding IS 'One immutable financial choice per owner-bound matter. A sponsored row reserves capacity, not delivered credit. DTC is a cap decision, never payment evidence. Source attribution stays unchanged.';


--
-- Name: clinic_packet_reservations; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.clinic_packet_reservations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    event_id uuid NOT NULL,
    clinic_case_id uuid NOT NULL,
    render_job_id uuid NOT NULL,
    participant_user_id uuid NOT NULL,
    status text DEFAULT 'reserved'::text NOT NULL,
    packet_credit_ledger_id uuid,
    reserved_at timestamp with time zone DEFAULT now() NOT NULL,
    consumed_at timestamp with time zone,
    released_at timestamp with time zone,
    release_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT clinic_packet_reservations_check CHECK (((status = 'consumed'::text) = (consumed_at IS NOT NULL))),
    CONSTRAINT clinic_packet_reservations_check1 CHECK (((status = 'released'::text) = (released_at IS NOT NULL))),
    CONSTRAINT clinic_packet_reservations_check2 CHECK (((status <> 'consumed'::text) OR (packet_credit_ledger_id IS NOT NULL))),
    CONSTRAINT clinic_packet_reservations_release_reason_check CHECK (((release_reason IS NULL) OR (release_reason = ANY (ARRAY['generation_failed'::text, 'route_changed'::text, 'event_closed'::text, 'manual_cancellation'::text])))),
    CONSTRAINT clinic_packet_reservations_status_check CHECK ((status = ANY (ARRAY['reserved'::text, 'consumed'::text, 'released'::text])))
);


ALTER TABLE public.clinic_packet_reservations OWNER TO postgres;

--
-- Name: consumer_briefcase_items; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.consumer_briefcase_items (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    item_type text NOT NULL,
    jurisdiction text NOT NULL,
    pathway_label text,
    result_code text,
    packet_type text,
    payment_allowed boolean DEFAULT false NOT NULL,
    status text NOT NULL,
    summary_json jsonb DEFAULT '{}'::jsonb NOT NULL,
    next_steps_json jsonb DEFAULT '[]'::jsonb NOT NULL,
    artifact_refs_json jsonb DEFAULT '{}'::jsonb NOT NULL,
    payment_status text DEFAULT 'not_applicable'::text NOT NULL,
    packet_status text DEFAULT 'not_started'::text NOT NULL,
    reminder_at timestamp with time zone,
    source_session_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    payment_provider text,
    checkout_session_id text,
    payment_intent_id text,
    amount_cents integer,
    receipt_url text,
    currency text,
    provider_event_id text,
    payment_authority text,
    payment_recorded_at timestamp with time zone,
    payment_recorded_by text,
    payment_product_id text,
    payment_person_id uuid,
    payment_matter_id uuid,
    source_pending_result_id uuid,
    regular_price_cents integer,
    discount_cents integer,
    CONSTRAINT consumer_briefcase_items_amount_cents_check CHECK (((amount_cents IS NULL) OR ((amount_cents >= 0) AND (amount_cents <= 5000)))),
    CONSTRAINT consumer_briefcase_items_currency_check CHECK (((currency IS NULL) OR (currency = 'usd'::text))),
    CONSTRAINT consumer_briefcase_items_item_type_check CHECK ((item_type = ANY (ARRAY['eligibility_check'::text, 'result'::text, 'packet'::text, 'wilma_conversation'::text]))),
    CONSTRAINT consumer_briefcase_items_packet_status_check CHECK ((packet_status = ANY (ARRAY['not_started'::text, 'pending'::text, 'generating'::text, 'ready'::text, 'failed'::text, 'downloaded'::text]))),
    CONSTRAINT consumer_briefcase_items_packet_type_check CHECK (((packet_type IS NULL) OR (packet_type = ANY (ARRAY['official_pdf_overlay'::text, 'custom_pleading'::text, 'legacy_packet'::text, 'guidance_packet'::text])))),
    CONSTRAINT consumer_briefcase_items_paid_requires_server_evidence CHECK (((payment_status <> 'paid'::text) OR ((payment_authority IS NOT NULL) AND (provider_event_id IS NOT NULL) AND (payment_recorded_at IS NOT NULL) AND (currency = 'usd'::text) AND (regular_price_cents = 5000) AND ((discount_cents >= 0) AND (discount_cents <= regular_price_cents)) AND (amount_cents = (regular_price_cents - discount_cents)) AND (NULLIF(TRIM(BOTH FROM COALESCE(checkout_session_id, ''::text)), ''::text) IS NOT NULL) AND (payment_product_id = 'expungement_packet'::text) AND (payment_person_id IS NOT NULL) AND (payment_matter_id = public.consumer_matter_id_for_briefcase_item(id))))),
    CONSTRAINT consumer_briefcase_items_payment_authority_check CHECK (((payment_authority IS NULL) OR (payment_authority = ANY (ARRAY['server_webhook'::text, 'server_admin'::text])))),
    CONSTRAINT consumer_briefcase_items_payment_product_check CHECK (((payment_product_id IS NULL) OR (payment_product_id = 'expungement_packet'::text))),
    CONSTRAINT consumer_briefcase_items_payment_provider_check CHECK (((payment_provider IS NULL) OR (payment_provider = ANY (ARRAY['stripe'::text, 'dry_run'::text])))),
    CONSTRAINT consumer_briefcase_items_payment_status_check CHECK ((payment_status = ANY (ARRAY['not_applicable'::text, 'unpaid'::text, 'paid'::text, 'refunded'::text]))),
    CONSTRAINT consumer_briefcase_items_result_code_check CHECK (((result_code IS NULL) OR (result_code = ANY (ARRAY['packet_ready'::text, 'packet_ready_with_caution'::text, 'needs_more_info'::text, 'not_yet'::text, 'guidance_only'::text, 'not_covered_yet'::text, 'likely_not_eligible'::text, 'needs_review'::text, 'hard_stop'::text])))),
    CONSTRAINT consumer_briefcase_items_status_check CHECK ((status = ANY (ARRAY['check_saved'::text, 'guidance_saved'::text, 'packet_ready'::text, 'needs_info'::text, 'needs_review'::text, 'waiting'::text, 'not_eligible'::text, 'hard_stop'::text])))
);


ALTER TABLE public.consumer_briefcase_items OWNER TO postgres;

--
-- Name: TABLE consumer_briefcase_items; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.consumer_briefcase_items IS 'Expungement.ai consumer-owned Briefcase items. Isolated from partner RCAP records.';


--
-- Name: COLUMN consumer_briefcase_items.user_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.consumer_briefcase_items.user_id IS 'Auth user owner. RLS policies require auth.uid() to match this value for consumer access.';


--
-- Name: COLUMN consumer_briefcase_items.packet_status; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.consumer_briefcase_items.packet_status IS 'Consumer packet generation lifecycle for paid Expungement.ai packets: not_started, pending, generating, ready, failed, downloaded.';


--
-- Name: COLUMN consumer_briefcase_items.payment_provider; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.consumer_briefcase_items.payment_provider IS 'Consumer checkout provider for Expungement.ai packet payments. Isolated from partner billing.';


--
-- Name: COLUMN consumer_briefcase_items.checkout_session_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.consumer_briefcase_items.checkout_session_id IS 'Stripe Checkout session ID or dry-run session ID for consumer packet checkout.';


--
-- Name: COLUMN consumer_briefcase_items.amount_cents; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.consumer_briefcase_items.amount_cents IS 'Consumer packet checkout amount. Current product price is fixed at 5000 cents.';


--
-- Name: COLUMN consumer_briefcase_items.payment_product_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.consumer_briefcase_items.payment_product_id IS 'Server-only product discriminator for the matter-level payment entitlement. Phase 55.';


--
-- Name: COLUMN consumer_briefcase_items.payment_person_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.consumer_briefcase_items.payment_person_id IS 'Canonical consumer person bound to this paid matter. Phase 55.';


--
-- Name: COLUMN consumer_briefcase_items.payment_matter_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.consumer_briefcase_items.payment_matter_id IS 'Canonical matter bound to this paid Briefcase item. Phase 55.';


--
-- Name: COLUMN consumer_briefcase_items.source_pending_result_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.consumer_briefcase_items.source_pending_result_id IS 'The pending result this matter was claimed from. UNIQUE: one pending result can produce exactly one matter, which is what makes two tabs, two auth callbacks and a refresh mid-claim converge.';


--
-- Name: consumer_packet_artifact_provenance; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.consumer_packet_artifact_provenance (
    briefcase_item_id uuid NOT NULL,
    consumer_auth_user_id uuid NOT NULL,
    matter_id uuid NOT NULL,
    render_job_id uuid,
    verification_hash text,
    entitlement_source text NOT NULL,
    artifact jsonb NOT NULL,
    legacy_evidence jsonb,
    revision integer DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT consumer_packet_artifact_provenance_entitlement_source_check CHECK ((entitlement_source = ANY (ARRAY['consumer_payment'::text, 'partner_sponsorship'::text, 'legacy_backfill'::text]))),
    CONSTRAINT consumer_packet_artifact_provenance_legacy_evidence_required CHECK (((entitlement_source <> 'legacy_backfill'::text) OR (legacy_evidence IS NOT NULL))),
    CONSTRAINT consumer_packet_artifact_provenance_revision_check CHECK ((revision >= 1)),
    CONSTRAINT consumer_packet_artifact_provenance_verification_hash_check CHECK (((verification_hash IS NULL) OR (verification_hash ~ '^[a-f0-9]{64}$'::text)))
);


ALTER TABLE public.consumer_packet_artifact_provenance OWNER TO postgres;

--
-- Name: TABLE consumer_packet_artifact_provenance; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.consumer_packet_artifact_provenance IS 'Protected provenance for an issued consumer packet artifact. The authority behind the private download link. No RLS policy exists, so it is unreadable except by the service role; the participant reaches it only through the download route.';


--
-- Name: consumer_packet_payment_consumption; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.consumer_packet_payment_consumption (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    consumer_briefcase_item_id uuid NOT NULL,
    consumer_auth_user_id uuid NOT NULL,
    provider_event_id text,
    person_id uuid,
    matter_id uuid NOT NULL,
    first_render_job_id uuid NOT NULL,
    consumption_unit_hash text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    product_id text NOT NULL,
    checkout_session_id text NOT NULL,
    amount_cents integer NOT NULL,
    currency text NOT NULL,
    CONSTRAINT consumer_payment_consumption_amount_check CHECK ((amount_cents = 5000)),
    CONSTRAINT consumer_payment_consumption_currency_check CHECK ((currency = 'usd'::text)),
    CONSTRAINT consumer_payment_consumption_product_check CHECK ((product_id = 'expungement_packet'::text))
);


ALTER TABLE public.consumer_packet_payment_consumption OWNER TO postgres;

--
-- Name: TABLE consumer_packet_payment_consumption; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.consumer_packet_payment_consumption IS 'One row per consumer payment actually consumed, keyed on the Briefcase item and the provider receipt rather than the render job. Survives refund so a delivered artifact is preserved. Phase 52.';


--
-- Name: consumer_packet_verifications; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.consumer_packet_verifications (
    briefcase_item_id uuid NOT NULL,
    consumer_auth_user_id uuid NOT NULL,
    matter_id uuid NOT NULL,
    status text NOT NULL,
    reason text NOT NULL,
    verification_hash text,
    verification_snapshot jsonb,
    draft_hash text NOT NULL,
    draft_snapshot jsonb NOT NULL,
    revision integer NOT NULL,
    invalidated_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT consumer_packet_verifications_draft_hash_check CHECK ((draft_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT consumer_packet_verifications_draft_shape CHECK (((draft_snapshot ->> 'schemaVersion'::text) = 'expungement-ai/protected-packet-draft/v1'::text)),
    CONSTRAINT consumer_packet_verifications_reason_check CHECK ((NULLIF(TRIM(BOTH FROM reason), ''::text) IS NOT NULL)),
    CONSTRAINT consumer_packet_verifications_revision_check CHECK ((revision >= 0)),
    CONSTRAINT consumer_packet_verifications_status_check CHECK ((status = ANY (ARRAY['unverified'::text, 'verified'::text, 'invalidated'::text]))),
    CONSTRAINT consumer_packet_verifications_verification_hash_check CHECK (((verification_hash IS NULL) OR (verification_hash ~ '^[a-f0-9]{64}$'::text))),
    CONSTRAINT consumer_packet_verifications_verified_shape CHECK ((((status = 'verified'::text) AND (verification_hash IS NOT NULL) AND ((verification_snapshot ->> 'schemaVersion'::text) = 'expungement-ai/final-verification/v1'::text)) OR ((status <> 'verified'::text) AND (verification_hash IS NULL) AND (verification_snapshot IS NULL))))
);


ALTER TABLE public.consumer_packet_verifications OWNER TO postgres;

--
-- Name: consumer_pending_screening_results; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.consumer_pending_screening_results (
    pending_id uuid DEFAULT gen_random_uuid() NOT NULL,
    claim_token_hash text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone DEFAULT (now() + '24:00:00'::interval) NOT NULL,
    claimed_at timestamp with time zone,
    claimed_user_id uuid,
    product text DEFAULT 'expungement_ai_dtc'::text NOT NULL,
    jurisdiction text NOT NULL,
    result_code text NOT NULL,
    pathway_label text,
    packet_type text,
    payment_allowed boolean DEFAULT false NOT NULL,
    summary text NOT NULL,
    next_steps jsonb DEFAULT '[]'::jsonb NOT NULL,
    screening_answers jsonb DEFAULT '{}'::jsonb NOT NULL,
    result_payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    profile_version text,
    screening_correlation_id text,
    packet_plan jsonb DEFAULT '{}'::jsonb NOT NULL,
    anonymous_session_id uuid,
    status text DEFAULT 'PENDING'::text NOT NULL,
    claimed_matter_id uuid,
    revoked_at timestamp with time zone,
    locale text,
    partner_slug text,
    program_id text,
    event_id uuid,
    campaign_name text,
    access_code_id uuid,
    consent_grant_id uuid,
    candidate_route_context jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT consumer_pending_screening_results_claim_shape CHECK (((status <> 'CLAIMED'::text) OR ((claimed_user_id IS NOT NULL) AND (claimed_matter_id IS NOT NULL) AND (claimed_at IS NOT NULL)))),
    CONSTRAINT consumer_pending_screening_results_matter_implies_claimed CHECK (((claimed_matter_id IS NULL) OR (status = 'CLAIMED'::text))),
    CONSTRAINT consumer_pending_screening_results_next_steps_check CHECK ((jsonb_typeof(next_steps) = 'array'::text)),
    CONSTRAINT consumer_pending_screening_results_packet_plan_check CHECK ((jsonb_typeof(packet_plan) = 'object'::text)),
    CONSTRAINT consumer_pending_screening_results_pending_needs_token CHECK (((status <> 'PENDING'::text) OR (claim_token_hash IS NOT NULL))),
    CONSTRAINT consumer_pending_screening_results_product_check CHECK ((product = ANY (ARRAY['expungement_ai_dtc'::text, 'rcap_partner'::text]))),
    CONSTRAINT consumer_pending_screening_results_result_payload_check CHECK ((jsonb_typeof(result_payload) = 'object'::text)),
    CONSTRAINT consumer_pending_screening_results_screening_answers_check CHECK ((jsonb_typeof(screening_answers) = 'object'::text)),
    CONSTRAINT consumer_pending_screening_results_status_check CHECK ((status = ANY (ARRAY['PENDING'::text, 'CLAIMED'::text, 'EXPIRED'::text, 'REVOKED'::text]))),
    CONSTRAINT consumer_pending_screening_results_token_shape CHECK (((claim_token_hash IS NULL) OR (claim_token_hash ~ '^[0-9a-f]{64}$'::text)))
);


ALTER TABLE public.consumer_pending_screening_results OWNER TO postgres;

--
-- Name: TABLE consumer_pending_screening_results; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.consumer_pending_screening_results IS 'Short-lived unauthenticated Expungement.ai DTC screening result handoff used to attach a completed possible-path result to a user after email verification.';


--
-- Name: COLUMN consumer_pending_screening_results.claim_token_hash; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.consumer_pending_screening_results.claim_token_hash IS 'SHA-256 hex of the single-use opaque claim token. The token itself is returned to the browser exactly once and is never stored. pending_id authorizes nothing on its own.';


--
-- Name: COLUMN consumer_pending_screening_results.screening_answers; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.consumer_pending_screening_results.screening_answers IS 'Raw answers needed to resume or audit the completed check. The URL carries only pending_id, never answers.';


--
-- Name: COLUMN consumer_pending_screening_results.screening_correlation_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.consumer_pending_screening_results.screening_correlation_id IS 'Correlation identifier for the evaluation that produced this preliminary result. It is not a matter identifier and must never be treated as durable authority.';


--
-- Name: COLUMN consumer_pending_screening_results.anonymous_session_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.consumer_pending_screening_results.anonymous_session_id IS 'The anonymous screening_sessions row this preliminary result came from.';


--
-- Name: COLUMN consumer_pending_screening_results.status; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.consumer_pending_screening_results.status IS 'PENDING | CLAIMED | EXPIRED | REVOKED. A pending result holds no owner, Briefcase, entitlement, payment, artifact or verification snapshot.';


