--
-- Name: content_promotion_outbox; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.content_promotion_outbox (
    event_id uuid DEFAULT gen_random_uuid() NOT NULL,
    event_type text NOT NULL,
    idempotency_key text NOT NULL,
    post_id uuid,
    campaign_id uuid,
    payload jsonb NOT NULL,
