--

CREATE TABLE public.legalease_os_support_items (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    source text DEFAULT 'expungement_ai'::text NOT NULL,
    channel text DEFAULT 'web_support_form'::text NOT NULL,
