--
-- Name: partner_onboarding; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.partner_onboarding (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    partner_slug text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    agreement_status text DEFAULT 'not_sent'::text NOT NULL,
    agreement_date date,
    billing_contact_name text,
    billing_contact_email text,
    package_name text,
    internal_billing_notes text,
    internal_notes text,
    public_display_name text,
    public_headline text,
    public_subheadline text,
    support_instructions text,
    show_partner_logo boolean DEFAULT true NOT NULL,
    show_powered_by boolean DEFAULT true NOT NULL,
    profile_ready boolean DEFAULT false NOT NULL,
    billing_ready boolean DEFAULT false NOT NULL,
    access_controls_ready boolean DEFAULT false NOT NULL,
    landing_page_ready boolean DEFAULT false NOT NULL,
    admin_users_ready boolean DEFAULT false NOT NULL,
    launch_materials_ready boolean DEFAULT false NOT NULL,
    training_review_ready boolean DEFAULT false NOT NULL,
    internal_approved_at timestamp with time zone,
    launched_at timestamp with time zone,
    paused_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    partner_record_id uuid,
    schema_version text DEFAULT 'rcap-partner-onboarding-v1'::text NOT NULL,
    aggregate_version bigint DEFAULT 1 NOT NULL,
    completion_percentage integer DEFAULT 0 NOT NULL,
    blocker_code text,
    next_action_code text,
    next_action_owner text DEFAULT 'partner'::text NOT NULL,
    target_launch_date date,
    target_launch_date_reason text,
    target_launch_date_changed_at timestamp with time zone,
    target_launch_date_changed_by uuid,
    commercial_gate_status text DEFAULT 'blocked'::text NOT NULL,
    commercial_gate_evidence_reference text,
    commercial_gate_override_reason text,
    commercial_gate_changed_at timestamp with time zone,
    commercial_gate_changed_by uuid,
    submitted_at timestamp with time zone,
    submitted_by uuid,
    submission_request_id uuid,
    submitted_schema_version text,
    internal_approved_by uuid,
    internal_approval_reason text,
    closed_at timestamp with time zone,
    closed_by uuid,
    closed_reason text,
    last_meaningful_activity_at timestamp with time zone,
    launch_readiness_state text,
    rcap_launch_operation_id uuid,
    rcap_policy_version text DEFAULT 'legacy'::text NOT NULL,
    operating_model text DEFAULT 'partner_managed'::text NOT NULL,
    CONSTRAINT partner_onboarding_aggregate_version_check CHECK ((aggregate_version > 0)),
    CONSTRAINT partner_onboarding_agreement_status_check CHECK ((agreement_status = ANY (ARRAY['not_sent'::text, 'sent'::text, 'signed'::text, 'waived_internal'::text]))),
    CONSTRAINT partner_onboarding_closed_consistency_check CHECK ((((status <> 'closed'::text) AND (closed_at IS NULL) AND (closed_by IS NULL)) OR ((status = 'closed'::text) AND (closed_at IS NOT NULL) AND (closed_by IS NOT NULL)))),
    CONSTRAINT partner_onboarding_commercial_gate_evidence_check CHECK ((((commercial_gate_status <> ALL (ARRAY['cleared_by_paid_invoice'::text, 'cleared_by_approved_purchase_order'::text])) OR (NULLIF(btrim(commercial_gate_evidence_reference), ''::text) IS NOT NULL)) AND ((commercial_gate_status <> 'cleared_by_authorized_internal_override'::text) OR (NULLIF(btrim(commercial_gate_override_reason), ''::text) IS NOT NULL)))),
    CONSTRAINT partner_onboarding_commercial_gate_status_check CHECK ((commercial_gate_status = ANY (ARRAY['blocked'::text, 'cleared_by_paid_invoice'::text, 'cleared_by_approved_purchase_order'::text, 'cleared_by_authorized_internal_override'::text]))),
    CONSTRAINT partner_onboarding_completion_percentage_check CHECK (((completion_percentage >= 0) AND (completion_percentage <= 100))),
    CONSTRAINT partner_onboarding_internal_reason_lengths_check CHECK (((COALESCE(char_length(target_launch_date_reason), 0) <= 5000) AND (COALESCE(char_length(commercial_gate_evidence_reference), 0) <= 500) AND (COALESCE(char_length(commercial_gate_override_reason), 0) <= 5000) AND (COALESCE(char_length(internal_approval_reason), 0) <= 5000) AND (COALESCE(char_length(closed_reason), 0) <= 5000))),
    CONSTRAINT partner_onboarding_launch_readiness_state_check CHECK (((launch_readiness_state IS NULL) OR (launch_readiness_state = ANY (ARRAY['ready'::text, 'not_ready'::text])))),
    CONSTRAINT partner_onboarding_next_action_owner_check CHECK ((next_action_owner = ANY (ARRAY['partner'::text, 'legalease'::text, 'none'::text]))),
    CONSTRAINT partner_onboarding_operating_model_check CHECK ((operating_model = ANY (ARRAY['partner_managed'::text, 'legalease_managed'::text]))),
    CONSTRAINT partner_onboarding_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'commercially_blocked'::text, 'setup_in_progress'::text, 'waiting_on_partner'::text, 'ready_for_review'::text, 'ready_to_launch'::text, 'live'::text, 'paused'::text, 'closed'::text]))),
    CONSTRAINT partner_onboarding_submission_consistency_check CHECK ((((submitted_at IS NULL) AND (submitted_by IS NULL) AND (submission_request_id IS NULL)) OR ((submitted_at IS NOT NULL) AND (submitted_by IS NOT NULL) AND (submission_request_id IS NOT NULL)))),
    CONSTRAINT partner_onboarding_target_launch_audit_check CHECK ((((target_launch_date_reason IS NULL) AND (target_launch_date_changed_at IS NULL) AND (target_launch_date_changed_by IS NULL)) OR ((NULLIF(btrim(target_launch_date_reason), ''::text) IS NOT NULL) AND (target_launch_date_changed_at IS NOT NULL) AND (target_launch_date_changed_by IS NOT NULL))))
);


ALTER TABLE public.partner_onboarding OWNER TO postgres;

