-- Name: TABLE partner_onboarding; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.partner_onboarding IS 'Standardized RCAP partner onboarding workflow state. Packet cap/overage live in partner_entitlement; access mode on partner_records; users in partner_users.';


