    request_id uuid,
    dedupe_key text,
    occurred_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    artifact_version_id uuid,
    CONSTRAINT partner_onboarding_activity_event_type_check CHECK ((event_type = ANY (ARRAY['workspace_created'::text, 'commercial_gate_changed'::text, 'section_started'::text, 'section_completed'::text, 'section_change_requested'::text, 'section_resubmitted'::text, 'required_asset_uploaded'::text, 'required_asset_replaced'::text, 'required_asset_deleted'::text, 'onboarding_submitted'::text, 'section_approved'::text, 'section_waived'::text, 'ready_for_launch_decided'::text, 'prefill_batch_created'::text, 'prefill_known_data_imported'::text, 'prefill_suggestion_approved'::text, 'prefill_suggestion_rejected'::text, 'prefill_suggestion_superseded'::text, 'prefill_apply_conflict'::text, 'prefill_applied'::text, 'prefill_section_confirmed'::text, 'prefill_section_modified'::text, 'prefill_conflict_override_recorded'::text, 'artifact_generated'::text, 'artifact_generation_failed'::text, 'artifact_changes_requested'::text, 'artifact_approved'::text, 'artifact_superseded'::text, 'artifact_partner_reviewed'::text, 'artifact_approval_invalidated'::text, 'launch_check_recorded'::text, 'launch_check_invalidated'::text, 'launch_approval_recorded'::text, 'launch_readiness_achieved'::text, 'launch_readiness_lost'::text]))),
    CONSTRAINT partner_onboarding_activity_owner_check CHECK ((owner_type = ANY (ARRAY['partner'::text, 'legalease'::text, 'system'::text]))),
    CONSTRAINT partner_onboarding_activity_section_key_check CHECK (((section_key IS NULL) OR (section_key = ANY (ARRAY['organization_contacts'::text, 'program_goals'::text, 'geography_audience_language_accessibility'::text, 'access_sponsorship_capacity'::text, 'brand_public_page'::text, 'staff_dashboard_plan'::text, 'support_referrals_reporting'::text, 'review_authorization'::text])))),
    CONSTRAINT partner_onboarding_activity_status_code_check CHECK (((status_code IS NULL) OR (((char_length(status_code) >= 1) AND (char_length(status_code) <= 120)) AND (status_code ~ '^[a-z0-9_]+$'::text)))),
    CONSTRAINT partner_onboarding_activity_summary_check CHECK ((((char_length(summary_code) >= 1) AND (char_length(summary_code) <= 120)) AND (summary_code ~ '^[a-z0-9_]+$'::text)))
);


