--
-- Name: partner_onboarding_artifact_versions; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.partner_onboarding_artifact_versions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    artifact_id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    version_number integer NOT NULL,
    source_workspace_version bigint NOT NULL,
    source_section_revisions jsonb DEFAULT '{}'::jsonb NOT NULL,
    source_asset_versions jsonb DEFAULT '{}'::jsonb NOT NULL,
    normalized_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    snapshot_hash text NOT NULL,
    generator_version text NOT NULL,
    rendered_content jsonb DEFAULT '{}'::jsonb NOT NULL,
    generation_status text DEFAULT 'pending'::text NOT NULL,
    generation_error_code text,
    approval_status text DEFAULT 'draft'::text NOT NULL,
    partner_review_status text DEFAULT 'not_requested'::text NOT NULL,
    partner_visible_instructions text,
    source_drift_invalidated_at timestamp with time zone,
    source_drift_fields text[] DEFAULT '{}'::text[] NOT NULL,
    invalidated_against_snapshot_hash text,
    generated_by uuid NOT NULL,
    generated_at timestamp with time zone DEFAULT now() NOT NULL,
    superseded_at timestamp with time zone,
    request_id uuid NOT NULL,
    CONSTRAINT partner_onboarding_artifact_versions_approval_check CHECK ((approval_status = ANY (ARRAY['draft'::text, 'ready_for_review'::text, 'changes_requested'::text, 'approved'::text, 'superseded'::text, 'generation_failed'::text]))),
    CONSTRAINT partner_onboarding_artifact_versions_drift_pair_check CHECK ((((source_drift_invalidated_at IS NULL) AND (invalidated_against_snapshot_hash IS NULL)) OR ((source_drift_invalidated_at IS NOT NULL) AND (invalidated_against_snapshot_hash IS NOT NULL)))),
    CONSTRAINT partner_onboarding_artifact_versions_failed_consistency_check CHECK (((generation_status = 'failed'::text) = (approval_status = 'generation_failed'::text))),
    CONSTRAINT partner_onboarding_artifact_versions_failure_reason_check CHECK (((generation_status = 'failed'::text) = (generation_error_code IS NOT NULL))),
    CONSTRAINT partner_onboarding_artifact_versions_generation_check CHECK ((generation_status = ANY (ARRAY['pending'::text, 'succeeded'::text, 'failed'::text]))),
    CONSTRAINT partner_onboarding_artifact_versions_generator_version_check CHECK ((((char_length(generator_version) >= 1) AND (char_length(generator_version) <= 120)) AND (generator_version ~ '^[a-z0-9_]+$'::text))),
    CONSTRAINT partner_onboarding_artifact_versions_instructions_check CHECK (((partner_visible_instructions IS NULL) OR ((char_length(partner_visible_instructions) >= 1) AND (char_length(partner_visible_instructions) <= 5000)))),
    CONSTRAINT partner_onboarding_artifact_versions_number_check CHECK ((version_number > 0)),
    CONSTRAINT partner_onboarding_artifact_versions_partner_review_check CHECK ((partner_review_status = ANY (ARRAY['not_requested'::text, 'awaiting_partner'::text, 'changes_requested'::text, 'approved'::text]))),
    CONSTRAINT partner_onboarding_artifact_versions_snapshot_hash_check CHECK ((snapshot_hash ~ '^[a-f0-9]{64}$'::text))
);


