    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT partner_onboarding_launch_checks_category_check CHECK ((category = ANY (ARRAY['commercial_and_procurement'::text, 'configuration'::text, 'page_and_brand'::text, 'partner_team_and_reporting'::text, 'participant_journey'::text, 'training_and_resources'::text, 'approvals'::text]))),
    CONSTRAINT partner_onboarding_launch_checks_determination_check CHECK ((determination = ANY (ARRAY['automated'::text, 'manual'::text]))),
    CONSTRAINT partner_onboarding_launch_checks_evidence_length_check CHECK ((((evidence_summary IS NULL) OR ((char_length(evidence_summary) >= 1) AND (char_length(evidence_summary) <= 2000))) AND ((evidence_reference IS NULL) OR ((char_length(evidence_reference) >= 1) AND (char_length(evidence_reference) <= 500))))),
    CONSTRAINT partner_onboarding_launch_checks_invalidation_pair_check CHECK ((((invalidated_at IS NULL) AND (invalidated_reason IS NULL)) OR ((invalidated_at IS NOT NULL) AND (invalidated_reason IS NOT NULL)))),
    CONSTRAINT partner_onboarding_launch_checks_key_check CHECK ((check_key ~ '^[a-z0-9_]{3,80}$'::text)),
    CONSTRAINT partner_onboarding_launch_checks_owner_check CHECK ((owner_type = ANY (ARRAY['legalease'::text, 'partner'::text]))),
    CONSTRAINT partner_onboarding_launch_checks_reviewer_required_check CHECK (((status <> ALL (ARRAY['passing'::text, 'waived'::text, 'not_applicable'::text])) OR ((checked_by IS NOT NULL) AND (checked_at IS NOT NULL)))),
    CONSTRAINT partner_onboarding_launch_checks_status_check CHECK ((status = ANY (ARRAY['not_started'::text, 'passing'::text, 'failing'::text, 'needs_review'::text, 'waived'::text, 'not_applicable'::text])))
);


ALTER TABLE public.partner_onboarding_launch_checks OWNER TO postgres;

