-- Name: TABLE partner_onboarding_launch_checks; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.partner_onboarding_launch_checks IS 'Recorded launch-check decisions only. Automated check state is recomputed on every read and is never served from this table.';


--
-- Name: partner_onboarding_planned_users; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.partner_onboarding_planned_users (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workspace_id uuid NOT NULL,
    name text NOT NULL,
    work_email text NOT NULL,
    requested_role text NOT NULL,
    special_permissions text[] DEFAULT '{}'::text[] NOT NULL,
    training_attendee boolean DEFAULT false NOT NULL,
    revision bigint DEFAULT 1 NOT NULL,
    training_status text DEFAULT 'not_started'::text NOT NULL,
    training_completed_at timestamp with time zone,
    invitation_status text DEFAULT 'not_invited'::text NOT NULL,
    membership_status text DEFAULT 'planned'::text NOT NULL,
    deleted_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT partner_onboarding_planned_users_email_check CHECK ((((char_length(work_email) >= 3) AND (char_length(work_email) <= 254)) AND (work_email = lower(work_email)) AND (work_email ~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$'::text))),
    CONSTRAINT partner_onboarding_planned_users_invitation_status_check CHECK ((invitation_status = ANY (ARRAY['not_invited'::text, 'planned'::text, 'released'::text]))),
    CONSTRAINT partner_onboarding_planned_users_membership_status_check CHECK ((membership_status = ANY (ARRAY['planned'::text, 'active'::text, 'disabled'::text]))),
    CONSTRAINT partner_onboarding_planned_users_name_check CHECK (((char_length(name) >= 1) AND (char_length(name) <= 120))),
    CONSTRAINT partner_onboarding_planned_users_permissions_check CHECK ((special_permissions <@ ARRAY['manage_codes'::text, 'view_reports'::text, 'export_reports'::text, 'manage_users'::text])),
    CONSTRAINT partner_onboarding_planned_users_revision_check CHECK ((revision > 0)),
    CONSTRAINT partner_onboarding_planned_users_role_check CHECK ((requested_role = ANY (ARRAY['partner_administrator'::text, 'program_staff'::text, 'reporting_viewer'::text]))),
    CONSTRAINT partner_onboarding_planned_users_training_status_check CHECK ((training_status = ANY (ARRAY['not_started'::text, 'scheduled'::text, 'in_progress'::text, 'complete'::text])))
);


ALTER TABLE public.partner_onboarding_planned_users OWNER TO postgres;

