    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    approved_by uuid,
    approved_at timestamp with time zone,
    applied_at timestamp with time zone,
    superseded_at timestamp with time zone,
    aggregate_version bigint DEFAULT 1 NOT NULL,
    request_id uuid NOT NULL,
    CONSTRAINT partner_onboarding_prefill_batches_approval_check CHECK ((((approved_at IS NULL) AND (approved_by IS NULL)) OR ((approved_at IS NOT NULL) AND (approved_by IS NOT NULL)))),
    CONSTRAINT partner_onboarding_prefill_batches_source_summary_check CHECK ((((char_length(source_summary) >= 1) AND (char_length(source_summary) <= 500)) AND (source_summary !~ '[[:cntrl:]]'::text))),
    CONSTRAINT partner_onboarding_prefill_batches_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'ready_for_review'::text, 'approved'::text, 'partially_applied'::text, 'applied'::text, 'rejected'::text, 'superseded'::text]))),
    CONSTRAINT partner_onboarding_prefill_batches_version_check CHECK ((aggregate_version > 0))
);


ALTER TABLE public.partner_onboarding_prefill_batches OWNER TO postgres;

