--
-- Name: partner_onboarding_prefill_values; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.partner_onboarding_prefill_values (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    batch_id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    section_key text NOT NULL,
    field_key text NOT NULL,
    proposed_value jsonb NOT NULL,
    source_type text NOT NULL,
    source_reference_id text,
    source_label text NOT NULL,
    confidence numeric(5,4),
    review_status text DEFAULT 'proposed'::text NOT NULL,
    base_value_hash text NOT NULL,
    proposed_value_hash text NOT NULL,
    base_section_revision bigint NOT NULL,
    applied_value_hash text,
    applied_section_revision bigint,
    applied_workspace_version bigint,
    partner_review_status text DEFAULT 'not_applied'::text NOT NULL,
    partner_reviewed_at timestamp with time zone,
    partner_reviewed_section_revision bigint,
    partner_modified boolean DEFAULT false NOT NULL,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    reviewed_by uuid,
    reviewed_at timestamp with time zone,
    applied_at timestamp with time zone,
    superseded_at timestamp with time zone,
    supersedes_value_id uuid,
    override_reason text,
    override_by uuid,
    override_at timestamp with time zone,
    override_partner_value_hash text,
    CONSTRAINT partner_onboarding_prefill_values_apply_check CHECK ((((review_status <> 'applied'::text) AND (applied_at IS NULL) AND (applied_value_hash IS NULL) AND (applied_section_revision IS NULL) AND (applied_workspace_version IS NULL) AND (partner_review_status = 'not_applied'::text) AND (partner_reviewed_at IS NULL)) OR ((review_status = 'applied'::text) AND (applied_at IS NOT NULL) AND (applied_value_hash IS NOT NULL) AND (applied_section_revision IS NOT NULL) AND (applied_workspace_version IS NOT NULL) AND (partner_review_status = ANY (ARRAY['pending'::text, 'confirmed'::text, 'modified'::text, 'rejected'::text]))))),
    CONSTRAINT partner_onboarding_prefill_values_confidence_check CHECK (((confidence IS NULL) OR ((confidence >= (0)::numeric) AND (confidence <= (1)::numeric)))),
    CONSTRAINT partner_onboarding_prefill_values_field_key_check CHECK ((((char_length(field_key) >= 1) AND (char_length(field_key) <= 120)) AND (field_key ~ '^[a-z0-9_]+$'::text))),
    CONSTRAINT partner_onboarding_prefill_values_hash_check CHECK (((base_value_hash ~ '^[0-9a-f]{64}$'::text) AND (proposed_value_hash ~ '^[0-9a-f]{64}$'::text) AND ((applied_value_hash IS NULL) OR (applied_value_hash ~ '^[0-9a-f]{64}$'::text)))),
    CONSTRAINT partner_onboarding_prefill_values_override_check CHECK ((((override_reason IS NULL) AND (override_by IS NULL) AND (override_at IS NULL) AND (override_partner_value_hash IS NULL)) OR ((override_reason IS NOT NULL) AND ((char_length(override_reason) >= 10) AND (char_length(override_reason) <= 500)) AND (override_reason !~ '[[:cntrl:]]'::text) AND (override_by IS NOT NULL) AND (override_at IS NOT NULL) AND (override_partner_value_hash ~ '^[0-9a-f]{64}$'::text)))),
    CONSTRAINT partner_onboarding_prefill_values_partner_review_check CHECK ((((partner_review_status = ANY (ARRAY['not_applied'::text, 'pending'::text])) AND (partner_reviewed_at IS NULL) AND (partner_reviewed_section_revision IS NULL)) OR ((partner_review_status = ANY (ARRAY['confirmed'::text, 'modified'::text, 'rejected'::text])) AND (partner_reviewed_at IS NOT NULL) AND (partner_reviewed_section_revision IS NOT NULL)))),
    CONSTRAINT partner_onboarding_prefill_values_partner_review_status_check CHECK ((partner_review_status = ANY (ARRAY['not_applied'::text, 'pending'::text, 'confirmed'::text, 'modified'::text, 'rejected'::text]))),
    CONSTRAINT partner_onboarding_prefill_values_review_actor_check CHECK ((((reviewed_at IS NULL) AND (reviewed_by IS NULL)) OR ((reviewed_at IS NOT NULL) AND (reviewed_by IS NOT NULL)))),
    CONSTRAINT partner_onboarding_prefill_values_review_status_check CHECK ((review_status = ANY (ARRAY['proposed'::text, 'approved'::text, 'rejected'::text, 'applied'::text, 'conflict'::text, 'superseded'::text]))),
    CONSTRAINT partner_onboarding_prefill_values_revision_check CHECK (((base_section_revision >= 0) AND ((applied_section_revision IS NULL) OR (applied_section_revision > 0)) AND ((applied_workspace_version IS NULL) OR (applied_workspace_version > 0)) AND ((partner_reviewed_section_revision IS NULL) OR (partner_reviewed_section_revision > 0)))),
    CONSTRAINT partner_onboarding_prefill_values_section_check CHECK ((section_key = ANY (ARRAY['organization_contacts'::text, 'program_goals'::text, 'geography_audience_language_accessibility'::text, 'access_sponsorship_capacity'::text, 'brand_public_page'::text, 'staff_dashboard_plan'::text, 'support_referrals_reporting'::text, 'review_authorization'::text]))),
    CONSTRAINT partner_onboarding_prefill_values_size_check CHECK ((octet_length((proposed_value)::text) <= 65536)),
    CONSTRAINT partner_onboarding_prefill_values_source_label_check CHECK ((((char_length(source_label) >= 1) AND (char_length(source_label) <= 200)) AND (source_label !~ '[[:cntrl:]]'::text))),
    CONSTRAINT partner_onboarding_prefill_values_source_reference_check CHECK (((source_reference_id IS NULL) OR (((char_length(source_reference_id) >= 1) AND (char_length(source_reference_id) <= 200)) AND (source_reference_id !~ '[[:cntrl:]]'::text)))),
    CONSTRAINT partner_onboarding_prefill_values_source_type_check CHECK ((source_type = ANY (ARRAY['partner_record'::text, 'contact_record'::text, 'order_form'::text, 'agreement'::text, 'proposal'::text, 'meeting'::text, 'email'::text, 'kickoff'::text, 'manual'::text, 'other'::text]))),
    CONSTRAINT partner_onboarding_prefill_values_supersedes_self_check CHECK (((supersedes_value_id IS NULL) OR (supersedes_value_id <> id)))
);


ALTER TABLE public.partner_onboarding_prefill_values OWNER TO postgres;

--
-- Name: TABLE partner_onboarding_prefill_values; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.partner_onboarding_prefill_values IS 'Canonical field suggestions with internal provenance and independent partner confirmation state.';


--
-- Name: COLUMN partner_onboarding_prefill_values.proposed_value; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.partner_onboarding_prefill_values.proposed_value IS 'A canonical structured field value only; raw notes, messages, transcripts, and source documents are prohibited.';


--
