--

COMMENT ON COLUMN public.partner_onboarding_prefill_values.override_partner_value_hash IS 'Fingerprint of the partner answer that a recorded override replaced. Present only on an overridden suggestion.';


--
-- Name: partner_onboarding_prefill_values_safe; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.partner_onboarding_prefill_values_safe WITH (security_barrier='true', security_invoker='true') AS
 SELECT id,
    batch_id,
    workspace_id,
    section_key,
    field_key,
    review_status,
    partner_review_status,
    partner_reviewed_at,
    partner_modified,
    applied_at,
    applied_section_revision,
    partner_reviewed_section_revision
   FROM public.partner_onboarding_prefill_values
  WHERE ((review_status = 'applied'::text) AND (superseded_at IS NULL));


ALTER VIEW public.partner_onboarding_prefill_values_safe OWNER TO postgres;

