--
-- Name: partner_onboarding_sections; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.partner_onboarding_sections (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workspace_id uuid NOT NULL,
    section_key text NOT NULL,
    response_data jsonb DEFAULT '{}'::jsonb NOT NULL,
    revision bigint DEFAULT 1 NOT NULL,
    status text DEFAULT 'not_started'::text NOT NULL,
    completion_percentage integer DEFAULT 0 NOT NULL,
    missing_required_keys text[] DEFAULT '{}'::text[] NOT NULL,
    first_started_at timestamp with time zone,
    completed_at timestamp with time zone,
    submitted_at timestamp with time zone,
    approved_at timestamp with time zone,
    approved_by uuid,
    waived_at timestamp with time zone,
    waived_by uuid,
    waiver_reason text,
    reviewed_at timestamp with time zone,
    reviewed_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    review_reason text,
    CONSTRAINT partner_onboarding_sections_completion_check CHECK (((completion_percentage >= 0) AND (completion_percentage <= 100))),
    CONSTRAINT partner_onboarding_sections_key_check CHECK ((section_key = ANY (ARRAY['organization_contacts'::text, 'program_goals'::text, 'geography_audience_language_accessibility'::text, 'access_sponsorship_capacity'::text, 'brand_public_page'::text, 'staff_dashboard_plan'::text, 'support_referrals_reporting'::text, 'review_authorization'::text]))),
    CONSTRAINT partner_onboarding_sections_response_size_check CHECK ((octet_length((response_data)::text) <= 65536)),
    CONSTRAINT partner_onboarding_sections_review_reason_check CHECK (((review_reason IS NULL) OR ((char_length(review_reason) >= 1) AND (char_length(review_reason) <= 5000)))),
    CONSTRAINT partner_onboarding_sections_revision_check CHECK ((revision > 0)),
    CONSTRAINT partner_onboarding_sections_status_check CHECK ((status = ANY (ARRAY['not_started'::text, 'in_progress'::text, 'submitted'::text, 'needs_changes'::text, 'approved'::text, 'waived'::text, 'not_applicable'::text]))),
    CONSTRAINT partner_onboarding_sections_waiver_check CHECK (((status <> 'waived'::text) OR ((waived_at IS NOT NULL) AND (waived_by IS NOT NULL) AND (NULLIF(btrim(waiver_reason), ''::text) IS NOT NULL))))
);


