    CONSTRAINT rcap_launch_exception_events_kind_check CHECK ((kind = ANY (ARRAY['grant'::text, 'revoke'::text]))),
    CONSTRAINT rcap_launch_exception_events_reason_check CHECK ((length(btrim(reason)) >= 10)),
