--
-- Name: content_media content_media_anon_public_read; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY content_media_anon_public_read ON public.content_media FOR SELECT TO anon USING (((NOT archived) AND ((EXISTS ( SELECT 1
   FROM (public.content_media_usages u
     JOIN public.content_posts p ON ((p.post_id = u.post_id)))
  WHERE ((u.media_id = content_media.media_id) AND (p.status = ANY (ARRAY['published'::text, 'updated'::text])) AND (p.published_at IS NOT NULL) AND (p.published_at <= now())))) OR (EXISTS ( SELECT 1
   FROM public.content_posts p
  WHERE (((p.featured_media_id = content_media.media_id) OR (p.og_media_id = content_media.media_id)) AND (p.status = ANY (ARRAY['published'::text, 'updated'::text])) AND (p.published_at IS NOT NULL) AND (p.published_at <= now())))) OR (EXISTS ( SELECT 1
   FROM public.content_state_editorial e
  WHERE (((e.featured_media_id = content_media.media_id) OR (e.og_media_id = content_media.media_id)) AND (e.status = 'published'::text)))) OR (EXISTS ( SELECT 1
   FROM public.content_testimonials t
  WHERE ((t.media_id = content_media.media_id) AND t.approved))))));


